-- Questions batch 5 (250 rows)
INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_213', 'mbe', '213', '130', 'MBE-1978-83-part1', '', '64', 'Householder resented the fact that joggers and walkers would sometimes come onto his property just beside the sidewalk in order to enjoy the feel of walking or running on grass. He put up a sign, "No Trespassing," but it did not stop the practice. He then put up a sign, "Beware of Skunk," and bought a young skunk. He took the skunk to Dr. Vet to have its scent gland removed. Unfortunately, Dr. Vet did not perform the operation properly, and the scent gland was not removed. Householder was unaware that it had not been removed, One day Walker was out for a stroll. When she came to Householder''s property, she walked on the grass alongside the sidewalk on Householder''s property. The skunk came up behind Walker and sprayed her with its scent. The smell was overpowering, and she fainted. She struck her head on the sidewalk and suffered serious injuries.', 'The probable result of Walker''s claim against Householder is that she will', 'recover, because the skunk was a private nuisance', 'recover, because the skunk was not a domesticated animal', 'not recover, because Walker was a trespasser', 'not recover, because Dr. Vet was the cause of the injury', 'B', 'To recover on a claim of strict liability for injury by a dangerous domesticated animal, a plaintiff must prove: (1) the defendant was the owner or possessor of the animal; (2) the animal had dangerous propensities abnormal to its class; (3) the defendant knew or had reason to know the animal had dangerous propensities; and (4) those propensities were a producing cause of the plaintiff''s injury.', 'mbe_174', 0, '64'),
('mbe_214', 'mbe', '214', '130', 'MBE-1978-83-part1', '', '65', 'Householder resented the fact that joggers and walkers would sometimes come onto his property just beside the sidewalk in order to enjoy the feel of walking or running on grass. He put up a sign, "No Trespassing," but it did not stop the practice. He then put up a sign, "Beware of Skunk," and bought a young skunk. He took the skunk to Dr. Vet to have its scent gland removed. Unfortunately, Dr. Vet did not perform the operation properly, and the scent gland was not removed. Householder was unaware that it had not been removed, One day Walker was out for a stroll. When she came to Householder''s property, she walked on the grass alongside the sidewalk on Householder''s property. The skunk came up behind Walker and sprayed her with its scent. The smell was overpowering, and she fainted. She struck her head on the sidewalk and suffered serious injuries.', 'If Walker asserts a claim against Dr. Vet, she will', 'recover on the ground of negligence', 'recover on the ground of strict liability', 'not recover, because Walker was trespassing at the time of her injury', 'not recover, because Dr. Vet''s professional services were rendered for Householder', 'A', 'In order to sustain a claim for negligence, a plaintiff must be able to establish “(1) a legal duty; (2) a breach of this duty; (3) an injury; and (4) a causal connection between the breach and the injury.” Persinger v. Step By Step Infant Dev. Ctr., 253 Ga. App. 768, 769, 560 S.E.2d 333 (2002) (quoting Vaughan v. Glymph, 241 Ga. App. 346, 348, 526 S.E.2d 357 (1999) ).', 'mbe_175', 0, '65'),
('mbe_215', 'mbe', '215', '131', 'MBE-1978-83-part1', '', '66', '', 'In a collision case, Plaintiff offers in evidence a photograph showing the scene of the accident while the cars were still in place. A proper foundation must include, as a minimum, testimony by which of the following?', 'The photographer', 'A person who was present at the time the photograph was taken', 'A person who observed the cars while they were still in place', 'A person in whose custody the photograph has been since it was developed', 'C', 'However, before an exhibit can be offered into evidence, you must prove to the court that it is authentic, which is known as laying the foundation. This simply means that you must demonstrate to the court that you have the knowledge sufficient to prove that the exhibit is authentic.', 'mbe_2335', 0, '66'),
('mbe_216', 'mbe', '216', '132', 'MBE-1978-83-part1', '', '67', 'While negligently driving his father''s uninsured automobile, 25-year-old Arthur crashed into an automobile driven by Betty. Both Arthur and Betty were injured. Charles, Arthur''s father, erroneously believing that he was liable because he owned the automobile, said to Betty: "I will see to it that you are reimbursed for any losses you incur as a result of the accident." Charles also called Physician and told him to take care of Betty, and that he, Charles, would pay the bill. Arthur, having no assets, died as a result of his injuries. Dodge, one of Arthur''s creditors, wrote to Charles stating that Arthur owed him a clothing bill of $200 and that he was going to file a claim against Arthur''s estate. Charles replied: "If you don''t file a claim against Arthur''s estate, I will pay what he owed you."', 'In an action by Betty against Charles for wages lost while she was incapacitated as a result of the accident, which of the following would be Charles''s best defense?', 'Lack of consideration', 'Mistake of fact as to basic assumption', 'Statute of Frauds', 'Indefiniteness of Charles''s promise', 'A', 'the essential elements of a contract are (1) competent parties, (2) subject matter, (3) legal consideration, (4) mutual agreement, (5) and mutual obligations.3 Consideration is any benefit conferred or agreed to be conferred upon the promisor to which he is not lawfully entitled, or any prejudice suffered or agreed to be suffered by promisor, other than that which he is lawfully bound to suffer.4 Mutual promises constitute consideration, each for the other.5 While mutual promises will sustain a contract, there is no valid agreement if there is no promise by one party as a consideration for the other''s promise.6', 'mbe_176', 0, '67'),
('mbe_217', 'mbe', '217', '132', 'MBE-1978-83-part1', '', '68', 'While negligently driving his father''s uninsured automobile, 25-year-old Arthur crashed into an automobile driven by Betty. Both Arthur and Betty were injured. Charles, Arthur''s father, erroneously believing that he was liable because he owned the automobile, said to Betty: "I will see to it that you are reimbursed for any losses you incur as a result of the accident." Charles also called Physician and told him to take care of Betty, and that he, Charles, would pay the bill. Arthur, having no assets, died as a result of his injuries. Dodge, one of Arthur''s creditors, wrote to Charles stating that Arthur owed him a clothing bill of $200 and that he was going to file a claim against Arthur''s estate. Charles replied: "If you don''t file a claim against Arthur''s estate, I will pay what he owed you."', 'Which of the following, if true, would be significant in determining whether or not there was bargainedfor consideration to support Charles''s promise to Physician? I. Physician had not begun treating Betty before Charles called him. II Charles had a contract with Betty.', 'I only', 'II only', 'Both I and II', 'Neither I nor II', 'C', 'Consideration is “some right, interest, profit or benefit or some forbearance, detriment, loss or responsibility given, suffered or undertaken by the other.” Homestyle Direct, LLC v. DHS, 354 Or. 253, 262, 311 P.3d 487 (2013); see also Restatement (Second) of Contracts § 71(2) (1981) (defining “consideration” as a performance or return promise “sought by the promisor in exchange for his promise” and “given by the promisee in exchange for that promise”). Consideration is “the basis for a bargain that two parties reach; it is what is sought by the promisor in exchange for a promise and given by the promisee in exchange for the promise.” State v. Villagomez, 362 Or. 390, 397, 412 P.3d 183 (2018).', 'mbe_177', 0, '68'),
('mbe_218', 'mbe', '218', '132', 'MBE-1978-83-part1', '', '69', 'While negligently driving his father''s uninsured automobile, 25-year-old Arthur crashed into an automobile driven by Betty. Both Arthur and Betty were injured. Charles, Arthur''s father, erroneously believing that he was liable because he owned the automobile, said to Betty: "I will see to it that you are reimbursed for any losses you incur as a result of the accident." Charles also called Physician and told him to take care of Betty, and that he, Charles, would pay the bill. Arthur, having no assets, died as a result of his injuries. Dodge, one of Arthur''s creditors, wrote to Charles stating that Arthur owed him a clothing bill of $200 and that he was going to file a claim against Arthur''s estate. Charles replied: "If you don''t file a claim against Arthur''s estate, I will pay what he owed you."', 'If Physician discontinued treating Betty before she had fully recovered and Betty brought an action against Physician for breach of contract, which of the following arguments, if any, by Physician would probably be effective in defense? I. Betty furnished no consideration, either express or implied. II. Physician''s contract was with Charles and not with Betty. III. Whatever contract Physician may have had with Betty was discharged by novation on account of the agreement with Charles.', 'I only', 'I and II only', 'II and III only', 'Neither I nor II nor III', 'D', '“[t]he four elements of a novation, which the party establishing the defense must prove by a preponderance of the evidence, are: ‘[1] a previous, valid obligation; [2] a subsequent agreement of all the parties to the new contract; [3] the extinguishment of the old contract; and [4] the validity of the new contract.’ ” Id. at 887 (quoting Phillips & Arnold, Inc. v. Frederick J. Borgsmiller, Inc., 462 N.E.2d 924, 928 (Ill. App. Ct. 1984)).', 'mbe_178', 0, '69'),
('mbe_219', 'mbe', '219', '132', 'MBE-1978-83-part1', '', '70', 'While negligently driving his father''s uninsured automobile, 25-year-old Arthur crashed into an automobile driven by Betty. Both Arthur and Betty were injured. Charles, Arthur''s father, erroneously believing that he was liable because he owned the automobile, said to Betty: "I will see to it that you are reimbursed for any losses you incur as a result of the accident." Charles also called Physician and told him to take care of Betty, and that he, Charles, would pay the bill. Arthur, having no assets, died as a result of his injuries. Dodge, one of Arthur''s creditors, wrote to Charles stating that Arthur owed him a clothing bill of $200 and that he was going to file a claim against Arthur''s estate. Charles replied: "If you don''t file a claim against Arthur''s estate, I will pay what he owed you."', 'If Dodge did not file an action against Arthur''s estate, would Dodge succeed in an action against Charles for $200 ?', 'Yes, because Dodge had detrimentally relied on Charles''s promise.', 'Yes, because Charles''s promise was supported by a bargained-for exchange.', 'No, because Dodge''s claim against Arthur''s estate was worthless.', 'No, because Charles at most had only a moral obligation to pay Arthur''s debts.', 'B', '“It is a well-established principle that a valid contract requires ‘competent parties, subject matter, a legal consideration, mutuality of agreement, and mutuality of obligation.’ ” Voccola v. Forte, 139 A.3d 404, 414 (R.I. 2016) (quoting DeLuca v. City of Cranston, 22 A.3d 382, 384 (R.I. 2011) (mem.)). “[C]onsideration ‘consists of some legal right acquired by the promisor in consideration of his promise, or forborne by the promisee in consideration of such promise.’ ” DeLuca, 22 A.3d at 384 (quoting DeAngelis v. DeAngelis, 923 A.2d 1274, 1279 (R.I. 2007)). “When evaluating the sufficiency of contractual consideration, we employ ‘the bargained-for exchange test.’ ” Id. (quoting DeAngelis, 923 A.2d at 1279). That test “provides that something is bargained for, * * * if it is sought by the promisor in exchange for his [or her] promise and is given by the promisee in exchange for that promise.” Id. (quoting DeAngelis, 923 A.2d at 1279).', 'mbe_179', 0, '70'),
('mbe_22', 'mbe', '22', '11', 'MBE-1972-78-part2', '', '23', 'Jack and Paul planned to hold up a bank. They drove to the bank in Jack''s car. Jack entered while Paul remained as lookout in the car. After a few moments, Paul panicked and drove off. Jack looked over the various tellers, approached one and wispered nervously, "Just hand over the cash. Don''t look around, don''t make a false move-or it''s your life." The teller looked at the fidgeting Jack, laughed, flipped him a dollar bill and said, "Go on, beat it." Flustered, Jack grabbed the dollar and left. Soon after leaving the scene, Paul was stopped by the police for speeding. Noting his nervous condition, the police asked Paul if they might search the car. Paul agreed. The search turned up heroin concealed in the lid of the trunk.', 'Paul''s best defense to a charge of robbery would be that', 'Jack alone entered the bank', 'Paul withdrew before commission of the crime when he fled the scene', 'Paul had no knowledge of what Jack whispered to the teller', 'the teller was not placed in fear by Jack', 'D', '“Robbery” is the “[f]elonious taking of ... [any] article of value, in the possession of another, from his person or immediate presence, and against his will, accomplished by means of force or fear.” Id. at 1193 (emphasis added) (citations omitted). Finally, the act of “pillaging” is the “forcible taking of private property by an invading or conquering army from the enemy''s subjects.” Id. at 1033 (emphasis added).', 'mbe_19', 0, '23'),
('mbe_220', 'mbe', '220', '132', 'MBE-1978-83-part1', '', '71', 'While negligently driving his father''s uninsured automobile, 25-year-old Arthur crashed into an automobile driven by Betty. Both Arthur and Betty were injured. Charles, Arthur''s father, erroneously believing that he was liable because he owned the automobile, said to Betty: "I will see to it that you are reimbursed for any losses you incur as a result of the accident." Charles also called Physician and told him to take care of Betty, and that he, Charles, would pay the bill. Arthur, having no assets, died as a result of his injuries. Dodge, one of Arthur''s creditors, wrote to Charles stating that Arthur owed him a clothing bill of $200 and that he was going to file a claim against Arthur''s estate. Charles replied: "If you don''t file a claim against Arthur''s estate, I will pay what he owed you."', 'Assume that Charles, honestly believing that he owed Dodge nothing, refused to pay anything to Dodge, who honestly believed that Charles owed him $200. If Dodge then accepts $150 from Charles in settlement of the claim, will Dodge succeed in an action against Charles for the remaining $50 ?', 'Yes, because Arthur''s debt of $200 was liquidated and undisputed.', 'Yes, because Dodge honestly believed that he had a legal right against Charles for the full $200.', 'No, because Charles honestly believed that Dodge did not have a legal right against him for the $200.', 'No, because Charles was not contractually obligated to pay Dodge $200 in the first place.', 'C', 'an administrator who within the year allowed by statute pays a creditor''s claim in full, acting upon the honest belief that the estate is solvent, may, upon the estate proving actually insolvent, recover back the difference between the amount so paid and the pro rata share which the creditor would have been entitled to in common with all general creditors.’ Such right of action is declared to arise out of the equitable doctrine that the creditor has received money which in equity and good conscience belongs to the estate for the purpose of making an equal distribution among all the general creditors. This purpose is characterized in the opinion as ‘the cardinal principle of the laws relating to the administration and settlement of decedent''s estates.’', 'mbe_180', 0, '71'),
('mbe_221', 'mbe', '221', '133', 'MBE-1978-83-part1', '', '72', 'Until 1954, the state of New Atlantic required segregation in all public and private schools, but all public schools are now desegregated. Other state laws, enacted before 1954 and continuing to the present, provide for free distribution of the same textbooks on secular subjects to students in all public and private schools. In addition, the state accredits schools and certifies teachers. Little White School House, a private school that offers elementary and secondary education in the state, denies admission to all non-Caucasians. Stone School is a private school that offers religious instruction.', 'Which of the following is the strongest argument against the constitutionality of free distribution of textbooks to the students at the Little White School House?', 'No legitimate educational function is served by the free distribution of textbooks.', 'The state may not in any way aid private schools''.', 'The Constitution forbids private bias of any kind-', 'Segregation is furthered by the distribution of textbooks to these students.', 'D', '“Equal protection under the law requires that no person or class of persons be denied the protection afforded by the law to other persons or classes in like circumstances.  * * * The Equal Protection Clause does not prevent all classification, however. It simply forbids laws that treat persons differently when they are otherwise alike in all relevant respects.” State v. Alfieri (1998), 132 Ohio App.3d 69, 77, 724 N.E.2d 477.', 'mbe_181', 0, '72'),
('mbe_222', 'mbe', '222', '133', 'MBE-1978-83-part1', '', '73', 'Until 1954, the state of New Atlantic required segregation in all public and private schools, but all public schools are now desegregated. Other state laws, enacted before 1954 and continuing to the present, provide for free distribution of the same textbooks on secular subjects to students in all public and private schools. In addition, the state accredits schools and certifies teachers. Little White School House, a private school that offers elementary and secondary education in the state, denies admission to all non-Caucasians. Stone School is a private school that offers religious instruction.', 'Which of the following is the strongest argument in favor of the constitutionality of free distribution of textbooks to the students at Stone School?', 'Private religious schools, like public nonsectarian schools, fulfill an important educational function.', 'Religious instruction in private schools is not constitutionally objectionable.', 'The purpose and effect of the free distribution of these textbooks is secular and does not entangle church and state.', 'The free exercise clause requires identical treatment by the state of students in public and private schools.', 'C', 'Under the test developed in Lemon v. Kurtzman, government action survives an Establishment Clause challenge if (1) it has “a secular legislative purpose,” (2) its “principal or primary” effect “neither advances nor inhibits religion,” and (3) it does “not foster an excessive government entanglement with religion.” Lemon v. Kurtzman, 403 U.S. 602, 612–13, 91 S.Ct. 2125, 29 L.Ed.2d 745 (1971) (internal quotations omitted) (emphasis added); see also Freedom From Religion Found. v. Hanover Sch. Dist., 626 F.3d 1, 9 (1st Cir. 2010).', 'mbe_182', 0, '73'),
('mbe_223', 'mbe', '223', '134', 'MBE-1978-83-part1', '', '74', '', 'On a foggy night, Vera was clubbed from behind by a man wielding a blackjack. Damon was arrested in the vicinity shortly thereafter. As they were booking Damon, the police took his photograph. They promptly showed that photograph, along with the photographs of seven people who have the same general features as Damon, to Vera. Vera identifled Damon as the culprit. At trial, Damon objects to the introduction into evidence of his out-of-court identification. His objection should be', 'sustained, because Vera did not have a good opportunity to observe the culprit', 'sustained, because Damon was not represented by counsel at the showing of the photographs to Vera', 'sustained, because the action of the police in showing the photographs to Vera was unnecessarily suggestive', 'denied', 'D', 'An out-of-court identification should be suppressed if (1) “police used an unnecessarily suggestive procedure to obtain the out-of-court identification; and (2) ... the suggestive procedure gave rise to a substantial likelihood of irreparable misidentification.” Rimmer v. State, 825 So.2d 304, 316 (Fla.2002). Lineup photographs “are not unduly suggestive if the suspect''s picture does not stand out more than those of the others, and the people depicted all exhibit similar facial characteristics.” State v. Francois, 863 So.2d 1288, 1289-90 (Fla. 4th DCA 2004). Here, the defendant does not suggest that his picture stood out more than the others. Rather, he argues that, because it was the only picture common to both lineups, the *149 second photo lineup was unduly suggestive.', 'mbe_2624', 0, '74'),
('mbe_224', 'mbe', '224', '135', 'MBE-1978-83-part1', '', '75', '', 'Defendant is charged with assault and battery. The state''s evidence shows that Victim was struck in the face by Defendant''s fist. In which of the following situations is Defendant most likely to be not guilty of assault and battery?', 'Defendant had been hypnotized at a party and ordered by the hypnotist to strike the person he disliked the most.', 'Defendant was suffering from an epileptic seizure and had no control over his motions.', 'Defendant was heavily intoxicated and was shadow boxing without realizing that Victim was near him.', 'Defendant, who had just awakened from a deep sleep, was not fully aware of what was happening and mistakenly thought Victim was attacking him.', 'B', 'A battery is the “unpermitted application of trauma by one person upon the body of another person.” McQuiggan v. Boy Scouts of America, 73 Md.App. 705, 714, 536 A.2d 137 (1988) (citation omitted). Accord, Saba v. Darling, 72 Md.App. 487, 491, 531 A.2d 696 (1987), aff''d, 320 Md. 45, 575 A.2d 1240 (1990).  Accidental or inadvertent contact does not constitute battery. Richard J. Gilbert & Paul T. Gilbert, Maryland Tort Law Handbook § 3.1, at 29 (2d ed. 1992) (hereinafter, “Gilbert ”). Rather, the tort of battery requires intent by the actor “to bring about a harmful or offensive contact.... [It is] confined to intentional invasions of the interests in freedom from harmful or offensive contact.”5 Fowler V. Harper, et al., 1 The Law of Torts § 3.3, at 272–73, 276 (2d ed. 1986) (hereinafter, “Harper ”). See also, Ghassemieh v. *36 Schafer, 52 Md.App. 31, 38, 447 A.2d 84, cert. denied, 294 Md. 543 (1982).', 'mbe_183', 0, '75'),
('mbe_225', 'mbe', '225', '136', 'MBE-1978-83-part1', '', '76', '', 'Leader is a labor leader in Metropolis. Ten years ago he was divorced. Both he and his first wife have since married other persons. Recently, News, a newspaper in another city, ran a feature article on improper influences it asserted had been used by labor officials to secure favorable rulings from government officials. The story said that in 1960 Leader''s first wife, with Leader''s knowledge and concurrence, gave sexual favors to the mayor of Metropolis and then persuaded him to grant concessions to Leader''s union, with which Metropolis was then negotiating a labor contract. The story named Leader and identified his first wife by her former and current surnames. The reporter for News believed the story to be true, since it had been related to him by two very reliable sources. Leader''s first wife suffered emotional distress and became very depressed. If she asserts a claim based on defamation against News, she will', 'prevail, because the story concerned her personal, private life', 'prevail if the story was false', 'not prevail, because News did not print the story with knowledge of its falsity or with reckless disregard for its truth or falsity', 'not prevail if News exercised ordinary care in determining whether the story was true or false', 'D', 'In order to prevail on a defamation action, a plaintiff must prove the following four elements: “(1) a false and defamatory statement concerning another; (2) an unprivileged publication to a third party; (3) fault (negligence or greater) on the part of the publisher; and (4) resulting injury.” Id. “In other words, a plaintiff must prove that the defendant, with actual malice or other fault, published a false statement with defamatory words which caused plaintiff damages.” Id. (citations and quotations omitted).', 'mbe_2336', 0, '76'),
('mbe_226', 'mbe', '226', '137', 'MBE-1978-83-part1', '', '77', 'In 1975, Utility constructed a new plant for the generation of electricity. The plant burns lignite, a low -grade fuel which is available in large quantities. Although the plant was constructed in accordance with the best practicable technology, the plant emits a substantial quantity of invisible fumes. The only way Utility can reduce the fumes is by the use of scrubbing equipment that would cost $50,000,000 to install and would increase the retail price of generated electricity by 50 per cent while reducing the volume of fumes by only 20 per cent. Because of the expense of such equipment and its relative ineffectiveness, no other generating plants burning lignite use such equipment. The plant was located in a sparsely settled rural area, remote from the large city served by Utility. Farmer owned a farm adjacent to the plant. He had farmed the land for forty years and lived on the premises. The prevailing winds carried fumes from tIe new plant over Farmer''s land. His 1975 crop was less than half the average size of his crop over the five years immediately preceding the construction of the plant. It can be established that the fumes caused the crop reduction. Farmer''s hay fever, from which he had long suffered, became worse in 1976. Physicians advised him that the lignite fumes were affecting it and that serious lung disease would soon result unless he moved away from the plant. He did so, selling his farm at its reasonable market value, which was then $10,000 less than before the construction of the plant.', 'If Farmer asserts a claim based on nuisance against Utility for damages for personal injuries, will Farmer prevail?', 'No, because there is no practicable way for Utility to reduce the fumes.', 'No, because Utility''s acts constituted a public nuisance.', 'Yes, because Farmer''s personal injuries were within the scope of the liability imposed on Utility.', 'Yes, because the generation of electricity is an ultra-hazardous activity.', 'C', 'To support their claim of private nuisance, plaintiffs were required to show that (1) defendants interfered with the use or enjoyment of their property rights and privileges; (2) defendants'' invasion of those property interests caused plaintiffs significant harm; and (3) the invasion was either intentional and unreasonable or otherwise “actionable under the rules governing liability for negligent, reckless, or ultrahazardous conduct.” Capitol Properties Group, LLC v. 1247 Ctr St, LLC, 283 Mich. App. 422, 431-432; 770 N.W.2d 105 (2009).', 'mbe_184', 0, '77'),
('mbe_227', 'mbe', '227', '137', 'MBE-1978-83-part1', '', '78', 'In 1975, Utility constructed a new plant for the generation of electricity. The plant burns lignite, a low -grade fuel which is available in large quantities. Although the plant was constructed in accordance with the best practicable technology, the plant emits a substantial quantity of invisible fumes. The only way Utility can reduce the fumes is by the use of scrubbing equipment that would cost $50,000,000 to install and would increase the retail price of generated electricity by 50 per cent while reducing the volume of fumes by only 20 per cent. Because of the expense of such equipment and its relative ineffectiveness, no other generating plants burning lignite use such equipment. The plant was located in a sparsely settled rural area, remote from the large city served by Utility. Farmer owned a farm adjacent to the plant. He had farmed the land for forty years and lived on the premises. The prevailing winds carried fumes from tIe new plant over Farmer''s land. His 1975 crop was less than half the average size of his crop over the five years immediately preceding the construction of the plant. It can be established that the fumes caused the crop reduction. Farmer''s hay fever, from which he had long suffered, became worse in 1976. Physicians advised him that the lignite fumes were affecting it and that serious lung disease would soon result unless he moved away from the plant. He did so, selling his farm at its reasonable market value, which was then $10,000 less than before the construction of the plant.', 'If Farmer asserts a claim based on negligence against Utility for crop damage, will Farmer prevail?', 'No, because Utility was not negligent.', 'No as to 1976 crop damage, because Farmer did not mitigate damages by selling his farm in 1975.', 'Yes as to 20 per cent of his crop damage, because use of available equipment would have reduced the fumes by 20 per cent.', 'Yes, because operation of the plant constituted a nuisance.', 'A', 'industry customs and usage are relevant though not conclusive evidence on the question of product liability. We adhere to the principle that evidence of industry custom or usage, and evidence of compliance with applicable regulations, is relevant to whether the manufacturer was negligent or whether the product poses an unreasonable risk of injury, but that such evidence should not conclusively demonstrate whether the manufacturer was negligent or the product was defective', 'mbe_185', 0, '78'),
('mbe_228', 'mbe', '228', '138', 'MBE-1978-83-part1', '', '79', 'Phillips purchased a suit of thermal underwear manufactured by Makorp from synthetic materials. While he was attempting to stamp out a fire, Phillips'' thermal underwear caught fire and burned in a melting fashion up to his waist. He suffered a heart attack a half hour later. In a suit against Makorp, Phillips alleged that negligence and breach of warranty caused both the burn and the heart attack. Phillips testified to the fpregoing.', 'Dr. Jones, a physician, having listened to Phillips'' testimony, is called by Phillips and asked whether, assuming the truth of such testimony, Phillips'' subsequent heart attack could have resulted from the burns. His opinion is', 'admissible as a response to a hypothetical question', 'admissible, because the physician''s expertise enables him to judge the credibility of Phillips'' testimony', 'inadmissible, because a hypothetical question may not be based on prior testimony', 'inadmissible, because an expert''s opinion may not be based solely on information provided by lay persons', 'A', 'Expert opinion may touch on issues within a layperson''s knowledge while providing specialized context for understanding how to connect the dots, to utilize that knowledge within a medical field otherwise foreign to the jury, and to understand how these assumptions may or may not translate to that area of expertise. Fed. R. Evid. 702.', 'mbe_186', 0, '79'),
('mbe_229', 'mbe', '229', '138', 'MBE-1978-83-part1', '', '80', 'Phillips purchased a suit of thermal underwear manufactured by Makorp from synthetic materials. While he was attempting to stamp out a fire, Phillips'' thermal underwear caught fire and burned in a melting fashion up to his waist. He suffered a heart attack a half hour later. In a suit against Makorp, Phillips alleged that negligence and breach of warranty caused both the burn and the heart attack. Phillips testified to the fpregoing.', 'Dr. Black, a physician, is called by Phillips to testify that, on the basis of her examination of Phillips and blood study reports by an independent laboratory, reports which were not introduced in evidence, she believes that Phillips has a permanent disability. This testimony is', 'admissible, because such laboratory reports are business records', 'admissible if such reports are reasonably relied upon in medical practice', 'inadmissible unless Dr. Black has been shown to be qualified to conduct laboratory blood analyses', 'inadmissible, because Dr. Black''s testimony cannot be based on tests performed by persons not under her supervision', 'B', 'Because the requirements for proper medical diagnosis and treatment ordinarily are not within the common knowledge of laypersons, a former patient who wishes to pursue a medical malpractice action generally must present expert testimony to the trier of fact. Dimmock v. Lawrence & Memorial Hospital, Inc., 286 Conn. 789, 813, 945 A.2d 955 (2008). To be admissible, such testimony must comply with the requirements for reliability and relevance established in State v. Porter, 241 Conn. 57, 698 A.2d 739 (1997) (en banc), cert. denied, 523 U.S. 1058, 118 S.Ct. 1384, 140 L.Ed.2d 645 (1998).', 'mbe_187', 0, '80'),
('mbe_23', 'mbe', '23', '11', 'MBE-1972-78-part2', '', '24', 'Jack and Paul planned to hold up a bank. They drove to the bank in Jack''s car. Jack entered while Paul remained as lookout in the car. After a few moments, Paul panicked and drove off. Jack looked over the various tellers, approached one and wispered nervously, "Just hand over the cash. Don''t look around, don''t make a false move-or it''s your life." The teller looked at the fidgeting Jack, laughed, flipped him a dollar bill and said, "Go on, beat it." Flustered, Jack grabbed the dollar and left. Soon after leaving the scene, Paul was stopped by the police for speeding. Noting his nervous condition, the police asked Paul if they might search the car. Paul agreed. The search turned up heroin concealed in the lid of the trunk.', 'The prosecution''s best argument to sustain the validity of the search of Jack''s car would be that', 'the search was reasonable under the circumstances, including Paul''s nervous condition', 'the search was incident to a valid arrest', 'Paul had, under the circumstances, sufficient standing and authority to consent to the search', 'exigent circumstances, including the inherent mobility of a car, justified the search', 'C', 'The Fourth Amendment provides that “[t]he right of the people ... against unreasonable searches and seizures, shall not be violated ....” U.S. Const. Amend. IV. And it is axiomatic that a warrantless search is “ ‘per se unreasonable’ unless it falls within one of the ‘specifically established and well-delineated exceptions’ to the warrant requirement.” United States v. Simons, 206 F.3d 392, 399-400 (4th Cir. 2000) (quoting Katz v. United States, 389 U.S. 347, 357, 88 S.Ct. 507, 19 L.Ed.2d 576 (1967) ). One such exception occurs when there is valid consent to the search. Fernandez v. California, 571 U.S. 292, 298, 134 S.Ct. 1126, 188 L.Ed.2d 25 (2014). Fourth Circuit and Supreme Court precedent make clear that consent to search is valid for Fourth Amendment purposes if it is (1) “knowing and voluntary,”3 and (2) given by one with authority to consent.', 'mbe_20', 0, '24'),
('mbe_230', 'mbe', '230', '138', 'MBE-1978-83-part1', '', '81', 'Phillips purchased a suit of thermal underwear manufactured by Makorp from synthetic materials. While he was attempting to stamp out a fire, Phillips'' thermal underwear caught fire and burned in a melting fashion up to his waist. He suffered a heart attack a half hour later. In a suit against Makorp, Phillips alleged that negligence and breach of warranty caused both the burn and the heart attack. Phillips testified to the fpregoing.', 'Phillips testified that his purchase of the underwear occurred on April 17th, a fact of minor importance in the case. He stated that he could identify the date because his secretary had taken the day off to attend the first game of the baseball season and he had checked his company''s payroll records to verify the date. Makorp moves to strike the testimony as to the date. The motion should be', 'sustained, because the best evidence of the information contained in the payroll records is the records themselves', 'sustained, because Phillips'' testimony is based upon hearsay declarations contained in the payroll records', 'overruled if the judge has personal knowledge of the date on which the baseball season opened', 'overruled, because the payroll records relate to a collateral matter', 'D', 'A collateral matter is evidence solely affecting the credibility of a witness. While questioned about a collateral matter, the party cross examining the witness is bound by the witness''s answer to matters solely affecting credibility.', 'mbe_188', 0, '81'),
('mbe_231', 'mbe', '231', '139', 'MBE-1978-83-part1', '', '82', 'On March 1, Computer Programs, Inc. (CP) orally agreed with Holiday Department Store (HDS) to write a set of programs for HDS''s computer and to coordinate the programs with HDS''s billing methods. A subsequent memo, signed by both parties, provided in its entirety: HDS will pay CP $20,000 in two equal installments within one month of completion if CP is successful in shortening by one-half the processing time for the financial transactions now handled on HDS''s Zenon 747 computer; CP to complete by July 1. This agreement may be amended only by a signed writing. On June 6, CP demanded $10,000, saying the job was one-half done. After HDS denied liability, the parties orally agreed that HDS should deposit $20,000 in escrow, pending completion to the satisfaction of HDS''s computer systems manager. The escrow deposit was thereupon made. On July 5, CP completed the programs, having used an amount of time in which it could have earned $18,000 had it devoted that time to other jobs. Tests by CP and HDS''s computer systems manager then showed that the computer programs, not being perfectly coordinated with HDS''s billing methods, cut processing time by only 47%. They would, however, save HDS $12,000 a year. Further, if HDS would spend $5,000 to change its invoice preparation methods, as recommended by CP, the programs would cut processing time by a total of 58%, saving HDS another $8,000 a year. HDS''s computer systems manager refused in good faith to certify satisfactory completion. HDS requested the escrow agent to return the $20,000 and asserted that nothing was owed to CP even though HDS continued to use the programs.', 'If HDS denies liability on the ground that CP had orally agreed to coordinate with HDS''s methods of accounting, and CP seeks in litigation to bar introduction of that agreement because of the parol evidence rule, HDS''s most effective argument is that', 'the parol evidence rule does not bar the introduction of evidence for the purpose of interpreting a written agreement', 'the memorandum was not a completely integrated agreement', 'HDS detrimentally relied on the oral promise of coordination in signing the memorandum', 'the memorandum was not a partially integrated agreement', 'B', 'A completely integrated agreement is one adopted by the parties as a complete and exclusive statement of the terms of the agreement. It is contrasted with a partially integrated agreement, where the writing represents the agreement of the parties with respect to the matters stated therein but where there may be additional consistent oral terms. Id. at § 210.
Whether an agreement is integrated ultimately depends upon the intent of the parties. Stamenich v. Markovic, 462 A.2d 452, 456 (D.C.1983).', 'mbe_2337', 0, '82'),
('mbe_232', 'mbe', '232', '139', 'MBE-1978-83-part1', '', '83', 'On March 1, Computer Programs, Inc. (CP) orally agreed with Holiday Department Store (HDS) to write a set of programs for HDS''s computer and to coordinate the programs with HDS''s billing methods. A subsequent memo, signed by both parties, provided in its entirety: HDS will pay CP $20,000 in two equal installments within one month of completion if CP is successful in shortening by one-half the processing time for the financial transactions now handled on HDS''s Zenon 747 computer; CP to complete by July 1. This agreement may be amended only by a signed writing. On June 6, CP demanded $10,000, saying the job was one-half done. After HDS denied liability, the parties orally agreed that HDS should deposit $20,000 in escrow, pending completion to the satisfaction of HDS''s computer systems manager. The escrow deposit was thereupon made. On July 5, CP completed the programs, having used an amount of time in which it could have earned $18,000 had it devoted that time to other jobs. Tests by CP and HDS''s computer systems manager then showed that the computer programs, not being perfectly coordinated with HDS''s billing methods, cut processing time by only 47%. They would, however, save HDS $12,000 a year. Further, if HDS would spend $5,000 to change its invoice preparation methods, as recommended by CP, the programs would cut processing time by a total of 58%, saving HDS another $8,000 a year. HDS''s computer systems manager refused in good faith to certify satisfactory completion. HDS requested the escrow agent to return the $20,000 and asserted that nothing was owed to CP even though HDS continued to use the programs.', 'If CP in fact had half-completed the job on June 6, would it then have been entitled to $10,000 ?', 'Yes, because June 6 was within one month of completion.', 'Yes, because CP had done one-half the job.', 'No, because of a constructive condition precedent requiring at least substantial completion of the work before HDS would have a duty to pay.', 'No, because "within one month of completion" would, in these circumstances, be interpreted to mean "within one month after completion."', 'D', 'The rules of interpretation require that a court interpret a contract as a whole, reading each provision in light of all the others to find their plain meaning.', 'mbe_2338', 0, '83'),
('mbe_233', 'mbe', '233', '139', 'MBE-1978-83-part1', '', '84', 'On March 1, Computer Programs, Inc. (CP) orally agreed with Holiday Department Store (HDS) to write a set of programs for HDS''s computer and to coordinate the programs with HDS''s billing methods. A subsequent memo, signed by both parties, provided in its entirety: HDS will pay CP $20,000 in two equal installments within one month of completion if CP is successful in shortening by one-half the processing time for the financial transactions now handled on HDS''s Zenon 747 computer; CP to complete by July 1. This agreement may be amended only by a signed writing. On June 6, CP demanded $10,000, saying the job was one-half done. After HDS denied liability, the parties orally agreed that HDS should deposit $20,000 in escrow, pending completion to the satisfaction of HDS''s computer systems manager. The escrow deposit was thereupon made. On July 5, CP completed the programs, having used an amount of time in which it could have earned $18,000 had it devoted that time to other jobs. Tests by CP and HDS''s computer systems manager then showed that the computer programs, not being perfectly coordinated with HDS''s billing methods, cut processing time by only 47%. They would, however, save HDS $12,000 a year. Further, if HDS would spend $5,000 to change its invoice preparation methods, as recommended by CP, the programs would cut processing time by a total of 58%, saving HDS another $8,000 a year. HDS''s computer systems manager refused in good faith to certify satisfactory completion. HDS requested the escrow agent to return the $20,000 and asserted that nothing was owed to CP even though HDS continued to use the programs.', 'Was the escrow agreement a valid modification?', 'Yes, because it was the compromise of an honest dispute.', 'Yes, because the Statute of Frauds does not apply to subsequent oral modifications.', 'No, because it was oral.', 'No, because it was not supported by consideration.', 'A', 'For a valid modification to exist, there must be mutual assent *822 to the meaning and conditions of the modification and the parties must assent to the same thing in the same sense.... Modification of a contract may be inferred from the attendant circumstances and conduct of the parties.” (Citation omitted; internal quotation marks omitted.) Tsionis v. Martens, 116 Conn.App. 568, 577, 976 A.2d 53 (2009). “A modification of an agreement must be supported by valid consideration and requires a party to do, or promise to do, something further than, or different from, that which he is already bound to do.” (Internal quotation marks omitted.) Christian v. Gouldin, supra, 72 Conn.App. at 23, 804 A.2d 865.', 'mbe_2339', 0, '84'),
('mbe_234', 'mbe', '234', '139', 'MBE-1978-83-part1', '', '85', 'On March 1, Computer Programs, Inc. (CP) orally agreed with Holiday Department Store (HDS) to write a set of programs for HDS''s computer and to coordinate the programs with HDS''s billing methods. A subsequent memo, signed by both parties, provided in its entirety: HDS will pay CP $20,000 in two equal installments within one month of completion if CP is successful in shortening by one-half the processing time for the financial transactions now handled on HDS''s Zenon 747 computer; CP to complete by July 1. This agreement may be amended only by a signed writing. On June 6, CP demanded $10,000, saying the job was one-half done. After HDS denied liability, the parties orally agreed that HDS should deposit $20,000 in escrow, pending completion to the satisfaction of HDS''s computer systems manager. The escrow deposit was thereupon made. On July 5, CP completed the programs, having used an amount of time in which it could have earned $18,000 had it devoted that time to other jobs. Tests by CP and HDS''s computer systems manager then showed that the computer programs, not being perfectly coordinated with HDS''s billing methods, cut processing time by only 47%. They would, however, save HDS $12,000 a year. Further, if HDS would spend $5,000 to change its invoice preparation methods, as recommended by CP, the programs would cut processing time by a total of 58%, saving HDS another $8,000 a year. HDS''s computer systems manager refused in good faith to certify satisfactory completion. HDS requested the escrow agent to return the $20,000 and asserted that nothing was owed to CP even though HDS continued to use the programs.', 'Assume for this question only that the programs completed on July 5 had cut processing time by one-half for all of HDS''s financial transactions. Is HDS entitled to renounce the contract because of Cl"s delay in completion?', 'Yes, because "CP to complete by July 1" is an express condition,', 'Yes, because the doctrine of substantial performance does not apply to commercial contracts.', 'No, because both parties manifested an understanding that time was not of the essence.', 'No, because the contract did not contain a liquidated damages clause dealing with delay in completion.', 'C', 'Ordinarily, in contracts where time is not of the essence, a failure to complete the work within the specified time will not terminate the contract, but it will subject the contractor to damages for the delay. See 13 Am.Jur.2d Building and Construction Contracts s 47.', 'mbe_2340', 0, '85'),
('mbe_235', 'mbe', '235', '139', 'MBE-1978-83-part1', '', '86', 'On March 1, Computer Programs, Inc. (CP) orally agreed with Holiday Department Store (HDS) to write a set of programs for HDS''s computer and to coordinate the programs with HDS''s billing methods. A subsequent memo, signed by both parties, provided in its entirety: HDS will pay CP $20,000 in two equal installments within one month of completion if CP is successful in shortening by one-half the processing time for the financial transactions now handled on HDS''s Zenon 747 computer; CP to complete by July 1. This agreement may be amended only by a signed writing. On June 6, CP demanded $10,000, saying the job was one-half done. After HDS denied liability, the parties orally agreed that HDS should deposit $20,000 in escrow, pending completion to the satisfaction of HDS''s computer systems manager. The escrow deposit was thereupon made. On July 5, CP completed the programs, having used an amount of time in which it could have earned $18,000 had it devoted that time to other jobs. Tests by CP and HDS''s computer systems manager then showed that the computer programs, not being perfectly coordinated with HDS''s billing methods, cut processing time by only 47%. They would, however, save HDS $12,000 a year. Further, if HDS would spend $5,000 to change its invoice preparation methods, as recommended by CP, the programs would cut processing time by a total of 58%, saving HDS another $8,000 a year. HDS''s computer systems manager refused in good faith to certify satisfactory completion. HDS requested the escrow agent to return the $20,000 and asserted that nothing was owed to CP even though HDS continued to use the programs.', 'Assume for this question only that CP''s delay in completion did not give HDS the right to renounce the contract and that the parties'' escrow agreement was enforceable. Is CP entitled to recover damages for breach of the contract?', 'Yes, because CP had substantially performed.', 'Yes, because the programs would save HDS $12,000 a year.', 'No, because shortening the processing time by one-half was an express condition subsequent.', 'No, because HDS''s computer systems manager did not certify satisfactory completion of the programs.', 'D', 'A condition, which follows liability on a contract but provides for a contingency which, if it occurs, will defeat a contract already in effect, is a condition subsequent. See Nichols Bros. Investments v. Rector–Phillips–Morse, Inc. and Bill Haupt, 33 Ark.App. 47, 801 S.W.2d 308 (1990) (citing 17 Am.Jur.2d Contracts § 323 (1964)).', 'mbe_2341', 0, '86'),
('mbe_236', 'mbe', '236', '139', 'MBE-1978-83-part1', '', '87', 'On March 1, Computer Programs, Inc. (CP) orally agreed with Holiday Department Store (HDS) to write a set of programs for HDS''s computer and to coordinate the programs with HDS''s billing methods. A subsequent memo, signed by both parties, provided in its entirety: HDS will pay CP $20,000 in two equal installments within one month of completion if CP is successful in shortening by one-half the processing time for the financial transactions now handled on HDS''s Zenon 747 computer; CP to complete by July 1. This agreement may be amended only by a signed writing. On June 6, CP demanded $10,000, saying the job was one-half done. After HDS denied liability, the parties orally agreed that HDS should deposit $20,000 in escrow, pending completion to the satisfaction of HDS''s computer systems manager. The escrow deposit was thereupon made. On July 5, CP completed the programs, having used an amount of time in which it could have earned $18,000 had it devoted that time to other jobs. Tests by CP and HDS''s computer systems manager then showed that the computer programs, not being perfectly coordinated with HDS''s billing methods, cut processing time by only 47%. They would, however, save HDS $12,000 a year. Further, if HDS would spend $5,000 to change its invoice preparation methods, as recommended by CP, the programs would cut processing time by a total of 58%, saving HDS another $8,000 a year. HDS''s computer systems manager refused in good faith to certify satisfactory completion. HDS requested the escrow agent to return the $20,000 and asserted that nothing was owed to CP even though HDS continued to use the programs.', 'Assume for this question only that CP was in breach of contract because of its four-day delay in completion and that an express condition precedent to HDS''s duty to pay the contract price has failed. Can CP nevertheless recover the reasonable value of its services?', 'Yes, because continued use of the programs by HDS would save at least $12,000 a year.', 'Yes, because HDS was continuing to use programs created by CP for which, as HDS knew, CP expected to be paid.', 'No, because failure of an express condition precedent excused HDS from any duty to compensate CP.', 'No, because such a recovery by CP would be inconsistent with a claim by HOS against CP for breach of contract.', 'B', 'failure to satisfy a condition precedent ordinarily is considered an affirmative defense.', 'mbe_2342', 0, '87'),
('mbe_237', 'mbe', '237', '140', 'MBE-1978-83-part1', '', '88', '', 'Police Officer stopped Dexter for speeding late one night. Noting that Dexter was nervous, he ordered him from the car and placed him under arrest for speeding. By state law, Police Officer was empowered to arrest Dexter and take him to the nearest police station for booking. He searched Dexter''s person and discovered a package of heroin in his jacket pocket. Dexter is charged with possession of heroin. At trial, Dexter''s motion to prevent introduction of the heroin into evidence, on the ground that the search violated his federal constitutional rights, will most probably be', 'denied, because the search was incident to a valid custodial arrest', 'denied, because police officer acted under both a reasonable suspicion and a legitimate concern for his own personal safety', 'granted, because there was no reasonable or proper basis upon which to justify conducting the search', 'granted if Police Officer was not in fear and had no suspicion that Dexter was transporting narcotics', 'A', 'Warrantless searches incident to arrest are justified based on “interests in officer safety and evidence preservation that are typically implicated in arrest situations.” Arizona v. Gant, 556 U.S. 332, 338, 129 S.Ct. 1710, 173 L.Ed.2d 485 (2009). “[A] search incident to arrest may only include ‘the arrestee''s person and the area ‘within his immediate control’—construing that phrase to mean the area from within which he might gain possession of a weapon or destructible evidence.’ ” Id. at 339, 129 S.Ct. 1710 (citation omitted).  This limitation on the search-incident-to-arrest exception to the warrant requirement “ensures that the scope of a search incident to arrest is commensurate with its purposes of protecting arresting officers and safeguarding any evidence of the offense of arrest that an arrestee might conceal or destroy.” Id. Thus, “[w]here the item to be searched is not within reasonable reach of the person arrested, the rationale for application of this exception is absent.” United States v. Perea, 986 F.2d 633, 643 (2d Cir.1993). Therefore, “[t]o determine whether a warrantless search incident to an arrest exceeded constitutional bounds, a court must ask: was the area in question, at the time it was searched, conceivably accessible to the arrestee—assuming that he was neither an acrobat [nor] a Houdini?” United States v. Lyons, 706 F.2d 321, 330 (D.C.Cir.1983) (internal quotation marks and citations omitted).', 'mbe_189', 0, '88'),
('mbe_238', 'mbe', '238', '141', 'MBE-1978-83-part1', '', '89', '', 'Dunn was arrested moments after a forcible rape and was prosecuted for it. The victim testified she tore the assailant''s shirt. Dunn did not testify. In jury argument, Dunn''s counsel urged that the state''s failure to offer in evidence the shirt Dunn was wearing when arrested indicated that the evidence would be unfavorable to the state''s case. In his closing argument, the prosecutor said, "If the defense had thought the clothing would show anything, they could have brought it in as evidence themselves." The prosecutor''s argument is', 'proper as rebuttal to the inference that the evidence would be unfavorable to the prosecution', 'proper as a comment on Dunn''s failure to testify', 'improper as an argument going beyond the evidence in the case', 'improper as a comment on Dunn''s failure to testify', 'A', 'Rebuttal evidence is within a trial court''s sound discretion and will not be disturbed on appeal unless there is an abuse of discretion. State v. Booze, 334 Md. 64, 68 [637 A.2d 1214] (1994).  Rebuttal evidence is admissible when it “ ‘explains, or is a direct reply to, or a contradiction of, any new matter that has been brought into the case by the accused.’ ” Id. at 70 [637 A.2d 1214] (citations omitted).', 'mbe_2625', 0, '89'),
('mbe_239', 'mbe', '239', '142', 'MBE-1978-83-part1', '', '90', '', 'Donna was arrested and taken to police headquarters, where she was given her Miranda warnings. Donna indicated that she wished to telephone her lawyer and was told that she could do so after her fingerprints had been taken. While being fingerprinted, however, Donna blurted out, "Paying a lawyer is a waste of money because I know you have me." At trial, Donna''s motion to prevent the introduction of the statement she made while being fingerprinted will most probably be', 'granted, because Donna''s request to contact her attorney by telephone was reasonable and should have been granted immediately', 'granted because of the "fruit of the poisonous tree" doctrine', 'denied, because the statements were volunteered and not the result of interrogation', 'denied, because fingerprinting is not a critical stage of the proceeding requiring the assistance of counsel', 'C', 'For there to be a voluntary waiver of Miranda rights, the State must demonstrate: “1) that the waiver was the result of a free choice on the part of the defendant and not the product of intimidation, coercion, or deception; and 2) the waiver was made with a full awareness of the nature of the right being abandoned and the consequences of the abandonment.” Barger v. State, 923 So. 2d 597, 601 (Fla. 5th DCA 2006) (citing Moran v. Burbine, 475 U.S. 412, 106 S.Ct. 1135, 89 L.Ed.2d 410 (1986)). “Only if the totality of the circumstances surrounding the interrogation reveals both an uncoerced choice and the requisite level of comprehension may a court properly conclude that Miranda rights have been waived.” Id. (citing *289 Globe v. State, 877 So. 2d 663 (Fla. 2004)). When a defendant is questioned concerning the waiver of Miranda rights, if he or she gives an ambiguous or equivocal answer, then a law enforcement officer is “required to inquire further before initiating further questioning.” Madeus v. State, 244 So. 3d 1095, 1096 (Fla. 4th DCA 2018).', 'mbe_190', 0, '90'),
('mbe_24', 'mbe', '24', '12', 'MBE-1972-78-part2', '', '25', '', 'Pace sues Def Company for injuries suffered when Pace''s car collided with Def Company''s truck. Def''s general manager prepared a report of the accident at the request of the company''s attorney in preparation for the trial, and delivered the report to the attorney. Pace demands that the report be produced. Will production of the report be required?', 'Yes, because business reports are not generally privileged.', 'No, because it is a privileged communication from client to the attorney.', 'No, because such reports contain hearsay.', 'No, because such reports are self-serving.', 'B', 'The attorney-client privilege protects communications made in confidence by a client and a client''s employees to an attorney, acting as an attorney, for the purpose of obtaining legal advice. Sandra T.E. v. South Berwyn School Dist. 100, 600 F.3d 612, 618 (7th Cir.2010). The analysis is “(1) whether ‘legal advice of any kind [was] sought ... from a professional legal adviser in his capacity as such’; and (2) whether the communication was ‘relat[ed] to that purpose’ and ‘made in confidence ... by the client.’ ” Id. (citation omitted). “[T]he attorney-client privilege protects not only the attorney-client relationship in imminent or ongoing litigation but also the broader attorney-client relationship outside the litigation context.” Id. at 621.', 'mbe_21', 0, '25'),
('mbe_240', 'mbe', '240', '143', 'MBE-1978-83-part1', '', '91', 'Barnes was hired as an assistant professor of mathematics at Reardon State College and is now in his third consecutive one-year contract. Under state law he cannot acquire tenure until after five consecutive annual contracts. In his third year, Barnes was notified that he was not being re-hired for the following year. Applicable state law and college rules did not require either a statement of reasons or a hear ing, and in fact neither was offered to Barnes.', 'Which of the following, if established, sets forth the strongest constitutional argument Barnes could make to compel the college to furnish him a statement of reasons for the failure to rehire him and an opportunity for a hearing?', 'There is no evidence that tenured teachers are any more qualified than he is.', 'He leased a home in reliance on an oral promise of reemployment by the college president.', 'He was the only teacher at the college whose contract was not renewed that year.', 'In the expectation of remaining at the college, he had just moved his elderly parents to the town in which the college is located.', 'B', 'A property right exists where state or local laws, charters, ordinances, policies, contracts, or agreements provide that the employee will only be disciplined or dismissed for “cause,” “just cause,” “proper cause,” “sufficient cause,” or some similar language. Without an express grant of a property interest, even public employees are generally considered at will employees, with no vested property interest in their employment.Due Process
If it is determined that an employee has a property right in continued employment, the employer generally must provide what is known as a “Loudermill” hearing prior to termination. In providing guidance, the Supreme Court explained that due process requires “a very limited hearing prior to termination, to be followed by a more comprehensive post-termination hearing.” Cleveland Bd. of Educ. v. Loudermill, 470 U.S. 532 (1985).', 'mbe_191', 0, '91'),
('mbe_241', 'mbe', '241', '143', 'MBE-1978-83-part1', '', '92', 'Barnes was hired as an assistant professor of mathematics at Reardon State College and is now in his third consecutive one-year contract. Under state law he cannot acquire tenure until after five consecutive annual contracts. In his third year, Barnes was notified that he was not being re-hired for the following year. Applicable state law and college rules did not require either a statement of reasons or a hear ing, and in fact neither was offered to Barnes.', 'Which of the following, if established, most strongly supports the college in refusing to give Barnes a statement of reasons or an opportunity for a hearing?', 'Barnes ''s academic performance had been substandard.', 'A speech he made that was critical of administration policies violated a college regulation concerning teacher behavior.', 'Barnes worked at the college for less than five years.', 'Barnes could be replaced with a more competent teacher.', 'C', 'Rebuttal evidence is proper when it directly or indirectly explains, counteracts, repels, or disproves a defendant''s evidence.', 'mbe_192', 0, '92'),
('mbe_242', 'mbe', '242', '144', 'MBE-1978-83-part1', '', '93', '', 'National regulation of predatory wild animals on federal lands is most likely', 'constitutional, because the protection of wild animals is important to the general welfare', 'constitutional, because Congress has authority to make regulations respecting federal property', 'unconstitutional, because wild animals as defined by state common law are not federal property', 'unconstitutional, because regulation and control of wild animals is retained by the states under the Tenth Amendment', 'B', 'It is the Property Clause, for instance, that provides *540 the basis for governing the Territories of the United States. Hooven & Allison Co. v. Evatt, 324 U.S. 2, 673-674, 65 S.Ct. 870, 880-81, 89 L.Ed. 1252 (1945); Balzac v. Porto Rico, 258 U.S. 298, 305, 42 S.Ct. 343, 345, 66 L.Ed. 627 (1922); Dorr v. United States, 195 U.S. 138, 149, 24 S.Ct. 808, 813, 49 L.Ed. 128 (1904); United States v. Gratiot, supra, 14 Pet., at 537; Sere v. Pitot, 6 Cranch 332, 336-337, 3 L.Ed. 240 (1810). See also Vermilya-Brown Co. v. Connell, 335 U.S. 377, 381, 69 S.Ct. 140, 142, 93 L.Ed. 76 (1948). And even over public land within the States, “(t)he general government doubtless has a power over its own property analogous to the police power of the several states, and the extent to which it may go in the exercise of such power is measured by the exigencies of the particular case.” Camfield v. United States, supra, 167 U.S., at 525, 17 S.Ct., at 867. We have noted, for example, that the Property Clause gives Congress the power over the public lands “to control their occupancy and use, to protect them from trespass and injury, and to prescribe the conditions upon which others may obtain rights in them . . . .” Utah Power & Light Co. v. United States, 243 U.S. 389, 405, 37 S.Ct. 387, 389, 61 L.Ed. 791 (1917). And we have approved legislation respecting the public lands “(i)f it be found to be necessary, for the protection of the public or of intending settlers (on the public lands).” Camfield v. United States, supra, 167 U.S., at 525, 17 S.Ct., at 867. In short, Congress exercises the powers both of a proprietor and of a legislature over the public domain. Alabama v. Texas, supra, 347 U.S., at 273, 74 S.Ct., at 481; Sinclair v. United States, 279 U.S. 263, 297, 49 S.Ct. 268, 273, 73 L.Ed. 692 (1929); United States v. Midwest Oil Co., 236 U.S. 459, 474, 35 S.Ct. 309, 313, 59 L.Ed. 673 (1915). Although the Property Clause does not authorize “an exercise of a general control over public policy in a State,” it does permit “an exercise of the complete power which Congress has over particular public property entrusted to it.” United States v. San Francisco, supra, 310 U.S., at 30, 60 S.Ct., at 757. (footnote omitted). In our view, the “complete power” that *541 Congress has over public lands necessarily includes the power to regulate and protect the wildlife living there.', 'mbe_193', 0, '93'),
('mbe_243', 'mbe', '243', '145', 'MBE-1978-83-part1', '', '94', '', 'By her validly executed will, Sallie devised a certain tract of land to her son, Ben, for his life with remainder to such of Ben''s children as should be living at his death, "Provided, however, that no such child of Ben shall mortgage or sell, or attempt to mortgage or sell, his or her interest in the property prior to attaining 25 years of age: and, if any such child of Ben shall violate this provision, then upon such violation his or her interest shall pass to and become the property of the remaining children of Ben then living, share and share alike." Sallie''s will included an identical provision for each of her four other children concerning four other tracts of land. The residuary clause of the will gave the residuary estate to Sallie''s five children equally. Sallie died and was survived by the five children named in her will and by eleven grandchildren. Several additional grandchildren have since been born. In an action for a declaration of rights, it was claimed that the attempted gifts to Sallie''s grandchildren were entirely void and that the interests following the life estates to Sallie''s children passed to the children absolutely by the residuary clause. Assuming that the action was properly brought with all necessary parties and with a guardian ad item appointed to represent the interests of unborn and infant grandchildren, the decision should be that', 'the attempted gifts to grandchildren are void under the Rule Against Perpetuities', 'the attempted gifts to grandchildren are void as unlawful restraints on alienation', 'the provisions concerning grandchildren are valid and will be upheld according to their terms', 'even if the provisions against sale or mortgage by the grandchildren are void, the remainders to grandchildren are otherwise valid and will be given effect', 'D', 'If a remainder interest is in an ascertainable person, and no condition precedent exists other than the termination of prior estates, then it is a vested remainder.', 'mbe_194', 0, '94'),
('mbe_244', 'mbe', '244', '146', 'MBE-1978-83-part1', '', '95', '', 'Seth was an elderly widower who lived alone on a small farm which he owned. Except for the farm, including the house and its furnishings, and the usual items of personal clothing and similar things, Seth owned substantially no property. Under proper management, the farm was capable of producing an adequate family income. Because of the usual deterioration accompanying old age, Seth was unable to do farm work or even to provide for his own personal needs. Seth entered into an oral contract with his nephew, Jim, by which Seth agreed to convey the farm to Jim and Jim agreed to move into the house with Seth, operate the farm, and take care of Seth for the rest of his life. The oral contract was silent as to when the land was to be conveyed. Jim, who lived about fifty miles away where he was operating a small business of his own, terminated his business and moved in with Seth. With the assistance of his wife, Jim gave Seth excellent care until Seth died intestate about five years after the date of the contract. In his final years Seth was confined to his bed and required much personal service of an intimate and arduous sort. Seth was survived by his only son, Sol, who was also Seth''s sole heir and next of kin. Sol resided in a distant city and gave his father no attention in his father''s final years. Sol showed up for Seth''s funeral and demanded that Jim vacate the farm immediately. Upon Jim''s refusal to do so, Sol brought an appropriate action for possession. Jim answered by way of a counterclaim to establish Jim''s right to possession and title to the farm. If the court ''s decision is in favor of Jim, it will be because', 'the land is located in a state where the Statute of Frauds will not be applied if there has been such part performance as will result in an irreparable hardship if the contract is not performed', 'the land is located in a state where the Statute of Frauds will not be applied if there has been such part performance that is by its very nature unequivocally referable to the contract', 'Sol is precluded by the "clean hands" doctrine from enforcing his claim against Jim', 'the blood relationship of uncle-nephew is sufficient to remove the necessity for any writing to satisfy the Statute of Frauds', 'A', 'The part -performance exception to the Statute of Frauds is a matter in avoidance of the affirmative defense of the Statute of Frauds, and, therefore, once a party makes a prima facie showing that a contract meets the criteria of the provision containing such exception, the opposing party bears the burden of proving the applicability of the exception.', 'mbe_195', 0, '95'),
('mbe_245', 'mbe', '245', '147', 'MBE-1978-83-part1', '', '96', '', 'The following events took place in a state that does not recognize the common-law marriage. The state does recognize the common-law estate of tenancy by the entirety and has no statute on the subject. Wade Sloan and Mary Isaacs, who were never formally married, lived together over a sevenyear period. During this time Mary identified herself as "Mrs. Sloan" with the knowledge and consent of Wade, Wade and Mary maintained several charge accounts at retail stores under the names "Mr. and Mrs. Wade Sloan," and they filed joint income tax returns as Mr. and Mrs. Sloan. Within this period Wade decided to buy a home. The deed was in proper form and identified the grantees as "Wade Sloan and Mary Sloan, his wife, and their heirs and assigns forever as tenants by the entirety." Wade made a down payment of $10,000, and gave a note and mortgage for the unpaid balance. Both Wade and Mary signed the note and mortgage for the unpaid balance. Both Wade and Mary signed the note and mortgage as husband and wife. Wade made the monthly payments as they become due until he and Mary had a disagreement and he abandoned her and the house. Mary then made the payments for three months. She then brought an action against Wade for partition of the land in question. ''The prayer for partition should be', 'denied, because a tenant by the entirety has no right to partition', 'denied, because Wade has absolute title to the property', 'granted, because the tenancy by the entirety that was created by the deed was severed when Wade abandoned Mary', 'granted, because the estate created by the deed was not a tenancy by the entirety', 'D', 'A tenancy by the entirety is available only to husband and wife and is essentially a joint tenancy modified by the common law theory that a husband and wife are one person. Survivorship is the predominant and distinguishing feature of both a joint tenancy and a tenancy by the entirety. Dorf v. Tuscarora Pipe Line Co., Ltd., 48 N.J.Super. 26, 32, 136 A.2d 778 (App.Div.1957).', 'mbe_196', 0, '96'),
('mbe_246', 'mbe', '246', '148', 'MBE-1978-83-part1', '', '97', 'Sand Company operated an installation for distributing sand and gravel. The installation was adjacent to a residential area. On Sand''s grounds there was a chute with polished metal sides for loading sand and gravel into trucks. The trucks being loaded stopped on the public street below the chute. After closing hours, a plywood screen was placed in the chute and the ladder used for inspection was removed to another section of the installation. For several months, however, a number of children, 8 to 10 years of age, had been playing on Sand''s property and the adjoining street after closing hours. The children found the ladder and also discovered that they could remove the plywood screen from the chute and slide down to the street below. Sand knew of this activity. One evening, the children were using the chute as a play device. As an automobile driven by Commuter approached the chute, Ladd, an 8-year-old boy, slid down just in front of the automobile. Commuter applied her brakes, but they suddenly failed, and she hit and injured Ladd. Commuter saw the child in time to have avoided hitting him if her brakes had worked properly. Two days previously, Commuter had taken her car to Garage to have her brakes inspected. Garage inspected the brakes and told her that the brakes were in perfect working order. Claims were asserted on behalf of Ladd by his proper legal representative against Sand, Commuter, and Garage.', 'On Ladd''s claim against Sand, will Ladd prevail?', 'Yes, if Sand could have effectively secured the chute at moderate cost.', 'Yes, because Sand is strictly liable for harm resulting from an artificial condition on its property.', 'No, if Commuter had the last clear chance to avoid the injury.', 'No, because Ladd was a trespasser.', 'A', 'The last clear chance doctrine, which doctrine is a plaintiff''s defense to a defendant''s allegation that the plaintiff was contributorily negligent, contemplates two or more parties who are both negligent, but one is in helpless peril unable to avoid the imminent danger; the doctrine imposes liability on the party who is aware of the danger and is in control of the instrumentality and thus in a position to avoid the impending danger.', 'mbe_197', 0, '97'),
('mbe_247', 'mbe', '247', '148', 'MBE-1978-83-part1', '', '98', 'Sand Company operated an installation for distributing sand and gravel. The installation was adjacent to a residential area. On Sand''s grounds there was a chute with polished metal sides for loading sand and gravel into trucks. The trucks being loaded stopped on the public street below the chute. After closing hours, a plywood screen was placed in the chute and the ladder used for inspection was removed to another section of the installation. For several months, however, a number of children, 8 to 10 years of age, had been playing on Sand''s property and the adjoining street after closing hours. The children found the ladder and also discovered that they could remove the plywood screen from the chute and slide down to the street below. Sand knew of this activity. One evening, the children were using the chute as a play device. As an automobile driven by Commuter approached the chute, Ladd, an 8-year-old boy, slid down just in front of the automobile. Commuter applied her brakes, but they suddenly failed, and she hit and injured Ladd. Commuter saw the child in time to have avoided hitting him if her brakes had worked properly. Two days previously, Commuter had taken her car to Garage to have her brakes inspected. Garage inspected the brakes and told her that the brakes were in perfect working order. Claims were asserted on behalf of Ladd by his proper legal representative against Sand, Commuter, and Garage.', 'On Ladd''s claim against Commuter, Commuter''s best defense is that', 'her conduct was not the cause in fact of the harm', 'she used reasonable care in the maintenance of her brakes', 'she could not reasonably foresee Ladd''s presence in the street', 'she did not act willfully and wantonly', 'B', 'The “ordinary care” standard is generally defined as that which an ordinarily prudent person, exercising ordinary care, would have done under the same circumstances.', 'mbe_198', 0, '98'),
('mbe_248', 'mbe', '248', '148', 'MBE-1978-83-part1', '', '99', 'Sand Company operated an installation for distributing sand and gravel. The installation was adjacent to a residential area. On Sand''s grounds there was a chute with polished metal sides for loading sand and gravel into trucks. The trucks being loaded stopped on the public street below the chute. After closing hours, a plywood screen was placed in the chute and the ladder used for inspection was removed to another section of the installation. For several months, however, a number of children, 8 to 10 years of age, had been playing on Sand''s property and the adjoining street after closing hours. The children found the ladder and also discovered that they could remove the plywood screen from the chute and slide down to the street below. Sand knew of this activity. One evening, the children were using the chute as a play device. As an automobile driven by Commuter approached the chute, Ladd, an 8-year-old boy, slid down just in front of the automobile. Commuter applied her brakes, but they suddenly failed, and she hit and injured Ladd. Commuter saw the child in time to have avoided hitting him if her brakes had worked properly. Two days previously, Commuter had taken her car to Garage to have her brakes inspected. Garage inspected the brakes and told her that the brakes were in perfect working order. Claims were asserted on behalf of Ladd by his proper legal representative against Sand, Commuter, and Garage.', 'On Ladd''s claim against Garage, will Ladd prevail?', 'Yes, because Garage is strictly liable in tort.', 'Yes, if Garage was negligent in inspecting Commuter''s brakes.', 'No, if Ladd was in the legal category of a bystander.', 'No, because Sand ''s conduct was an independent and superseding cause.', 'B', 'the essential elements of negligent inspection are the same as general negligence, i.e., the existence of a legal duty, breach of that duty, damages, and a causal connection between the defendant''s conduct and the plaintiff''s injury.', 'mbe_199', 0, '99'),
('mbe_249', 'mbe', '249', '149', 'MBE-1978-83-part1', '', '100', '', 'Driving down a dark road, Defendant accidentally ran over a man. Defendant stopped and found that the victim was dead. Defendant, fearing that he might be held responsible, cook the victim''s wallet, which contained a substantial amount of money. He removed the identification papers and put the wallet and money back into the victim''s pocket. Defendant is not guilty of', 'larceny, because he took the papers only to prevent identification and not for his own use', 'larceny, because he did not take anything from a living victim', 'robbery, because he did not take the papers by means of force or putting in fear', 'robbery, because he did nor take anything of monetary value', 'C', '“[r]obbery is ‘the felonious taking and carrying away of the personal property of another from his person by the use of violence or by putting in fear.’ ” Metheny, 359 Md. at 605, 755 A.2d 1088 (citation omitted); see Ball v. State, 347 Md. 156, 184, 699 A.2d 1170 (1997), cert. denied, 522 U.S. 1082, 118 S.Ct. 866, 139 L.Ed.2d 763 (1998). Put another way, robbery is a larceny or theft accompanied by violence or putting in fear. West v. State, 312 Md. 197, 202, 539 A.2d 231 (1988).', 'mbe_2626', 0, '100'),
('mbe_25', 'mbe', '25', '13', 'MBE-1972-78-part2', '', '26', '', 'The following facts concern a tract of land in a state which follows general United States law. Each instrument is in proper form, recorded, marital property rights were waived when necessary, and each person named was adult and competent at the time of the named transaction. 1. In 1940 Oleg, the owner, conveyed his interest in fee simple "to my brothers Bob and Bill, their heirs and assigns as joint tenants with right of survivorship." 2. In 1950 Bob died, devising his interest to his only child, "Charles, for life, and then to Charles''s son, Sam, for life, and then to Sam''s children, their heirs and assigns." 3. In 1970 Bill died, devising his interest "to my friend, Frank, his heirs and assigns." 4. In 1972 Frank conveyed by quitclaim deed "to Paul, his heirs and assigns whatever right, title and interest I own." Paul has never married. Paul has contracted to convey marketable record title in the land to Patrick. Can Paul do so?', 'Yes, without joinder of any other person in the conveyance.', 'Yes, if Charles, Sam, and Sam''s only child (Gene, aged 25) will join in the conveyance.', 'No, regardless of who joins in the conveyance, because Sam may have additional children whose interests cannot be defeated.', 'No, regardless of who joins in the conveyance, because a title acquired by quitclaim deed is impliedly unmerchantable.', 'A', 'In the instant case the husband had been dead for several months at the time the wife joined in the conveyance, and he could not, therefore, have consented to her subsequent execution of the same. When he died on April 1, 1948, he was the absolute owner of the land in question, because of the invalidity of his former deed of conveyance thereof without the signature of his wife, and, therefore, the rights of the complainants in the present case had intervented long prior to her signing and acknowledging the deed. This fact distinguishes Howell v. Hill from the case at bar. Even though the wife of John Brassel may have been willing that the homestead be sold on October 24, 1942, the time at which the contemporaneous assent of the husband and wife must exist is the time when the deed is finally executed by her joinder therein. In other words, the deed is void as to the owner of the homestead who has executed a deed to the same until the other spouse joins therein with the contemporaneous assent of both.  Consequently, there can be no joinder by the wife in the execution of a conveyance of the homestead by the husband unless she executes the conveyance during his lifetime, and with his consent.', 'mbe_22', 0, '26'),
('mbe_250', 'mbe', '250', '150', 'MBE-1978-83-part1', '', '101', '', 'Al and Bill are identical twins. Al, angry at David, said, "You''d better stay out of my way. The next time I find you around here, I''ll beat you up." Two days later, while in the neighborhood, David saw Bill coming toward him. As Bill came up to David, Bill raised his hand. Thinking Bill was Al and fearing bodily harm, David struck Bill. If Bill asserts a claim against David and David relies on the privilege of self-defense, David will', 'not prevail, because Bill was not an aggressor', 'not prevail unless Bill intended his gesture as a threat', 'prevail if David honestly believed that Bill would attack him', 'prevail only if a reasonable person under the circumstances would have believed that Bill would attack him', 'D', '“[T]he questions of the reasonableness of a defendant''s belief that self-defense is necessary and of the reasonableness of the actions taken in self-defense do not call for an evaluation of the defendant''s subjective state of mind, but for an objective evaluation of the defendant''s assertedly defensive acts. California law expresses the criterion for this evaluation in the objective terms of whether a reasonable person, as opposed to the defendant, would have believed and acted as the defendant did. We hold that expert testimony about a defendant''s state of mind is not relevant to the reasonableness of the defendant''s self-defense.” (People v. Aris, supra, 215 Cal.App.3d at p. 1196, 264 Cal.Rptr. 167, italics in original.)', 'mbe_200', 0, '101'),
('mbe_251', 'mbe', '251', '151', 'MBE-1978-83-part1', '', '102', 'Section 1 of the Vehicle Code of State makes it illegal to cross a street in a central business district other than at a designated crosswalk. Section 2 of the Code prohibits parking any motor vehicle so that it blocks any part of a designated crosswalk. Ped wanted to cross Main Street in the central business district of City, located in State, but a truck parked by Trucker was blocking the designated crosswalk. Ped stepped out into Main Street and carefully walked around the back of the truck. Ped was struck by a motor vehicle negligently operated by Driver.', 'If Ped asserts a claim against Driver, Ped''s failure to be in the crosswalk will have which of the following effects?', 'It is not relevant in determining the rights of Ped.', 'It may be considered by the trier of the facts on the issue of Driver''s liability.', 'It will bar Ped''s recovery unless Driver saw Ped in time to avoid the impact.', 'It will bar Ped''s recovery as a matter of law.', 'B', '“Contributory negligence” is defined as conduct on the part of the plaintiff which falls below the standard to which he should conform for his own protection and which is the legally contributing cause, cooperating with the negligence of the defendant, in bringing about the plaintiff''s harm.', 'mbe_201', 0, '102'),
('mbe_252', 'mbe', '252', '151', 'MBE-1978-83-part1', '', '103', 'Section 1 of the Vehicle Code of State makes it illegal to cross a street in a central business district other than at a designated crosswalk. Section 2 of the Code prohibits parking any motor vehicle so that it blocks any part of a designated crosswalk. Ped wanted to cross Main Street in the central business district of City, located in State, but a truck parked by Trucker was blocking the designated crosswalk. Ped stepped out into Main Street and carefully walked around the back of the truck. Ped was struck by a motor vehicle negligently operated by Driver.', 'If Ped asserts a claim against Trucker, the most likely result is that Ped will', 'prevail, because Trucker''s violation of a state statute makes him strictly liable for all injuries caused thereby', 'prevail, because the probable purpose of Section 2 of the Vehicle Code of State was to safeguard pedestrians in using crosswalks', 'not prevail, because Ped assumed the risk of injury when he crossed the street outside the crosswalk', 'not prevail, because Driver''s conduct was the actual cause of Ped''s harm', 'B', 'A statute''s violation is deemed negligence per se if the claimed injury (a) was caused by the law''s violation, (b) was of the type intended to be prevented by the statute, and (c) the injured party was a member of the class meant to be protected by the statute.', 'mbe_202', 0, '103'),
('mbe_253', 'mbe', '253', '152', 'MBE-1978-83-part1', '', '104', '', 'Suspecting that students in a dormitory were using narcotics, the president of a private college arranged for local police to place concealed microphones in several suites of the dormitory. Using these microphones, the college security officers recorded a conversation in which Green, a student, offered to sell marijuana to another student. The tape was turned over to the local police, who played it for a local judge. The judge issued a warrant to search Green''s room. The room was searched by police, and marijuana was discovered. Green is charged with unlawful possession of narcotics. At trial, Green''s motion to prevent the introduction of the marijuana into evidence will most probably be', 'denied, because the college president, in loco parentis, had the responsibility of preventing unlawful activity by students under the president''s supervision', 'denied, because there was probable cause to make the search and police obtained a warrant before commencing the search', 'granted, because Green''s privacy was unreasonably invaded', 'granted, because the electronic surveillance was "fundamentally unfair"', 'C', 'An invasion-of-privacy claim protects against four types of invasion of privacy: “(1) intrusion upon the plaintiff''s seclusion or solitude or into his private affairs; (2) public disclosure of embarrassing private facts about the plaintiff; (3) publicity that places the plaintiff in a false light in the public eye; and (4) appropriation, for the defendant''s advantage, of the plaintiff''s name or likeness.” Doe v. Mills, 212 Mich. App. 73, 80, 536 N.W.2d 824 (1995).', 'mbe_203', 0, '104'),
('mbe_254', 'mbe', '254', '153', 'MBE-1978-83-part1', '', '105', '', 'Tom had a heart ailment so serious that his doctors had concluded that only a heart transplant could save his life. They therefore arranged to have him flown to Big City to have the operation performed. Dan, Tom''s nephew, who stood to inherit from him, poisoned him. The poison produced a reaction which required postponing the journey. The plane on which Tom was to have flown crashed, and all aboard were killed. By the following day, Tom''s heart was so weakened by the effects of the poison that he suffered a heart attack and died. If charged with criminal homicide, Dan should be found', 'guilty', 'not guilty, because his act did not hasten the deceased''s death, but instead prolonged it by one day', 'not guilty, because the deceased was already suffering from a fatal illness', 'not guilty, because the poison was not the sole cause of death', 'A', '“Murder” is the killing of one human being by another with the requisite malevolent state of mind and without justification, excuse, or mitigation.', 'mbe_204', 0, '105'),
('mbe_255', 'mbe', '255', '154', 'MBE-1978-83-part1', '', '106', '', 'In which of the following situations is Defendant most likely to be not guilty of the charge made?', 'Police arrested Thief and recovered goods he had stolen. At the direction of the Police Thief took the goods to Defendant. Defendant believing the goods to be stolen, Purchased them. Defendant is charged with attempting to receive stolen property.', 'Defendant misrepresented his identity to secure a loan from a bank. The banker was not deceived and refused to grant the loan. Defendant is charged with attempting to obtain property by false pretenses.', 'Believing that state law made it a crime to purchase codeine without a prescription, Defendant purchased, without a prescription, cough syrup containing codeine. Unknown to Defendant, the statute had been repealed and codeine could be legally purchased without a prescription. Defendant is charged with attempting to purchase codeine without a prescription.', 'Defendant, intending to kill Selma, shot at Selma. Unknown to Defendant, Selma had died of a heart attack minutes before Defendant shot at her. Defendant is charged with attempted murder.', 'C', 'The crime of attempt is complete when the intent to commit the underlying crime is coupled with sufficient acts to demonstrate the improbability of free will desistance; the actual intervention of an extraneous factor is not a “third element” of the crime of attempt, although it is often part of the proof. See id. at 39–42, 420 N.W.2d 44; see also, Hamiel v. State, 92 Wis.2d 656, 662–68, 285 N.W.2d 639 (1979). There is no statutory defense of voluntary abandonment once an attempt is completed, and this court has declined to create such a defense at common law. Stewart, 143 Wis.2d at 45–46, 420 N.W.2d 44.', 'mbe_205', 0, '106'),
('mbe_256', 'mbe', '256', '155', 'MBE-1978-83-part1', '', '107', '', 'Potts sued Dobbs on a product liability claim. Louis testified for Potts. On cross-examination, which of the following questions is the trial judge most likely to rule improper?', '"Isn''t it a fact that you are Potts'' close friend?"', '"Isn''t it true that you are known in the community as "Louie the Lush" because of your addiction to alcohol?"', '"Didn''t you fail to report some income on your tax return last year?"', '"Weren''t you convicted, seven years ago in this court, of obtaining money under false pretenses?"', 'B', '(a) Control by the Court; Purposes. The court should exercise reasonable control over the mode and order of examining witnesses and presenting evidence so as to: (1) make those procedures effective for determining the truth; (2) avoid wasting time; and (3) protect witnesses from harassment or undue embarrassment.  (b) Scope of Cross-Examination. Cross-examination should not go beyond the subject matter of the direct examination and matters affecting the witness’s credibility. The court may allow inquiry into additional matters as if on direct examination. (c) Leading Questions. Leading questions should not be used on direct examination except as necessary to develop the witness’s testimony. Ordinarily, the court should allow leading questions: (1) on cross-examination; and (2) when a party calls a hostile witness, an adverse party, or a witness identified with an adverse party.', 'mbe_206', 0, '107'),
('mbe_257', 'mbe', '257', '156', 'MBE-1978-83-part1', '', '108', '', 'In an action to recover for personal injuries arising out of an automobile accident, Plaintiff calls Bystander to testify. Claiming the privilege against self-incrimination, Bystander refuses to answer a question as to whether she was at the scene of the accident. Plaintiff moves that Bystander be ordered to answer the question. The judge should allow Bystander to remain silent only if', 'the judge is convinced that she will incriminate herself', 'there is clear and convincing evidence that she will incriminate herself', 'there is a preponderance of evidence that she will incriminate herself', 'the judge believes that there is some reasonable possibility that she will incriminate herself', 'D', 'The Self–Incrimination Clause of the Fifth Amendment to the United States Constitution provides that “[n]o person ... shall be compelled in any criminal case to be a witness against himself.” U.S. Const. amend. V, cl. 2. To assert this privilege against self-incrimination, as an initial matter, a witness'' fear of conviction on the basis of his testimony must be reasonable, real, and appreciable. See Brown v. Walker, 161 U.S. 591, 599, 16 S.Ct. 644, 648, 40 L.Ed. 819 (1896). The witness must face a “real danger” of conviction to invoke the privilege because the privilege does not protect against “remote and speculative possibilities.” Zicarelli v. New Jersey State Comm''n of Investigation, 406 U.S. 472, 478, 92 S.Ct. 1670, 1675, 32 L.Ed.2d 234 (1972). If the privilege applies to foreign proceedings, Gecas must demonstrate, first, that the information to be disclosed through his testimony would incriminate him under foreign law and, second, that his fear of foreign conviction is real and substantial rather than merely speculative. See In re Application of the President''s Comm''n on Organized Crime, 763 F.2d 1191, 1198 (11th Cir.1985) [hereinafter In re President''s Comm''n ].', 'mbe_207', 0, '108'),
('mbe_258', 'mbe', '258', '157', 'MBE-1978-83-part1', '', '109', '', 'Venner, the owner of Greenacre, a tract of land, entered into an enforceable written agreement with Brier providing that Venner would sell Greenacre to Brier for an agreed price. At the place and time designated for the closing, Venner tendered an appropriate deed, but Brier responded that he had discovered a mortgage on Greenacre and would not complete the transaction, because Venner ''s title was not free of encumbrances, as the contract required. Venner said that it was his intent to pay the mortgage from the proceeds of the sale, and he offered to put the proceeds in escrow for that pur pose with any agreeable, responsible escrowee. The balance due on the mortgage was substantially less than the contract purchase price. Brier refused Venner ''s proposal. Venner began an appropriate legal action against Brier for specific performance. There is no applicable statute in the jurisdiction where Greenacre is located. Venner s best legal argument in support of his claim for relief is that', 'as the seller of real estate, he had an implied right to use the contract proceeds to clear the title being conveyed', 'the lien of the mortgage shifts from Greenacre to the contract proceeds', 'under the doctrine of equitable conversion, title has already passed to Brier, and the only issue is how the purchase price is to be allocated', 'no provision of the contract has been breached by Venner', 'A', 'Where a deed is delivered to a third person with instructions to deliver to the grantee named therein upon the happending of an event which is certain to occur, the title vests in the grantee upon the delivery in escrow, and is not derived through any contract other than the deed itself. An escrow is any written instrument which by its terms imposes a legal obligation, and which is deposited by the grantor, promisor, or obligor, or his agent, with a stranger or third party, to be kept by the depositary until the performance of a condition or the happening of a certain event, and then to be delivered over to the grantee, promisee, or obligee. Main v. Pratt, 276 Ill. 218, 114 N. E. 576.', 'mbe_208', 0, '109'),
('mbe_259', 'mbe', '259', '158', 'MBE-1978-83-part1', '', '110', '', 'Blackacre is a three-acre tract of land with a small residence. Olga, the owner of Blackacre, rented it to Terrence at a monthly rental of $200. After Terrence had been in possession of Blackacre for several years, Terrence and Olga orally agreed that Terrence would purchase Blackacre from Olga for the sum of $24,000, payable at the rate of $200 a month for ten years and also would pay the real estate taxes and the expenses of insuring and maintaining Blackacre. Olga agreed to give Terrence a deed to Blackacre after five years had passed and $12,000 had been paid on account and to accept from Terrence a note secured by a mortgage for the balance. Terrence continued in possession of Blackacre and performed his obligations as orally agreed. Terrence, without consulting Olga, made improvements for which he paid $1,000. When Terrence had paid $12,000, he tendered a proper note and mortgage to Olga and demanded the delivery of the deed as agreed. Olga did not deny the oral agreement but told Terrence that she had changed her mind, and she refused to complete the transaction. Terrence then brought an action for specific performance. Olga pleaded the Statute of Frauds as her defense. If Olga wins, it will be because', 'nothing Terrence could have done would have overcome the original absence of a written agreement', 'the actions and payments of Terrence are as consistent with his being a tenant as with an oral contract', 'Terrence did not secure Olga''s approval for the improvements that he made', 'Olga has not received any unconscionable benefit, and, therefore, Terrence is not entitled to equitable relief', 'B', 'An unconscionable contract is one “which is so grossly unreasonable as to be unenforceable because of an absence of meaningful choice on part of one of the parties together with contract terms which are unreasonably favorable to the other party” (King v. Fox, 7 N.Y.3d 181, 191, 818 N.Y.S.2d 833, 851 N.E.2d 1184 [2006] ).', 'mbe_209', 0, '110'),
('mbe_26', 'mbe', '26', '14', 'MBE-1972-78-part2', '', '27', 'Peter was rowing a boat on a mountain lake when a storm suddenly arose. Fearful that the boat might sink, Peter rowed to a boat dock on shore and tied the boat to the dock. The shore property and dock were the private property of Owner. While the boat was tied at the dock, Owner came down and ordered Peter to remove the boat, because the action of the waves was causing the boat to rub against a bumper on the dock. When Peter refused, Owner untied the boat and cast it adrift. The boat sank. Peter was wearing a pair of swimming trunks nothing else. He had a pair of shoes and a parka in the boat, but they were lost when Owner set it adrift. Peter was staying at a cabin one mile from Owner''s property. The only land routes back were a short rocky trail that was dangerous during the storm, and a 15-mile road around the lake. The storm continued with heavy rain and hail, and Peter having informed Owner of the location of his cabin, asked Owner to take him back there in Owner''s car. Owner said, " You got here by yourself and you''ll have to get back home yourself." After one hour the storm stopped, and Peter walked home over the trail.', 'A necessary element in determining if Peter is liable for a trespass is whether', 'Owner had clearly posted his property with a sign indicating that it was private property', 'Peter knew that the property belonged to a private person', 'Peter had reasonable grounds to believe the property belonged to a private person', 'Peter had reasonable grounds to believe his boat might be swamped and sink', 'D', 'To state a claim for trespass, a plaintiff must establish “(1) an interference with a possessory interest in his property; (2) through the defendant’s physical act or force against that property; (3) which was executed without [the plaintiff’s] consent.” Mitchell v. Baltimore Sun. Co., 883 A.2d 1008, 1014 (Md. Ct. Spec. App. 2005). The alleged trespasser does not need to cause any actual damage to the property; nominal damages may be recovered for any unauthorized entry. Tyler v. Cedar Island Club, 122 A. 38, 39 (Md. 1923).', 'mbe_23', 0, '27'),
('mbe_260', 'mbe', '260', '159', 'MBE-1978-83-part1', '', '111', 'During 1976 a series of arsons, one of which damaged the Humongous Store, occurred in the City of Swelter. In early 1977 Swelter''s City Council adopted this resolution: The City will pay $10,000 for the arrest and conviction of anyone guilty of any of the 1976 arsons committed here. The foregoing was telecast by the city''s sole television station once daily for one week. Subsequently, Humongous, by a written memorandum to Gimlet, a private detective, proposed to pay Gimlet $200 "for each day ''s work you actually perform in investigating our fire." Thereafter, in August, 1977, the City Council by resolution repealed its reward offer and caused this resolution to be broadcast once daily for a week over two local radio stations, the local television station having meanwhile ceased operations. In September, 1977, a Humongous employee voluntarily confessed to Gimlet to having committed all of the 1976 arsons. Humongous'' president thereupon paid Gimlet at the proposed daily rate for his investigation and suggested that Gimlet also claim the city''s reward, of which Gimlet had been previously unaware. Gimlet immediately made the claim. In December, 1977, as a result of Gimlet''s investigation, the Humongous employee was convicted of burning the store. The city, which has no immunity to suit, has since refused to pay Gimlet anything, although he swears that he never heard of the city''s repealer before claiming its reward.', 'In which of the following ways could the city''s reward offer be effectively accepted?', 'Only by an offeree''s return promise to make a reasonable effort to bring about the arrest and conviction of an arsonist within the scope of the offer', 'Only by an offeree''s making the arrest and assisting in the successful conviction of an arsonist within the scope of the offer', 'By an offeree''s supplying information leading to arrest and conviction of an arsonist within the scope of the offer', 'By an offeree''s communication of assent through the same medium (television) used by the city in making its offer', 'C', 'An “acceptance” is an “expression of the intent to accept the offer, by word, sign, writing or act, communicated or delivered to the person making the offer or the offeror''s agent.” Garrison, 889 P.2d at 281.  A party can demonstrate its acceptance by performing according to the terms of an offer or by accepting the consideration accompanying the offer. Hardin v. First Cash Fin. Servs., Inc., 465 F.3d 470, 476 (10th Cir. 2006) (“In general, Oklahoma follows traditional contract principles in permitting acceptance of an offer by performance: ‘Performance of the conditions of a proposal, or the acceptance of the consideration offered with a proposal, is an acceptance of the proposal.’ ” (quoting Okla. Stat. tit. 15, § 70)).', 'mbe_210', 0, '111'),
('mbe_261', 'mbe', '261', '159', 'MBE-1978-83-part1', '', '112', 'During 1976 a series of arsons, one of which damaged the Humongous Store, occurred in the City of Swelter. In early 1977 Swelter''s City Council adopted this resolution: The City will pay $10,000 for the arrest and conviction of anyone guilty of any of the 1976 arsons committed here. The foregoing was telecast by the city''s sole television station once daily for one week. Subsequently, Humongous, by a written memorandum to Gimlet, a private detective, proposed to pay Gimlet $200 "for each day ''s work you actually perform in investigating our fire." Thereafter, in August, 1977, the City Council by resolution repealed its reward offer and caused this resolution to be broadcast once daily for a week over two local radio stations, the local television station having meanwhile ceased operations. In September, 1977, a Humongous employee voluntarily confessed to Gimlet to having committed all of the 1976 arsons. Humongous'' president thereupon paid Gimlet at the proposed daily rate for his investigation and suggested that Gimlet also claim the city''s reward, of which Gimlet had been previously unaware. Gimlet immediately made the claim. In December, 1977, as a result of Gimlet''s investigation, the Humongous employee was convicted of burning the store. The city, which has no immunity to suit, has since refused to pay Gimlet anything, although he swears that he never heard of the city''s repealer before claiming its reward.', 'With respect to duration, the city''s reward offer was terminable', 'by lapse of time, on December 31 of the year in which it was made', 'not by lapse of time, but only by effective revocation', 'not by revocation, but only by lapse of a reasonable time', 'either by lapse of a reasonable time or earlier by effective revocation', 'D', 'An offer lapses if not accepted within a “reasonable time,” whatever that might be. See A.G.E., Inc. v. Buford, 105 S.W.3d 667, 673 (Tex. App.—Austin 2003, pet. denied). “A reasonable period of time is usually shorter in cases of contract for oil and gas leases than in the instance of conventional land transaction for the reason that values of leases fluctuate rapidly.', 'mbe_211', 0, '112'),
('mbe_262', 'mbe', '262', '159', 'MBE-1978-83-part1', '', '113', 'During 1976 a series of arsons, one of which damaged the Humongous Store, occurred in the City of Swelter. In early 1977 Swelter''s City Council adopted this resolution: The City will pay $10,000 for the arrest and conviction of anyone guilty of any of the 1976 arsons committed here. The foregoing was telecast by the city''s sole television station once daily for one week. Subsequently, Humongous, by a written memorandum to Gimlet, a private detective, proposed to pay Gimlet $200 "for each day ''s work you actually perform in investigating our fire." Thereafter, in August, 1977, the City Council by resolution repealed its reward offer and caused this resolution to be broadcast once daily for a week over two local radio stations, the local television station having meanwhile ceased operations. In September, 1977, a Humongous employee voluntarily confessed to Gimlet to having committed all of the 1976 arsons. Humongous'' president thereupon paid Gimlet at the proposed daily rate for his investigation and suggested that Gimlet also claim the city''s reward, of which Gimlet had been previously unaware. Gimlet immediately made the claim. In December, 1977, as a result of Gimlet''s investigation, the Humongous employee was convicted of burning the store. The city, which has no immunity to suit, has since refused to pay Gimlet anything, although he swears that he never heard of the city''s repealer before claiming its reward.', 'If the city''s reward offer was revocable, revocation could be effectively accomplished only', 'by publication in the legal notices of a local newspaper', 'in the same manner as made, i.e., by local telecast at least once daily for one week', 'in the same manner as made or by a comparable medium and frequency of publicity', 'by notice mailed to all residents of the city and all other reasonably identifiable, potential offerees', 'C', 'Any act or communication that would cause a reasonable person to believe that an offer has been withdrawn or revoked is sufficient to constitute a withdrawal or revocation of the offer (no specific words or magic words are necessary). See Williston on Contracts § 5:8 (“In general, any statement which clearly indicates or implies unwillingness on the part of the offeror to contract according to the terms of the offer is sufficient, though the offeror does not use the word “revoke” or any similar operative language.”).', 'mbe_27', 0, '113'),
('mbe_263', 'mbe', '263', '159', 'MBE-1978-83-part1', '', '114', 'During 1976 a series of arsons, one of which damaged the Humongous Store, occurred in the City of Swelter. In early 1977 Swelter''s City Council adopted this resolution: The City will pay $10,000 for the arrest and conviction of anyone guilty of any of the 1976 arsons committed here. The foregoing was telecast by the city''s sole television station once daily for one week. Subsequently, Humongous, by a written memorandum to Gimlet, a private detective, proposed to pay Gimlet $200 "for each day ''s work you actually perform in investigating our fire." Thereafter, in August, 1977, the City Council by resolution repealed its reward offer and caused this resolution to be broadcast once daily for a week over two local radio stations, the local television station having meanwhile ceased operations. In September, 1977, a Humongous employee voluntarily confessed to Gimlet to having committed all of the 1976 arsons. Humongous'' president thereupon paid Gimlet at the proposed daily rate for his investigation and suggested that Gimlet also claim the city''s reward, of which Gimlet had been previously unaware. Gimlet immediately made the claim. In December, 1977, as a result of Gimlet''s investigation, the Humongous employee was convicted of burning the store. The city, which has no immunity to suit, has since refused to pay Gimlet anything, although he swears that he never heard of the city''s repealer before claiming its reward.', 'Which of the following best characterizes the relationship between Humongous and Gimlet?', 'A unilateral offer of employment by Humongous which became irrevocable for a reasonable number of days after Gimlet commenced his investigation of the store''s arson', 'An employment for compensation subject to a condition precedent that Gimlet succeed in his investigation', 'A series of daily bilateral contracts, Humongous exchanging an express promise to pay the daily rate for Gimlet''s implied promise to pursue his investigation with reasonable diligence', 'A series of daily unilateral contracts, Humongous exchanging an express promise to pay the daily rate for Gimlet''s daily activity of investigating the store''s arson', 'D', '“unilateral contract” is one in which one party makes a unilateral offer to contract, which becomes a binding obligation if another party takes whatever actions are specified as conditions of acceptance.', 'mbe_212', 0, '114'),
('mbe_264', 'mbe', '264', '159', 'MBE-1978-83-part1', '', '115', 'During 1976 a series of arsons, one of which damaged the Humongous Store, occurred in the City of Swelter. In early 1977 Swelter''s City Council adopted this resolution: The City will pay $10,000 for the arrest and conviction of anyone guilty of any of the 1976 arsons committed here. The foregoing was telecast by the city''s sole television station once daily for one week. Subsequently, Humongous, by a written memorandum to Gimlet, a private detective, proposed to pay Gimlet $200 "for each day ''s work you actually perform in investigating our fire." Thereafter, in August, 1977, the City Council by resolution repealed its reward offer and caused this resolution to be broadcast once daily for a week over two local radio stations, the local television station having meanwhile ceased operations. In September, 1977, a Humongous employee voluntarily confessed to Gimlet to having committed all of the 1976 arsons. Humongous'' president thereupon paid Gimlet at the proposed daily rate for his investigation and suggested that Gimlet also claim the city''s reward, of which Gimlet had been previously unaware. Gimlet immediately made the claim. In December, 1977, as a result of Gimlet''s investigation, the Humongous employee was convicted of burning the store. The city, which has no immunity to suit, has since refused to pay Gimlet anything, although he swears that he never heard of the city''s repealer before claiming its reward.', 'In a suit by Gimlet against the city to recover the $10,000 reward, which of the following, in light of the facts given, most usefully supports Gimlet''s claim?', 'The city was benefited as a result of Gimlet''s services.', 'The city''s offer was in the nature of a bounty, so that the elements of contract are not essential to the city''s liability.', 'The fact that the city attempted to revoke its offer -only a few months after making it demonstrated that the attempted revocation was in bad faith.', 'Although there was no bargained -for exchange between Gimlet and the city, Gimlet ''s claim for the reward is supported by a moral obligation on the part of the city.', 'B', 'Plaintiffs must establish four elements to prove the existence of a contract: “(1) identifiable parties capable of contracting; (2) their consent; (3) a lawful object; and (4) a sufficient cause or consideration.” Section 28–2–102, MCA.', 'mbe_213', 0, '115'),
('mbe_265', 'mbe', '265', '160', 'MBE-1978-83-part1', '', '117', 'Husband and Wife, walking on a country road, were frightened by a bull running loose on the road. They climbed over a fence to get onto the adjacent property, owned by Grower. After climbing over the fence, Husband and Wife damaged some of Grower''s plants which were near the fence. The fence was posted with a large sign, "No Trespassing." Grower saw Husband and Wife and came toward them with his large watchdog on a long leash. The dog rushed at Wife. Grower had intended only to frighten Husband and Wife, but the leash broke, and before Grower could restrain the dog, the dog bit Wife.', 'If Wife asserts a claim based on battery against Grower, will Wife prevail?', 'Yes, because Grower intended that the dog frighten Wife.', 'Yes, because the breaking of the leash establishes liability under res ipsa loquitur.', 'No, because Wife made an unauthorized entry on Grower''s land.', 'No, because Grower did not intend to cause any harmful contact with Wife.', 'A', 'Battery is defined as “the unprivileged touching or striking of one person by another, done with the intent of bringing about either a contact or an apprehension of contact, that is harmful or offensive.” PIK Civ.3d 127.02; see Laurent, 1 Kan. at *431. The gravamen of a civil assault and battery is grounded upon the actor''s intention to inflict injury. Stricklin v. Parsons Stockyard Co., 192 Kan. 360, 366, 388 P.2d 824 (1964).', 'mbe_214', 0, '117'),
('mbe_266', 'mbe', '266', '160', 'MBE-1978-83-part1', '', '118', 'Husband and Wife, walking on a country road, were frightened by a bull running loose on the road. They climbed over a fence to get onto the adjacent property, owned by Grower. After climbing over the fence, Husband and Wife damaged some of Grower''s plants which were near the fence. The fence was posted with a large sign, "No Trespassing." Grower saw Husband and Wife and came toward them with his large watchdog on a long leash. The dog rushed at Wife. Grower had intended only to frighten Husband and Wife, but the leash broke, and before Grower could restrain the dog, the dog bit Wife.', 'If Husband asserts a claim based on assault against Grower, will Husband prevail?', 'Yes, because the landowner did not have a privilege to use excessive force.', 'Yes, if Husband reasonably believed that the dog might bite him.', 'No, if the dog did not come in contact with him.', 'No, if Grower was trying to protect his property.', 'B', 'To establish assault, the following elements must be proved: (1) the defendant acted either with the intent of making a contact with the person of the plaintiff or with the intent of putting the plaintiff in apprehension of such a contact; (2) the plaintiff was placed in apprehension of an imminent contact with his or her person by the conduct of the defendant; and (3) such contact was or appeared to be harmful or offensive', 'mbe_215', 0, '118'),
('mbe_267', 'mbe', '267', '160', 'MBE-1978-83-part1', '', '119', 'Husband and Wife, walking on a country road, were frightened by a bull running loose on the road. They climbed over a fence to get onto the adjacent property, owned by Grower. After climbing over the fence, Husband and Wife damaged some of Grower''s plants which were near the fence. The fence was posted with a large sign, "No Trespassing." Grower saw Husband and Wife and came toward them with his large watchdog on a long leash. The dog rushed at Wife. Grower had intended only to frighten Husband and Wife, but the leash broke, and before Grower could restrain the dog, the dog bit Wife.', 'If Grower asserts a claim against Wife and Husband for damage to his plants, will Grower prevail?', 'Yes, because Wife and Husband entered on his land without permission.', 'Yes, because Grower had posted his property with a "No Trespassing" sign.', 'No, because Wife and Husband were confronted by an emergency situation.', 'No, because Grower used excessive force toward Wife and Husband.', 'A', '“In order to prevail on a cause of action for trespass, the plaintiff must establish: (1) an interference with a possessory interest in his property; (2) through the defendant''s physical act or force against that property; (3) which was executed without his consent.” Id.', 'mbe_216', 0, '119'),
('mbe_268', 'mbe', '268', '161', 'MBE-1978-83-part1', '', '120', 'Ben was the illegitimate, unacknowledged child of Fred. Fred died intestate, leaving neither spouse nor any children other than Ben. The state''s law of intestate succession provides that an unacknowledged illegitimate child may not inherit his father''s property. The spouse, all other blood relations, and the state are preferred as heirs over the unacknowledged illegitimate child. Ben filed suit in an appropriate court alleging that the state statute barring an illegitimate child from sharing in a parent s estate is invalid, and that he should be declared lawful heir to his father''s estate.', 'In challenging the validity of the state statute, Ben''s strongest argument would be that', 'there is no rational basis for preferring as heirs collateral relatives and even the state over unacknowledged children, and, therefore, the law violates the equal protection clause', 'he has been deprived of property without due process because his fundamental right to inherit has been compromised without a compelling state need', 'it violates the privileges and immunities clause of the Fourteenth Amendment', 'it is a denial of procedural due process because it does not give the unacknowledged illegitimate child an opportunity to prove paternity', 'A', 'The Equal Protection Clause of the Fourteenth Amendment commands that no state shall “deny to any person within its jurisdiction the equal protection of the laws,” U.S. Const. amend. XIV, which essentially is a direction that all persons similarly situated should be treated alike, Plyler v. Doe, 457 U.S. 202, 216, 102 S.Ct. 2382, 72 L.Ed.2d 786 (1982).', 'mbe_217', 0, '120'),
('mbe_269', 'mbe', '269', '161', 'MBE-1978-83-part1', '', '121', 'Ben was the illegitimate, unacknowledged child of Fred. Fred died intestate, leaving neither spouse nor any children other than Ben. The state''s law of intestate succession provides that an unacknowledged illegitimate child may not inherit his father''s property. The spouse, all other blood relations, and the state are preferred as heirs over the unacknowledged illegitimate child. Ben filed suit in an appropriate court alleging that the state statute barring an illegitimate child from sharing in a parent s estate is invalid, and that he should be declared lawful heir to his father''s estate.', 'The state''s strongest defense of the statute would be that', 'the authority of a state over the disposition of decedents'' property located in the state is not affected by the Constitution of the United States', 'a statute prescribing the means of disposing of the property of intestate decedents does not constitute invidious discrimination', 'inheritance under intestate succession laws is a privilege, not a right, and therefore is not protected as property under the due process clause', 'its interest in promoting family life and in encouraging the formal acknowledgment of paternity gives the law a rational basis', 'D', 'Under the rational basis test, this court must determine whether (1) the legislation applies alike to all members within the designated class, (2) there are reasonable grounds to distinguish between those within and those without that class, and (3) the classification has a rational relationship to the proper purpose of the legislation. DeYoung v. Providence Med. Ctr., 136 Wash.2d 136, 144, 960 P.2d 919 (1998). To succeed with an equal protection challenge, McClinton must first establish that he is similarly situated with other persons in a class who have received different treatment under the same law. State v. Osman, 157 Wash.2d 474, 484, 139 P.3d 334 (2006).', 'mbe_218', 0, '121'),
('mbe_27', 'mbe', '27', '14', 'MBE-1972-78-part2', '', '28', 'Peter was rowing a boat on a mountain lake when a storm suddenly arose. Fearful that the boat might sink, Peter rowed to a boat dock on shore and tied the boat to the dock. The shore property and dock were the private property of Owner. While the boat was tied at the dock, Owner came down and ordered Peter to remove the boat, because the action of the waves was causing the boat to rub against a bumper on the dock. When Peter refused, Owner untied the boat and cast it adrift. The boat sank. Peter was wearing a pair of swimming trunks nothing else. He had a pair of shoes and a parka in the boat, but they were lost when Owner set it adrift. Peter was staying at a cabin one mile from Owner''s property. The only land routes back were a short rocky trail that was dangerous during the storm, and a 15-mile road around the lake. The storm continued with heavy rain and hail, and Peter having informed Owner of the location of his cabin, asked Owner to take him back there in Owner''s car. Owner said, " You got here by yourself and you''ll have to get back home yourself." After one hour the storm stopped, and Peter walked home over the trail.', 'If Peter asserts a claim against Owner for loss of the boat, the most likely result is that Owner will', 'have no defense under the circumstances', 'prevail because Peter was a trespasser ab initio', 'prevail because the boat might have damaged the dock', 'prevail because Peter became a trespasser when he refused to remove the boat', 'A', 'A constable who seizes the property of a defendant under an execution, and refuses to permit such defendant to select, and to have appraised for him property to the amount of $300 under the Act of 1849, the defendant demanding, and being entitled to the benefit of the exemption, becomes liable as a trespasser ab initio.', 'mbe_24', 0, '28'),
('mbe_270', 'mbe', '270', '162', 'MBE-1978-83-part1', '', '122', '', 'Alice conveyed Twinoaks Farm "to Barbara, her heirs and assigns, so long as the premises are used for residential and farm purposes, then to Charles and his heirs and assigns." The jurisdiction in which Twinoaks Farm is located has adopted the common-law Rule Against Perpetuities unmodified by statute. As a consequence of the conveyance, Alice''s interest in Twinoaks Farm is', 'nothing', 'a possibility of reverter', 'a right of entry for condition broken', 'a reversion in fee simple absolute', 'B', 'A possibility of reverter is “a future interest retained by a grantor after conveying a fee simple determinable, so that the grantee''s estate terminates automatically and reverts to the grantor if the terminating event ever occurs.” BLACK''S LAW DICTIONARY 1284 (9th ed.2009).', 'mbe_219', 0, '122'),
('mbe_271', 'mbe', '271', '163', 'MBE-1978-83-part1', '', '123', '', 'Lawnacre was conveyed to Celeste and Donald by a deed which, in the jurisdiction in which Lawn. acre is situated, created a cotenancy in equal shares and with the right of survivorship. The jurisdiction has no statute directly applicable to any of the problems posed. Celeste, by deed, conveyed "my undivided one-half interest in Lawnacre" to Paul. Celeste has since died. In an appropriate action between Paul and Donald in which title to Lawnacre is at issue, Donald will', 'prevail, because he is the sole owner of Lawnacre', 'prevail if, but only if, the cotenancy created in Celeste and Donald was a tenancy by the entirety', 'not prevail if he had knowledge of the conveyance prior to Celeste''s death', 'not prevail, because Paul and Donald own Lawnacre as tenants in common', 'B', 'a joint tenancy, by definition, “is an estate held by two or more people who ... are not husband and wife.” Sanderson v. Saxon, 834 S.W.2d 676, 678 (Ky.1992) (emphasis added). A tenancy by the entirety, on the other hand, “is an estate in land shared by husband and wife, whereby at the death of either the survivor is entitled to full fee simple ownership.” Id. “[T]he survivor takes the entire estate at the death of the deceased co-tenant not by virtue of that death, but because, in law, each was viewed to own the entire estate from the time of its creation.” Id. (emphasis in original).', 'mbe_220', 0, '123'),
('mbe_272', 'mbe', '272', '164', 'MBE-1978-83-part1', '', '124', 'Storekeeper, the owner of a large hardware store, sells power saws for both personal and commercial use. He often takes old power saws as trade-ins on new ones. The old power saws are then completely disassembled and rebuilt with new bearings by Storekeeper''s employees and sold by Storekeeper as "reconditioned saws. " Purchaser, the owner and operator of a cabinetmaking shop, informed Storekeeper that he wanted to buy a reconditioned circular saw for use in his cabinetmaking business. However, the blade that was on the saw he picked out had very coarse teeth for cutting rough lumber. Purchaser told Storekeeper that he wanted a saw blade that would cut plywood. Storekeeper exchanged the coarse blade for a new one with finer teeth that would cut plywood smoothly. The new blade was manufactured by Saw- Blade Company, which uses all available techniques to inspect its products for defects. The reconditioned saw had been manufactured by Power Saw Company. The week after the saw was purchased, Employee, who works for Purchaser in Purchaser''s cabinetmaking shop, was injured while using the saw. Employee''s arm was severely cut. As a result, the cabinetmaking shop was shut down for a week until a replacement for Employee could be found.', 'If Employee was injured while cutting plywood when the shaft holding the saw blade came loose when a bearing gave way and the shaft and blade flew off the saw, and if Employee asserts a claim based on strict liability in tort against Power Saw Company, Employee will probably', 'recover if the shaft that came loose was a part of the saw when it was new', 'recover, because Power Saw Company was in the business of manufacturing dangerous machines', 'not recover, because Employee was not the buyer of the power saw', 'not recover, because the saw had been rebuilt by Storekeeper', 'D', 'Strict liability is established only with proof that the product reached the user or consumer without substantial change in the condition in which it was sold.1 Similarly, in order for the plaintiff to recover, he or she must show that the product was defective when it left the defendant''s control.2
Thus, the possibility that an allegedly defective product was altered after it left the manufacturer''s possession may give rise to two related sets of issues: (1) Who is responsible for the condition of the product, and is the defect traceable to the manufacturer? That is, did the defect exist when the product left the manufacturer''s hands, or did it result from later alterations by someone else? (2) What is the effect of the alteration? Given that the product was altered or modified by a person other than the manufacturer, did this alteration constitute a substantial change” that should bar the plaintiff''s recovery?
This article focuses on cases in which the product was altered by someone other than the manufacturer (such as the plaintiff or the plaintiff''s employer), thus concentrating on the second set of issues, those relating to whether the change in the product was “substantial,” relieving the manufacturer of liability.', 'mbe_221', 0, '124'),
('mbe_273', 'mbe', '273', '164', 'MBE-1978-83-part1', '', '125', 'Storekeeper, the owner of a large hardware store, sells power saws for both personal and commercial use. He often takes old power saws as trade-ins on new ones. The old power saws are then completely disassembled and rebuilt with new bearings by Storekeeper''s employees and sold by Storekeeper as "reconditioned saws. " Purchaser, the owner and operator of a cabinetmaking shop, informed Storekeeper that he wanted to buy a reconditioned circular saw for use in his cabinetmaking business. However, the blade that was on the saw he picked out had very coarse teeth for cutting rough lumber. Purchaser told Storekeeper that he wanted a saw blade that would cut plywood. Storekeeper exchanged the coarse blade for a new one with finer teeth that would cut plywood smoothly. The new blade was manufactured by Saw- Blade Company, which uses all available techniques to inspect its products for defects. The reconditioned saw had been manufactured by Power Saw Company. The week after the saw was purchased, Employee, who works for Purchaser in Purchaser''s cabinetmaking shop, was injured while using the saw. Employee''s arm was severely cut. As a result, the cabinetmaking shop was shut down for a week until a replacement for Employee could be found.', 'If Employee was injured while cutting plywood when the shaft holding the saw blade came loose when a bearing gave way and the shaft and blade flew off the saw, and if Purchaser asserts a claim based on strict liability in tort against Storekeeper for loss of business because of the injury to Employee, Purchaser probably will', 'not recover, because economic loss from injury to an employee is not within the scope of Storekeeper''s duty', 'not recover, because Storekeeper was not the manufacturer of the power saw', 'recover, because Storekeeper knew the power saw was to be used in Purchaser''s cabinetmaking business', 'recover, because the reconditioned power saw was the direct cause of Purchaser''s loss of business', 'A', '“The economic loss doctrine holds that absent tangible physical harm to persons or tangible things there is generally no duty to exercise reasonable care to avoid economic losses to others. Queen City Terminals, Inc. v. Gen. Am. Transp. Corp., 73 Ohio St.3d 609, 653 N.E.2d 661 (1995). These economic losses may be recovered in contract only. Id.” J.F. Meskill Enters., LLC v. Acuity, 2006 U.S. Dist. LEXIS 41491, 2006 WL 903207 (N.D.Ohio Apr. 7, 2006). The economic-loss rule applies in a tort action when, as here, economic loss is unaccompanied by personal injury or property damage. Pavlovich, 435 F.3d at 569.', 'mbe_222', 0, '125'),
('mbe_274', 'mbe', '274', '164', 'MBE-1978-83-part1', '', '126', 'Storekeeper, the owner of a large hardware store, sells power saws for both personal and commercial use. He often takes old power saws as trade-ins on new ones. The old power saws are then completely disassembled and rebuilt with new bearings by Storekeeper''s employees and sold by Storekeeper as "reconditioned saws. " Purchaser, the owner and operator of a cabinetmaking shop, informed Storekeeper that he wanted to buy a reconditioned circular saw for use in his cabinetmaking business. However, the blade that was on the saw he picked out had very coarse teeth for cutting rough lumber. Purchaser told Storekeeper that he wanted a saw blade that would cut plywood. Storekeeper exchanged the coarse blade for a new one with finer teeth that would cut plywood smoothly. The new blade was manufactured by Saw- Blade Company, which uses all available techniques to inspect its products for defects. The reconditioned saw had been manufactured by Power Saw Company. The week after the saw was purchased, Employee, who works for Purchaser in Purchaser''s cabinetmaking shop, was injured while using the saw. Employee''s arm was severely cut. As a result, the cabinetmaking shop was shut down for a week until a replacement for Employee could be found.', 'If Employee was injured while cutting plywood when the shaft holding the saw blade came loose when a bearing gave way and the shaft and blade flew off the saw, and if Employee asserts a claim based on strict liability in tort against Storekeeper, Employee probably will', 'not recover unless Purchaser told Storekeeper that Employee would use the power saw', 'not recover if Employee failed to notice that the shaft was coming loose', 'recover unless Employee knew that the shaft was coming loose', 'recover unless Storekeeper used all possible care in reconditioning the power saw', 'C', 'contributory negligence is a defense to a negligence claim in a product liability action', 'mbe_223', 0, '126'),
('mbe_275', 'mbe', '275', '164', 'MBE-1978-83-part1', '', '127', 'Storekeeper, the owner of a large hardware store, sells power saws for both personal and commercial use. He often takes old power saws as trade-ins on new ones. The old power saws are then completely disassembled and rebuilt with new bearings by Storekeeper''s employees and sold by Storekeeper as "reconditioned saws. " Purchaser, the owner and operator of a cabinetmaking shop, informed Storekeeper that he wanted to buy a reconditioned circular saw for use in his cabinetmaking business. However, the blade that was on the saw he picked out had very coarse teeth for cutting rough lumber. Purchaser told Storekeeper that he wanted a saw blade that would cut plywood. Storekeeper exchanged the coarse blade for a new one with finer teeth that would cut plywood smoothly. The new blade was manufactured by Saw- Blade Company, which uses all available techniques to inspect its products for defects. The reconditioned saw had been manufactured by Power Saw Company. The week after the saw was purchased, Employee, who works for Purchaser in Purchaser''s cabinetmaking shop, was injured while using the saw. Employee''s arm was severely cut. As a result, the cabinetmaking shop was shut down for a week until a replacement for Employee could be found.', 'If Employee was cutting a sheet of plywood, and while he was doing so, the saw blade flew to pieces and severely cut Employee''s arm, and if.Employee asserts a claim against Storekeeper, the theory on which Employee is most likely to prevail is', 'strict liability in tort', 'express warranty', 'negligence, relying on res ipsa loquitur', 'negligence, relying on the sale of an inherently dangerous product', 'A', 'a strict liability products liability claim must establish “(1) the manufacturer''s relationship to the product in question, (2) the unreasonably dangerous condition of the product, and (3) the existence of a proximate causal connection between the condition of the product and the plaintiff''s injury.” Cintron v. Osmose Wood Preserving, Inc., 681 So.2d 859, 861 (Fla. 5th DCA 1996); see also Bailey, 288 F. App''x at 605 (11th Cir. 2008)', 'mbe_224', 0, '127'),
('mbe_276', 'mbe', '276', '164', 'MBE-1978-83-part1', '', '128', 'Storekeeper, the owner of a large hardware store, sells power saws for both personal and commercial use. He often takes old power saws as trade-ins on new ones. The old power saws are then completely disassembled and rebuilt with new bearings by Storekeeper''s employees and sold by Storekeeper as "reconditioned saws. " Purchaser, the owner and operator of a cabinetmaking shop, informed Storekeeper that he wanted to buy a reconditioned circular saw for use in his cabinetmaking business. However, the blade that was on the saw he picked out had very coarse teeth for cutting rough lumber. Purchaser told Storekeeper that he wanted a saw blade that would cut plywood. Storekeeper exchanged the coarse blade for a new one with finer teeth that would cut plywood smoothly. The new blade was manufactured by Saw- Blade Company, which uses all available techniques to inspect its products for defects. The reconditioned saw had been manufactured by Power Saw Company. The week after the saw was purchased, Employee, who works for Purchaser in Purchaser''s cabinetmaking shop, was injured while using the saw. Employee''s arm was severely cut. As a result, the cabinetmaking shop was shut down for a week until a replacement for Employee could be found.', 'If Employee was cutting a sheet of hard plastic, and while he was doing so, the saw blade flew to pieces and severely cut Employee''s arm, and if Employee asserts a claim based on strict liability in tort against Saw-Blade Company, the defense most likely to prevail is', 'Employee did not purchase the saw blade', 'the blade was being put to an improper use', 'Employee was contributorily negligent in using the blade to cut hard plastic', 'Saw-Blade Company used every available means to inspect the blade for defects', 'B', 'Unless a seller has reason to expect otherwise, a seller is entitled to assume that its product will be put to a normal use, for the purpose intended, and it is a defense to an action for breach of warranty that the injury resulted from use of a product, ordinarily safe, in some unusual and unforeseeable way.
The defense of improper or unforeseeable use of a product is also a defense to a products liability action based in negligence and to an action for strict products liability.', 'mbe_225', 0, '128'),
('mbe_277', 'mbe', '277', '165', 'MBE-1978-83-part1', '', '129', '', 'In which of the following situations is Defendant most likely to be guilty of common-law murder?', 'Angered because his neighbor is having a noisy party, Defendant fires a rifle into the neighbor''s house. The bullet strikes and kills a guest at the party.', 'During an argument, Harry slaps Defendant. Angered, Defendant responds by shooting and killing Harry.', 'Defendant drives his car through a red light and strikes and kills a pedestrian who is crossing the street.', 'Using his fist, Defendant punches Walter in the face. As a result of the blow, Walter falls and hits his head on a concrete curb, suffers a concussion, and dies.', 'A', 'To prove voluntary manslaughter, the prosecution must prove that: (1) the defendant killed in the heat of passion; (2) the passion was caused by adequate provocation; and (3) **223 there was no lapse of time during which a reasonable person could have controlled his passions. People v. Sullivan, 231 Mich.App. 510, 518, 586 N.W.2d 578 (1998), aff''d by equal division 461 Mich. 992, 609 N.W.2d 193 (2000).', 'mbe_226', 0, '129'),
('mbe_278', 'mbe', '278', '166', 'MBE-1978-83-part1', '', '130', 'Miller is tried for armed robbery of the First Bank of City.', 'The prosecution, in its case in chief, offers evidence that when Miller was arrested one day after the crime, he had a quantity of heroin and a hypodermic needle in his possession. This evidence should be', 'admitted to prove Miller''s motive to commit the crime', 'admitted to prove Miller''s propensity to commit crimes', 'excluded, because its probative value is substantially outweighed by the danger of unfair prejudice', 'excluded, because such evidence may be offered only to rebut evidence of good character offered by defendant', 'C', '“In determining whether the prejudicial effect of otherwise relevant evidence outweighs its probative value, we consider whether: (1) ... the facts offered may unduly arouse the jury''s emotions, hostility or sympathy, (2) ... the proof and answering evidence it provokes may create a side issue that will unduly distract the jury from the main issues, (3) ... the evidence offered and the counterproof will consume an undue amount of time, and (4) ... the defendant, having no reasonable ground to anticipate the evidence, is unfairly surprised and unprepared to meet it.” (Internal quotation marks omitted.) Id., at 586–87, 10 A.3d 1005.', 'mbe_2343', 0, '130'),
('mbe_279', 'mbe', '279', '166', 'MBE-1978-83-part1', '', '131', 'Miller is tried for armed robbery of the First Bank of City.', 'The prosecutor offers the testimony of a bartender that when he saw the money in Miller''s wallet, he said, "You must have robbed a bank," to which Miller made no reply. This evidence is', 'admissible to prove that Miller''s conduct caused the bartender to believe that Miller robbed the bank', 'admissible as a statement made in the presence of the defendant', 'inadmissible, because it would violate Miller''s privilege against self-incrimination', 'inadmissible, because Miller had no reason to respond to the bartender''s statement', 'D', '“Although relevant, evidence may be excluded by the trial court if the court determines that the prejudicial effect of the evidence outweighs its probative value.... Of course, [a]ll adverse evidence is damaging to one''s case, but it is inadmissible only if it creates undue prejudice so that it threatens an injustice were it to be admitted.... The test for determining whether evidence is unduly prejudicial is not whether it is damaging to the defendant but whether it will improperly arouse the emotions of the jury.... Reversal is required only whe[n] an abuse of discretion is manifest or whe[n] injustice appears to have been done.” (Citations omitted; emphasis added; internal quotation marks omitted.) State v. Wilson, 308 Conn. 412, 429–30, 64 A.3d 91 (2013).', 'mbe_2344', 0, '131'),
('mbe_28', 'mbe', '28', '15', 'MBE-1972-78-part2', '', '29', '', 'Park brought an action against Dan for injuries received in an automobile accident, alleging negligence in that Dan was speeding and inattentive. Park calls White to testify that Dan had a reputation in the community of being a reckless driver and was known as "dare-devil Dan." White''s testimony is', 'admissible as habit evidence', 'admissible because it tends to prove that Dan was negligent at the time of this collision', 'inadmissible because Dan has not offered testimony of his own good character', 'inadmissible to show negligence', 'D', '. Rule 404 makes character evidence inadmissible in most circumstances, but admissible under
several exceptions.
 Character is not the same as reputation. "Character" consists of the individual patterns of
behavior and characteristics which make up and distinguish one person from another.
"Reputation" is the general opinion of people in the community as to a person’s character
traits, and is therefore evidence of (and a common way to prove) character. Reputation also
may be independently relevant, as in a defamation case in which a party sues for damage to
reputation.', 'mbe_25', 0, '29'),
('mbe_280', 'mbe', '280', '166', 'MBE-1978-83-part1', '', '132', 'Miller is tried for armed robbery of the First Bank of City.', 'At the request of police, the teller who was robbed prepared a sketch bearing a strong likeness to Miller, but the teller died in an automobile accident before Miller was arrested. At trial the prosecution offers the sketch. The sketch is', 'admissible as an identification of a person after perceiving him', 'admissible as past recollection recorded', 'inadmissible as hearsay not within any exception', 'inadmissible as an opinion of the teller', 'C', 'Past recollection recorded “allows a witness with a faded memory to testify from notes or a memorandum that the witness can show was made by her or under her direction while the information was fresh in the witness''[s] memory and reflects that knowledge correctly.” The rule “requires the offering party to prove and the trial judge to find that the witness ‘has insufficient recollection to enable the witness to testify fully and accurately’ (taking into account the extent to which the memory can be refreshed from examination of the writing).” Under KRE 803(5), “the recorded recollection is admissible, but only after verification of its accuracy. Even if admitted, ‘the memorandum or record may be read into evidence but may not be received as an exhibit unless offered by an adverse party.’ ” If a party''s notes do refresh the party''s recollection, “there is no need to admit the recording into evidence, because the witness will be able to testify from his or her refreshed memory.”', 'mbe_2345', 0, '132'),
('mbe_281', 'mbe', '281', '166', 'MBE-1978-83-part1', '', '133', 'Miller is tried for armed robbery of the First Bank of City.', 'Miller testified on direct examination that he had never been in the First Bank of City. His counsel asks, "What, if anything, did you tell the police when you were arrested?" If his answer would be, "I told them I had never been in the bank," this answer would be', 'admissible to prove Miller had never been in the bank', 'admissible as a prior consistent statement', 'inadmissible as hearsay not within any exception', 'inadmissible, because it was a self-serving statement by a person with a substantial motive to fabricate', 'C', 'However, prior consistent statements are admissible as non-hearsay if: (1) the individual who made the prior consistent statement testifies at trial and is subject to cross-examination concerning the statement; and (2) the statement is offered in an effort to rebut an express or implied accusation of improper influence, motive or recent fabrication. See Chandler, 702 So.2d at 197–98; see also § 90.801(2)(b), Fla. Stat. (2001). Both conditions must be met for admission of a prior consistent statement as nonhearsay. Harris v. State, 843 So.2d 856, 862 (Fla.2003).', 'mbe_2346', 0, '133'),
('mbe_282', 'mbe', '282', '166', 'MBE-1978-83-part1', '', '134', 'Miller is tried for armed robbery of the First Bank of City.', 'On cross-examination of Miller, the prosecutor asks Miller whether he was convicted the previous year of tax fraud. This question is', 'proper to show that Miller is inclined to lie', 'proper to show that Miller is inclined to steal money', 'improper, because the conviction has insufficient similarity to the crime charged', 'improper, because the probative value of the evidence is outweighed by the danger of unfair prejudice', 'A', 'A trial court has discretion to permit leading questions on direct examination when a witness is reluctant, hostile, or overly nervous.', 'mbe_2347', 0, '134'),
('mbe_283', 'mbe', '283', '167', 'MBE-1978-83-part1', '', '135', '', 'In an effort to relieve serious and persistent unemployment in the industrialized state of Onondaga, its legislature enacted a statute requiring every business with annual sales in Onondaga of over one million dollars to purchase goods and/or services In Onondaga equal in value to at least half of the annual sales in Onondaga of the business. Which of the following constitutional provisions is the strongest basis on which to attack this statute?', 'The due process clause of the Fourteenth Amendment', 'The equal protection clause', 'The commerce clause', 'The privileges and immunities clause of the Fourteenth Amendment', 'C', 'Discrimination claims under the dormant Commerce Clause require a two-step analysis. “ ‘[D]iscrimination’ simply means differential treatment of in-state and out-of-state economic interests that benefits the former and burdens the latter.” Or. Waste, 511 U.S. at 99, 114 S.Ct. 1345 (emphasis added). “[I]f a state law discriminates against out-of-state goods or nonresident economic actors, the law can be sustained only on a showing that it is narrowly tailored to ‘advanc[e] a legitimate local purpose.’ ” Tennessee Wine, ––– U.S. ––––, 139 S. Ct. at 2461 (alteration in original) (quoting Dep''t of Revenue of Ky. v. Davis, 553 U.S. 328, 338, 128 S.Ct. 1801, 170 L.Ed.2d 685 (2008)).
However, “[w]here [a] statute regulates evenhandedly to effectuate a legitimate local public interest, and its effects on interstate commerce are only incidental, it will be upheld unless the burden imposed on such commerce is clearly excessive in relation to the putative local benefits.” City of Philadelphia v. New Jersey, 437 U.S. 617, 624, 98 S.Ct. 2531, 57 L.Ed.2d 475 (1978) (quoting Pike v. Bruce Church, Inc., 397 U.S. 137, 142, 90 S.Ct. 844, 25 L.Ed.2d 174 (1970)). “The crucial inquiry, therefore, must be directed to determining whether [the statute] is basically a protectionist measure, or whether it can fairly be viewed as a law directed to legitimate local concerns, with effects upon interstate commerce that are only incidental.” Ibid.', 'mbe_227', 0, '135'),
('mbe_284', 'mbe', '284', '168', 'MBE-1978-83-part1', '', '136', '', 'Tess occupied an apartment in a building owned by Len. She paid rent of $125 in advance each month. During the second month of occupancy, Tess organized the tenants in the building as a tenants'' association and the association made demands of Len concerning certain repairs and improvements the tenants wanted. When Tess tendered rent for the third month, Len notified her that rent for the fourth and subsequent months would be $200 per month. Tess protested and pointed out that all other tenants paid rent of $125 per month. Thereupon, Len gave the required statutory notice that the tenancy was being terminated at the end of the third month. By an appropriate proceeding, Tess contests Len''s right to terminate. If Tess succeeds, it will be because', 'a periodic tenancy was created by implication', 'the doctrine prohibiting retaliatory eviction is part of the law of the jurisdiction', 'the $200 rent demanded violates the agreement implied by the rate charged to other tenants', 'the law implies a term of one year in the absence of any express agreement', 'B', '"Retaliatory evidence" is called the doctrine of "curative admissibility" in the cases. It is a doctrine which seeks to level the playing field in a way. Under it, when one party "opens the door" by introducing otherwise inadmissible evidence, the opposing party is provided with the unconditional right to rebut such evidence with other illegal evidence on the same subject.
The law is that "even though a party introduces evidence that may be immaterial or illegal, his opponent has the right to rebut such evidence and this right is unconditional." A party "who has brought out evidence on a certain subject has no valid complaint as to the trial court''s action in allowing his opponent or adversary to introduce evidence on the same subject."', 'mbe_2348', 0, '136'),
('mbe_285', 'mbe', '285', '169', 'MBE-1978-83-part1', '', '137', 'Meadowview is a large tract of undeveloped land. Black, the owner of Meadowview, prepared a development plan creating 200 house lots in Meadowview with the necessary streets and public areas. The plan was fully approved by all necessary governmental agencies and duly recorded. However, construction of the streets, utilities, and other aspects of the development of Meadowview has not yet begun, and none of the streets can be opened as public ways until they are completed in accordance with the applicable ordinances of the municipality in which Meadowview is located. College Avenue, one of the streets laid out as part of the Meadowview development, abuts Whiteacre, an adjacent one-acre parcel owned by White. Whiteacre has no access to any public way except an old, poorly developed road which is inconvenient and cannot be used without great expense. White sold Whiteacre to Breyer. The description used in the deed from White to Breyer was the same as that used in prior deeds except that the portion of the description which formerly said, "thence by land of Black, north-easterly a distance of 200 feet, more or less," was changed to "thence by College Avenue as laid out on the Plan of Meadowview North 460 East 201.6 feet," with full reference to the plan and its recording data. Breyer now seeks a building permit which will show that Breyer intends to use College Avenue for access to Whiteacre. Black objects to the granting of a building permit on the grounds that he has never granted any rights to White or Breyer to use College Avenue. There are no governing statutes or ordinances relating to the problem. Black brings an appropriate action in which the right of Breyer to use College Avenue without an express grant from Black is at issue.', 'The best argument for Black in this action is that', 'Breyer ''s right must await the action of appropriate public authorities to open College Avenue as a public street, since no private easements arose by implication', 'the Statute of Frauds prevents the introduction of evidence which might prove the necessity for Breyer to use College Avenue', 'Breyer ''s right to use College Avenue is restricted to the assertion of a way by necessity and the facts preclude the success of such a claim', 'Breyer would be unjustly enriched if he were permitted to use College Avenue', 'A', 'An easement by implication arises where, during unity of title, a landowner imposes an apparently permanent and obvious servitude on part of his property in favor of another part and where, at the time of a later severance of ownership, the servitude is in use and is reasonably necessary for the enjoyment of that part of the property favored by the servitude. Berry v. Moon, 2011 Ark. App. 781, 387 S.W.3d 306. In order for such an easement to be established, it must appear not only that the easement is obvious and apparently permanent but also that it is reasonably necessary for the enjoyment of the property. Id. The term “necessary” in this context means that there could be no other reasonable mode of enjoying the dominant tenement without the easement. Id. The necessity for the easement must have existed at the time of the severance. Id. Further, the apparently permanent nature of the easement must be in existence at the time of common ownership.', 'mbe_228', 0, '137'),
('mbe_286', 'mbe', '286', '169', 'MBE-1978-83-part1', '', '138', 'Meadowview is a large tract of undeveloped land. Black, the owner of Meadowview, prepared a development plan creating 200 house lots in Meadowview with the necessary streets and public areas. The plan was fully approved by all necessary governmental agencies and duly recorded. However, construction of the streets, utilities, and other aspects of the development of Meadowview has not yet begun, and none of the streets can be opened as public ways until they are completed in accordance with the applicable ordinances of the municipality in which Meadowview is located. College Avenue, one of the streets laid out as part of the Meadowview development, abuts Whiteacre, an adjacent one-acre parcel owned by White. Whiteacre has no access to any public way except an old, poorly developed road which is inconvenient and cannot be used without great expense. White sold Whiteacre to Breyer. The description used in the deed from White to Breyer was the same as that used in prior deeds except that the portion of the description which formerly said, "thence by land of Black, north-easterly a distance of 200 feet, more or less," was changed to "thence by College Avenue as laid out on the Plan of Meadowview North 460 East 201.6 feet," with full reference to the plan and its recording data. Breyer now seeks a building permit which will show that Breyer intends to use College Avenue for access to Whiteacre. Black objects to the granting of a building permit on the grounds that he has never granted any rights to White or Breyer to use College Avenue. There are no governing statutes or ordinances relating to the problem. Black brings an appropriate action in which the right of Breyer to use College Avenue without an express grant from Black is at issue.', 'The best argument for Breyer in this action is that', 'there is a way by necessity over Meadowview ''s lands to gain access to a public road', 'the deed from White to Breyer referred to the recorded plan and therefore created rights to use the streets delineated on the plan', 'sale of lots in Meadowview by reference to its plan creates private easements in the streets shown on the plan', 'the recording of the plan is a dedication of the streets shown on the plan to public use', 'D', 'To create a public road by statutory dedication, two elements are required: (a) “a recorded plat designating the areas for public use, evidencing a clear intent by the plat proprietor to dedicate those areas to public use,” and (b) “acceptance by the proper public authority.” Kraus, 451 Mich. at 424, 547 N.W.2d 870.', 'mbe_229', 0, '138'),
('mbe_287', 'mbe', '287', '170', 'MBE-1978-83-part1', '', '139', 'Reggie offered Harriet $200 for a 30-day option to buy Harriet''s land, Grandvale, for $10,000. As Harriet knew, Reggie, if granted the option, intended to resell Grandvale at a profit. Harriet declined, believing that she could find a desirable purchaser herself. Reggie thereupon said to Harriet, "Make me a written 30-day offer, revocable at your pleasure, to sell me Grandvale at a sale price of $10,000, and tomorrow I will pay you $200 for so doing. " Harriet agreed and gave Reggie the following document: For 30 days I offer my land known as Grandvale to Reggie for $10,000, this offer to be revocable at my pleasure at any time before acceptance. [Signed] Harriet Later that day Harriet''s neighbor, Norma, said to Harriet, "I know someone who would probably buy Grandvale for $15,000." Harriet asked, "Who?" and Norma replied, "My cousin Portia." Harriet thanked Norma. Several hours later, Norma telephoned Harriet and said, "Of course, if you sell to Portia I will expect the usual 5 per cent brokerage fee for finding a buyer." Harriet made no reply. The next day Harriet telephoned Reggie, declared that her written offer to him was revoked, and demanded payment of $200. Reggie refused to pay. Harriet subsequently sold Grandvale to Portia for $15,000 but refused to pay Norma anything.', 'In a lawsuit by Harriet against Reggie to recover $200, which of the following arguments would plausibly support Harriet''s position? I. Despite its wording, Harriet''s writing was in legal effect an irrevocable offer for 30 days, given in consideration of Reggie''s promise to pay $200. II. Although Harriet''s writing was an offer that Harriet could revoke at will before acceptance, such an offer was exactly what Reggie had bargained for. III. Although Harriet''s writing does not show any consideration for her act of making a revocable offer, such consideration (Reggie''s promise to pay $200) can be proved by parol evidence.', 'I and II only', 'I and III only', 'II and III only', 'I, II, and III', 'C', 'Under Ohio law, parol, or extrinsic, evidence is only admissible if the terms of a contract are ambiguous, and can only be used to interpret, not contradict, the express language of the contract.', 'mbe_2627', 0, '139'),
('mbe_288', 'mbe', '288', '170', 'MBE-1978-83-part1', '', '140', 'Reggie offered Harriet $200 for a 30-day option to buy Harriet''s land, Grandvale, for $10,000. As Harriet knew, Reggie, if granted the option, intended to resell Grandvale at a profit. Harriet declined, believing that she could find a desirable purchaser herself. Reggie thereupon said to Harriet, "Make me a written 30-day offer, revocable at your pleasure, to sell me Grandvale at a sale price of $10,000, and tomorrow I will pay you $200 for so doing. " Harriet agreed and gave Reggie the following document: For 30 days I offer my land known as Grandvale to Reggie for $10,000, this offer to be revocable at my pleasure at any time before acceptance. [Signed] Harriet Later that day Harriet''s neighbor, Norma, said to Harriet, "I know someone who would probably buy Grandvale for $15,000." Harriet asked, "Who?" and Norma replied, "My cousin Portia." Harriet thanked Norma. Several hours later, Norma telephoned Harriet and said, "Of course, if you sell to Portia I will expect the usual 5 per cent brokerage fee for finding a buyer." Harriet made no reply. The next day Harriet telephoned Reggie, declared that her written offer to him was revoked, and demanded payment of $200. Reggie refused to pay. Harriet subsequently sold Grandvale to Portia for $15,000 but refused to pay Norma anything.', 'In a lawsuit by Harriet against Reggie to recover $200, which of the following arguments would plausibly support Reggie'' s position? I. Any promise implied by Harriet in making her offer was illusory because of the revocability provision. II. Since Harriet''s offer, if any, was in writing and involved realty, it could not be revoked by telephone. III. Enforced payment of $200 by Reggie to Harriet would defeat Reggie''s reasonable expectation if Harriet''s offer was legally open for only one day.', 'I and II only', 'I and III only', 'II and III only', 'I, II, and III', 'B', 'While revokable offer to bilateral contract may be revoked at any time prior to acceptance, that revocation or rejection is effective at moment of receipt, but acceptance is effective upon dispatch.', 'mbe_2628', 0, '140'),
('mbe_289', 'mbe', '289', '170', 'MBE-1978-83-part1', '', '141', 'Reggie offered Harriet $200 for a 30-day option to buy Harriet''s land, Grandvale, for $10,000. As Harriet knew, Reggie, if granted the option, intended to resell Grandvale at a profit. Harriet declined, believing that she could find a desirable purchaser herself. Reggie thereupon said to Harriet, "Make me a written 30-day offer, revocable at your pleasure, to sell me Grandvale at a sale price of $10,000, and tomorrow I will pay you $200 for so doing. " Harriet agreed and gave Reggie the following document: For 30 days I offer my land known as Grandvale to Reggie for $10,000, this offer to be revocable at my pleasure at any time before acceptance. [Signed] Harriet Later that day Harriet''s neighbor, Norma, said to Harriet, "I know someone who would probably buy Grandvale for $15,000." Harriet asked, "Who?" and Norma replied, "My cousin Portia." Harriet thanked Norma. Several hours later, Norma telephoned Harriet and said, "Of course, if you sell to Portia I will expect the usual 5 per cent brokerage fee for finding a buyer." Harriet made no reply. The next day Harriet telephoned Reggie, declared that her written offer to him was revoked, and demanded payment of $200. Reggie refused to pay. Harriet subsequently sold Grandvale to Portia for $15,000 but refused to pay Norma anything.', 'Which of the following would best describe the basis of any duty or duties created by Reggie''s oral promise and Harriet''s writing?', 'Firm option', 'Precontractual liability by promissory estoppel', 'Unilateral contract', 'Quasi-contractual liability', 'C', 'A unilateral contract is a contract in which “performance is based on the wish, will, or pleasure of one of the parties.” Cook v. Coldwell Banker, 967 S.W.2d 654, 657 (Mo.App. E.D.1998).', 'mbe_2629', 0, '141'),
('mbe_29', 'mbe', '29', '16', 'MBE-1972-78-part2', '', '30', '', 'Alex and Sam were arrested for holding up a gas station. They were taken to police headquarters and placed in a room for interrogation. As a police officer addressingboth started to give them the Miranda warnings prior to the questioning, Alex said, "Look, Sam planned the damned thing and I was dumb enough to go along with it. We robbed the place-what else is there to say?" Sam said nothing. Sam was escorted into another room and a full written confession was then obtained from Alex. If Sam is brought to trial on an indictment charging him with robbery, the fact that Sam failed to object to Alex''s statement and remained silent after Alex had implicated him in the crime should be ruled', 'admissible because his silence was an implied admission by Sam that he had participated in the crime', 'admissible because a statement of a participant in a crime is admissible against another participant', 'inadmissible because, under the circumstances, there was no duty or responsibility on Sam''s part to respond', 'inadmissible because whatever Alex may have said has no probative value in a trial against Sam', 'C', 'General admissibility. Except as provided in par. (b) 2., evidence of other crimes, wrongs, or acts is not admissible to prove the character of a person in order to show that the person acted in conformity therewith. This subsection does not exclude the evidence when offered for other purposes, such as proof of motive, opportunity, intent, preparation, plan, knowledge, identity, or absence of mistake or accident.', 'mbe_2321', 0, '30'),
('mbe_290', 'mbe', '290', '170', 'MBE-1978-83-part1', '', '142', 'Reggie offered Harriet $200 for a 30-day option to buy Harriet''s land, Grandvale, for $10,000. As Harriet knew, Reggie, if granted the option, intended to resell Grandvale at a profit. Harriet declined, believing that she could find a desirable purchaser herself. Reggie thereupon said to Harriet, "Make me a written 30-day offer, revocable at your pleasure, to sell me Grandvale at a sale price of $10,000, and tomorrow I will pay you $200 for so doing. " Harriet agreed and gave Reggie the following document: For 30 days I offer my land known as Grandvale to Reggie for $10,000, this offer to be revocable at my pleasure at any time before acceptance. [Signed] Harriet Later that day Harriet''s neighbor, Norma, said to Harriet, "I know someone who would probably buy Grandvale for $15,000." Harriet asked, "Who?" and Norma replied, "My cousin Portia." Harriet thanked Norma. Several hours later, Norma telephoned Harriet and said, "Of course, if you sell to Portia I will expect the usual 5 per cent brokerage fee for finding a buyer." Harriet made no reply. The next day Harriet telephoned Reggie, declared that her written offer to him was revoked, and demanded payment of $200. Reggie refused to pay. Harriet subsequently sold Grandvale to Portia for $15,000 but refused to pay Norma anything.', 'In a lawsuit by Norma against Harriet to recover $750 as a brokerage fee, which of the following arguments would effectively support Harriet''s position? I. Harriet made no promise to pay such a fee. II. Even if it be assumed arguendo that Harriet made a promise to pay such a fee, there was no bargained-for consideration for that promise. III. There was no effective offer and acceptance between Norma and Harriet.', 'I and II only', 'I and III only', 'II and III only', 'I, II, and III', 'D', 'a party must prove the existence of a contract by showing that: “(1) there was a meeting of the minds; (2) there was an offer and acceptance; (3) there was consideration; and, (4) there was certainty in the terms of the agreement.” See id. at *3 (citation omitted).', 'mbe_2630', 0, '142'),
('mbe_291', 'mbe', '291', '171', 'MBE-1978-83-part1', '', '143', 'John Doe, the owner of a milk container manufacturing firm, sought to focus public attention on the milk packaging law of the State of Clinton in order to have it repealed. On a weekday at 12:00 noon, he delivered an excited, animated, and loud harangue on the steps of the State Capitol in front of the main entryway. An audience of 200 onlookers, who gathered on the steps, heckled him and laughed as he delivered his tirade. Doe repeatedly stated, gesturing expressively and making faces, that "the g-ddamned milk packaging law is stupid," and that "I will strangle every one of those g-ddamned legislators I can get hold of because this law they created proves they are all too dumb to live." After about fifteen minutes, Doe stopped speaking, and the amused crowd dispersed. There are three relevant statutes of the State of Clinton. The first statute prohibits "all speech making, picketing, and public gatherings of every sort on the Capitol steps in front of the main entryway between 7:45 a.m. -8:15 a.m., 11:45 a.m. -12:15 p.m., 12:45 p.m. -1:15 p.m., and 4:45 p.m. -5:15 p.m., on Capitol working days."', 'If Doe is prosecuted under the "Capitol steps" statute and defends on constitutional grounds, which of the following best describes the proper burden of proof?', 'Doe would have to prove thet the state did not have a rational basis for enacting this statute.', 'Doe would have to prove that the state did not have a compelling need for this statute or that it had less restrictive means by which it could satisfy that need.', 'The state would have to prove that it had a rational basis for enacting this statute.', 'The state would have to prove that it had a compelling need for this statute and that there were no less restrictive means by which it could satisfy that need.', 'D', 'Because use of the least restrictive means is determined in light of the specific interest asserted as compelling, we must ordinarily determine which government interest is compelling. See id. (requiring the state to use “[t]he least restrictive means of furthering that compelling governmental interest” (emphasis added)).', 'mbe_230', 0, '143'),
('mbe_292', 'mbe', '292', '171', 'MBE-1978-83-part1', '', '144', 'John Doe, the owner of a milk container manufacturing firm, sought to focus public attention on the milk packaging law of the State of Clinton in order to have it repealed. On a weekday at 12:00 noon, he delivered an excited, animated, and loud harangue on the steps of the State Capitol in front of the main entryway. An audience of 200 onlookers, who gathered on the steps, heckled him and laughed as he delivered his tirade. Doe repeatedly stated, gesturing expressively and making faces, that "the g-ddamned milk packaging law is stupid," and that "I will strangle every one of those g-ddamned legislators I can get hold of because this law they created proves they are all too dumb to live." After about fifteen minutes, Doe stopped speaking, and the amused crowd dispersed. There are three relevant statutes of the State of Clinton. The first statute prohibits "all speech making, picketing, and public gatherings of every sort on the Capitol steps in front of the main entryway between 7:45 a.m. -8:15 a.m., 11:45 a.m. -12:15 p.m., 12:45 p.m. -1:15 p.m., and 4:45 p.m. -5:15 p.m., on Capitol working days."', 'Which of the following possible plaintiffs other than Doe would be most likely to obtain an adjudication in a federal court on the validity of the "Capitol steps" statute?', 'A state taxpayer in the highest tax bracket', 'A politician intending to make a campaign speech on the Capitol steps during a prohibited time', 'A legislator who voted against the statute because he thought it unconstitutional', 'An organization whose purpose was "to seek judicial invalidation of unconstitutional laws"', 'B', 'A party has standing to challenge the constitutionality of a statute only insofar as it has an adverse impact on his own rights.', 'mbe_231', 0, '144'),
('mbe_293', 'mbe', '293', '171', 'MBE-1978-83-part1', '', '145', 'John Doe, the owner of a milk container manufacturing firm, sought to focus public attention on the milk packaging law of the State of Clinton in order to have it repealed. On a weekday at 12:00 noon, he delivered an excited, animated, and loud harangue on the steps of the State Capitol in front of the main entryway. An audience of 200 onlookers, who gathered on the steps, heckled him and laughed as he delivered his tirade. Doe repeatedly stated, gesturing expressively and making faces, that "the g-ddamned milk packaging law is stupid," and that "I will strangle every one of those g-ddamned legislators I can get hold of because this law they created proves they are all too dumb to live." After about fifteen minutes, Doe stopped speaking, and the amused crowd dispersed. There are three relevant statutes of the State of Clinton. The first statute prohibits "all speech making, picketing, and public gatherings of every sort on the Capitol steps in front of the main entryway between 7:45 a.m. -8:15 a.m., 11:45 a.m. -12:15 p.m., 12:45 p.m. -1:15 p.m., and 4:45 p.m. -5:15 p.m., on Capitol working days."', 'The "Capitol steps" statute is probably', 'constitutional both on its face and as applied to Doe', 'constitutional on its face but unconstitutional as applied to Doe', 'unconstitutional on its face, because it applies to all working days', 'unconstitutional on its face, because it concerns the State Capitol', 'A', 'The “designated public forum,” and its subset, the “limited public forum,” fall next along the spectrum. Id. at 142–43. A “designated public forum” is a place not traditionally open to public assembly and debate—a public school, for example—that the government has taken affirmative steps to open for general public discourse. Id. Speech in a designated public forum is entitled to the same constitutional protection as that extended to expression in a traditional public forum, so long as the state continues to designate the forum for such use. Id. at 143. A “limited public forum,” instead, is created when the State “opens a non-public forum but limits the expressive activity to certain kinds of speakers or to the discussion of certain subjects.” Hotel Employees & Rest. Employees Union Local 100 v. City of New York Dep''t of Parks & Recreation, 311 F.3d 534, 545 (2d Cir.2002). In limited public fora, the government may make reasonable, viewpoint-neutral rules governing the content of speech allowed. Id. at 545–46; see also Good News Club v. Milford Cent. Sch., 533 U.S. 98, 106–07, 121 S.Ct. 2093, 150 L.Ed.2d 151 (2001).', 'mbe_232', 0, '145'),
('mbe_294', 'mbe', '294', '171', 'MBE-1978-83-part1', '', '146', 'John Doe, the owner of a milk container manufacturing firm, sought to focus public attention on the milk packaging law of the State of Clinton in order to have it repealed. On a weekday at 12:00 noon, he delivered an excited, animated, and loud harangue on the steps of the State Capitol in front of the main entryway. An audience of 200 onlookers, who gathered on the steps, heckled him and laughed as he delivered his tirade. Doe repeatedly stated, gesturing expressively and making faces, that "the g-ddamned milk packaging law is stupid," and that "I will strangle every one of those g-ddamned legislators I can get hold of because this law they created proves they are all too dumb to live." After about fifteen minutes, Doe stopped speaking, and the amused crowd dispersed. There are three relevant statutes of the State of Clinton. The first statute prohibits "all speech making, picketing, and public gatherings of every sort on the Capitol steps in front of the main entryway between 7:45 a.m. -8:15 a.m., 11:45 a.m. -12:15 p.m., 12:45 p.m. -1:15 p.m., and 4:45 p.m. -5:15 p.m., on Capitol working days."', 'A second state statute punishes "any person who shall intentionally threaten the life or safety of any public official for any act which he performed as part of his public office." Which of the following statements is correct concerning the possible punishment of Doe under the second statute?', 'The statute is unconstitutional on its face.', 'The statute is constitutional on its face, but Doe could not constitutionally be punished under it for this speech.', 'Doe could constitutionally be punished under the statute for his speech.', 'Doe could constitutionally be punished under the statute for his speech, but only if one or more legislators were actually present when he delivered it.', 'B', 'When enforcing the First Amendment''s prohibition on government interference with speech, we often begin by asking whether a regulation is content-based or content-neutral. Becerra, 138 S.Ct. at 2371. Content-based regulations “target speech based on its communicative content.” Id. (quoting Reed v. Town of Gilbert, 576 U.S. 155, 163, 135 S.Ct. 2218, 192 L.Ed.2d 236 (2015)).  Such regulations “are presumptively unconstitutional and may be justified only if the government proves that they are narrowly tailored to serve compelling state interests.” Becerra, 138 S. Ct. at 2371.', 'mbe_233', 0, '146'),
('mbe_295', 'mbe', '295', '171', 'MBE-1978-83-part1', '', '147', 'John Doe, the owner of a milk container manufacturing firm, sought to focus public attention on the milk packaging law of the State of Clinton in order to have it repealed. On a weekday at 12:00 noon, he delivered an excited, animated, and loud harangue on the steps of the State Capitol in front of the main entryway. An audience of 200 onlookers, who gathered on the steps, heckled him and laughed as he delivered his tirade. Doe repeatedly stated, gesturing expressively and making faces, that "the g-ddamned milk packaging law is stupid," and that "I will strangle every one of those g-ddamned legislators I can get hold of because this law they created proves they are all too dumb to live." After about fifteen minutes, Doe stopped speaking, and the amused crowd dispersed. There are three relevant statutes of the State of Clinton. The first statute prohibits "all speech making, picketing, and public gatherings of every sort on the Capitol steps in front of the main entryway between 7:45 a.m. -8:15 a.m., 11:45 a.m. -12:15 p.m., 12:45 p.m. -1:15 p.m., and 4:45 p.m. -5:15 p.m., on Capitol working days."', 'A third state statute, enacted in 1880, makes criminal "the utterance in any public place of any blasphemy or sacrilege." Assume that there have been only a few recorded prosecutions under the 1880 statute. Doe is charged with violating its proscriptions. The charge is based wholly on the speech he delivered on the steps of the Clinton State Capitol. Which of the following constitutional defenses to this prosecution under the 1880 statute would be the LEAST likely to succeed?', 'This statute is vague and, therefore, violates. the due process clause of the Fourteenth Amendment.', 'This statute is an establishment of religion and, therefore, violates the due process clause of the Fourteenth Amendment.', 'Application of this statute to Doe denies him equal protection of the laws in violation of the Fourteenth Amendment.', 'Application of this statute to Doe denies him freedom of speech in violation of the Fourteenth Amendment.', 'C', '‘Broadly stated, equal protection of the laws means “that no person or class of persons shall be denied the same protection of the laws [that] is enjoyed by other persons or other classes in like circumstances in their lives, liberty and property and in their pursuit of happiness.” [Citation.]’ [Citation.].... Thus, ... a threshold requirement of any meritorious equal protection claim ‘is a showing that the state has adopted a classification that affects two or more similarly situated groups in an unequal manner. [Citation.]’ [Citation.] ‘This initial inquiry is not whether persons are similarly situated for all purposes, but “whether they are similarly situated for purposes of the law challenged.” [Citation.]’ [Citation.]” (People v. Guzman (2005) 35 Cal.4th 577, 591–592, 25 Cal.Rptr.3d 761, 107 P.3d 860, italics omitted; see also Reed v. Reed (1971) 404 U.S. 71, 75–76, 92 S.Ct. 251, 30 L.Ed.2d 225; People v. Hofsheier (2006) 37 Cal.4th 1185, 1199–1200, 39 Cal.Rptr.3d 821, 129 P.3d 29.)', 'mbe_234', 0, '147'),
('mbe_296', 'mbe', '296', '172', 'MBE-1978-83-part1', '', '148', 'Peri sues Denucci for a libelous letter received by Investigator. The authenticity and contents of the letter are disputed.', 'Peri''s attorney asks Investigator to testify that, a week before receiving the libelous letter, he had written to Denucci inquiring about Peri. The testimony is', 'admissible provided this inquiry was made in the regular course of Investigator''s business', 'admissible without production of the inquiry letter or the showing of its unavailability', 'inadmissible unless Peri''s attorney has given Denucci notice of Investigator''s intended testimony', 'inadmissible unless the inquiry letter itself is shown to be unavailable', 'B', 'A record created by a third party which is adopted by a business may be admitted under the business record exception to the hearsay rule if certain criteria are met: (1) the record must be procured in the normal course of business; (2) the business must show that it relied on the record; and (3) there must be other circumstances indicating the trustworthiness of the document.', 'mbe_235', 0, '148'),
('mbe_297', 'mbe', '297', '172', 'MBE-1978-83-part1', '', '149', 'Peri sues Denucci for a libelous letter received by Investigator. The authenticity and contents of the letter are disputed.', 'Investigator, if permitted, will testify that, "I received a letter that I cannot now find, which read: Dear Investigator, You inquired about Peri. We fired him last month when we discovered that he had been stealing from the stockroom. Denucci" The testimony should be admitted in evidence only if the', 'jury finds that Investigator has quoted the letter precisely', 'jury is satisfied that the original letter is unavailable', 'judge is satisfied that Investigator has quoted the letter precisely', 'judge finds that the original letter is unavailable', 'D', 'In the event that the original is unavailable, the party must provide a valid reason why. If the original document is not available, and the court finds the reason provided acceptable, then the party is allowed to use secondary evidence to prove the contents of the document and have it as admissible evidence.', 'mbe_236', 0, '149'),
('mbe_298', 'mbe', '298', '173', 'MBE-1978-83-part1', '', '150', 'Photo, a free-lance photographer, took a Picture of Player in front of Shoe Store. Player was a nationally known amateur basketball star who had received much publicity in the press. At the time, the window display in Shoe Store featured "Jumpers," a well-known make of basketball shoes. Photo sold the picture, greatly enlarged, to Shoe Store and told Shoe Store that Photo had Player''s approval to do so and that Player had consented to Shoe Store''s showing the enlarged picture in the window. Shoe Store made no effort to ascertain whether Player had given his consent to Photo. In fact, Player did not even know that Photo had taken the picture. Shoe Store put the enlarged picture in the window with the display of "Jumpers" shoes. The college that Player attended believed that Player had intentionally endorsed Shoe Store and "Jumpers" shoes, and the college cancelled his athletic scholarship.', 'If Player asserts a claim based on defamation against Shoe Store, will Player prevail?', 'Yes, if Shoe Store was reckless in accepting Photo''s statement that Photo had Player''s approval.', 'Yes, because the defamatory material was in printed form.', 'No, if Shoe Store believed Photo''s statement that Photo had Player''s approval.', 'No, because the picture of Player was not defamatory per se', 'A', 'A defendant is liable for defaming a private person if he knowingly or recklessly publishes a false and disparaging communication concerning that person to a third party.', 'mbe_237', 0, '150'),
('mbe_299', 'mbe', '299', '173', 'MBE-1978-83-part1', '', '151', 'Photo, a free-lance photographer, took a Picture of Player in front of Shoe Store. Player was a nationally known amateur basketball star who had received much publicity in the press. At the time, the window display in Shoe Store featured "Jumpers," a well-known make of basketball shoes. Photo sold the picture, greatly enlarged, to Shoe Store and told Shoe Store that Photo had Player''s approval to do so and that Player had consented to Shoe Store''s showing the enlarged picture in the window. Shoe Store made no effort to ascertain whether Player had given his consent to Photo. In fact, Player did not even know that Photo had taken the picture. Shoe Store put the enlarged picture in the window with the display of "Jumpers" shoes. The college that Player attended believed that Player had intentionally endorsed Shoe Store and "Jumpers" shoes, and the college cancelled his athletic scholarship.', 'If Player asserts a claim based on invasion of privacy against Shoe Store, will Player prevail?', 'Yes, because Photo had no right to take Player''s picture.', 'Yes, because Shoe Store, without Player''s permission, used Player''s picture for profit.', 'No, because Player was already a basketball star who had received much publicity in the press.', 'No, because Shoe Store believed it had permission to put the picture in its window.', 'B', '“right of publicity” signifies the right of an individual, especially a public figure or celebrity, to control the commercial value and exploitation of his name and picture or likeness and to prevent others from unfairly appropriating this value for commercial benefit.', 'mbe_238', 0, '151'),
('mbe_3', 'mbe', '3', '1', 'MBE-1972-78-part2', '', '4', '', 'Jim watched a liquor store furtively for some time, planning to hold it up. He bought a realistic-looking toy gun for the job. One night, just before the store''s closing time, he drove to the store, opened the front door and entered. He reached in his pocket for the toy gun, but then became frightened and began to move back toward the front door. However, the shopkeeper had seen the butt of the gun. Fearing a hold up, the shopkeeper produced a gun from under the counter, pointed it at Jim, and yelled, "Stop!" Jim ran to the door and the toy gun fell from his pocket. The shopkeeper fired. The shot missed Jim, but struck and killed a passerby outside the store. A statute in the jurisdiction defines burglary as "breaking and entering any building or structure with the intent to commit a felony or to steal therein." On a charge of burglary, Jim''s best defense would be that', 'the intent required was not present', 'the liquor store was open to the public', 'he had a change of heart and withdrew before committing any crime inside the store', 'he was unsuccessful, and so at most could only be guilty of attempted burglary', 'B', 'By contrast, generic burglary''s unlawful-entry element excludes any case in which a person enters premises open to the public, no matter his intent; the generic crime requires breaking and entering or similar unlawful activity. See Brief for United States 38; LaFave § 21.1(a). So everything rests on the Government''s *276 third point: that this mismatch does not preclude applying the modified categorical approach, because it results not from a missing element but instead from an element''s overbreadth.', 'mbe_3', 0, '4'),
('mbe_30', 'mbe', '30', '17', 'MBE-1972-78-part2', '', '31', 'Duffer and Slicker, who lived in different suburbs twenty miles apart, were golfing acquaintances at the Interurban Country Club. Both were traveling salesmen-Duffer for a pharmaceutical house and Slicker for a widget manufacturer. Duffer wrote Slicker by United States mail on Friday, October 8: I need a motorcycle for transportation to the country club, and will buy your Sujocki for $1,200 upon your bringing it to my home address above [stated in the letterhead] on or beforenoon, November 12 next. This offer is not subject to countermand. Sincerely, [signed] Duffer Slicker replied by mail the following day: I accept your offer, and promise to deliver the bike as you specified. Sincerely, [signed] Slicker This letter, although properly addressed, was misdirected by the postal service and not received by Duffer until November 10. Duffer had bought another Sujocki bike from Koolcat for $1,050 a few hours before. Koolcat saw Slicker at the Interurban Country Club on November I I and said: " I sold my Sujocki to Duffer yesterday for $1,050. Would you consider selling me yours for $950?" Slicker replied: "I''ll let you know in a few days." On November 12, Slicker took his Sujocki to Duffer''s residence; he arrived at 11:55 a.m. Duffer was asleep and did not answer Slicker''s doorbell rings until 12:15 p.m. Duffer than rejected Slicker''s bike on the ground that he had already bought Koolcat''s.', 'In Duffer''s letter of October 8, what was the legal effect of the language: "This offer is not subject to countermand"?', 'Under the Uniform Commercial Code the offer was irrevocable until noon, November 12.', 'Such language prevented an effective acceptance by Slicker prior to noon, November 12.', 'At common law, such language created a binding option in Slicker''s favor.', 'Such language did not affect the offeror''s power of revocation of the offer.', 'D', 'The offeror can create in the offeree a power of acceptance that is as limited, or as difficult to exercise, as the offeror pleases and can reserve a power of revocation to be exercised in any way. In order to do this, all that is necessary is that the offeree shall be informed of the limitation, or of the reservation, at any time before the offer is accepted. If the offer is in writing, the limitation, or the reservation should be expressed in the writing itself, so that knowledge of the whole comes to the offeree at the same time. Id. at 221.', 'mbe_26', 0, '31'),
('mbe_300', 'mbe', '300', '174', 'MBE-1978-83-part1', '', '152', '', 'Landover, the owner in fee simple of Highacre, an apartment house property, entered into an enforceable written agreement with VanMeer to sell Highacre to VanMeer. The agreement provided that a good and marketable title was to be conveyed free and clear of all encumbrances. However, the agreement was silent as to the risk of fire prior to the closing, and there is no applicable statute in the state where the land is located. The premises were not insured. The day before the scheduled closing date, Highacre was wholly destroyed by fire. When VanMeer refused to close, Landover brought an action for specific performance. If Landover prevails, the most likely reason will be that', 'the failure of VanMeer to insure his interest as the purchaser of Highacre precludes any relief for him', 'the remedy at law is inadequate in actions concerning real estate contracts and either party is entitled to specific performance', 'equity does not permit consideration of surrounding circumstances in actions concerning real estate contracts', 'the doctrine of equitable conversion applies', 'D', 'To establish a claim for conversion, a plaintiff must prove that (1) the plaintiff owned or had possession of the property or entitlement to possession; (2) the defendant unlawfully and without authorization assumed and exercised control over the property to the exclusion of, or inconsistent with, the plaintiff''s rights as an owner; (3) the plaintiff demanded return of the property; and (4) the defendant refused to return the property. Apple Imports, Inc. v. Koole, 945 S.W.2d 895, 899 (Tex.App.–Austin 1997, writ denied).', 'mbe_90', 0, '152'),
('mbe_301', 'mbe', '301', '175', 'MBE-1978-83-part1', '', '153', '', 'Realco Realtors acquired a large tract of land upon which Realco developed a mobile home subdivision. The tract was divided into 60 lots, appropriate utilities were installed, and a plat of the entire tract, including a Declaration of Restrictions, was properly drawn and recorded. The Declaration of Restrictions included the following: "3. Ownership and/or occupancy are restricted to persons 21 years of age or over; one family per lot." As the separate lots were sold, the deed to each lot included the following provision: "As shown on recorded plat [properly identified by page and plat book reference] and subject to the restrictions therein contained." One of the lots was purchased by Dawson, who now resides in a mobile home on the lot together with his wife and two children, aged 11 and 13. Other lot owners in the subdivision brought action against Dawson to enjoin further occupancy by the children under 21 years of age. If judgment Is for Dawson, the issue that most likely will determine the case will be whether', 'the mobile home is treated as personalty or realty', 'the restriction constitutes an unlawful restraint on alienation', 'enforcement of the restriction is considered a violation of the equal protection clause of the Fourteenth Amendment to the United States Constitution', 'the terms of the restriction are expressly repeated verbatim In Dawson''s deed', 'C', 'The Equal Protection Clause is essentially a requirement that all persons similarly situated should be treated alike.', 'mbe_2631', 0, '153'),
('mbe_302', 'mbe', '302', '176', 'MBE-1978-83-part1', '', '154', 'In the application for a life insurance policy, Mary answered in the negative the question, "Have you ever had any heart disease?" Both the application and the insurance policy which was issued provided: "Applicant warrants the truthfulness of the statements made in the application and they are made conditions to the cont ract of insurance." Unknown to Mary, she had had a heart disease at a very early age. The policy provided that the proceeds were not to be paid over to the named beneficiary, Mary''s daughter, Joan, "until she reaches the age of 21." No contingent beneficiary was named in the policy. Mary was killed in an automobile accident two months after the policy was issued. Joan died one month later at the age of 19 from injuries incurred in the same accident.', 'If the question is raised in an action against the insurance company, how is the court likely to construe the clause dealing with the truthfulness of statements in the application?', 'The clause is a condition, and because the condition was not met, the company will not be liable.', 'The clause is a condition, but it will be interpreted to mean, "truthfulness to the best of my knowledge."', 'The clause is not a condition, and therefore the company may be liable even though Mary''s statement was not true.', 'The clause is not a condition but is a promise, and therefore the company will have a cause of action against Mary ''s estate for any losses it suffered because of Mary ''s misstatement.', 'B', '“A condition precedent is an act or event, other than a lapse of time, which, unless the condition is excused, must occur before a duty to perform a promise in the agreement arises” (Oppenheimer & Co., 86 N.Y.2d at 690, 636 N.Y.S.2d 734, 660 N.E.2d 415 [internal quotation marks omitted]). An express condition -- that is, one agreed to by the parties that must be literally performed (substantial compliance will not suffice) -- must be reflected in clear, express language (see id. at 691, 636 N.Y.S.2d 734, 660 N.E.2d 415); “[c]ourts are reluctant to interpret a contractual clause as a condition precedent in the absence of ... unmistakable conditional language” ( VXI Lux Holdco S.A.R.L. v. SIC Holdings, LLC, 171 A.D.3d 189, 195, 98 N.Y.S.3d 1 [1st Dept. 2019]).', 'mbe_239', 0, '154'),
('mbe_303', 'mbe', '303', '176', 'MBE-1978-83-part1', '', '155', 'In the application for a life insurance policy, Mary answered in the negative the question, "Have you ever had any heart disease?" Both the application and the insurance policy which was issued provided: "Applicant warrants the truthfulness of the statements made in the application and they are made conditions to the cont ract of insurance." Unknown to Mary, she had had a heart disease at a very early age. The policy provided that the proceeds were not to be paid over to the named beneficiary, Mary''s daughter, Joan, "until she reaches the age of 21." No contingent beneficiary was named in the policy. Mary was killed in an automobile accident two months after the policy was issued. Joan died one month later at the age of 19 from injuries incurred in the same accident.', 'If no objection is made concerning Mary''s misstatement in the application, how is the court most likely to construe the clause dealing with the payment of the proceeds to Joan?', 'Joan''s reaching the age of 21 is a constructive condition concurrent.', 'Joan''s reaching the age of 21 is a condition precedent to the insurance company''s duty to pay anyone.', 'Joan''s reaching the age of 21 has legal significance only with respect to the time of payment.', 'Joan''s reaching the age of 21 has no legal significance.', 'C', 'Contingent beneficiary under life policy was not entitled to policy proceeds upon death of insured, where primary beneficiary, though disqualified from receiving proceeds by virtue of fact he had murdered insured, survived insured, and policy lacked specific provisions defining term contingent beneficiary.', 'mbe_240', 0, '155'),
('mbe_304', 'mbe', '304', '177', 'MBE-1978-83-part1', '', '156', 'Defendant became intoxicated at a bar. He got into his car and drove away. Within a few blocks, craving another drink, he stopped ails car in the middle of the street, picked up a brick, and broke the display window of a liquor store. As he was reaching for a bottle, the night watchman arrived. Startled, Defendant turned, struck the watchman on the head with the bottle, killing him. Only vaguely aware of what was happening, Defendant returned to his car, consumed more liquor, and then drove off at a high speed. He ran a red light and struck and killed a pedestrian who was crossing the street. Relevant statutes define burglary to include "breaking and entering a building not used as a dwelling with the intent to commit a crime therein." Manslaughter is defined as the "killing of a human being in a criminally reckless manner." Criminal recklessness is "consciously disregarding a substantial and unjustifiable risk resulting from the actor''s conduct." Murder is defined as "the premeditated and intentional killing of another or the killing of another in the commission of committing rape, robbery, burglary, or arson." Another statute provides that intoxication is not a defense to crime unless it negates an element of the offense. Defendant was charged with the murder of the watchman and manslaughter in the death of the pedestrian. Assume that he is tried separately on each charge.', 'At Defendant''s trial for the murder of the watchman, the court should in substance charge the jury on the issue of the defense of intoxication that', 'intoxication is a defense to the underlying crime of burglary if Defendant, due to drunkenness, did not form an intent to commit a crime within the building, in which case there can be no conviction for murder unless Defendant intentionally and with premeditation killed the watchman', 'voluntary intoxication is no defense to the crime of murder', 'Defendant is guilty of murder despite his intoxication only if the state proves beyond a reasonable doubt that the killing of the watchman was premeditated and intentional', 'voluntary intoxication is a defense to the crime of murder if Defendant would not have killed the watchman but for his intoxication', 'A', 'Intoxication instruction given in state homicide prosecution did not create unconstitutional presumption of premeditation insofar as it stated there was no presumption that intoxicated person was incapable of premeditation.', 'mbe_241', 0, '156'),
('mbe_305', 'mbe', '305', '177', 'MBE-1978-83-part1', '', '157', 'Defendant became intoxicated at a bar. He got into his car and drove away. Within a few blocks, craving another drink, he stopped ails car in the middle of the street, picked up a brick, and broke the display window of a liquor store. As he was reaching for a bottle, the night watchman arrived. Startled, Defendant turned, struck the watchman on the head with the bottle, killing him. Only vaguely aware of what was happening, Defendant returned to his car, consumed more liquor, and then drove off at a high speed. He ran a red light and struck and killed a pedestrian who was crossing the street. Relevant statutes define burglary to include "breaking and entering a building not used as a dwelling with the intent to commit a crime therein." Manslaughter is defined as the "killing of a human being in a criminally reckless manner." Criminal recklessness is "consciously disregarding a substantial and unjustifiable risk resulting from the actor''s conduct." Murder is defined as "the premeditated and intentional killing of another or the killing of another in the commission of committing rape, robbery, burglary, or arson." Another statute provides that intoxication is not a defense to crime unless it negates an element of the offense. Defendant was charged with the murder of the watchman and manslaughter in the death of the pedestrian. Assume that he is tried separately on each charge.', 'At Defendant''s trial on the charge of manslaughter in the death of the pedestrian, his best argument would be that', 'he was too intoxicated to realize he was creating a substantial and unjustifiable risking the manner in which he was operating his car', 'when he got in the car his acts were not volun. tary because he was too intoxicated to know where he was or what he was doing', 'the pedestrian was contributorily negligent in failing to see Defendant''s car approaching', 'he was too intoxicated to form any intent to voluntarily operate the automobile', 'A', 'Because DUI manslaughter is not a specific intent crime, but rather a general intent crime, voluntary intoxication is not a defense to DUI manslaughter.', 'mbe_242', 0, '157'),
('mbe_306', 'mbe', '306', '177', 'MBE-1978-83-part1', '', '158', 'Defendant became intoxicated at a bar. He got into his car and drove away. Within a few blocks, craving another drink, he stopped ails car in the middle of the street, picked up a brick, and broke the display window of a liquor store. As he was reaching for a bottle, the night watchman arrived. Startled, Defendant turned, struck the watchman on the head with the bottle, killing him. Only vaguely aware of what was happening, Defendant returned to his car, consumed more liquor, and then drove off at a high speed. He ran a red light and struck and killed a pedestrian who was crossing the street. Relevant statutes define burglary to include "breaking and entering a building not used as a dwelling with the intent to commit a crime therein." Manslaughter is defined as the "killing of a human being in a criminally reckless manner." Criminal recklessness is "consciously disregarding a substantial and unjustifiable risk resulting from the actor''s conduct." Murder is defined as "the premeditated and intentional killing of another or the killing of another in the commission of committing rape, robbery, burglary, or arson." Another statute provides that intoxication is not a defense to crime unless it negates an element of the offense. Defendant was charged with the murder of the watchman and manslaughter in the death of the pedestrian. Assume that he is tried separately on each charge.', 'The state''s best argument to counter Defendant''s argument in Question 157 on the intoxication issue in the manslaughter death of the pedestrian is that', 'intoxication is no defense to the crime charged, because manslaughter is historically a general intent crime', 'intoxication is a defense only to a specific intent crime, and no specific intent is involved in the definition of the crime of manslaughter', 'conscious risk-taking refers to Defendant''s entire course of conduct, including drinking with the knowledge that he might become intoxicated and seriously injure or kill someone while driving', 'whether Defendant was intoxicated or not is not the crucial issue here; the real issue is whether the manner in which Defendant was operating his car can be characterized under the facts as criminally reckless', 'C', 'a number of courts have concluded that a defendant’s prior drunk driving conviction(s), or attendance at educational programs highlighting the hazards of driving while intoxicated, evidence a defendant’s subjective understanding and conscious disregarding of the risk to human life created by driving while intoxicated. (See, e.g., People v. Marlin (2004) 124 Cal.App.4th 559, 572 [defendant’s eight prior convictions for driving under the influence of alcohol provided sufficient basis for no contest plea to implied malice murder charge]; People v. McCarnes (1986) 179 Cal.App.3d 525, 532 [defendant’s prior convictions for driving under the influence and attendance at driver’s education program as required by sentences on those convictions admissible to show implied malice].)', 'mbe_243', 0, '158'),
('mbe_307', 'mbe', '307', '178', 'MBE-1978-83-part1', '', '159', 'The Federal Automobile Safety Act establishes certain safety and performance standards for all automobiles manufactured in the United States. The Act creates a five-member "Automobile Commission" to investigate automobile safety, to make recommendations to Congress for new laws, to make further rules establishing safety and performance standards, and to prosecute violations of the act. The chairman is appointed by the President, two members are selected by the President pro tempore of the Senate, and two by the Speaker of the House of Representatives. Minicar, Inc., a minor United States car manufacturer. seeks to enjoin enforcement of the Commission''s rules.', 'The best argument that Minicar can make is that', 'legislative power may not be delegated by Congress to an agency in the absence of clear guidelines', 'the commerce power does not extend to the manufacture of automobiles not used in interstate commerce', 'Minicar Is denied due process of law because it is not represented on the Commission', 'the Commission lacks authority to enforce its standards because not all of its members were appointed by the President', 'D', 'The Constitution gave the power of appointing federal officers, including ambassadors, judges, and other officials, to the President along with the advice and consent of the Senate. The President nominates the officials and the nominations move to the Senate for the confirmation process.', 'mbe_2632', 0, '159'),
('mbe_308', 'mbe', '308', '178', 'MBE-1978-83-part1', '', '160', 'The Federal Automobile Safety Act establishes certain safety and performance standards for all automobiles manufactured in the United States. The Act creates a five-member "Automobile Commission" to investigate automobile safety, to make recommendations to Congress for new laws, to make further rules establishing safety and performance standards, and to prosecute violations of the act. The chairman is appointed by the President, two members are selected by the President pro tempore of the Senate, and two by the Speaker of the House of Representatives. Minicar, Inc., a minor United States car manufacturer. seeks to enjoin enforcement of the Commission''s rules.', 'The appropriate decision for the court is to', 'allow the Commission to continue investigating automobile safety and making recommendations to Congress', 'allow the Commission to prosecute violations of the act but not allow it to issue rules', 'forbid the Commission to take any action under the act', 'order that all members of the Commission be appointed by the President by and with the advice and consent of the Senate', 'A', 'Under the Appointments Clause, which prescribes the exclusive means of appointing Officers of the United States, only the President, a court of law, or a head of department can do so, and only the President, with the advice and consent of the Senate, can appoint a principal officer, but Congress, instead of relying on that method, may authorize the President alone, a court, or a department head to appoint an inferior officer.', 'mbe_2633', 0, '160'),
('mbe_309', 'mbe', '309', '179', 'MBE-1978-83-part1', '', '161', 'Johnson wanted to purchase a used motor vehicle. The used car lot of Car Company, in a remote section away from town, was enclosed by a ten-foot chain link fence. While Johnson and Sales Representative, an employee of Car Company, were in the used car lot looking at cars, a security guard locked the gate at 1:30 p. i., because it was Saturday and the lot was supposed to be closed after 1:00 p. m. Saturday until Monday morning. At 1:45 p. m., Johnson and Sales Representative discovered they were locked in. There was no traffic in the vicinity and no way in which help could be summoned. After two hours, Johnson began to panic at the prospect of remaining undiscovered and without food and water until Monday morning. Sales Representative decided to wait in a car until help should come. Johnson tried to climb over the fence and, in doing so, fell and was injured. Johnson asserts a claim against Car Company for damages for his injuries.', 'If Johnson''s claim is based on negligence, is the defense of assumption of the risk applicable?', 'Yes, if a reasonable person would have recognized that there was some risk of falling while climbing the fence.', 'Yes, because Sales Representative, as Car Company''s agent, waited for help.', 'No, if it appeared that there was no other practicable way of getting out of the lot before Monday.', 'No, because Johnson was confined as the result of a volitional act.', 'C', 'To prove assumption of risk, a defendant must show: (1) that the plaintiff had actual or constructive knowledge of the existence of the specific risk involved; (2) that the plaintiff appreciated the risk''s character; and (3) that the plaintiff voluntarily accepted the risk, having had the time, knowledge, and experience to make an intelligent choice.', 'mbe_244', 0, '161'),
('mbe_31', 'mbe', '31', '17', 'MBE-1972-78-part2', '', '32', 'Duffer and Slicker, who lived in different suburbs twenty miles apart, were golfing acquaintances at the Interurban Country Club. Both were traveling salesmen-Duffer for a pharmaceutical house and Slicker for a widget manufacturer. Duffer wrote Slicker by United States mail on Friday, October 8: I need a motorcycle for transportation to the country club, and will buy your Sujocki for $1,200 upon your bringing it to my home address above [stated in the letterhead] on or beforenoon, November 12 next. This offer is not subject to countermand. Sincerely, [signed] Duffer Slicker replied by mail the following day: I accept your offer, and promise to deliver the bike as you specified. Sincerely, [signed] Slicker This letter, although properly addressed, was misdirected by the postal service and not received by Duffer until November 10. Duffer had bought another Sujocki bike from Koolcat for $1,050 a few hours before. Koolcat saw Slicker at the Interurban Country Club on November I I and said: " I sold my Sujocki to Duffer yesterday for $1,050. Would you consider selling me yours for $950?" Slicker replied: "I''ll let you know in a few days." On November 12, Slicker took his Sujocki to Duffer''s residence; he arrived at 11:55 a.m. Duffer was asleep and did not answer Slicker''s doorbell rings until 12:15 p.m. Duffer than rejected Slicker''s bike on the ground that he had already bought Koolcat''s.', 'In a lawsuit by Slicker against Duffer for breach of contract, what would the court probably decide regarding Slicker''s letter of October 9?', 'The letter bound both parties to a unilateral contract as soon as Slicker mailed it.', 'Mailing of the letter by Slicker did not, of itself, prevent a subsequent, effective revocation by Duffer of his offer.', 'The letter bound both parties to a bilateral contract, but only when received by Duffer on November 10.', 'Regardless of whether Duffer''s offer had proposed a unilateral or a bilateral contract, the letter was an effective acceptance upon receipt, if not upon dispatch.', 'B', 'Any act or communication that would cause a reasonable person to believe that an offer has been withdrawn or revoked is sufficient to constitute a withdrawal or revocation of the offer (no specific words or magic words are necessary). See Williston on Contracts § 5:8 (“In general, any statement which clearly indicates or implies unwillingness on the part of the offeror to contract according to the terms of the offer is sufficient, though the offeror does not use the word “revoke” or any similar operative language.”).', 'mbe_27', 0, '32'),
('mbe_310', 'mbe', '310', '179', 'MBE-1978-83-part1', '', '162', 'Johnson wanted to purchase a used motor vehicle. The used car lot of Car Company, in a remote section away from town, was enclosed by a ten-foot chain link fence. While Johnson and Sales Representative, an employee of Car Company, were in the used car lot looking at cars, a security guard locked the gate at 1:30 p. i., because it was Saturday and the lot was supposed to be closed after 1:00 p. m. Saturday until Monday morning. At 1:45 p. m., Johnson and Sales Representative discovered they were locked in. There was no traffic in the vicinity and no way in which help could be summoned. After two hours, Johnson began to panic at the prospect of remaining undiscovered and without food and water until Monday morning. Sales Representative decided to wait in a car until help should come. Johnson tried to climb over the fence and, in doing so, fell and was injured. Johnson asserts a claim against Car Company for damages for his injuries.', 'If Johnson''s claim is based on false imprisonment, will Johnson prevail?', 'Yes, because he was confined against his will.', 'Yes, because he was harmed as a result of his confinement.', 'No, unless the security guard was negligent in locking the gate.', 'No, unless the security guard knew that someone was in the lot at the time the guard locked the gate.', 'D', '“''The elements of false imprisonment are (1) an act committed with the intention of confining another; (2) the act directly or indirectly results in such confinement, and (3) the person confined is conscious of his confinement.'' ” Bletz v. Gribble, 641 F.3d 743, 758 (6th Cir. 2011) (citing Walsh v. Taylor, 689 N.W.2d 506, 514 (Mich. Ct. App. 2004)). “The ''substance of a false imprisonment claim is that the imprisonment is false because it occurs without right or authority.'' ” Blount v. McQuiggin, No. 1:09-cv-58, 2011 WL 1434911 at *4 (W.D. Mich. Mar. 23, 2011) (citing Hart v. Danak, 2010 WL 1404431 at *2 (Mich. Ct. App. Apr. 8, 2010)).', 'mbe_245', 0, '162'),
('mbe_311', 'mbe', '311', '180', 'MBE-1978-83-part1', '', '163', 'Albert, the owner of a house and lot, leased the same to Barnes for a term of five years. In addition to the house, there was also an unattached, two-car brick garage located on the lot. Barnes earned his living as an employee in a local grocery store, but his hobby consisted of wood carving and the making of small furniture. Barnes installed a work bench, electric lights, and a radiator in the garage. He also laid pipes connecting the radiator with the heating plant inside the house. Thereafter Albert mortgaged the premises to Good Bank to secure a loan. Barnes was not given notice of the mortgage, but the mortgage was recorded. Still later, Albert defaulted on his mortgage payments, and Good Bank began foreclosure proceedings, as it was entitled to do under the terms of the mortgage. By this time Barnes''s lease was almost ended. Barnes began the removal of the equipment he had installed in the garage. Good Bank brought an action to enjoin the removal of the equipment mentioned above. Both Barnes and Albert were named as defendants.', 'If the court refuses the injunction, it will be because', 'Barnes was without notice of the mortgage', 'the circumstances reveal that the equipment was installed for Barnes''s exclusive benefit', 'in the absence of a contrary agreement, a residential tenant is entitled to remove any personal property he voluntarily brings upon the premises', 'the Statute of Frauds precludes the Bank from claiming any interest In the equipment', 'B', '[F]ixtures and trade fixtures are differentiated under the law. A fixture is an item of personal property which is incorporated into or attached to realty. Nokomis Quarry Co. v. Dietl, 333 Ill.App.3d 480, 484, 266 Ill.Dec. 829, 775 N.E.2d 669 (2002). Because a fixture is deemed a part of the realty, it cannot be removed by a tenant without incurring liability. Nokomis, 333 Ill.App.3d at 484, 266 Ill.Dec. 829, 775 N.E.2d 669. A finding that certain property is a fixture requires ***682 **290 the court to consider a number of factors, including the agreement and intent of the parties, the nature of the attachment to the real estate, and whether the property can be removed without damage to the real estate. See Crane Erectors & Riggers, Inc. v. LaSalle National Bank, 125 Ill.App.3d 658, 662, 80 Ill.Dec. 945, 466 N.E.2d 397 (1984).
A trade fixture is an item of personal property that is attached to the realty by a tenant for the purpose of carrying on the tenant''s business. Nokomis, 333 Ill.App.3d at 484, 266 Ill.Dec. 829, 775 N.E.2d 669. A tenant may only remove a trade fixture from the realty if doing so would not damage the realty. Nokomis, 333 Ill.App.3d at 484, 266 Ill.Dec. 829, 775 N.E.2d 669 (“[r]emoval is allowed only if, after the fixture is removed, the realty is the same as it was prior to the tenant''s tenancy”).  “In other words, a fixture is a trade fixture when the tenant leases property and adds a fixture for use in the tenant''s business. Before the lease expires, the tenant would be allowed to remove a trade fixture, so long as the tenant did not damage the realty in the process of the removal.” Nokomis, 333 Ill.App.3d at 484, 266 Ill.Dec. 829, 775 N.E.2d 669.', 'mbe_246', 0, '163'),
('mbe_312', 'mbe', '312', '180', 'MBE-1978-83-part1', '', '164', 'Albert, the owner of a house and lot, leased the same to Barnes for a term of five years. In addition to the house, there was also an unattached, two-car brick garage located on the lot. Barnes earned his living as an employee in a local grocery store, but his hobby consisted of wood carving and the making of small furniture. Barnes installed a work bench, electric lights, and a radiator in the garage. He also laid pipes connecting the radiator with the heating plant inside the house. Thereafter Albert mortgaged the premises to Good Bank to secure a loan. Barnes was not given notice of the mortgage, but the mortgage was recorded. Still later, Albert defaulted on his mortgage payments, and Good Bank began foreclosure proceedings, as it was entitled to do under the terms of the mortgage. By this time Barnes''s lease was almost ended. Barnes began the removal of the equipment he had installed in the garage. Good Bank brought an action to enjoin the removal of the equipment mentioned above. Both Barnes and Albert were named as defendants.', 'If the equipment concerned had been installed by Albert, but the facts were otherwise unchanged, the effect on Good Bank''s prayer for an injunction would be that the', 'likelihood of Good Bank''s succeeding would be improved', 'likelihood of Good Bank''s succeeding would be lessened', 'likelihood of Good Bank''s succeeding would be unaffected', 'outcome of the litigation would depend upon whether or not the mortgage expressly mentioned personal property located on the premises', 'A', 'trade fixtures are removable by a tenant so long as he remains in possession of the leasehold, provided they are capable of removal without material injury to the realty; notwithstanding his failure to preserve such right in a renewal lease. Greenspan-Greenberger Co. v. Goerke Co., supra; Radey v. McCurdy, 1904, 209 Pa. 306, 58 A. 558, 67 L.R.A. 359, 103 Am.St.Rep. 1009; Ray v. Young, 1913, 160 Iowa 613, 142 N.W. 393, 46 L.R.A.,N.S., 947, Ann.Cas.1915D, 258; Andrews v. Williams, 1946, 115 Colo. 478, 173 P.2d 882, 169 A.L.R. 471, 476; Notes 110 A.L.R. 480; 22 Am.Jur., Fixtures, s 48, p. 762. Also see Bergh v. Herring-Hall-Marvin Safe Co., supra.', 'mbe_247', 0, '164'),
('mbe_313', 'mbe', '313', '181', 'MBE-1978-83-part1', '', '165', '', 'Lester, the owner in fee simple of a small farm consisting of thirty acres of land improved with a house and several outbuildings, leased the same to Tanner for a ten-year period. After two years had expired, the government condemned twenty acres of the property and allocated the compensation award to Lester and Tanner according to their respective interest so taken. It so happened, how. ever, that the twenty acres taken embraced all of the farm''s tillable land, leaving only the house, outbuildings, and a small woodlot. There is no applicable statute in the jurisdiction where the property is located nor any provision in the lease relating to condemnation. Tanner quit possession, and Lester brought suit against him to recover rent, Lester will', 'lose, because there has been a frustration of purpose which excuses Tanner from further performance of his contract to pay rent', 'lose, because there has been a breach of the implied covenant of quiet enjoyment by Lester ''s inability to provide Tanner with possession of the whole of the property for the entire term', 'win, because of the implied warranty on the part of the tenant to return the demised premises in the same condition at the end of the term as they were at the beginning', 'win, because the relationship of landlord and tenant was unaffected by the condemnation, thus leaving Tanner still obligated to pay rent', 'D', '“[a] covenant for quiet enjoyment of the premises is necessarily implied in every lease and goes to the extent of [representing] that the landlord has a good title and can give a free and unencumbered lease of the premises for the term stipulated.”', 'mbe_2349', 0, '165'),
('mbe_314', 'mbe', '314', '182', 'MBE-1978-83-part1', '', '166', 'Statutes in the jurisdiction define criminal assault as "an attempt to commit a criminal battery" and criminal battery as "causing an offensive touching." As Edward was walking down the street, a gust of wind blew his hat off. Edward reached out, trying to grab his hat, and narrowly missed striking Margaret in the face with his hand. Margaret, fearful of being struck by Edward, pushed Edward away.', 'If charged with criminal assault, Edward should be found', 'guilty, because he caused Margaret to be in apprehension of an offensive touching', 'guilty, because he should have realized he might strike someone by reaching out', 'not guilty, because he did not intend to hit Margaret', 'not guilty, because he did not hit Margaret', 'C', 'The definition of assault is the same in a civil or criminal trial. Gibbins v. Berlin, 162 S.W.3d 335, 340 (Tex.App.-Fort Worth 2005, no pet.); see City of Waco v. Williams, 209 S.W.3d 216, 223 n. 7 (Tex.App.-Waco 2006, pet. denied). Thus, to establish his assault claim, Cox must show that Wadley (1) intentionally, knowingly, or recklessly caused him bodily injury, (2) intentionally or knowingly threatened him with imminent bodily injury, or (3) intentionally or knowingly caused physical contact with him when Wadley knew or should have reasonably believed that he would regard the contact as offensive or provocative. See Tex. Penal Code Ann. § 22.01(a) (Vernon Supp. 2009); City of Waco, 209 S.W.3d at 223 n. 7. A threat is “imminent” when it is a threat of present harm, not future or conditional harm. Devine v. State, 786 S.W.2d 268, 270 (Tex.Crim.App.1989).', 'mbe_248', 0, '166'),
('mbe_315', 'mbe', '315', '182', 'MBE-1978-83-part1', '', '167', 'Statutes in the jurisdiction define criminal assault as "an attempt to commit a criminal battery" and criminal battery as "causing an offensive touching." As Edward was walking down the street, a gust of wind blew his hat off. Edward reached out, trying to grab his hat, and narrowly missed striking Margaret in the face with his hand. Margaret, fearful of being struck by Edward, pushed Edward away.', 'If charged with criminal battery, Margaret should be found', 'guilty, because she intentionally pushed Edward', 'guilty, because she caused the touching of Edward whether she meant to do so or not', 'not guilty, because a push is not an offensive touching', 'not guilty, because she was justified in pushing Edward', 'D', 'Under the Model Penal Code, a person is guilty of battery if he “purposely, knowingly or recklessly causes bodily injury to another.” Model Penal Code § 211.1(1)(a) (Official Draft 1962). Although section 211.1 is entitled “Assault,” it incorporates the crime of battery. See id., cmt. 2 at 183–84.', 'mbe_249', 0, '167'),
('mbe_316', 'mbe', '316', '183', 'MBE-1978-83-part1', '', '168', '', 'Police were concerned about an increase in marijuana traffic in Defendant''s neighborhood. One night, Police Officers, accompanied by dogs trained to sniff out marijuana, went into the back yard of Defendant''s house and onto his porch. Defendant and his friend were inside having dinner The dogs acted as if they smelled marijuana. Police Officers knocked on the back door. Defendant answered the door and let them in. Defendant was immediately placed under arrest. After a brief search, Police Officers confiscated a large quantity of marijuana which they found in Defendant''s linen closet. Defendant''s motion to prevent introduction of the marijuana into evidence will most probably be', 'denied, because the search was incident to a valid arrest', 'denied, because Defendant permitted Police Officers to enter his house', 'granted, because under the circumstances the police activity violated Defendant''s reasonable expectations of privacy', 'granted, because this kind of detection by trained dogs has not been scientifically verified and cannot be the basis for probable cause', 'C', 'A “reasonable expectation of privacy” is “said to be an expectation ‘that has a source outside of the Fourth Amendment, either by reference to concepts of real or personal property law or to understandings that are recognized and permitted by society.’ ” United States v. Jones, 132 S.Ct. at 951. See United States v. Harmon, 785 F.Supp.2d at 1157 (“To decide whether a reasonable expectation of privacy exists, courts consider concepts of real or personal property law....”). In analyzing whether an expectation of privacy is reasonable in the Fourth Amendment context based on property law, “arcane distinctions developed in property and tort law between guests, licensees, invitees, and the like, ought not to control.” Rakas v. Illinois, 439 U.S. at 143 & n. 12, 99 S.Ct. 421. While ownership or lawful possession is not determinative under the Katz v. United States reasonable-expectation-of-privacy test, it is often a dispositive factor; because the Fourth Amendment is a personal right, a defendant bears the burden of demonstrating “that he gained possession [of the area searched] from the owner or someone with the authority to grant possession.” United States v. Arango, 912 F.2d 441, 445–46 (10th Cir.1990).', 'mbe_250', 0, '168'),
('mbe_317', 'mbe', '317', '184', 'MBE-1978-83-part1', '', '169', 'Drew was tried for the July 21 murder of Victor.', 'In his case in chief, Drew called as his first witness Wilma to testify to Drew''s reputation in his community as "a peaceable man." The testimony is', 'admissible as tending to prove Drew is believable', 'admissible as tending to prove Drew is innocent', 'inadmissible, because Drew has not testified', 'inadmissible, because reputation is not a proper way to prove character', 'B', 'A reputation witness must be qualified by showing that the witness has a sufficient acquaintance with the person, the community in which he has lived or worked, and the circles in which he has moved to speak with authority of the terms in which he is generally regarded. People v. Erickson, 883 P.2d 511 (Colo.App.1994); United States v. Watson, 669 F.2d 1374, 1381 (11th Cir.1982). Similarly, a witness must have sufficient familiarity to be qualified to express an opinion as to a person''s character. United States v. Koessel, 706 F.2d 271, 275 (8th Cir.1983) (witness who had met person only once not qualified).', 'mbe_251', 0, '169'),
('mbe_318', 'mbe', '318', '184', 'MBE-1978-83-part1', '', '170', 'Drew was tried for the July 21 murder of Victor.', 'Drew called William to testify that on July 20 Drew said that he was about to leave that day to visit relatives in a distant state. The testimony Is', 'admissible, because it is a declaration of present mental state', 'admissible, because it is not hearsay', 'inadmissible, because it is irrelevant', 'inadmissible, because it is hearsay not within any exception', 'A', 'A statement of a declarant''s then existing state of mind, emotion, sensation, or physical condition is an exception to the Hearsay Rule; however, a statement of memory or belief is within this exception only if it relates to the execution, revocation, identification, or terms of the declarant''s will. Pa.R.E. 803(3). Com. v. Pronkoskie, 477 Pa. 132, 136–137, 383 A.2d 858, 859–860 (1978); see Glockner v. Glockner, 263 Pa. 393, 106 A. 731 (1919).
A declaration of present mental state is one of the applications of the res gestae rule. Com. v. Pronkoskie, 477 Pa. 132, 136–137, 383 A.2d 858, 859–860 (1978). See Com. v. Robinson, 273 Pa.Super. 337, 341–343, 417 A.2d 677, 680 (1979). A description of a previous event does not qualify under this hearsay exception. Id.', 'mbe_252', 0, '170'),
('mbe_319', 'mbe', '319', '184', 'MBE-1978-83-part1', '', '171', 'Drew was tried for the July 21 murder of Victor.', 'Drew called Wilson to testify to alibi. On cross-examination of Wilson, the prosecutor asked, "Isn''t it a fact that you are Drew''s first cousin?" The question is', 'proper, because it goes to bias', 'proper, because a relative is not competent to give reputation testimony', 'improper, because the question goes beyond the scope of direct examination', 'improper, because the evidence being sought is irrelevant', 'A', 'A “leading question” is “one that suggests to the witness the specific answer desired by the examining attorney.” Tanner v. State, 764 So.2d 385, 405 (¶ 58) (Miss.2000) (quoting Clemons v. State, 732 So.2d 883, 889 (¶ 25) (Miss.1999)). Mississippi Rule of Evidence 611(c) states:
Leading questions should not be used on the direct examination of a witness except as may be necessary to develop his testimony. Ordinarily, leading questions should be permitted on cross-examination. When a party calls a hostile witness, an adverse party, or a witness identified with an adverse party, interrogation may be by leading questions.', 'mbe_253', 0, '171'),
('mbe_32', 'mbe', '32', '17', 'MBE-1972-78-part2', '', '33', 'Duffer and Slicker, who lived in different suburbs twenty miles apart, were golfing acquaintances at the Interurban Country Club. Both were traveling salesmen-Duffer for a pharmaceutical house and Slicker for a widget manufacturer. Duffer wrote Slicker by United States mail on Friday, October 8: I need a motorcycle for transportation to the country club, and will buy your Sujocki for $1,200 upon your bringing it to my home address above [stated in the letterhead] on or beforenoon, November 12 next. This offer is not subject to countermand. Sincerely, [signed] Duffer Slicker replied by mail the following day: I accept your offer, and promise to deliver the bike as you specified. Sincerely, [signed] Slicker This letter, although properly addressed, was misdirected by the postal service and not received by Duffer until November 10. Duffer had bought another Sujocki bike from Koolcat for $1,050 a few hours before. Koolcat saw Slicker at the Interurban Country Club on November I I and said: " I sold my Sujocki to Duffer yesterday for $1,050. Would you consider selling me yours for $950?" Slicker replied: "I''ll let you know in a few days." On November 12, Slicker took his Sujocki to Duffer''s residence; he arrived at 11:55 a.m. Duffer was asleep and did not answer Slicker''s doorbell rings until 12:15 p.m. Duffer than rejected Slicker''s bike on the ground that he had already bought Koolcat''s.', 'What is the probable legal effect of Koolcat''s conversation with Slicker and report that he (Koolcat) had sold his Sujocki to Duffer on November 10?', 'This report had no legal effect because Duffer''s offer was irrevocable until November 12.', 'Unless a contract had already been formed between Slicker and Duffer. Koolcat''s report to Slicker operated to terminate Slicker''s power of accepting Duffer''s offer.', 'This report had no legal effect because the offer had been made by a prospective buyer (Duffer) rather than a prospective seller.', 'Koolcat''s conversation with Slicker on November II terminated Duffer''s original offer and operated as an offer by Koolcat to buy Slicker''s Sujocki for $950.', 'B', 'Termination of the offeree’s power of acceptance can result from any of the following six causes: 

expiration or lapse of the offer,
rejection by the offeree,
a counteroffer by the offeree, 
a qualified or conditional acceptance by the offeree, 
a valid revocation of the offer by the offeror, and 
by operation of law.', 'mbe_28', 0, '33'),
('mbe_320', 'mbe', '320', '184', 'MBE-1978-83-part1', '', '172', 'Drew was tried for the July 21 murder of Victor.', 'Drew called Warren to testify to alibi. On cross-examination of Warren, the prosecutor asked, "Weren''t you on the jury that acquitted Drew of another criminal charge?" The best reason for sustaining an objection to this question is that', 'the question goes beyond the scope of direct examination', 'the probative value of the answer would be outweighed by its tendency to mislead', 'the question is leading', 'prior jury service in a case involving a party renders the fitness incompetent', 'B', 'Evidence has “probative value” only if it has any tendency to establish or disestablish a legally necessary (material) proposition in the case through proof of the probability that the proposition is true (or untrue). See Berger, supra, ¶ 401; see also Epoch Producing Corp. v. Killiam Shows, 522 F.2d 737, 744 (2d. Cir.1975) (“An inference will be upheld only if application of common experience and logic to the underlying evidence will support it.”), cert. denied, 424 U.S. 955, 96 S.Ct. 1429, 47 L.Ed.2d 360 (1976).', 'mbe_254', 0, '172'),
('mbe_321', 'mbe', '321', '185', 'MBE-1978-83-part1', '', '173', '', 'Re-direct examination of a witness must be permitted in which of the following circumstances?', 'To reply to any matter raised in crossexamination', 'only to reply to significant new matter raised in cross-examination', 'Only to reiterate the essential elements of the case', 'Only to supply significant information inadvertently omitted on direct examination', 'B', '“[R]edirect examination is limited to matters which were first raised on cross-examination, to which the opposing party is merely responding on redirect.” Dobson v. United States, 426 A.2d 361, 365 (D.C.1981) (quoting Singletary v. United States, 383 A.2d 1064, 1073 (D.C.1978)); see Hilton v. United States, 435 A.2d 383, 389 (D.C.1981). “The reply on redirect may take the form of explanation, avoidance, or qualification of the new substantive facts or impeachment matters elicited by the cross-examiner.” 1 MCCORMICK ON EVIDENCE § 32, at 119–20 (John W. Strong ed., 5th ed.1999) (citations omitted).', 'mbe_255', 0, '173'),
('mbe_322', 'mbe', '322', '186', 'MBE-1978-83-part1', '', '174', '', 'On March 1, Mechanic agreed to repair Ohner''s machine for $5,000, to be paid on completion of the work. On March 15, before the work was completed, Mechanic sent a letter to Ohner with a copy to Jones, telling Ohner to pay the $5,000 to Jones, who was one of Mechanic''s creditors, Mechanic then completed the work. Which of the following, if true, would best serve Ohner as a defense in an action brought against him by Jones for $5,000 ?', 'Jones was incapable of performing Mechanic''s work.', 'Mechanic had not performed his work in a workmanlike manner.', 'On March 1, Mechanic had promised Ohner that he would not assign the contract.', 'Jones was not the intended beneficiary of the Ohner-Mechanic contract.', 'B', 'a general contractor does impliedly warrant that the work agreed upon will be done in a workmanlike manner. Sveum v. J. Mess Plumbing, Inc., 965 S.W.2d 924, 926 (Mo.App.1998); *661 Ribando v. Sullivan, 588 S.W.2d 120, 123 (Mo.App.1979). Workmanlike in this context is defined as “work which is completed in a skillful manner and is non-defective.” Evans v. Werle, 31 S.W.3d 489, 491 (Mo.App.2000) (citation omitted).', 'mbe_256', 0, '174'),
('mbe_323', 'mbe', '323', '187', 'MBE-1978-83-part1', '', '175', 'BCD, a manufacturer of computers, pays its salespeople a salary of $1,000 per month and a commission of 5% on billings actually rendered for machines that they sell. BCD salespeople are employed at will under written agreements which provide that in order to receive a commission the salesperson must be in the employment of the company when the bill is sent to the customer. In 1976, John, a salesperson for BCD, worked for eight months to get an order from Bobb Corporation for a large $750,000 computer. He consulted extensively with Bobb''s top executives and worked with its operating personnel to dt.velop detailed specifications for the new equipment. He also promised Bobb, with BCD''s knowledge and approval, to assist Bobb for six months after installation in making the equipment work. On January 1, 1977, Bobb signed an order, and on March 1 the computer was installed. On March 15, BCD fired John on the stated ground that he had failed to meet his 1975 and 1976 sales quotas. John thought that BCD was correct in this statement. Another salesperson, Franklin, was thereupon assigned to service the Bobb account. On March 31, BCD billed Bobb for the computer.', 'Assume for this question only that BCD''s termination of John''s employment was not wrongful. If John, after demand and refusal, sues BCD for the Bobb sale commission, which of the following is the most likely result?', 'John will win, because he had procured the sale of the computer.', 'John will win, because he had promised Bobb to assist in making the equipment work.', 'BCD will win, because Franklin is entitled to the commission on a quantum meruit basis.', 'BCD will win, because John was not employed as a BCD salesperson when Bobb was billed for the computer.', 'D', 'Vicarious liability. The Commonwealth was required to present evidence to the grand jury that Roland knowingly forced the victims to perform services under circumstances that make Martins vicariously liable for Roland''s crimes.15 See *193 Commonwealth v. Beneficial Fin. Co., 360 Mass. 188, 264-265, 275 N.E.2d 33 (1971), cert. denied, 407 U.S. 914, 92 S.Ct. 2433, 32 L.Ed.2d 689 (1972). Under the vicarious liability theory, the Commonwealth must prove “(1) that an individual committed a criminal offense; (2) that at the time of committing the offense, the individual ‘was engaged in some particular corporate business or project’; and (3) that the individual had been vested by the corporation with the authority to act for it, and on its behalf, in carrying out that particular corporate business or project when the offense occurred” (citation omitted). Commonwealth v. Angelo Todesca Corp., 446 Mass. 128, 134, 842 N.E.2d 930 (2006). See Springfield Terminal Ry. Co., 80 Mass. App. Ct. at 31 n.14, 951 N.E.2d 696.', 'mbe_257', 0, '175'),
('mbe_324', 'mbe', '324', '187', 'MBE-1978-83-part1', '', '176', 'BCD, a manufacturer of computers, pays its salespeople a salary of $1,000 per month and a commission of 5% on billings actually rendered for machines that they sell. BCD salespeople are employed at will under written agreements which provide that in order to receive a commission the salesperson must be in the employment of the company when the bill is sent to the customer. In 1976, John, a salesperson for BCD, worked for eight months to get an order from Bobb Corporation for a large $750,000 computer. He consulted extensively with Bobb''s top executives and worked with its operating personnel to dt.velop detailed specifications for the new equipment. He also promised Bobb, with BCD''s knowledge and approval, to assist Bobb for six months after installation in making the equipment work. On January 1, 1977, Bobb signed an order, and on March 1 the computer was installed. On March 15, BCD fired John on the stated ground that he had failed to meet his 1975 and 1976 sales quotas. John thought that BCD was correct in this statement. Another salesperson, Franklin, was thereupon assigned to service the Bobb account. On March 31, BCD billed Bobb for the computer.', 'Assume for this question only that BCD''s termination of John''s employment was not wrongful. If John sues BCD for the reasonable value of his services, which of the following is the most likely result?', 'John will win, because BCD benefited as a result of John'' services.', 'John will win, because BCD made an impliedin-fact promise to pay a reasonable commission for services that result in sales.', 'John will lose, because there is an express contractual provision pre-empting the subject of compensation for his services.', 'John will lose, because he cannot perform his agreement to assist the customer for six months.', 'C', '“To support a claim of wrongful termination under [New Hampshire] law, a plaintiff must establish two elements: one, that the employer terminated the employment out of bad faith, malice, or retaliation; and two, that the employer terminated the employment because the employee performed acts which public policy would encourage or because he refused to perform acts which public policy would condemn.” Short v. Sch. Admin. Unit No. 16, 136 N.H. 76, 612 A.2d 364, 370 (1992).', 'mbe_258', 0, '176'),
('mbe_325', 'mbe', '325', '187', 'MBE-1978-83-part1', '', '177', 'BCD, a manufacturer of computers, pays its salespeople a salary of $1,000 per month and a commission of 5% on billings actually rendered for machines that they sell. BCD salespeople are employed at will under written agreements which provide that in order to receive a commission the salesperson must be in the employment of the company when the bill is sent to the customer. In 1976, John, a salesperson for BCD, worked for eight months to get an order from Bobb Corporation for a large $750,000 computer. He consulted extensively with Bobb''s top executives and worked with its operating personnel to dt.velop detailed specifications for the new equipment. He also promised Bobb, with BCD''s knowledge and approval, to assist Bobb for six months after installation in making the equipment work. On January 1, 1977, Bobb signed an order, and on March 1 the computer was installed. On March 15, BCD fired John on the stated ground that he had failed to meet his 1975 and 1976 sales quotas. John thought that BCD was correct in this statement. Another salesperson, Franklin, was thereupon assigned to service the Bobb account. On March 31, BCD billed Bobb for the computer.', 'Which of the following additional facts, if shown by the evidence, would support a claim by John against BCD ? 1. BCD terminated John because Franklin is the son of the company''s president, who wanted his son to have the commission instead of John. II. BCD and John were mistaken; John had in fact exceeded his sales quotas for 1975 and 1976. III. John had worked for BCD as a salesperson for 20 years.', 'I only', 'II only', 'I and II only', 'I, II, and III', 'C', 'To establish a claim for wrongful discharge in violation of public policy, Mendlovic must show (1) that a clear public policy existed and was manifested in a state or federal constitution, statute or administrative regulation, or in the common law; (2) that dismissing employees under circumstances like those involved in Mendlovic''s dismissal would jeopardize the public policy; (3) that Mendlovic''s dismissal was motivated by conduct related to the public policy; and (4) that Life Line lacked overriding legitimate business justification for the dismissal. Painter v. Graley (1994), 70 Ohio St.3d 377, 384, 639 N.E.2d 51.', 'mbe_259', 0, '177'),
('mbe_326', 'mbe', '326', '188', 'MBE-1978-83-part1', '', '178', '', 'In 1963 Hobson was appointed to a tribunal established pursuant to a congressional act. The tribunal''s duties were to review claims made by veterans and to make recommendations to the Veterans Administration on their merits. Congress later abolished the tribunal and established a different format for review of such claims. Hobson was offered a federal administrative position in the same bureau at a lesser salary. He thereupon sued the government on the ground that Congress may not remove a federal judge from office during good behavior nor diminish his compensation during continuance in office. Government attorneys filed a motion to dismiss the action. The court should', 'deny the motion because of the independence of the federal judiciary constitutionally guaranteed by Article III', 'deny the motion, because Hobson has established a property right to his federal employment on the tribunal', 'grant the motion, because Hobson lacked standing to raise the question', 'grant the motion, because Hobson was not a judge under Article III and is not entitled to life tenure', 'D', 'Article III states that these judges “hold their office during good behavior,” which means they have a lifetime appointment, except under very limited circumstances. Article III judges can be removed from office only through impeachment by the House of Representatives and conviction by the Senate.', 'mbe_2634', 0, '178'),
('mbe_327', 'mbe', '327', '189', 'MBE-1978-83-part1', '', '179', 'In 1940, Cattle Company paid $30,000 for a 150-acre tract of agricultural land well suited for a cattle feed lot. The tract was ten miles from the city of Metropolis, then a community of 50,000 people, and five miles from the nearest home. By 1976, the city limits extended to Cattle Company''s feed lot, and the city had a population of 350,000. About 10,000 people lived within three miles of the cattle feeding operation. The Cattle Company land is outside the city limits and no zoning ordinance applies. The Cattle Company land is now worth $300,000, and $25,000 has been invested in buildings and pens. Cattle Company, conscious of its obligations to its neighbors, uses the best and most sanitary feed lot procedures, including chemical sprays, to keep down flies and odors and frequently removes manure. Despite these measures, residents of Metropolis complain of flies and odors. An action has been filed by five individual homeowners who live within half a mile of the Cattle Company feed lot. The plaintiffs'' homes are valued currently at $25,000 to $40,000 each. Flies in the area are five to ten times more numerous than in other parts of Metropolis, and extremely obnoxious odors are frequently carried by the wind to the plaintiffs'' homes. The flies and odors are a substantial health hazard.', 'If plaintiffs assert a claim based on public nuisance, plaintiffs will', 'prevail if plaintiffs sustained harm different from that suffered by the public at large', 'prevail if Cattle Company''s acts interfered with any person''s enjoyment of his property', 'not prevail, because only the state may bring an action based on public nuisance', 'not prevail, because plaintiffs came to the nuisance', 'A', 'a public nuisance as “ ‘ “the doing of or the failure to do something that injuriously affects the safety, health or morals of the public, or works some substantial annoyance, inconvenience or injury to the public.” ’ [Citations.]” (Emphasis added.) Beretta, 213 Ill.2d at 370–71, 290 Ill.Dec. 525, 821 N.E.2d 1099. “Thus, the first element that must be alleged to state a claim for public nuisance is the existence of a right common to the general public.” Beretta, 213 Ill.2d at 370–71, 290 Ill.Dec. 525, 821 N.E.2d 1099.', 'mbe_260', 0, '179'),
('mbe_328', 'mbe', '328', '189', 'MBE-1978-83-part1', '', '180', 'In 1940, Cattle Company paid $30,000 for a 150-acre tract of agricultural land well suited for a cattle feed lot. The tract was ten miles from the city of Metropolis, then a community of 50,000 people, and five miles from the nearest home. By 1976, the city limits extended to Cattle Company''s feed lot, and the city had a population of 350,000. About 10,000 people lived within three miles of the cattle feeding operation. The Cattle Company land is outside the city limits and no zoning ordinance applies. The Cattle Company land is now worth $300,000, and $25,000 has been invested in buildings and pens. Cattle Company, conscious of its obligations to its neighbors, uses the best and most sanitary feed lot procedures, including chemical sprays, to keep down flies and odors and frequently removes manure. Despite these measures, residents of Metropolis complain of flies and odors. An action has been filed by five individual homeowners who live within half a mile of the Cattle Company feed lot. The plaintiffs'' homes are valued currently at $25,000 to $40,000 each. Flies in the area are five to ten times more numerous than in other parts of Metropolis, and extremely obnoxious odors are frequently carried by the wind to the plaintiffs'' homes. The flies and odors are a substantial health hazard.', 'If plaintiffs assert a claim based on private nuisance, plaintiffs will', 'prevail, because Cattle Company''s activity unreasonably interfered with plaintiffs'' use and enjoyment of their property', 'prevail, because Cattle Company''s activity constitutes an inverse condemnation of their property', 'not prevail, because Cattle Company had operated the feed lot for more than 25 years', 'not prevail, because Cattle Company uses the most reasonable procedures to keep down flies and odors', 'A', 'in order to recover damages in a common-law private nuisance cause of action, a plaintiff must show that the defendant''s conduct was the proximate cause of an unreasonable interference with the plaintiff''s use and enjoyment of his or her property. The interference may be either intentional; Quinnett v. Newman, supra, 213 Conn. at 348, 568 A.2d 786 (nuisance is created intentionally if defendant intends act that brings about condition found to be nuisance); or the result of the defendant''s negligence. Id., at 348–49, 568 A.2d 786. Whether the interference is unreasonable depends upon a balancing of the interests involved under the circumstances of each individual case. In balancing the interests, the fact finder must take into consideration all relevant factors, including the nature of both the interfering use and the use and enjoyment invaded, the nature, extent and duration of the interference, the suitability for the locality of both the interfering conduct and the particular use and enjoyment invaded, whether the defendant is taking all feasible precautions to avoid any unnecessary interference with the plaintiff''s use and enjoyment of his or her property, and any other factors that the fact finder deems relevant to the question of whether the interference is unreasonable. No one factor should dominate this balancing of interests; all relevant factors must be considered in determining whether the interference is unreasonable.', 'mbe_261', 0, '180'),
('mbe_329', 'mbe', '329', '190', 'MBE-1978-83-part1', '', '181', '', 'Alan, who was already married, went through a marriage ceremony with Betty and committed bigamy. Carl, his friend, who did not know of Alan''s previous marriage, had encouraged Alan to marry Betty and was best man at the ceremony, If Carl is charged with being an accessory to bigamy, he should be found', 'not guilty, because his encouragement and assistance was not the legal cause of the crime', 'not guilty, because he did not have the mental state required for aiding and abetting', 'guilty, because he encouraged Alan, and his mistake as to the existence of a prior marriage is no defense to a charge of bigamy', 'guilty, because he was present when the crime occurred and is thus a principal in the second degree', 'B', 'Aiding and abetting requires facts showing that the defendant “knowingly involved himself in a criminal act” and furthered the criminal act. United States v. Nusraty, 867 F.2d 759, 766 (2d Cir.1989).', 'mbe_262', 0, '181'),
('mbe_33', 'mbe', '33', '18', 'MBE-1972-78-part2', '', '34', '', 'In a suit attacking the validity of a deed executed fifteen years ago, Plaintiff alleges mental incompetency of Joe, the grantor, and offers in evidence a properly authenticated affidavit of Harry, Joe''s brother. The affidavit, which was executed shortly after the deed, stated that Harry had observed Joe closely over a period of weeks, that Joe had engaged in instances of unusual behavior (which were described), and that Joe''s appearance had changed from one of neatness and alertness to one of disorder and absentmindedness. The judge should rule Harry''s affidavit', 'inadmissible as opinion', 'inadmissible as hearsay, not within any exception', 'admissible as an official document', 'admissible as an ancient document', 'B', '“Hearsay is an out of court, unsworn, oral or written statement by a third person, which is offered for the truth of its content. Hearsay statements are inadmissible unless they fit into one of the recognized exceptions.” State v. Gremillion, 542 So.2d 1074, 1077 (La.1989) (citation omitted). One such exception to the hearsay exclusionary rule applies to unavailable witnesses:
A. Definition of unavailability. Except as otherwise provided by this Code, a declarant is “unavailable as a witness” when the declarant cannot or will not appear in court and testify to the substance of his statement made outside of court. This includes situations in which the declarant:
....
(2) Persists in refusing to testify concerning the subject matter of his statement despite an order of the court to do so;
....
B. Hearsay exceptions. The following are not excluded by the hearsay rule if the declarant is unavailable as a witness:
....
(3) Statement against interest. A statement which was at the time of its making so far contrary to the declarant''s pecuniary or proprietary interest, or so far tended to subject him to civil or criminal liability, or to render invalid a claim by him against another, that a reasonable man in his position would not have made the statement unless he believed it to be true. A statement tending to expose the declarant to criminal liability and offered to exculpate the accused is not admissible unless corroborating circumstances clearly indicate the trustworthiness of the statement.
La.Code Evid. art. 804.', 'mbe_29', 0, '34'),
('mbe_330', 'mbe', '330', '191', 'MBE-1978-83-part1', '', '182', '', 'Defendant was charged with murder. His principal defense was that he had killed in hot blood and should be guilty only of manslaughter. The judge instructed the jury that the state must prove guilt beyond a reasonable doubt, that the killing was presumed to be murder, and that the charge could bereduced to manslaughter, and Defendant accordingly found guilty of this lesser offense, if Defendant showed by a fair preponderance of the evidence that the killing was committed in the heat of passion on sudden provocation. Defendant was convicted of murder. On appeal, he seeks a new trial and claims error in the judge''s instructions to the jury. Defendant''s conviction will most probably be', 'affirmed, because the judge carefully advised the jury of the state''s obligation to prove guilt beyond a reasonable doubt', 'affirmed, because Defendant''s burden to show hot blood was not one of ultimate persuasion but only one of producing evidence to rebut a legitimate presumption', 'reversed, because the instruction put a burden on Defendant which denied him due process of law', 'reversed, because presumptions have a highly prejudicial effect and thus cannot be used on behalf of the state in a criminal case', 'C', 'Jury instructions are reviewed for abuse of discretion. Jowers v. Lincoln Elec. Co., 617 F.3d 346, 352 (5th Cir. 2010). Instructions that hinge on a question of statutory construction are reviewed de novo. GE Capital, 754 F.3d at 302. Reversal is appropriate when the “charge as a whole leaves [the court] with substantial and ineradicable doubt whether the jury [was] properly guided in its deliberations” and the challenged instructions, separately or collectively, “affected the outcome of the case.” Jowers, 617 F.3d at 352 (quoting Bender v. Brumley, 1 F.3d 271, 276–77 (5th Cir. 1993)).  Similarly, when a challenge involves the trial court''s failure to give a requested jury instruction, the court will find reversible error only if the requested instruction “1) was a substantially correct statement of law, 2) was not substantially covered in the charge as a whole, and 3) concerned an important point in the trial such that the failure to instruct the jury on the issue seriously impaired the [party''s] ability to present a given [claim].” Baisden v. I''m Ready Prods., Inc., 693 F.3d 491, 505 (5th Cir. 2012) (citation omitted).', 'mbe_263', 0, '182'),
('mbe_331', 'mbe', '331', '192', 'MBE-1978-83-part1', '', '183', '', 'Darlene was arrested on a murder charge. She was given Miranda warnings and refused to talk further with the police. At trial, she testified in her own defense. She recounted in some detail her whereabouts on the day of the ci ime and explained why she could not have committed the crime. On cross-examination and over defense objection, the prosecution emphasized the fact that she did not tell the police this story following her arrest. The prosecution thereby suggested that her testimony was false. Defendant was convicted. On appeal, she claims error in the prosecutor''s cross-examination. Her conviction will most probably be', 'affirmed, because defendant''s silence at time of arrest is tantamount to a prior inconsistent statement, giving rise to an inference that the story was fabricated', 'affirmed, because defendant''s silence was not used as direct evidence but only for impeachment, a purpose consistent with legitimate cross-examination', 'reversed, because post-arrest silence constituted defendant''s exercise of her Miranda rights and use of that silence against her at trial violated due process', 'reversed, because to require the defense to acquaint the prosecution with defendant''s testimony prior to trial would constitute unconstitutional pre-trial discovery', 'C', 'A waiver of Miranda rights may be implied through the defendant''s silence, coupled with an understanding of his rights and a course of conduct indicating waiver.', 'mbe_264', 0, '183'),
('mbe_332', 'mbe', '332', '193', 'MBE-1978-83-part1', '', '184', '', 'Alice was held up at the point of a gun, an unusual revolver with a red-painted barrel, while she was clerking in a neighborhood grocery store. Dennis is charged with armed robbery of Alice. The prosecutor calls Winthrop to testify that, a week after the robbery of Alice, he was robbed by Dennis with a pistol that had red paint on the barrel. Winthrop''s testimony is', 'admissible as establishing an identifying circumstance', 'admissible as showing that Dennis was willing to commit robbery', 'inadmissible, because it is improper character evidence', 'inadmissible, because its probative value is substantially outweighed by the danger of unfair prejudice', 'A', '“In determining whether identification procedures violate a defendant''s due process rights, the required *353 inquiry is made on an ad hoc basis and is two-pronged: first, it must be determined whether the identification procedure was unnecessarily suggestive; and second, if it is found to have been so, it must be determined whether the identification was nevertheless reliable based on examination of the totality of the circumstances.... The first suggestiveness prong involves the circumstances of the identification procedure itself ... and the critical question is whether the procedure was conducted in such a manner as to emphasize or highlight the individual whom the police believe is the suspect.... If the trial court determines that there was no unduly suggestive identification procedure, that is the end of the analysis, and the identification evidence is admissible.” (Citations omitted; internal quotation marks omitted.) State v. Dickson, 322 Conn. 410, 420–21, 141 A.3d 810 (2016), cert. denied, ––– U.S. ––––, 137 S.Ct. 2263, 198 L.Ed. 2d 713 (2017). “An identification procedure is unnecessarily suggestive only if it gives rise to a very substantial likelihood of irreparable misidentification.... The defendant bears the burden of proving both that the identification procedures were unnecessarily suggestive and that the resulting identification was unreliable.” (Internal quotation marks omitted.) State v. Thompson, 81 Conn. App. 264, 269–70, 839 A.2d 622, cert. denied, 268 Conn. 915, 847 A.2d 312 (2004).', 'mbe_265', 0, '184'),
('mbe_333', 'mbe', '333', '194', 'MBE-1978-83-part1', '', '185', 'An act of Congress provides that "no federal court shall order the implementation of a public school desegregation plan that would require the transportation of any student to a school ocher than the school closest or next closest to his place of residence."', 'Which of the following is the strongest argument for the constitutionality of the act?', 'The Fourteenth Amendment authorizes Congress to define governmental conduct which violates the equal protection clause.', 'Under Article III, Congress may restrict the jurisdiction of the federal courts.', 'Transportation of students is subject to regulation by Congress because commerce is involved.', 'Congress provides partial support for public education and is therefore entitled to establish conditions upon the expenditure of federal grants.', 'B', 'Unlike its original jurisdiction, the appellate jurisdiction of the Supreme Court is subject to “exceptions and regulations” prescribed by Congress, and the jurisdiction of the inferior federal courts is subject to congressional prescription. Additionally, Congress has power to regulate modes and practices of proceeding on the part of the inferior federal courts. Whether there are limitations to the exercise of these congressional powers, and what the limitations may be, are matters that have vexed scholarly and judicial interpretation over the years, inasmuch as congressional displeasure with judicial decisions has sometimes led to successful efforts to “curb” the courts and more frequently to proposed but unsuccessful curbs.', 'mbe_2635', 0, '185'),
('mbe_334', 'mbe', '334', '194', 'MBE-1978-83-part1', '', '186', 'An act of Congress provides that "no federal court shall order the implementation of a public school desegregation plan that would require the transportation of any student to a school ocher than the school closest or next closest to his place of residence."', 'Which of the following is the strongest argument against the constitutionality of the act?', 'This statute unduly burdens interstate commerce.', 'Congress cannot limit the authority of federal courts to hear and decide cases properly presented for decision.', 'The privileges and immunities clause of the Fourteenth Amendment prohibits Congress from limiting the forms of relief afforded by federal courts.', 'The courts, not Congress, have the primary responsibility for defining the minimum requirements of the equal protection clause of the Fourteenth Amendment.', 'D', 'Application of the Privileges and Immunities Clause to a particular instance of discrimination against out-of-state residents entails a two-step inquiry. As an initial matter, the court must decide whether the ordinance burdens one of those privileges and immunities protected by the Clause. Baldwin v. Montana Fish and Game Comm''n, 436 U.S. 371, 383, 98 S.Ct. 1852, 1860, 56 L.Ed.2d 354 (1978). Not all forms of discrimination against citizens of other States are constitutionally suspect.
“Some distinctions between residents and nonresidents merely reflect the fact that this is a Nation composed of individual States, and are permitted; other distinctions are prohibited because they hinder the formation, the purpose, or the development of a single Union of those States. Only with respect to those ‘privileges'' and ‘immunities'' bearing upon the vitality of the Nation as a single entity must the State treat all citizens, resident and nonresident, equally.” Ibid.
As a threshold matter, then, we must determine whether an out-of-state resident''s **1028 interest in employment on public works contracts in another State is sufficiently “fundamental” to the promotion of interstate harmony so as to “fall within the purview of the Privileges and Immunities Clause.” Id., at 388, 98 S.Ct., at 1862. See also *219 Canadian Northern Ry. Co. v. Eggen, 252 U.S. 553, 560, 40 S.Ct. 402, 403, 64 L.Ed. 713 (1920); Blake v. McClung, 172 U.S. 239, 248, 19 S.Ct. 165, 169, 43 L.Ed. 432 (1898).', 'mbe_2636', 0, '186'),
('mbe_335', 'mbe', '335', '195', 'MBE-1978-83-part1', '', '187', '', 'Maria is the owner and possessor of Goodacre, on which there is a lumber yard. Maria conveyed to Reliable Electric Company the right to construct and use an overhead electric line across Goodacre to serve other properties. The conveyance was in writing, but the writing made no provision concerning the responsibility for repair or maintenance of the line. Reliable installed the poles and erected the electric line in a proper and workmanlike manner. Neither Maria nor Reliable took any steps toward the maintenance or repair of the line after it was built. Neither party complained to the ocher about any failure to repair. Because of the failure to repair or properly maintain the line, it fell to the ground during a storm. In doing so, it caused a fire in the lumber yard and did considerable damage. Maria sued Reliable Electric Company to recover for damages to the lumber yard. The decision should be for', 'Maria, because the owner of an easement has a duty to so maintain the easement as to avoid unreasonable interference with the use of the servient tenement by its lawful possessor', 'Maria, because the owner of an easement is absolutely liable for any damage caused to the servient tenement by the exercise of the easement', 'Reliable Electric Company, because the possessor of the servient tenement has a duty to give the easement holder notice of defective conditions', 'Reliable Electric Company, because an easement holder''s right to repair is a right for his own benefit, and is therefore inconsistent with any duty to repair for the benefit of another', 'A', 'Generally, the grant of an easement over land does not preclude the grantor from using the land in any manner which does not unreasonable interfere with the special use for which the easement was acquired. Minneapolis Athletic Club v. Cohler, 287 Minn. 254, 177 N.W.2d 786 (1970). This includes the granting of additional easements in the same land. See 25 Am.Jur.2d Easements and Licenses s 89 (1966). The creation of an easement carries with it by implication only such incidents as are necessary for its reasonable enjoyment. The owner of the servient tenement may use the land for any purpose which does not unreasonably interfere with the rights of the owner of the dominant tenement.', 'mbe_266', 0, '187'),
('mbe_336', 'mbe', '336', '196', 'MBE-1978-83-part1', '', '188', 'Sartorial, Inc., a new business enterprise about to commence the manufacture of clothing, entered into a written agreement to purchase all of its monthly requirements of a certain elasticized fabric for a period of three years from the Stretch Company at a specified unit price and agreed delivery and payment terms. The agreement also provided: 1. The parties covenant not to assign this contract. 2. Payments coming due hereunder for the first two months shall be made directly by Sartorial to Virginia Wear and Son, Inc., a creditor of Stretch. Stretch promptly made an "assignment of the contract" to Finance Company as security for a $100,000 loan. Sartorial subsequently ordered, took delivery of, and paid Stretch the agreed price ( $5,000) for Sartorial''s requirement of the fabric for the first month of its operation.', 'Which of the following accurately states the legal effect of the covenant not to assign the contract?', 'The covenant made the assignment to Finance Company ineffective.', 'The covenant had no legal effect.', 'Stretch''s assignment was a breach of its contract with Sartorial but was nevertheless effective to transfer to Finance Company Stretch''s rights against Sartorial.', 'By normal interpretation, a covenant against assignment in a sale-of-goods agreement applies only to the buyer, not the seller.', 'C', 'Anti-assignment clauses, such as this one, are routinely enforced. Conoco, Inc. v. Republic Ins. Co., 819 F.2d 120, 123 (5th Cir.1987); Tex. Farmers Ins. Co. v. Gerdes, 880 S.W.2d 215, 218 (Tex.App.-Fort Worth 1994, writ denied). These clauses are enforceable unless rendered ineffective by an applicable statute, estoppel, waiver, or some other aspect of contract law. Johnson v. Structured Asset Servs., LLC, 148 S.W.3d 711, 721 (Tex.App.-Dallas 2004, no pet.); see Tex. Dev. Co. v. Exxon Mobil Corp., 119 S.W.3d 875, 880 (Tex.App.-Eastland 2003, no pet.).11 “In the absence of a successful attack upon an anti-assignment clause, a party is entitled to have the trial court enforce it.” Johnson, 148 S.W.3d at 721 (citing Tex. Pac. Indem. Co. v. Atl. Richfield Co., 846 S.W.2d 580, 583 (Tex.App.-Houston [14th Dist.] 1993, writ denied)).', 'mbe_2637', 0, '188'),
('mbe_337', 'mbe', '337', '196', 'MBE-1978-83-part1', '', '189', 'Sartorial, Inc., a new business enterprise about to commence the manufacture of clothing, entered into a written agreement to purchase all of its monthly requirements of a certain elasticized fabric for a period of three years from the Stretch Company at a specified unit price and agreed delivery and payment terms. The agreement also provided: 1. The parties covenant not to assign this contract. 2. Payments coming due hereunder for the first two months shall be made directly by Sartorial to Virginia Wear and Son, Inc., a creditor of Stretch. Stretch promptly made an "assignment of the contract" to Finance Company as security for a $100,000 loan. Sartorial subsequently ordered, took delivery of, and paid Stretch the agreed price ( $5,000) for Sartorial''s requirement of the fabric for the first month of its operation.', 'Assume for this question only that the assignment from Stretch to Finance Company was effective, and that Sartorial was unaware of the assignment when it paid Stretch the $5,000. Which of the following is correct?', 'Sartorial is liable to Finance Company for $5,000.', 'Stretch is liable to Finance Company for $5,000.', 'Sartorial and Stretch are each liable to Finance Company for $2,500.', 'Neither Sartorial nor Stretch is liable to Finance Company for any amount.', 'B', 'A covenant against the assignment of a lease without the owner''s consent applies to voluntary assignments and does not include transfers or assignments by operation of law, such as transfers in bankruptcy, execution sales, receiver''s sales, and other transfers in the interests of creditors or lienholders.', 'mbe_2638', 0, '189'),
('mbe_338', 'mbe', '338', '196', 'MBE-1978-83-part1', '', '190', 'Sartorial, Inc., a new business enterprise about to commence the manufacture of clothing, entered into a written agreement to purchase all of its monthly requirements of a certain elasticized fabric for a period of three years from the Stretch Company at a specified unit price and agreed delivery and payment terms. The agreement also provided: 1. The parties covenant not to assign this contract. 2. Payments coming due hereunder for the first two months shall be made directly by Sartorial to Virginia Wear and Son, Inc., a creditor of Stretch. Stretch promptly made an "assignment of the contract" to Finance Company as security for a $100,000 loan. Sartorial subsequently ordered, took delivery of, and paid Stretch the agreed price ( $5,000) for Sartorial''s requirement of the fabric for the first month of its operation.', 'Assume for this question only that the assignment from Stretch to Finance Company was effective, and that Virginia Wear and Son, Inc., did not become aware of the original agreement between Sartorial and Stretch until after Stretch''s acceptance of the $5,000 payment from Sartorial. Which of the following, if any, is (are) correct? I. Virginia Wear and Son, Inc., was an incidental beneficiary of the Sartorial-Stretch agreement. II. Virginia Wear and Son, Inc., has a prior right to Sartorial''s $5,000 payment as against either Stretch or Finance Company.', 'I only', 'II only', 'Both I and I', 'Neither I nor II', 'D', 'An incidental beneficiary is one “who will be benefited by performance of a promise but who is neither a promisee nor an intended beneficiary.” Only donee and creditor beneficiaries have enforceable rights under a contract.', 'mbe_2639', 0, '190'),
('mbe_339', 'mbe', '339', '196', 'MBE-1978-83-part1', '', '191', 'Sartorial, Inc., a new business enterprise about to commence the manufacture of clothing, entered into a written agreement to purchase all of its monthly requirements of a certain elasticized fabric for a period of three years from the Stretch Company at a specified unit price and agreed delivery and payment terms. The agreement also provided: 1. The parties covenant not to assign this contract. 2. Payments coming due hereunder for the first two months shall be made directly by Sartorial to Virginia Wear and Son, Inc., a creditor of Stretch. Stretch promptly made an "assignment of the contract" to Finance Company as security for a $100,000 loan. Sartorial subsequently ordered, took delivery of, and paid Stretch the agreed price ( $5,000) for Sartorial''s requirement of the fabric for the first month of its operation.', 'Assume for this question only that, two weeks after making the $5,000 payment to Stretch, Sartorial by written notice to Stretch terminated the agreement for purchase of the elasticized fabric because market conditions had in fact forced Sartorial out of the clothing manufacture business. In an immediate suit by Finance Company against Sartorial for total breach, which of the following would be useful in Sartorial''s defense?', 'Stretch''s rights under its agreement with Sartorial were personal and therefore nonassignable.', 'Stretch''s "assignment of the contract" to Finance Company to secure a loan would normally be interpreted as a delegation of Stretch''s duties under the contract as well as an assignment of its rights; and its duties, owed to Sartorial, were personal and therefore nondelegable.', 'The original contract between Sartorial and Stretch was unenforceable by either party for want of a legally sufficient consideration for Stretch''s promise to supply Sartorial''s requirements of the elasticized fabric.', 'Sartorial ceased in good faith to have any further requirements for elasticized fabric.', 'D', '“Generally, the buyer in a requirements contract governed by UCC § 2-306(1) is required merely to exercise good faith in determining his requirements and the seller assumes the risk of all good faith variations in the buyer''s requirements even to the extent of a determination to liquidate or discontinue the business.” Id. at 1261. “A requirements contract is one in which the purchaser agrees to buy all of its needs of a specified material exclusively from a particular supplier, and the supplier agrees, in turn, to fill all of the purchaser''s needs during the period of the contract.” Id. at 1259. The good faith requirement imposed under the UCC and Indiana Code section 26-1-2-306, prevents requirements contracts from being illusory or too indefinite to be enforced. Id. at 1260.
From time-to-time, there will be variations in the buyer''s requirements. “The essential ingredient of the buyer''s good faith under such circumstances is that he not merely have had second thoughts about the terms of the contract and want to get out of it.” Id. at 1261. On the other hand, if a buyer has a legitimate business reason for eliminating its requirements, instead of a desire to simply avoid the contract, then the buyer is acting in good faith. Id.', 'mbe_2640', 0, '191'),
('mbe_34', 'mbe', '34', '19', 'MBE-1972-78-part2', '', '35', '', '"A person is not responsible for criminal conduct if at the time of such conduct as a result of mental disease or defect he lacks substantial capacity either to appreciate the wrongfulness of his conduct or to conform his conduct to the requirements of law." This quotation is basically a statement of the', 'M''Naghten Rule', 'right and wrong plus irresistible impulse test', 'Durham Rule', 'Model Penal Code provision', 'D', 'The Model Penal Code presents a distinct formulation of the insanity defense.  Under this test, an individual is not liable for criminal offenses if, when he or she committed the crime or crimes, the individual suffered from a mental disease or defect that resulted in the individual lacking the substantial capacity to appreciate the wrongfulness of his or her actions or to conform his or her actions to requirements under the law.', 'mbe_30', 0, '35'),
('mbe_340', 'mbe', '340', '197', 'MBE-1978-83-part1', '', '192', '', 'Seth owned a vacant lot known as Richacre. Seth entered into a written contract with Bob to build a house of stated specifications on Richacre and to sell the house and lot to Bob. The contract provided for an "inside date" of April 1, 1977, and an "outside date" of May 1, 1977, for completion of the house and delivery of a deed. Neither party tendered performance on the dates stated. On May 3, 1977, Bob notified Seth in writing of Bob''s election to cancel the contract because of Seth''s failure to deliver title by May 1. On May 12, Seth notified Bob that some unanticipated construction difficulties had been encountered but that Seth was entitled to a reasonable time to complete in any event. The notification also included a promise that Seth would be ready to perform by May 29 and that he was setting that date as an adjourned closing date. Seth obtained a certificate of occupancy and appropriate documents of title, and he tendered performance on May 29. Bob refused. Seth brought an action to recover damages for breach of contract. The decision in the case will most likely be determined by whether', 'Seth acted with due diligence in completing the house', 'Bob can prove actual "undue hardship" caused by the delay', 'the expressions "inside date" and "outside date" are construed to make time of the essence', 'there Is a showing of good faith in Bob''s efforts to terminate the contract', 'C', 'To regard a contract as “of the essence,” one of two conditions must be satisfied: either the contract must expressly state that time is of the essence or there must be a clear indication that the parties intended for time to be of the essence. Ferrara, 919 So.2d at 885(¶ 25).  In the absence of either condition, time will not ordinarily be considered of the essence in contract performance. Id. at (¶ 24).', 'mbe_267', 0, '192'),
('mbe_341', 'mbe', '341', '198', 'MBE-1978-83-part1', '', '193', '', 'Metterly, the owner in fee simple of Brownacre by quitclaim deed conveyed Brownacre to her daughter, Doris, who paid no consideration for the conveyance. The deed was never recorded. About a year after the delivery of the deed, Metterly decided that this gift had been ill-advised, She requested that Doris destroy the deed, which Doris dutifully and voluntarily did. Within the month following the destruction of the deed, Metterly and Doris were killed in a common disaster. Each of the successors in interest claimed title to Brownacre. In an appropriate action to determine the title to Brownacre, the probable outcome will be that', 'Metterly was the owner of Brownacre, because Doris was a donee and therefore could not acquire title by quitclaim deed', 'Metterly was the owner of Brownacre, because title to Brownacre reverted to her upon the voluntary destruction of the deed by Doris', 'Doris was the owner of Brownacre, because her destruction of the deed to Brownacre was under the undue influence of Metterly', 'Doris was the owner of Brownacre, because the deed was merely evidence of her title, and its destruction was insufficient to cause title to pass back to Metterly', 'D', 'The destruction of a deed of conveyance by or at the instance of the grantee does not reinvest the grantor with the legal title.', 'mbe_268', 0, '193'),
('mbe_342', 'mbe', '342', '199', 'MBE-1978-83-part1', '', '194', 'Motorist arranged to borrow his friend Owner''s car to drive for one day while Motorist''s car was being repaired. Owner knew that the brakes on his car were faulty and might fail in an emergency. Owner forgot to tell Motorist about the brakes when Motorist picked up the car, but Owner did telephone Spouse, Motorist''s wife, and told her about them. Spouse, however, forgot to tell Motorist. Motorist was driving Owner''s car at a reasonable rate of speed and within the posted speed limit, with Spouse as passenger. Another car, driven by Cross, crossed in front of Motorist at an intersection and in violation of the traffic signal. Motorist tried to stop, but the brakes failed, and the two cars collided. If the brakes had been in proper working order, Motorist could have stopped in time to avoid the collision. Motorist and Spouse were injured.', 'If Motorist asserts a claim against Cross, Motorist will', 'recover the full amount of his damages, because Motorist himself was not at fault', 'recover only a proportion of his damages, because Spouse was also at fault', 'not recover, because Spouse was negligent and a wife''s negligence is imputed to her husband', 'not recover, because the failure of the brakes was the immediate cause of the collision', 'A', 'To sustain the allegation in the petition that defendant negligently furnished a car that was defective and unsafe, the plaintiff would be required to prove the fact that the car was unsafe; and, also, the fact that defendant either knew, or by ordinary care, might have known of the defect, because without such proof the charge of negligence would be unsustained. The charge that defendant negligently furnished a defective and unsafe car, stating wherein it was defective, is as broad as if the charge had been that the defendant furnished such car, which it either knew, or might have known by due care, was defective and unsafe. In either case he would have to make the same proof.', 'mbe_269', 0, '194'),
('mbe_343', 'mbe', '343', '199', 'MBE-1978-83-part1', '', '195', 'Motorist arranged to borrow his friend Owner''s car to drive for one day while Motorist''s car was being repaired. Owner knew that the brakes on his car were faulty and might fail in an emergency. Owner forgot to tell Motorist about the brakes when Motorist picked up the car, but Owner did telephone Spouse, Motorist''s wife, and told her about them. Spouse, however, forgot to tell Motorist. Motorist was driving Owner''s car at a reasonable rate of speed and within the posted speed limit, with Spouse as passenger. Another car, driven by Cross, crossed in front of Motorist at an intersection and in violation of the traffic signal. Motorist tried to stop, but the brakes failed, and the two cars collided. If the brakes had been in proper working order, Motorist could have stopped in time to avoid the collision. Motorist and Spouse were injured.', 'If the jurisdiction has adopted "pure" comparative negligence and Spouse asserts a claim against Cross, Spouse will', 'recover in full for her injuries, because Motorist, who was driving the car in which she was riding, was not himself at fault', 'recover a proportion of her damages based on the respective degrees of her negligence and that of Cross', 'not recover, because but for the failure of the brakes the collision would not have occurred', 'not recover, because she was negligent and her negligence continued until the moment of impact', 'B', '“Comparative negligence” means a failure to do an act that a reasonably careful person would do, or the doing of an act that a reasonably careful person would not do, under the same or similar circumstances, to protect himself or herself from bodily injury.', 'mbe_270', 0, '195'),
('mbe_344', 'mbe', '344', '199', 'MBE-1978-83-part1', '', '196', 'Motorist arranged to borrow his friend Owner''s car to drive for one day while Motorist''s car was being repaired. Owner knew that the brakes on his car were faulty and might fail in an emergency. Owner forgot to tell Motorist about the brakes when Motorist picked up the car, but Owner did telephone Spouse, Motorist''s wife, and told her about them. Spouse, however, forgot to tell Motorist. Motorist was driving Owner''s car at a reasonable rate of speed and within the posted speed limit, with Spouse as passenger. Another car, driven by Cross, crossed in front of Motorist at an intersection and in violation of the traffic signal. Motorist tried to stop, but the brakes failed, and the two cars collided. If the brakes had been in proper working order, Motorist could have stopped in time to avoid the collision. Motorist and Spouse were injured.', 'If Motorist asserts a claim against Owner, will Motorist prevail?', 'Yes, in negligence, because Owner knew the brakes were faulty and failed to tell Motorist.', 'Yes, in strict liability in tort, because the car was defective and Owner lent it to Motorist.', 'No, because Owner was a gratuitous lender, and thus his duty of care was slight.', 'No, because the failure of Spouse to tell Motorist about the brakes was the cause in fact of Motorist''s harm.', 'A', 'A duty of care may arise from four sources: “(1) legislative enactments or administration regulations; (2) judicial interpretations of such enactments or regulations; (3) other judicial precedent; and (4) a duty arising from the general facts of the case.” Clay Elec. Co–op., Inc. v. Johnson, 873 So.2d 1182, 1185 (Fla. 2003) (quoting McCain, 593 So.2d at 503 n.2).', 'mbe_271', 0, '196'),
('mbe_345', 'mbe', '345', '200', 'MBE-1978-83-part1', '', '197', '', 'In which of the following situations is Defendant most likely to be guilty of larceny?', 'Defendant took Sue''s television set, with the intention of returning it the next day. However, he dropped it and damaged it beyond repair.', 'Defendant went into Tom''s house and took $100 in the belief that Tom had damaged Defendant''s car to that amount.', 'Mistakenly believing that larceny does not include the taking of a dog, Defendant took his neighbor''s dog and sold it.', 'Unreasonably mistaking George''s car for his own, Defendant got into George''s car in a parking lot and drove it home.', 'C', 'The general larceny statute, G.L. c. 266, § 30, merges into one statutory crime “three common-law crimes of ‘stealing’ ”: larceny by theft, larceny by embezzlement, and larceny by false pretense. Commonwealth v. Mills, 436 Mass. 387, 391–392, 764 N.E.2d 854 (2002). “Larceny can be established by evidence that would have warranted a conviction upon any one of the three formerly separate charges.” Id. at 392, 764 N.E.2d 854.', 'mbe_272', 0, '197'),
('mbe_346', 'mbe', '346', '201', 'MBE-1978-83-part1', '', '198', '', 'Acting on an anonymous telephone call, police went to Desmond''s apartment, knocked on the door, and demanded to search it for narcotics. When Desmond refused, the police forced the door open and placed him under arrest. As they were removing him from the apartment, Desmond offered to give the officers "valuable information" in exchange for his release. Before he could say anything else, Desmond was given Miranda warnings by the police. Thereafter he told the police that he had stored some heroin in his friend''s apartment and that he and his friend had been going to sell it. The heroin was recovered, and Desmond was prosecuted for conspiracy to sell narcotics and for possession of narcotics. At his trial, Desmond moved to suppress his statements. Which of the following is Desmond''s best argument in support of the motion to suppress?', 'Desmond is entitled to know the identity of his accuser, and the state cannot supply this information.', 'The police should have given Desmond Miranda warnings prior to entry into the apartment, and the warnings were ineffectual once Desmond offered to give the police information.', 'Desmond was intimidated by the forced entry into the apartment, and since the statements were involuntary and coerced, their use against him would violate due process of law.', 'The statements were fruits of an unlawful arrest, and though the Miranda warnings may have been sufficient to protect his right against self-incrimination, they were not sufficient to purge the taint of the illegal arrest.', 'D', 'In Brown, the United States Supreme Court enunciated the following factors to be considered in determining whether the taint of an unlawful arrest has been sufficiently attenuated to justify admission of evidence seized in connection with the tainted arrest:
· whether Miranda warnings were given;
· the temporal proximity of the arrest and the evidence;
· the presence of intervening circumstances; and
· the purpose and flagrancy of the official misconduct.
Brown, 422 U.S. at 603–04, 95 S.Ct. at 2261–62; Dowthitt v. State, 931 S.W.2d 244, 261 (Tex.Crim.App.1996).', 'mbe_273', 0, '198'),
('mbe_347', 'mbe', '347', '202', 'MBE-1978-83-part1', '', '199', 'Kane, a member of the legislature of State, is prosecuted in federal court for a violation of the Federal Securities Act arising out of the activities of a state-owned corporation. Kane''s defense includes a claim that the alleged wrongful acts were committed in the course of legislative business and are immune from scrutiny.', 'Which of the following is the strongest constitutional argument supporting Kane?', 'Because of doctrines of federalism, federal law generally cannot be applied to state legislators acting in the course of their official duties.', 'State legislators enjoy the protection of the speech and debate clause of the United States Constitution.', 'A federal court must follow state law respecting the scope of legislative immunity.', 'To apply the Federal Securities Act to state legislators would violate the due process clause.', 'A', 'Federalism is a bedrock of our Constitution and political system. But the division of power between federal and state governments remains controversial despite its long history. Consider the present debate over the U.S. Senate and the system for electing the president, which give disproportionate power to states with smaller populations. In white-collar criminal law, principles of federalism have influenced how the Supreme Court has interpreted the broadly-worded mail and wire fraud statutes, particularly in prosecutions of state and local officials, as we have previously discussed. See, e.g., Elkan Abramowitz & Jonathan Sack, Limits on the Scope of Honest Services Fraud, N.Y.L.J., Nov. 7, 2017. The Supreme Court has expressed reservations about federal prosecutors becoming excessively involved in the regulation of state and local political behavior.

In its present term, the Supreme Court will hear an appeal arising from the controversy known as “Bridgegate”: the politically-motivated closure in 2013 of two lanes on the George Washington Bridge that served Fort Lee, N.J. The government alleged that defendants Bridget Kelly and William Baroni Jr. ordered the lanes closed for political reasons which they concealed by falsely saying the closure was part of a “traffic study.” The Supreme Court granted certiorari to decide the defendants’ claim that the federal wire fraud statute should not be held to extend to the sharp-elbowed local politics underlying the prosecution. After describing the factual and legal background, we discuss the arguments of the defense and the government in the Supreme Court. These arguments touch directly on the proper reach of federal criminal law into the realm of local politics', 'mbe_274', 0, '199'),
('mbe_348', 'mbe', '348', '202', 'MBE-1978-83-part1', '', '200', 'Kane, a member of the legislature of State, is prosecuted in federal court for a violation of the Federal Securities Act arising out of the activities of a state-owned corporation. Kane''s defense includes a claim that the alleged wrongful acts were committed in the course of legislative business and are immune from scrutiny.', 'Which of the following is the strongest argument against Kane''s constitutional defense?', 'Congress has plenary power under the commerce clause.', 'Congress may impose liability on state legislators as a means of guaranteeing a republican form of government.', 'Congress does not significantly interfere with state government by applying this law to state legislators.', 'Congress may impose liability on state legislators by virtue of the necessary and proper clause.', 'C', 'The U.S. Constitution establishes a system of dual sovereignty between the states and the federal government, with each state having its own government, endowed with all the functions essential to separate and independent existence. Although the Supremacy Clause of the Constitution designates “the Laws of the United States” as “the supreme Law of the Land,” other provisions of the Constitution—as well as legal principles undergirding those provisions—nonetheless prohibit the national government from enacting certain types of laws that impinge upon state sovereignty. The various principles that delineate the proper boundaries between the powers of the federal and state governments are collectively known as “federalism.” Federalism-based restrictions that the Constitution imposes on the national government’s ability to enact legislation may inform Congress’s work in any number of areas of law in which the states and the federal government dually operate. There are two central ways in which the Constitution imposes federalism-based limitations on Congress’s powers. First, Congress’s powers are restricted by and to the terms of express grants of power in the Constitution, which thereby establish internal constraints on the federal government’s authority. The Constitution explicitly grants Congress a limited set of carefully defined enumerated powers, while reserving most other legislative powers to the states. As a result, Congress may not enact any legislation that exceeds the scope of its limited enumerated powers. That said, Congress’s enumerated powers nevertheless do authorize the federal government to enact legislation that may significantly influence the scope of power exercised by the states. For instance, subject to certain restrictions, Congress may utilize its taxing and spending powers to encourage states to undertake certain types of actions that Congress might otherwise lack the constitutional authority to undertake on its own. Similarly, the Supreme Court has interpreted the Constitution’s Commerce Clause to afford Congress substantial (but not unlimited) authority to regulate certain purely intrastate economic activitiesthat substantially affect interstate commerce in the aggregate. Congress may also enact certain types of legislation in order to implement international treaties. Additionally, pursuant to a collection of constitutional amendments ratified shortly after the Civil War, Congress may directly regulate the states in limited respects in order to prevent states from depriving persons of certain procedural and substantive rights. Finally, the Necessary and Proper Clause augments Congress’s enumerated powers by empowering the federal government to enact laws that are “necessary and proper” to execute its express powers.', 'mbe_275', 0, '200'),
('mbe_349', 'mbe', '349', '203', 'MBE-1978-83-part5', '', '1', 'By way of a gift, Pat executed a deed naming his daughter, Marian, as grantee. The deed contained descriptions as follows: (1) All of my land and dwelling known as 44 Main Street, Midtown, United States, being one acre. (2) All that part of my farm, being a square with 200foot sides, the southeast corner of which is in the north line of my neighbor, Julia Brown. The deed contained covenants of general warranty, quiet enjoyment, and right to convey. Pat handed the deed to Marian who immediately returned it to her father for safekeeping. Her father kept it in his safe deposit box. The deed was not recorded. The property at 44 Main Street covered 7/8 of an acre of land, had a dwelling and a garage situate thereon, and was subject to a right of way, described in prior deeds, in favor of Jack, a neighbor. Pat owned no other land on Main Street. Jack had not used the right of way for ten years and it was not visible on inspection of the property.', 'The description of 44 Main Street was', 'sufficient, because the discrepancy in area is not fatal', 'not sufficient, because it contained no metes and bounds', 'Not sufficient, because the acreage given was not correct', 'Not sufficient, because a deed purporting to convey more than a grantor owns is void ab initio', 'A', 'The plaintiffs claim that the words “more or less” contained in the description of the acreage of the Fall Swamp lot in the various deeds covered the discrepancy between thirty acres as contained in the deeds and 62.7 acres as indicated on the Clark survey and again on the Waldo survey. The use of the language “more or less,” however, has been held to cover only slight discrepancies and irregularities and not substantial discrepancies, especially when the “more or less” is used in connection with an acreage discrepancy. A discrepancy in acreage of that extent is not protected by the “more or less” language. Ferrigno v. Odell, 113 Conn. 420, 155 A. 639 (1931); Russo v. Corideo, 102 Conn. 663, 129 A. 849 (1925).', 'mbe_276', 0, '1'),
('mbe_35', 'mbe', '35', '20', 'MBE-1972-78-part2', '', '36', 'Oscar, the owner in fee simple, laid out a subdivision of 325 lots on 150 acres of land. He obtained governmental approval (as required by applicable ordinances) and, between 1968 and 1970, he sold 140 of the lots, inserting in each of the 140 deeds the following provision: "The Grantee, for himself and his heirs, assigns and successors, covenants and agrees that the premises conveyed herein shall have erected thereon one single-family dwelling and that no other structure (other than a detached garage normally incident to a single-family dwelling) shall be erected or maintained; and, further, that no use shall ever be made or permitted to be made than occupancy by a single family for residential purposes only." Because of difficulty encountered in selling the remaining lots for single family use, in January, 1971, Oscar advertised the remaining lots with prom inent emphasis: " These lots are not subject to any restrictions and purchasers will find them adaptable to a wide range of uses."', 'Payne had purchased one of the 140 lots and brought suit against Oscar to establish that the remaining 185 lots, as well as the 140 sold previously, can be used only for residential purposes by single families. Assuming that procedural requirements have been met to permit adjudication of the issue Payne has tendered, which of the following is the most appropriate comment?', 'Oscar should win because the provision binds only the grantee.', 'The outcome turns on whether a common development scheme had been established for the entire subdivision.', 'The outcome turns on whether there are sufficient land areas devoted to multiple-family uses within the municipality to afford reasonable opportunity for all economic classes to move into the area so as to satisfy the standards of equal protection of the law.', 'Payne should win under an application of the doctrine which requires construction of deeds to resolve any doubt against the grantor.', 'B', 'A scheme by which an owner of a defined area of land divides it up into a number of separate lots for sale (or lease) and imposes on the purchasers (or lessors) restrictions as to the use and development of the land by means of uniform covenants restricting the use to which the grantees may put the lots, with the express intention that the area as a whole, and each and every lot, will benefit thereby. For example, a scheme that restricts the development of each lot to a single-family residence and requires that all buildings are to be erected and maintained in general conformity with a set of rules that are imposed on all purchasers. A scheme of development establishes a form of ''local law'' by which the development and management of the land is controlled for the benefit of all the purchasers and their successors. The essential aim of the scheme is that each purchaser will have the benefit of the same restrictions as those to which he has been subjected (Besch v. Hyman, 221 App Div 455, 223 NYS 233 (1927); Snow v. Van Dam, 291 Mass 477, 197 N.E. 224 (1935); Re Dolphin''s Conveyance [1970] Ch 654, 662, [1970] 2 All ER 664; Brunner v Greenslade [1971] Ch 993, 1003, [1970] 3 All ER 836; Texaco Antilles Ltd v Kernochan [1973] AC 609, [1973] 2 All ER 118 (PC)).
In order to be able to enforce the provisions of a scheme of development each purchaser of an area of land (or his successor), as well as the common vendor, must have a right to enforce the restrictions for his own benefit (technically by suing for breach of a negative or restrictive covenant), and by the same token, must accept the burdens imposed on his use of the land. Thus, "reciprocity is the foundation of the idea of a scheme … [and a purchaser] must know both the extent of his burden and the extent of his benefit", Reid v Bickerstaff [1909] 2 Ch 305, 319, [1908-10] All ER Rep 298 (CA) (Re Palmer v Reesor (1914) 6 OWN 622, 624 (Can)) (in the US called the ''doctrine of reciprocal negative easement''). The reciprocal benefits and burdens are referred to as ''equitable servitudes'' (as they are rights originating from the English Court of Equity—Tulk v Moxhay (1848) 2 Ph 774, 41 Eng Rep 1143) (Trustees of Columbia College v. Lynch, 70 NY 440 (1877); Allen v. Detroit, 167 Mich 464, 133 N.W. 317, 319 (1911); Weigman v. Kusel, 270 Ill 520, 110 N.E. 884 (1915)).
In common law, as a rule, a scheme of development requires five conditions to be satisfied for there to be the ''mutuality of enforcement'', that is an essential element of the scheme: (i) the area to which the scheme applies must be clearly defined (Reid v Bickerstaff, supra; Whitgift Homes Ltd v Stocks [2001] EWCA Civ 1732, [2001] 48 EG 130 (CA)); (ii) any of the parties seeking to enforce the scheme must have derived title to the land from a common vendor (or from a successor in title who is bound in equity to the common vendor); (iii) that prior to selling the land the common vendor must have laid out the area for sale in lots with the intention that the restrictions, drawn up in accordance with a common plan, would be imposed on the use and development of all the plots; (iv) each purchaser must have accepted the restrictions on the understanding that similar restrictions would be imposed on each and every purchaser of any one of the lots; and (v) the restrictions must be intended by the vendor to be, and are, imposed for the benefit of each and every plot (although the restrictions imposed on each plot need not be identical: Elliston v Reacher [1909] 2 Ch 384; Allen v Veranne Builders Ltd [1988] NPC 11; Sanborn v. McLean, 233 Mich 227, 206 N.W. 496, 60 ALR 1212 (1925); Anno: 4 ALR2d 1364, 1369: General Plan of Subdivision—Notice; Cash v. Granite Springs Retreat Ass''n, Inc., 2011 WY 25, 248 P.3d 614 (WYO 2011)). However, a scheme of development is likely to bind any owner of land on the estate where: (i) it is clear that the common vendor''s intention was to impose substantially the same restrictions on all the plots in the defined area; (ii) the purchasers acquired their plots on the understanding that the ''laws'' of the estate would be binding on them and would benefit the entire estate; and (iii) it was intended that the purchasers would have reciprocal rights to enforce the law against the other owners (Re Wembley Park Estate Co Ltd''s Transfer [1968] Ch 491, [1968] 1 All ER 457; Eagling v Gardner [1970] 2 All ER 838; The American Law Institute, Restatement of Property (St. Paul, MN: 1944), § 541; Wichmeyer v. Finch, 231 Ind 282, 107 N.E.2d 661, 665 (1952); Cf. Steinmann v. Silverman, 14 NY.2d 243, 251 NYS.2d 1, 200 N.E.2d 192 (1964) where there was no "common scheme" with respect to the covenants). "The material thing I [Greene M.R.] think is that every purchaser … must know when he buys what are the regulations to which he is subjecting himself, and what are the regulations to which other purchasers on the estate will be called upon to subject themselves", White v Bijou Mansions Ltd [1938] Ch 351, 361, [1938] 1 All ER 546 (CA). A scheme of development may apply in the same way if the land is sold on long-term ground leases.', 'mbe_31', 0, '36'),
('mbe_350', 'mbe', '350', '203', 'MBE-1978-83-part5', '', '2', 'By way of a gift, Pat executed a deed naming his daughter, Marian, as grantee. The deed contained descriptions as follows: (1) All of my land and dwelling known as 44 Main Street, Midtown, United States, being one acre. (2) All that part of my farm, being a square with 200foot sides, the southeast corner of which is in the north line of my neighbor, Julia Brown. The deed contained covenants of general warranty, quiet enjoyment, and right to convey. Pat handed the deed to Marian who immediately returned it to her father for safekeeping. Her father kept it in his safe deposit box. The deed was not recorded. The property at 44 Main Street covered 7/8 of an acre of land, had a dwelling and a garage situate thereon, and was subject to a right of way, described in prior deeds, in favor of Jack, a neighbor. Pat owned no other land on Main Street. Jack had not used the right of way for ten years and it was not visible on inspection of the property.', 'The description of part of Pat''s farm', 'is sufficient if consideration has been paid', 'is sufficient because no ambiguity therein appears on the face of the deed', 'could be enforced if the deed contained a covenant of seisin', 'is insufficient because of vagueness', 'D', 'Deed which did not fix beginning point or any of boundaries held too vague to admit of parol evidence to fit description to thing intended to be conveyed, and hence indefinite descriptions statute was inapplicable (C.S. § 992).', 'mbe_277', 0, '2'),
('mbe_351', 'mbe', '351', '204', 'MBE-1978-83-part5', '', '3', 'Questions 3-4 are based on the following statute. VEHICULAR MANSLAUGHTER. Whoever in the course of driving a motor vehicle as defined in the Vehicle Code is criminally negligent in driving such vehicle or omits to do anything that is his duty to do and shows a wanton and reckless disregard for the safety of other persons and as a result of such act or omission causes the death of a human being is guilty of vehicular manslaughter. Vehicular manslaughter is punishable by a sentence of not more than 10 years in the state prison or not more than one year in the county jail.', 'Defendant, driving along at a reasonable rate of speed, was distracted by a child carrying a silver balloon. He went through a boulevard stop light and hit and killed a pedestrian. He is charged with vehicular manslaughter. Of the following proposed definitions of criminal negligence, which is most favorable to the defendant?', 'Criminal negligence is something more than the slight negligence necessary to support a civil action for damages. It means disregard for the consequences of the act and indifference to rights of others.', 'Any person who drives a motor vehicle should realize the danger to others. If he fails to respond to surrounding circumstances, he is criminally negligent. Criminal negligence involves reckless disregard for the lives or safety of others.', 'To find the defendant guilty of criminal negligence, the jury must find as a fact that he intentionally did something he should not have done or intentionally failed to do something which he should have done under circumstances that demonstrate a conscious disregard of a known danger that his conduct would produce the result which it did produce.', 'Criminal negligence is something more than the slight negligence usually required for tort liability. It is something less than the wanton misconduct required for civil liability under the guest statute. It is, of course, conduct that demonstrates something less than the abandoned and malignant heart required for murder.', 'C', 'Criminal negligence exists when, although neither specific nor general criminal intent is present, there is such a disregard of the interest of the others that the offender''s conduct amounts to a gross deviation below the standard of care expected to be maintained by a reasonably careful man under like circumstances. Unlike general or specific criminal intent, criminal negligence is essentially negative. Rather than requiring the accused to intend some consequence of his actions, criminal negligence is found from the accused''s gross disregard for the consequences of his actions. La. R.S. 14:11; State v. Martin, 539 So.2d 1235 (La.1989).', 'mbe_278', 0, '3'),
('mbe_352', 'mbe', '352', '204', 'MBE-1978-83-part5', '', '4', 'Questions 3-4 are based on the following statute. VEHICULAR MANSLAUGHTER. Whoever in the course of driving a motor vehicle as defined in the Vehicle Code is criminally negligent in driving such vehicle or omits to do anything that is his duty to do and shows a wanton and reckless disregard for the safety of other persons and as a result of such act or omission causes the death of a human being is guilty of vehicular manslaughter. Vehicular manslaughter is punishable by a sentence of not more than 10 years in the state prison or not more than one year in the county jail.', 'In a particular jurisdiction there are no statutory standards for the amount of alcohol required to be in the blood to create a presumption that a person is under the influence of alcohol. Defendant, an alcoholic, while driving his motor vehicle, collided with another vehicle. A passenger was killed. Defendant is charged with vehicular manslaughter. Experts will testify that a person with blood alcohol of 0.00 to 0.05 per cent is not under the influence. From 0.05 to 0.10 per cent he may be under the influence. Most of those with 0.10 to 0.15 per cent are under the influence. All of those with over 0.15 per cent are under the influence. Defendant consented to and was given a blood alcohol test 60 minutes after the accident. The test showed 0.11 per cent alcohol. Of the following, what is Defendant''s most appropriate argument to the jury?', 'Assuming the jury finds that the Defendant was driving under the influence of alcohol, they cannot convict him if he lacked the capacity to have the mental state of criminal negligence.', 'The results of the blood tests were improperly admitted in evidence because there are no statutory standards for the interpretation of such tests.', 'The blood test should merely be one factor in the jury''s determination along with such things as the police officers'' opinion as to sobriety.', 'AnN statute which makes it a crime to kill someone while under the influence of alcohol is unconstitutional: alcoholism is a disease and cannot be punished any more than narcotic addiction.', 'C', '“Our case law provides that [a] person operates a motor vehicle within the meaning of [§ 14-227a], when in the vehicle he intentionally does any act or makes use of any mechanical or electrical agency which alone or in sequence will set in motion the motive power of the vehicle.” (Internal quotation marks omitted.) State v. Bereis, 117 Conn. App. 360, 366, 978 A.2d 1122 (2009). “Nothing in our definition of operation requires the vehicle to be in motion or its motor to be running.... The act of inserting the key into the ignition and the act of turning the key within the ignition are preliminary to starting the vehicle''s motor. Each act, in sequence with other steps, will set in motion the motive power of the vehicle.... Each act therefore constitutes operation of the vehicle under the definition set forth in [State v.] Swift, [125 Conn. 399, 6 A.2d 359 (1939) ]. See, e.g., State v. Jones, 2 Conn. Cir. Ct. 605, 607, 203 A.2d 447 (1964) (attempting to start engine constitutes operation, even if motor fails to catch).” (Citations omitted; internal quotation marks omitted.) State v. Haight, 279 Conn. 546, 552–53, 903 A.2d 217 (2006).', 'mbe_279', 0, '4'),
('mbe_353', 'mbe', '353', '205', 'MBE-1978-83-part5', '', '5', 'Dann, who was charged with the crime of assaulting Smith, admitted striking Smith but claimed to have acted in self-defense when he was attacked by Smith, who was drunk and belligerent after a football game.', 'Dann offered testimony of Employer, that he had known and employed Dann for twelve years and knew Dann''s reputation among the people with whom he lived and worked to be that of a peaceful, law-abiding, nonviolent person. The trial judge should rule this testimony', 'admissible, because relevant to show the improbability of Dann''s having committed an unprovoked assault', 'admissible, because relevant to a determination of the extent of punishment if Dann is convicted', 'not admissible, because whether Dann is normally a person of good character is irrelevant to the specific charge', 'not admissible, because irrevelant without a showing that Employer was one of the persons among whom Dann lived and worked', 'A', 'Evidence is logically relevant if “it tends to make the existence of any consequential fact more or less probable, or if it tends to corroborate evidence which itself is relevant and bears on the principal issue of the case.” Hesse v. Mo. Dept. Corr., 530 S.W.3d 1, 5 (Mo. App. W.D. 2017). Evidence is legally relevant if “its probative value outweighs any prejudicial effect on the jury.” Id.', 'mbe_280', 0, '5'),
('mbe_354', 'mbe', '354', '205', 'MBE-1978-83-part5', '', '6', 'Dann, who was charged with the crime of assaulting Smith, admitted striking Smith but claimed to have acted in self-defense when he was attacked by Smith, who was drunk and belligerent after a football game.', 'On cross-examination of Employer (Dann''s), the state''s attorney asked Employer if he had heard that Dann often engaged in fights and brawls. The trial judge should rule the question', 'not objectionable, because evidence of Dann''s previous fights and brawls may be used to prove his guilt', 'not objectionable, because it tests Employer''s knowledge of Dann ''s reputation', 'objectionable, because it seeks to put into evidence separate, unrelated offenses', 'Objectionable, because no specific time or incidents are specified and inquired about', 'B', 'Where objectionable and improper questions on cross-examination show consistent pattern apparently designed to prejudice witness in minds of jury, judge might properly interrupt cross-examination and declare mistrial or reprove counsel.', 'mbe_281', 0, '6'),
('mbe_355', 'mbe', '355', '205', 'MBE-1978-83-part5', '', '7', 'Dann, who was charged with the crime of assaulting Smith, admitted striking Smith but claimed to have acted in self-defense when he was attacked by Smith, who was drunk and belligerent after a football game.', 'Dann''s friend Frank was called to testify that Smith had a reputation among the people with whom he lived and worked for lawbreaking and frequently engaging in brawls. The trial judge should rule the testimony', 'admissible to support Dann''s theory of self-defense, touching on whether Dann or Smith was the aggressor', 'admissible if Frank testifies further as to specific acts of misconduct on Smith''s part of which Frank has personal knowledge', 'inadmissible on the question of Dann''s guilt because Dann, not Smith, is on trial', 'inadmissible, because Frank failed to lay a proper foundation', 'A', 'Reliance by the jury on one witness''s view of another witness''s reputation for truthfulness is fraught with similar concerns. Although permitted by Rule 608(a), such evidence may be introduced only after the proponent has laid a proper foundation. This means that it must be established that the reputation witness possesses a sufficient basis of knowledge such that the reputation evidence may be considered to be reliable. For this foundational predicate we require the following: the individual''s reputation must be held generally in a community of significant size; it must be developed over enough time to truly reflect character for truthfulness; and it must be based on the need of the members of the community to deal with the individual on a frequent basis. See United States v. Bedonie, 913 F.2d 782, 802 (10th Cir.1990), cert. denied, 501 U.S. 1253, 111 S.Ct. 2895, 115 L.Ed.2d 1059 (1991); State v. Mazerolle, 614 A.2d 68, 73 (Me.1992); State v. Land, 121 Wash.2d 494, 851 P.2d 678, 681 (1993); see generally Kelly, 312 A.2d at 908.', 'mbe_282', 0, '7'),
('mbe_356', 'mbe', '356', '206', 'MBE-1978-83-part5', '', '8', 'Motorco is a manufacturer of motor vehicles. A federal regulation requires that all motor vehicles manufactured for sale in the United States be equipped with seat belts for each passenger and prescribes specifications for such belts. Motorco equipped all its cars with seat belts. It purchased all the bolts used in its seat belt assemblies from Boltco and it tested samples from each shipment received. Dunn purchased a motor vehicle manufactured by Motorco. While operating the car, with Price as a passenger in the front seat, Dunn collided with another vehicle. The collision was due solely to Dunn''s negligence. Price had his seat belt fastened, but one of the bolts which anchored the belt to the frame broke. Price was thrown through the windshield, sustaining various injuries. Dunn, whose belt was fastened and held, was killed when, following the collision, the car went off the road, down an embankment, and overturned. Subsequent to the accident, tests of the bolt that broke showed metallurgical defects. Motorco''s records showed that tests of samples from the shipment in which the defective bolt was received revealed no defective bolts.', 'If there is a guest law in the state where the accident happened, then in any action by Price against Motorco, that guest statute has which of the following effects?', 'It bars recovery by Price.', 'It bars recovery by Price unless he can prove that Dunn was guilty of more than ordinary negligence.', 'It bars recovery by Price unless he can prove that Motorco was guilty of more than ordi. nary negligence.', 'It is not relevant.', 'D', 'Ordinary negligence is “the act or omission which a person of ordinary prudence would do or fail to do under like circumstances or conditions....” Nist, 67 Wash.2d at 331, 407 P.2d 798. There is no issue of gross negligence without “substantial evidence of serious negligence.” Nist, 67 Wash.2d at 332, 407 P.2d 798.', 'mbe_283', 0, '8'),
('mbe_357', 'mbe', '357', '206', 'MBE-1978-83-part5', '', '9', 'Motorco is a manufacturer of motor vehicles. A federal regulation requires that all motor vehicles manufactured for sale in the United States be equipped with seat belts for each passenger and prescribes specifications for such belts. Motorco equipped all its cars with seat belts. It purchased all the bolts used in its seat belt assemblies from Boltco and it tested samples from each shipment received. Dunn purchased a motor vehicle manufactured by Motorco. While operating the car, with Price as a passenger in the front seat, Dunn collided with another vehicle. The collision was due solely to Dunn''s negligence. Price had his seat belt fastened, but one of the bolts which anchored the belt to the frame broke. Price was thrown through the windshield, sustaining various injuries. Dunn, whose belt was fastened and held, was killed when, following the collision, the car went off the road, down an embankment, and overturned. Subsequent to the accident, tests of the bolt that broke showed metallurgical defects. Motorco''s records showed that tests of samples from the shipment in which the defective bolt was received revealed no defective bolts.', 'In a negligence action by Price against Motorco, the proof needed to establish a prima facie case is', 'only that the bolt was defective', 'that the bolt was defective and had not been inspected by Motorco', 'that the bolt was defective, was inspected by Motorco, and the defect was not discovered', 'that the bolt was defective and the defect would have been discovered in Motorco had exercised reasonable care in the inspection of component parts', 'D', 'Where a manufacturing defect causes an accident and the dealer has prior notice of difficulties apparently relating to the defect with an opportunity to discover and correct the defect, in order to avoid liability for damages occasioned by the defect the dealer has the burden of showing he made reasonable and adequate efforts to discover the source of the difficulties and that the defect could not be discovered in spite of such efforts.', 'mbe_284', 0, '9'),
('mbe_358', 'mbe', '358', '206', 'MBE-1978-83-part5', '', '10', 'Motorco is a manufacturer of motor vehicles. A federal regulation requires that all motor vehicles manufactured for sale in the United States be equipped with seat belts for each passenger and prescribes specifications for such belts. Motorco equipped all its cars with seat belts. It purchased all the bolts used in its seat belt assemblies from Boltco and it tested samples from each shipment received. Dunn purchased a motor vehicle manufactured by Motorco. While operating the car, with Price as a passenger in the front seat, Dunn collided with another vehicle. The collision was due solely to Dunn''s negligence. Price had his seat belt fastened, but one of the bolts which anchored the belt to the frame broke. Price was thrown through the windshield, sustaining various injuries. Dunn, whose belt was fastened and held, was killed when, following the collision, the car went off the road, down an embankment, and overturned. Subsequent to the accident, tests of the bolt that broke showed metallurgical defects. Motorco''s records showed that tests of samples from the shipment in which the defective bolt was received revealed no defective bolts.', 'In a negligence action by Price against Motorco, the negligence of Dunn will be considered to be', 'within the risk created by the action of Motorco', 'the proximate cause of Price''s injuries', 'the legal cause of Price''s injuries', 'an independent, intervening cause of Price''s injuries', 'A', 'The difficulty lies in the meaning to be assigned to foreseeable risk.  It has been noted that in determining whether certain events are within the risk created, the courts have been compelled of necessity to resort to hindsight rather than foresight. Restatement (Second) of Torts, § 281 comment g (1965). A post hoc step by step analysis, however, can render “foreseeable” almost anything that has in fact occurred. Cf. Petition of Kinsman Transit Company, 338 F.2d 708, 723 (1964). The courts have thus defined the foreseeable risk broadly:
Not only is the concept of foreseeability itself elastic and capable of expansion, but also it is generally recognized that the particular manner in which the injury is brought about need not be foreseeable by any test. It has been well said, “The fact is, that the consequences of negligence are almost invariably surprises.” This concept is an antidote to the requirement that plaintiff be injured by one of the dangers or risks that made defendant''s conduct negligent. There is often no hard and fast line between the risk or hazard (which must be foreseeable) and the manner in which an accident happens (which need not be). The tendency of these two notions to pull in opposite directions, therefore, both invites the courts to define the risk or hazard broadly, and also gives courts a choice to treat the freak case on an individualized basis.
2 F. Harper and F. James, The Law of Torts, § 18.2 at 1026–27 (1956) (footnotes omitted) (quoting Chavers v. A.R. Blossman, 45 So.2d 398, 402 (La.App.1950)).
Our supreme court has similarly defined the term “foreseeable risk” broadly:
The Palsgraf principle requires that liability be imposed only where both the plaintiff and the risk are foreseeable to a reasonable person. The holding here is that a broad view must be taken of the class of risks and victims that are foreseeable.
McFarlin v. Hall, 127 Ariz. 220, 222, 619 P.2d 729, 731 (1980).', 'mbe_285', 0, '10'),
('mbe_359', 'mbe', '359', '206', 'MBE-1978-83-part5', '', '11', 'Motorco is a manufacturer of motor vehicles. A federal regulation requires that all motor vehicles manufactured for sale in the United States be equipped with seat belts for each passenger and prescribes specifications for such belts. Motorco equipped all its cars with seat belts. It purchased all the bolts used in its seat belt assemblies from Boltco and it tested samples from each shipment received. Dunn purchased a motor vehicle manufactured by Motorco. While operating the car, with Price as a passenger in the front seat, Dunn collided with another vehicle. The collision was due solely to Dunn''s negligence. Price had his seat belt fastened, but one of the bolts which anchored the belt to the frame broke. Price was thrown through the windshield, sustaining various injuries. Dunn, whose belt was fastened and held, was killed when, following the collision, the car went off the road, down an embankment, and overturned. Subsequent to the accident, tests of the bolt that broke showed metallurgical defects. Motorco''s records showed that tests of samples from the shipment in which the defective bolt was received revealed no defective bolts.', 'In a negligence action by Price against Motorco, a defense that is likely to prevail is that', 'Motorco exercised due care in testing the bolts', 'Dunn''s negligence was the legal cause of Price''s injuries', 'Price was a passenger in Dunn''s car', 'Boltco, as the manufacturer of the bolts, has the sole responsibility for any defects therein', 'A', '“Due care” is that degree of care which a person of ordinary prudence would exercise under the same or similar circumstances. Id. The court in Colonial Savings cited section 323 of the Second Restatement of Torts, which provides:
One who undertakes, gratuitously or for consideration, to render services to another which he should recognize as necessary for the protection of the other''s person or things, is subject to liability to *598 the other for physical harm resulting from his failure to exercise reasonable care to perform his undertaking, if (a) his failure to exercise such care increases the risk of such harm, or (b) the harm is suffered because of the other''s reliance upon the undertaking.', 'mbe_286', 0, '11'),
('mbe_36', 'mbe', '36', '20', 'MBE-1972-78-part2', '', '37', 'Oscar, the owner in fee simple, laid out a subdivision of 325 lots on 150 acres of land. He obtained governmental approval (as required by applicable ordinances) and, between 1968 and 1970, he sold 140 of the lots, inserting in each of the 140 deeds the following provision: "The Grantee, for himself and his heirs, assigns and successors, covenants and agrees that the premises conveyed herein shall have erected thereon one single-family dwelling and that no other structure (other than a detached garage normally incident to a single-family dwelling) shall be erected or maintained; and, further, that no use shall ever be made or permitted to be made than occupancy by a single family for residential purposes only." Because of difficulty encountered in selling the remaining lots for single family use, in January, 1971, Oscar advertised the remaining lots with prom inent emphasis: " These lots are not subject to any restrictions and purchasers will find them adaptable to a wide range of uses."', 'Suppose that Oscar sold 50 lots during 1971 without inserting in the deeds any provisions relating to structures or uses. Doyle purchased one of the 50 lots and proposes to erect a service station and to conduct a retail business for the sale of gasoline, etc. Pringle purchased a lot from Boyer. Boyer had purchased from Oscar in 1968 and the deed had the provision that is quoted in the fact situation. Pringle brings suit to prevent Doyle from erecting the service station and from conducting a retail business. In the litigation between Pringle and Doyle, which of the following constitutes the best defense for Doyle?', 'Oscar''s difficulty in selling with provisions relating to use establishes a change in circumstances which renders any restrictions which may once have existed unenforceable.', 'Enforcement of the restriction, in view of the change of circumstances, would be an unreasonable restraint on alienation.', 'Since the proof (as stated) does not establish a danger of monetary loss tO Pringle, Pringle has failed to establish one of the necessary elements in a cause of action to prevent Doyle from using his lot for business purposes.', 'The facts do not establish a common building or development scheme forte entire subdivision.', 'D', 'We have acknowledged, but never expressly adopted, the common scheme of development doctrine, also known as the doctrine of implied equitable servitudes or implied restrictive covenants. See Thompson v. Pendleton, 1997 ME 127, ¶ 11 n. 2, 697 A.2d 56; 3 W Partners v. Bridges, 651 A.2d 387, 389 (Me.1994); Olson v. Albert, 523 A.2d 585, 588 (Me.1987) (per curiam); Chase v. Burrell, 474 A.2d 180, 181–82 (Me.1984). The doctrine applies when
(1) a common owner subdivides property into a number of lots for sale; (2) the common owner has a “general scheme of development” for the property as a whole, in which the use of the property will be restricted; (3) the vast majority of subdivided lots contain restrictive covenants which reflect the general scheme; (4) the property against which application of an implied covenant is sought is part of the general scheme of development; and (5) the purchaser of the lot in question has notice, actual or constructive, of the restriction.
Thompson, 1997 ME 127, ¶ 11 n. 2, 697 A.2d 56 (quoting Chase, 474 A.2d at 181). “The common grantor may establish a general scheme by conveying the majority of his subdivided lots subject to a restriction that reflects the general scheme.” 3 W Partners, 651 A.2d at 389. Whether a lot is part of a common scheme of development is a factual finding that we review for clear error. See Chase, 474 A.2d at 181–82. A finding is clearly erroneous only when it lacks any competent support in the record. Id.', 'mbe_32', 0, '37'),
('mbe_360', 'mbe', '360', '206', 'MBE-1978-83-part5', '', '12', 'Motorco is a manufacturer of motor vehicles. A federal regulation requires that all motor vehicles manufactured for sale in the United States be equipped with seat belts for each passenger and prescribes specifications for such belts. Motorco equipped all its cars with seat belts. It purchased all the bolts used in its seat belt assemblies from Boltco and it tested samples from each shipment received. Dunn purchased a motor vehicle manufactured by Motorco. While operating the car, with Price as a passenger in the front seat, Dunn collided with another vehicle. The collision was due solely to Dunn''s negligence. Price had his seat belt fastened, but one of the bolts which anchored the belt to the frame broke. Price was thrown through the windshield, sustaining various injuries. Dunn, whose belt was fastened and held, was killed when, following the collision, the car went off the road, down an embankment, and overturned. Subsequent to the accident, tests of the bolt that broke showed metallurgical defects. Motorco''s records showed that tests of samples from the shipment in which the defective bolt was received revealed no defective bolts.', 'In an action based on strict liability in tort by Price against Boltco, Price will rely principally on', 'rep ipsa loquitur', 'warranty', 'privity', 'the fact that one of the bolts anchoring his seat was defective', 'D', 'A claim for strict products liability based on a design defect differs from a cause of action for a negligently designed product in that the plaintiff is not required to establish that the manufacturer acted unreasonably in designing the product, thus shifting the focus from the manufacturer''s conduct to whether the product, as designed, was not reasonably safe. Voss, supra, at 207. The manufacturer will be held strictly liable regardless of the lack of actual knowledge of the product''s unsafe condition because the manufacturer is in a superior position to discover any design defect and to alter the design before making the product available to the public. Id. at 207–08.', 'mbe_287', 0, '12'),
('mbe_361', 'mbe', '361', '207', 'MBE-1978-83-part5', '', '13', 'As part of a comprehensive federal aid-to-education program, Congress included the following provisions as conditions for state receipt of federal funds: (1) Whenever textbooks are provided to students without charge, they must include no religious instruction and must be made available on the same terms to students in all public and private schools accredited by the state educational authority. (2) Salary supplements can be paid to teachers in public and private schools, up to ten percent of existing salary schedules, where present compensation is less than the average salary for persons of comparable training and experience, provided that no such supplement is paid to any teacher who instructs in religious subjects. (3) Construction grants can be made toward the cost of physical plant at private colleges and universities, provided that no part of the ant is used for buildings in which instruction in religious subJect matters is offered.', 'Federal taxpayer Allen challenges the provision that allows the distribution of free textbooks to students in a private school where religious instruction is included in the curriculum. On the question of the adequacy of Allen''s standing to raise the constitutional question, the most likely result is that standing will be', 'sustained, because any congressional spending authorization can be challenged by any taxpayer', 'sustained, because the challenge to the exercise of congressional spending power is based on a claimed violation of specific constitutional limitations on the exercise of such power', 'denied, because there is insufficient nexus between the taxpayer and the challenged expenditures', 'denied, because, in the case of private schools, no state action is involved', 'B', 'The spending power is of course not unlimited, Pennhurst State School and Hospital v. Halderman, 451 U.S. 1, 17, and n. 13, 101 S.Ct. 1531, 1540 n. 13, 67 L.Ed.2d 694 (1981), but is instead subject to several general restrictions articulated in our cases. The first of these limitations is derived from the language of the Constitution itself: the exercise of the spending power must be in pursuit of “the general welfare.” See Helvering v. Davis, 301 U.S. 619, 640–641, 57 S.Ct. 904, 908–909, 81 L.Ed. 1307 (1937); United States v. Butler, supra, at 65, 56 S.Ct., at 319. In considering whether a particular expenditure is intended to serve general public purposes, courts should defer substantially to the judgment of Congress. Helvering v. Davis, supra, at 640, 645, 57 S.Ct., at 908–909.', 'mbe_288', 0, '13'),
('mbe_362', 'mbe', '362', '207', 'MBE-1978-83-part5', '', '14', 'As part of a comprehensive federal aid-to-education program, Congress included the following provisions as conditions for state receipt of federal funds: (1) Whenever textbooks are provided to students without charge, they must include no religious instruction and must be made available on the same terms to students in all public and private schools accredited by the state educational authority. (2) Salary supplements can be paid to teachers in public and private schools, up to ten percent of existing salary schedules, where present compensation is less than the average salary for persons of comparable training and experience, provided that no such supplement is paid to any teacher who instructs in religious subjects. (3) Construction grants can be made toward the cost of physical plant at private colleges and universities, provided that no part of the ant is used for buildings in which instruction in religious subJect matters is offered.', 'Federal taxpayer Bates also challenges the salary supplements for teachers in private schools where religious instruction is included. in the curriculum. On the substantive constitutional issue, the most likely result is that the salary supplements will be', 'sustained, because the statute provides that no supplements will be made to teachers who are engaged in any religious instruction', 'sustained, because to distinguish between private and public school teachers would violate the religious freedom clause of the First Amendment', 'held unconstitutional, because some religions would benefit disproportionately', 'held unconstitutional, because the policing of the restriction would amount to an excessive entanglement with religion', 'D', 'When making such evaluations, courts examine two dimensions of entanglement under the Establishment Clause: substantive and procedural entanglement. Bollard v. California Province of the Society of Jesus, 196 F.3d 940, 948 (9th Cir.1999). *42 Substantive entanglement involves the same concerns as the Free Exercise Clause analysis and may occur, for example, when a “church''s freedom to choose its ministers is at stake.” Id. at 948–49. Thus, where a minister seeks redress for termination, failure to hire, changes in work schedule, or other similar decisions involving, at their heart, a church''s core right to decide who (and in what manner he or she) may propagate its religious beliefs, the Establishment Clause clearly prevents review by a civil court. Id. at 946 (“A church''s selection of its own clergy is one such core matter of ecclesiastical self-governance with which the state may not constitutionally interfere.” ) (citing **850 Milivojevich, supra, 426 U.S. at 717, 96 S.Ct. at 2384, 49 L.Ed.2d at 167; Kedroff, supra, 344 U.S. at 116, 73 S.Ct. at 154–55, 97 L.Ed. at 136; Gonzalez v. Roman Catholic Archbishop of Manila, 280 U.S. 1, 6, 50 S.Ct. 5, 7–8, 74 L.Ed. 131 (1929)); Gellington v. Christian Methodist Episcopal Church, Inc., 203 F.3d 1299, 1304 (11th Cir.2000) (“A church''s view on whether an individual is suited for a particular clergy position cannot be replaced by the courts without entangling the government in ‘questions of religious doctrine, polity, and practice.’ ” ) (quoting Jones v. Wolf, 443 U.S. 595, 603, 99 S.Ct. 3020, 3035, 61 L.Ed.2d 775 (1979)); Schmoll v. Chapman Univ., 70 Cal.App.4th 1434, 83 Cal.Rptr.2d 426, 427–28 (1999) (holding that First Amendment bars judicial scrutiny of religious university''s decision to reduce chaplain''s hours and benefits); cf. Welter v. Seton Hall Univ., 128 N.J. 279, 291, 295–96, 608 A.2d 206 (1992) (recognizing that court cannot constitutionally adjudicate claims concerning decision to hire or fire employees “charged with propagating the religion” but holding that nuns hired to teach computer science classes and who performed no ministerial functions were not barred by First Amendment from maintaining breach of express contract claim for their discharge).
Procedural entanglement, on the other hand, might result “from a protracted legal process pitting church and state as adversaries.” Rayburn, supra, 772 F.2d at 1171; see also *43 NLRB v. Catholic Bishop of Chicago, 440 U.S. 490, 502, 99 S.Ct. 1313, 1320, 59 L.Ed.2d 533, 542 (1979) (“It is not only the conclusions that may be reached by the Board which may impinge on rights guaranteed by the Religion Clauses, but also the very process of inquiry leading to findings and conclusions.” ) (footnote omitted). Additional procedural entanglement concerns may include a “far-reaching” impact of remedies on a church, such as the potential for “protracted government surveillance of church activities.” Bollard, supra, 196 F.3d at 949.', 'mbe_289', 0, '14'),
('mbe_363', 'mbe', '363', '207', 'MBE-1978-83-part5', '', '15', 'As part of a comprehensive federal aid-to-education program, Congress included the following provisions as conditions for state receipt of federal funds: (1) Whenever textbooks are provided to students without charge, they must include no religious instruction and must be made available on the same terms to students in all public and private schools accredited by the state educational authority. (2) Salary supplements can be paid to teachers in public and private schools, up to ten percent of existing salary schedules, where present compensation is less than the average salary for persons of comparable training and experience, provided that no such supplement is paid to any teacher who instructs in religious subjects. (3) Construction grants can be made toward the cost of physical plant at private colleges and universities, provided that no part of the ant is used for buildings in which instruction in religious subJect matters is offered.', 'Federal taxpayer Bates also challenges the construction grants to church-operated private colleges and universities. The most likely result is that the construction grants will be', 'sustained, because aid to one aspect of an institution of higher education not shown to be pervasively sectarian does not necessarily free it to spend its other resources for religious purposes', 'sustained, because bricks and mortar do not aid religion in a way forbidden by the establishment clause of the First Amendment', 'held unconstitutional, because any financial aid to a church-operated school strengthens the religious purposes of the institution', 'held unconstitutional, because the grants involve or cause an excessive entanglement with religion', 'A', 'Only in the context of aid to “pervasively sectarian” institutions have we invalidated an aid program on the grounds that there was a “substantial” risk that aid to these religious institutions would, knowingly or unknowingly, result in religious indoctrination. E.g., Grand Rapids, supra, 473 U.S., at 387–398, 105 S.Ct., at 3224–3330; Meek, supra, 421 U.S., at 371, 95 S.Ct., at 1766. In contrast, when the aid is to flow to religiously affiliated institutions that were not pervasively sectarian, as in Roemer, we refused to presume that it would be used in a way that would have the primary effect of advancing religion. Roemer, 426 U.S., at 760, 96 S.Ct., at 2351 (“We must assume that the colleges ... will exercise their delegated control over use of the funds in compliance with the statutory, and therefore the constitutional, mandate”). We think that the type of presumption that the District Court applied in this case is simply unwarranted. As we stated in Roemer: “It has not been the Court''s practice, in considering facial challenges to statutes of this kind, to strike them down in anticipation that particular applications may result in unconstitutional use of funds.” Id., at 761, 96 S.Ct., at 2352; see also Tilton, supra, at 682, 91 S.Ct., at 2097.', 'mbe_290', 0, '15'),
('mbe_364', 'mbe', '364', '208', 'MBE-1978-83-part5', '', '16', 'On November 1 the following notice was posted in a privately operated law school The faculty, seeking to encourage legal xesearch, offers to any student at this school who wins the current National Obscenity Law Competition the additional prize of $500. All competing papers must be submitted to the Dean''s office before next May 1. (The National Competition is conducted by an outside agency, unconnected with any law school.) Student read this notice on November 2, and thereupon intensified his effort to make his paper on obscenity law, which he started in October, a winner. Student also left on a counter in the Dean''s office a signed note saying, "I accept the faculty''s $500 Obscenity Competition offer." This note was madvertently placed in Student''s file and never reached the Dean or any faculty member personally. On the following April 1, the above notice was removed and the following substituted therefor: The faculty regrets that our offer regarding the National Obscenity Law Competition must be withdrawn. Student''s paper was submitted through the Dean''s office on April 15. On May 1, it was announced that Student had won the National Obscenity Law Competition and the prize of $1,000. The law faculty refused to pay anything.', 'Assuming that the faculty''s notice of November 1 was posted on a bulletin board or other conspicuous place commonly viewed by all persons in the law school, such notice constituted a', 'preliminary invitation to deal, analogous to newspaper advertisements for the sale of goods by merchants', 'contractual offer, creating a power of acceptance', 'preliminary invitation, because no offered was named therein', 'promise to make a conditional, future gift of money', 'B', 'An offer is defined as “the manifestation of willingness to enter into a bargain, so made as to justify another person in understanding that his assent to that bargain is invited and will conclude it.” Anderson v. United States, 344 F.3d 1343, 1353 (Fed.Cir.2003) (quoting Restatement (Second) of Contracts § 24); Franklin Sav. Corp. v. United States, 56 Fed.Cl. 720, 742–43 (2003). After an offer is made, “there must be an acceptance, [i.e.], a ‘manifestation of assent to the terms thereof made by the offeree in a manner invited or required by the offer.’ ” Anderson, 344 F.3d at 1355 (quoting Restatement (Second) of Contracts § 50(1)).', 'mbe_291', 0, '16'),
('mbe_365', 'mbe', '365', '208', 'MBE-1978-83-part5', '', '17', 'On November 1 the following notice was posted in a privately operated law school The faculty, seeking to encourage legal xesearch, offers to any student at this school who wins the current National Obscenity Law Competition the additional prize of $500. All competing papers must be submitted to the Dean''s office before next May 1. (The National Competition is conducted by an outside agency, unconnected with any law school.) Student read this notice on November 2, and thereupon intensified his effort to make his paper on obscenity law, which he started in October, a winner. Student also left on a counter in the Dean''s office a signed note saying, "I accept the faculty''s $500 Obscenity Competition offer." This note was madvertently placed in Student''s file and never reached the Dean or any faculty member personally. On the following April 1, the above notice was removed and the following substituted therefor: The faculty regrets that our offer regarding the National Obscenity Law Competition must be withdrawn. Student''s paper was submitted through the Dean''s office on April 15. On May 1, it was announced that Student had won the National Obscenity Law Competition and the prize of $1,000. The law faculty refused to pay anything.', 'As to Student, was the offer effectively revoked?', 'Yes, by the faculty''s second notice', 'No, because it became irrevocable after a reasonable time had elapsed', 'No, because of Student''s reliance, prior to April 1, on the offer', 'No, unless Student became aware of the April 1 posting and removal before submitting his paper', 'C', 'Had defendant''s bid expressly stated or clearly implied that it was revocable at any time before acceptance we would treat it accordingly. It was silent on revocation, however, and we must therefore determine whether there are conditions to the right of revocation imposed by law or reasonably inferable in fact.  In the analogous problem of an offer for a unilateral contract, the theory is now obsolete that the offer is revocable at any time before complete performance. Thus section 45 of the Restatement of Contracts provides: ‘If an offer for a unilateral contract is made, and part of the consideration requested in the offer is given or tendered by the offeree in response thereto, the offeror is bound by a contract, the duty of immediate performance of which is conditional on the full consideration being given or tendered within the time stated in the offer, or, if no time is stated therein, within a reasonable time.’ In explanation, comment b states that the ‘main offer includes as a subsidiary promise, necessarily implied, that if part of the requested performance is given, the offeror will not revoke his offer, and that if tender is made it will be accepted. Part performance or tender may thus furnish consideration for the subsidiary promise. Moreover, merely acting in justifiable reliance on an offer may in some cases serve as sufficient reason for making a promise binding (see s 90).’
Whether implied in fact or law, the subsidiary promise serves to preclude the injustice that would result if the offer could be revoked after the offeree had acted in detrimental reliance thereon.  Reasonable reliance resulting in a foreseeable prejudicial change in position affords a compelling basis also for implying a subsidiary promise not to revoke an offer for a bilateral contract.
The absence of consideration is not fatal to the enforcement of such a promise. It is true that in the case of unilateral contracts the Restatement finds consideration for the implied subsidiary promise in the part performance of the bargained-for exchange, but its reference to section 90 makes clear that consideration for such a promise is not always necessary. The very purpose of section 90 is to make a promise binding even though there was no consideration ‘in the sense of something that is bargained for and given in exchange.’ (See 1 Corbin, Contracts 634 et seq.) Reasonable reliance serves to hold the offeror in lieu of the consideration ordinarily required to make the offer binding. In a case involving similar facts the Supreme Court of South Dakota stated that ‘we believe that reason and justice demand that the doctrine (of section 90) be applied to the present facts. We cannot believe that by accepting this doctrine as controlling in the state of facts before us we will abolish the requirement of a consideration in contract *415 cases, in any different sense than an ordinary estoppel abolishes some legal requirement in its application. We are of the opinion, therefore, that the defendants in executing the agreement (which was not supported by consideration) made a promise which they should have reasonably expected would induce the plaintiff to submit a bid based thereon to the Government, that such promise did induce this action, and that injustice can be avoided only by enforcement of the promise.’ Northwestern Engineering Co. v. Ellerman, 69 S.D. 397, 408, 10 N.W.2d 879, 884; see also, Robert Gordon, Inc., v. Ingersoll-Rand Co., 7 Cir., 117 F.2d 654, 661; cf. James Baird Co. v. Gimbel Bros., 2 Cir., 64 F.2d 344.
When plaintiff used defendant''s offer in computing his own bid, he bound himself to perform in reliance on defendant''s terms. Though defendant did not bargain for this use of its bid neither did defendant make it idly, indifferent to whether it would be used or not. On the contrary it is reasonable to suppose that defendant submitted its bid to obtain the subcontract. It was bound to realize the substantial possibility that its bid would be the lowest, and that it would be included by plaintiff in his bid. It was to its own interest that the contractor be awarded the general contract; the lower the subcontract bid, the lower the general contractor''s bid was likely to be and the greater its cnance of acceptance and hence the greater defendant''s chance of getting the paving subcontract. Defendant had reason not only to expect plaintiff to rely on its bid but to want him to. Clearly defendant had a stake in plaintiff''s reliance on its bid. Given this interest and the fact that plaintiff is bound by his own bid, it is only fair that plaintiff should have at least an opportunity to accept defendant''s bid after the general contract has been awarded to him.', 'mbe_292', 0, '17'),
('mbe_366', 'mbe', '366', '208', 'MBE-1978-83-part5', '', '18', 'On November 1 the following notice was posted in a privately operated law school The faculty, seeking to encourage legal xesearch, offers to any student at this school who wins the current National Obscenity Law Competition the additional prize of $500. All competing papers must be submitted to the Dean''s office before next May 1. (The National Competition is conducted by an outside agency, unconnected with any law school.) Student read this notice on November 2, and thereupon intensified his effort to make his paper on obscenity law, which he started in October, a winner. Student also left on a counter in the Dean''s office a signed note saying, "I accept the faculty''s $500 Obscenity Competition offer." This note was madvertently placed in Student''s file and never reached the Dean or any faculty member personally. On the following April 1, the above notice was removed and the following substituted therefor: The faculty regrets that our offer regarding the National Obscenity Law Competition must be withdrawn. Student''s paper was submitted through the Dean''s office on April 15. On May 1, it was announced that Student had won the National Obscenity Law Competition and the prize of $1,000. The law faculty refused to pay anything.', 'The offer proposed a', 'unilateral contract only', 'bilateral contract only', 'Unilateral contract or bilateral contract. at the offeree''s option', 'unilateral contract which ripened into a bilateral contract, binding on both parties, as soon as Student intensified his effort in response to the offer', 'A', 'A unilateral contract is a contract in which “performance is based on the wish, will, or pleasure of one of the parties.” Cook v. Coldwell Banker, 967 S.W.2d 654, 657 (Mo.App. E.D.1998). A promisor does not receive a promise as consideration for his or her promise in a unilateral contract. Id. Despite this lack of mutuality, when the promisee performs, consideration is supplied, and the contract is enforceable to the extent performed. Id. An offer to make a unilateral contract is accepted when the requested performance is rendered. Id. In general, for an acceptance to be effective, it “must be positive and unambiguous.” Kunzie v. Jack–in–The–Box, Inc., 330 S.W.3d 476, 484 (Mo.App. E.D.2010) (quoting 2 Williston on Contracts § 6.10 (4th ed.2007)).', 'mbe_293', 0, '18'),
('mbe_367', 'mbe', '367', '208', 'MBE-1978-83-part5', '', '19', 'On November 1 the following notice was posted in a privately operated law school The faculty, seeking to encourage legal xesearch, offers to any student at this school who wins the current National Obscenity Law Competition the additional prize of $500. All competing papers must be submitted to the Dean''s office before next May 1. (The National Competition is conducted by an outside agency, unconnected with any law school.) Student read this notice on November 2, and thereupon intensified his effort to make his paper on obscenity law, which he started in October, a winner. Student also left on a counter in the Dean''s office a signed note saying, "I accept the faculty''s $500 Obscenity Competition offer." This note was madvertently placed in Student''s file and never reached the Dean or any faculty member personally. On the following April 1, the above notice was removed and the following substituted therefor: The faculty regrets that our offer regarding the National Obscenity Law Competition must be withdrawn. Student''s paper was submitted through the Dean''s office on April 15. On May 1, it was announced that Student had won the National Obscenity Law Competition and the prize of $1,000. The law faculty refused to pay anything.', 'The promise of the faculty on November 1 was', 'enforceable on principles of promissory estoppel', 'enforceable by Student''s personal representative even if Student had been killed in an accident on April 16', 'not enforceable on policy grounds because it produced a noncommercial agreement between a student and his teachers, analogous to intramural family agreements and informal social commitments', 'not enforceable because Student, after entering the National Competition in October, was already under a duty to perform to the best of his ability', 'B', 'Exception to general rule that only personal representatives of testator''s estate had standing and capacity to recover estate property when personal representative could not, or would not, bring suit or personal representative''s interests were antagonistic to those of estate did not apply to ancillary matter that testator''s daughter brought in probate proceeding regarding enforceability of marital settlement agreement; daughter did not give notice to personal representative before filing suit, daughter failed to establish that personal representative''s interests were antagonistic to the estate, and daughter did not lodge any claims against personal representative. Tex. Estates Code §§ 22.031, 351.054(a), 351.054(b).', 'mbe_294', 0, '19'),
('mbe_368', 'mbe', '368', '209', 'MBE-1978-83-part5', '', '20', 'Owner held 500 acres in fee simple absolute. In 1960 Owner platted and obtained all required governmental approvals of two subdivisions of 200 acres each. In 1960 and 1961 commercial buildings and parking facilities were constructed on one,RoyalCenter, in accordance with the plans disclosed by the plat for each subdivision. Royal Center continues to be used for commercial purposes. The plat of the other, Royal Oaks, showed 250 lots, streets, and utility and drainage easements. All of the lots in Royal Oaks were conveyed during 1960 and 1961. The deeds contained provisions, expressly stated to be binding upon the grantee, his heirs and assigns, requiring the lots to be used only for single-family, residential purposes until 1985. The deeds expressly stated that these provisions were enforceable by the owner of any lot in the Royal Oaks subdivision. At all times since 1959, the 200 acres in Royal Center have been zoned for shopping center use, and the 200 acres in Royal Oaks have been zoned for residential use in a classification which permits both single-family and multiplefamily use.', 'In an appropriate attack upon the limitation to residential user by single families, if the evidence disclosed no fact in addition to those listed above, the most probable judicial resolution would be that', 'there is no enforceable restriction because judicial recognition constitutes state action which is in conflict with the Fourteenth Amendment to the United States Constitution', 'there is no enforceable restriction because of Owner''s conflict of interest in that he did not make the restriction applicable to the 100 acres he retains', 'the restriction in user set forth in the deeds will be enforced at the suit of any present owner of a lot in Royal Oaks residential subdivision', 'any user consistent with zoning will be permitted but that such users so permitted as are in conflict with the restrictions in the deeds will give rise to a right to damages from Owner or Owner''s successor', 'C', 'Enforcement of zoning ordinances is akin to enforcement of deed-restriction ordinances. Both accomplish the same objectives. The enforcement of zoning ordinances provides a judicial forum for aggrieved landowners to resolve conflicting interests in land use. See Farmer v. Thompson, 289 S.W.2d 351, 355 (Tex.Civ.App.-Fort Worth 1956, writ ref''d n.r.e); Morton v. Sayles, 304 S.W.2d 759, 763 (Tex.Civ.App.-Eastland 1957, writ ref''d n.r.e.). Enforcement of zoning and deed restrictions preserves and maximizes property values. Young v. City of Houston, 756 S.W.2d 813, 814–15 (Tex.App.-Houston [1st Dist.] 1988, writ denied) (enforcing deed restrictions serves public purpose of maintaining property values).  Finally, courts will enforce deed restrictions and zoning laws to preserve, complement, and advance comprehensive city or residential planning. Curlee v. Walker, 112 Tex. 40, 244 S.W. 497, 498 (1922). Because the enforcement of deed restrictions is like the enforcement of zoning statutes, which qualifies as a governmental function, we hold that Houston''s action in enforcing the residential-use-only deed restrictions against appellants is a governmental function.', 'mbe_295', 0, '20'),
('mbe_369', 'mbe', '369', '209', 'MBE-1978-83-part5', '', '21', 'Owner held 500 acres in fee simple absolute. In 1960 Owner platted and obtained all required governmental approvals of two subdivisions of 200 acres each. In 1960 and 1961 commercial buildings and parking facilities were constructed on one,RoyalCenter, in accordance with the plans disclosed by the plat for each subdivision. Royal Center continues to be used for commercial purposes. The plat of the other, Royal Oaks, showed 250 lots, streets, and utility and drainage easements. All of the lots in Royal Oaks were conveyed during 1960 and 1961. The deeds contained provisions, expressly stated to be binding upon the grantee, his heirs and assigns, requiring the lots to be used only for single-family, residential purposes until 1985. The deeds expressly stated that these provisions were enforceable by the owner of any lot in the Royal Oaks subdivision. At all times since 1959, the 200 acres in Royal Center have been zoned for shopping center use, and the 200 acres in Royal Oaks have been zoned for residential use in a classification which permits both single-family and multiplefamily use.', 'For this question only, assume that Owner now desires to open his remaining 100 acres as a residential subdivision of 125 lots (with appropriate streets, etc.). He has, as an essential element of his scheme, the feature that the restrictions should be identical with those he planned for the original Royal Oaks residential subdivision and, further, that lot owners in Royal Oaks should be able to enforce (by lawsuits) restrictions on the lots in the 100 acres. The zoning for the 100 acres is identical with that for the 200 acres of Royal Oaks residential subdivision. Which of the following best states the chance of success for his scheme?', 'He can restrict use only to the extent of that imposed by zoning (that is, to residential user by not more than four dwelling units per lot).', 'He cannot restrict the 100 acres to residential user because of the conflicting user for retail commercial purposes in the 200 acres comprising the shopping center.', 'He cannot impose any enforceable restriction to residential user only.', 'Any chance of success depends upon the 100 acres being considered by the courts as a part of a common development scheme which also includes the 200 acres of Royal Oaks.', 'D', 'The doctrine of implied restrictive covenants is also known as the “common scheme of development” doctrine. Tisdale v. Buch, 2013 ME 95, ¶ 13, 81 A.3d 377. “We have acknowledged, but never expressly adopted, the common scheme of development doctrine ....” Id.; see also Thompson v. Pendleton, 1997 ME 127, ¶ 11 n.2, 697 A.2d 56; 3 W Partners v. Bridges, 651 A.2d 387, 389 (Me. 1994); Olson v. Albert, 523 A.2d 585, 588 (Me. 1987); Chase v. Burrell, 474 A.2d 180, 181-82 (Me. 1984). A factual finding that a common scheme of development exists would be a prerequisite to an action seeking to enforce a deed restriction because the reciprocal servitudes arising from the common scheme provide a party standing to challenge a property owner''s alleged violation. See Restatement (Third) of Servitudes § 2.14 (Am. L. Inst. 2000). Because of the interlocutory nature of this appeal, we express no opinion regarding the viability or applicability of the common scheme of development doctrine.', 'mbe_296', 0, '21'),
('mbe_37', 'mbe', '37', '21', 'MBE-1972-78-part2', '', '38', '', 'Adam and Bailey. brothers, operated an illicit still. They customarily sold to anyone unless they suspected the person of being a revenue agent or an informant. One day when Adam was at the still alone, he was approached by Mitchell, who asked to buy a gallon of liquor. Mitchell was in fact a revenue officer. After Adam had sold him the liquor, Mitchell revealed his identity. Adam grabbed one of the rifles that the brothers kept handy in case of trouble with the law, and shot and wounded Mitchell. Other officers, hiding nearby, overpowered and arrested Adam. Shortly thereafter, Bailey came on the scene. The officers in hiding had been waiting for him. One of them approached him and asked to buy liquor. Bailey was suspicious and refused to sell. The officers nevertheless arrested him. Adam and Bailey were charged with conspiracy to violate revenue laws, illegal selling of liquor, and battery of the officer. On the charge of battery, which statement concerning Adam and Bailey is true?', 'Neither is guilty.', 'Both are guilty.', 'Adam is guilty but Bailey is not, because the conspiracy had terminated with the arrest of Adam.', 'Adam is guilty but Bailey is not, because Adam''s act was outside the scope of the conspiracy.', 'B', 'Battery is an intentional, unconsented-to, injurious or otherwise offensive physical contact with the victim (a completed assault, so to speak): “Although the word ‘assault’ is sometimes used loosely to include a battery, and the whole expression ‘assault and battery’ to mean battery, it is more accurate to distinguish between the two separate crimes, assault and battery, on the basis of the existence or non-existence of physical injury or offensive touching.” Wayne R. LaFave, 2 Substantive Criminal Law § 16.1 (2d ed., Westlaw database updated Sept. 2014) (footnotes omitted).', 'mbe_33', 0, '38'),
('mbe_370', 'mbe', '370', '210', 'MBE-1978-83-part5', '', '22', '', 'A state accredits both public and private schools, licenses their teachers, and supplies textbooks on secular subjects to all such schools. Country School. house, a private school that offers elementary and secondary education in the state, denies admission to all non-Caucasians. In a suit to enjoin as unconstitutional the continued racially exclusionary admissions policy of the Country Schoolhouse, which of the fol., lowing is the strongest argument AGAINST the school?', 'Because education is a public function, the Country Schoolhouse may not discriminate on racial grounds.', 'The state is so involved in school regulation and support that the equal protection clause of the Fourteenth Amendment is applicable to the school.', 'The state is constitutionally obligated to eliminate segregation in all public and private educational institutions within the state.', 'Any school with teachers who are licensed by the state is forbidden to discriminate on racial grounds.', 'B', 'The Equal Protection Clause absolutely prohibits the use of race in many governmental contexts. To cite only a few: the government may not use race to decide who may serve on juries, who may use public services, who may marry, and who may be fit parents. The use of race in these situations is “utterly irrational” because it is completely unrelated to any valid public purpose; moreover, it is particularly pernicious because it constitutes a badge of oppression that is unfaithful to the central promise of the Fourteenth Amendment.', 'mbe_297', 0, '22'),
('mbe_371', 'mbe', '371', '211', 'MBE-1978-83-part5', '', '23', 'In 1971 two police officers in a squad car received a radio message from headquarters to be on the lookout for a large green sedan occupied by two men who had just committed a bank robbery. An hour later they saw a car answering this description traveling down a main boulevard leading out of town. They had the car pull to the side of the road and walked over to the car. One of the officers told the occupants that they were under arrest for bank robbery. Thereupon Dean, the driver, suddenly put the car in gear and drove off. One officer clumb to the car. The other officer pursued in the squad car. Unable to overtake the car and afraid he would lose sight of it in the heavy traffic, the officer fired, first a warning shot and then at the car. He struck Evans, the passenger sitting next to Dean. Dean was caught fives minutes later. Evans died from loss of blood. Dean was taken to the police station. The bank robbers had handed the teller a handwritten note, demanding the money. Dean was required over his protest, to write out the words of the note and have his fingerprints taken. He was then, for the first time, allowed to telephone a lawyer, who thereafter represented him. Dean was charged with murder of Evans.', 'The prosecution, after introducing the robbers'' note to the teller, also offers in evidence Dean''s writing of the words of the note at the request of the police. On appropriate objection, the court should rule this', 'admissible', 'inadmissible, because he was not advised that his handwriting sample could be admitted into evidence against him', 'inadmissible, because he was not advised of his right to refuse to give a handwriting sample', 'inadmissible, because he had not been informed he had a right to have counsel present', 'A', 'Compelling defendant to give handwriting sample did not violate his rights against self-incrimination under either Fifth Amendment or section of State Constitution providing that no person “shall be compelled to give evidence against himself”; handwriting sample is not communication by itself, but rather, is physical characteristic in itself. U.S.C.A. Const.Amend. 5; LSA-Const. Art. 1, § 16.', 'mbe_2641', 0, '23'),
('mbe_372', 'mbe', '372', '211', 'MBE-1978-83-part5', '', '24', 'In 1971 two police officers in a squad car received a radio message from headquarters to be on the lookout for a large green sedan occupied by two men who had just committed a bank robbery. An hour later they saw a car answering this description traveling down a main boulevard leading out of town. They had the car pull to the side of the road and walked over to the car. One of the officers told the occupants that they were under arrest for bank robbery. Thereupon Dean, the driver, suddenly put the car in gear and drove off. One officer clumb to the car. The other officer pursued in the squad car. Unable to overtake the car and afraid he would lose sight of it in the heavy traffic, the officer fired, first a warning shot and then at the car. He struck Evans, the passenger sitting next to Dean. Dean was caught fives minutes later. Evans died from loss of blood. Dean was taken to the police station. The bank robbers had handed the teller a handwritten note, demanding the money. Dean was required over his protest, to write out the words of the note and have his fingerprints taken. He was then, for the first time, allowed to telephone a lawyer, who thereafter represented him. Dean was charged with murder of Evans.', 'Suppose the jury finds Dean guilty of the murder of Evans. Before passing sentence, the judge hears argument by both parties. The prosecutor introduces the criminal record of Dean, showing two prior convictions for felony. Defense counsel admits the correctness of the record. The court imposes the maximum sentence of life imprisonment. On appeal, the appellate court should hold that this sentence', 'violated Dean''s right to due process, in that it deprived him of a fair and unbiased tribunal', 'was in error because the introduction of new evidence after the trial deprived Dean of a fair trial', 'was not in error', 'deprived Dean of the right to confront the witnesses against him', 'C', '“We afford the trial court wide latitude in sentencing and, generally, ‘will reverse a trial court''s sentencing decision only if it is an abuse of the judge''s discretion.’ ” State v. Bluff, 2002 UT 66,¶ 66, 52 P.3d 1210 (citation omitted). Trial courts abuse their discretion “when [they] fail [ ] to consider all legally relevant factors, or if the sentence imposed exceeds the limits prescribed by law.” Id. Generally, a trial court''s sentence “ ‘should be overturned only when it is inherently unfair or clearly excessive.’ ” Id. (citation omitted).', 'mbe_2642', 0, '24'),
('mbe_373', 'mbe', '373', '212', 'MBE-1978-83-part5', '', '25', '', 'Linda was fifteen years old, but she appeared and acted older. When asked, she always said she was twenty-two, and she carried false identification saying she was that old. She frequented taverns and drank heavily. One evening in a bar she became acquainted with Duke. He believed her when she told him her claimed age. They had several drinks and became inebriated. Later, they drove in Duke''s car to a secluded spot. After they had necked for a while, Duke propositioned Linda and she consented. Before Duke achieved penetration, Linda changed her mind, saying, "Stop! Don''t touch me! I don''t want to do it." When Duke did not desist, Linda started to cry and said, "I am only fifteen." Duke immediately jumped from the car and ran away. Duke was indicted for attempted rape, assault with intent to rape, contributing to the delinquency of a minor, and attempted statutory rape. The age of consent in the jurisdiction is sixteen. The attempted rape charge can only be sustained if', 'the jury acquits Duke on all other charges', 'the State can show that Duke thought Linda was over the age of consent', 'the jury finds that Linda was resisting force used by Duke to accomplish an act of intercourse', 'evidence of Duke''s flight is not admitted by the trial judge', 'C', 'Rape is generally defined as engaging in sexual intercourse or deviate sexual activity with another person by forcible compulsion.  Attempted rape is defined as purposely engaging in conduct which constitutes a substantial step toward accomplishing the rape. It is not necessary to prove an unlawful entry into an occupiable structure to establish rape or attempted rape. Once the intent to rape has been formed and substantial steps to accomplish it have been taken the offense of rape or attempted rape can be committed anywhere. Since each offense requires proof of elements not required by the other a defendant can be convicted and sentenced on both offenses.', 'mbe_298', 0, '25'),
('mbe_374', 'mbe', '374', '213', 'MBE-1978-83-part5', '', '26', 'Paul and Daniel entered a contract in writing on November 1, the essential part of which read as follows: "Paul to supply Daniel with 200 personalized Christmas cards on or before December 15, 1970, bearing photograph of Daniel and his family, and Daniel to pay $100 thirty days thereafter. Photograph to be taken by Paul at Daniel''s house. Cards guaranteed to be fully satisfactory and on time." Because Daniel suddenly became ill, Paul was unable to take the necessary photograph of Daniel and his family until the first week of December. The final week''s delay was caused by Paul''s not being notified promptly by Daniel of his recovery. Before taking the photograph of Daniel and his family, Paul advised Daniel that he was likely to be delayed a day or two beyond December 15 in making delivery because of the time required to process the photograph and cards. Daniel told Paul to take the photograph anyway. The cards were finally delivered by Paul to Daniel on December 17, Paul having diligently worked on them in the interim. Although the cards pleased the rest of the family, Daniel refused to accept them because, as he said squinting at one of the cards at arm''s length without bothering to put on his reading glasses, "The photograph makes me look too old. Besides, the cards weren''t delivered on time."', 'In an action by Paul against Daniel, which of the following would be Daniel''s best defense?', 'The cards, objectively viewed were not satisfactory.', 'The cards, subjectively viewed, were not satisfactory.', 'The cards were not delivered on time.', 'Daniel''s illness excused him from further obligation under the contract.', 'B', 'Where no time is fixed for the return of goods sold subject to the satisfaction of the buyer, they must be returned, or an offer made to return them, within a reasonable time; and a request for shipping directions and a statement that upon receiving them the goods will be returned is a sufficient offer to return.', 'mbe_299', 0, '26'),
('mbe_375', 'mbe', '375', '213', 'MBE-1978-83-part5', '', '27', 'Paul and Daniel entered a contract in writing on November 1, the essential part of which read as follows: "Paul to supply Daniel with 200 personalized Christmas cards on or before December 15, 1970, bearing photograph of Daniel and his family, and Daniel to pay $100 thirty days thereafter. Photograph to be taken by Paul at Daniel''s house. Cards guaranteed to be fully satisfactory and on time." Because Daniel suddenly became ill, Paul was unable to take the necessary photograph of Daniel and his family until the first week of December. The final week''s delay was caused by Paul''s not being notified promptly by Daniel of his recovery. Before taking the photograph of Daniel and his family, Paul advised Daniel that he was likely to be delayed a day or two beyond December 15 in making delivery because of the time required to process the photograph and cards. Daniel told Paul to take the photograph anyway. The cards were finally delivered by Paul to Daniel on December 17, Paul having diligently worked on them in the interim. Although the cards pleased the rest of the family, Daniel refused to accept them because, as he said squinting at one of the cards at arm''s length without bothering to put on his reading glasses, "The photograph makes me look too old. Besides, the cards weren''t delivered on time."', 'Which of the following statements is most accurate?', 'Payment by Daniel of the $100 was a condition precedent to Paul''s duty of performance.', 'The performances of Paul and Daniel under the contract were concurrently conditional.', 'Payment by Daniel of the $100 was a condition subsequent to Paul''s duty of performance.', 'Performance by Paul under the contract was a condition precedent to Daniel''s duty of payment of the $100.', 'D', 'A condition precedent is an act or event, other than a lapse of time, which, unless the condition is excused, must occur before a duty to perform a promise in the agreement arises” (Oppenheimer & Co., 86 N.Y.2d at 690, 636 N.Y.S.2d 734, 660 N.E.2d 415 [internal quotation marks omitted]). An express condition -- that is, one agreed to by the parties that must be literally performed (substantial compliance will not suffice) -- must be reflected in clear, express language (see id. at 691, 636 N.Y.S.2d 734, 660 N.E.2d 415); “[c]ourts are reluctant to interpret a contractual clause as a condition precedent in the absence of ... unmistakable conditional language” ( *86 VXI Lux Holdco S.A.R.L. v. SIC Holdings, LLC, 171 A.D.3d 189, 195, 98 N.Y.S.3d 1 [1st Dept. 2019]).', 'mbe_300', 0, '27'),
('mbe_376', 'mbe', '376', '213', 'MBE-1978-83-part5', '', '28', 'Paul and Daniel entered a contract in writing on November 1, the essential part of which read as follows: "Paul to supply Daniel with 200 personalized Christmas cards on or before December 15, 1970, bearing photograph of Daniel and his family, and Daniel to pay $100 thirty days thereafter. Photograph to be taken by Paul at Daniel''s house. Cards guaranteed to be fully satisfactory and on time." Because Daniel suddenly became ill, Paul was unable to take the necessary photograph of Daniel and his family until the first week of December. The final week''s delay was caused by Paul''s not being notified promptly by Daniel of his recovery. Before taking the photograph of Daniel and his family, Paul advised Daniel that he was likely to be delayed a day or two beyond December 15 in making delivery because of the time required to process the photograph and cards. Daniel told Paul to take the photograph anyway. The cards were finally delivered by Paul to Daniel on December 17, Paul having diligently worked on them in the interim. Although the cards pleased the rest of the family, Daniel refused to accept them because, as he said squinting at one of the cards at arm''s length without bothering to put on his reading glasses, "The photograph makes me look too old. Besides, the cards weren''t delivered on time."', 'Which of the following statements regarding the legal effect of Daniel''s illness is LEAST accurate?', 'Daniel''s illness and the related developments excused Paul from his obligation to deliver the cards on or before December 15.', 'Prompt notice by Daniel to Paul of Daniel''s recovery from illness was an implied condition of Paul''s duty under the circumstances.', 'Paul was under a duty of immediate performance of his promise to deliver the cards, as of December 15, by reason of the express language of the contract and despite the illness of Daniel and the related developments.', 'Daniel''s conduct after his illness constituted a waiver of the necessity of Paul''s performing on or before December 15.', 'C', '“A party''s obligation to perform under a contract is only excused when the other party''s breach of the contract is so substantial that it defeats the object of the parties in making the contract.” Frank Felix Associates, Ltd. v. Austin Drugs, Inc., 111 F.3d 284, 289 (2d Cir.1997). See also Medical Malpractice Ins. Assoc. v. Hirsch (In re Lavigne), 114 F.3d 379, 387 (2d Cir.1997).', 'mbe_301', 0, '28'),
('mbe_377', 'mbe', '377', '214', 'MBE-1978-83-part5', '', '29', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'Pedersen''s counsel wants to introduce testimony from Sheriff concerning a discussion between Sheriff and Passerby at the police station after the accident, when Passerby excitedly exclaimed, "Pedersen ran out in the street and was not in the crosswalk!" Sheriff duly recorded the statement in an official police report. The trial judge should rule Sheriff''s oral testimony', 'admissible as a spontaneous utterance', 'admissible as based on past recollection recorded', 'inadmissible because Passerby has not been shown unavailable as a witness', 'inadmissible under the excited utterance exception because it can be a product of reflection and deliberation', 'D', '[I]n order for an excited utterance to be admissible, the following requirements must be met: (1) there must have been an event startling enough to cause nervous excitement; (2) the statement must have been made before there was time to contrive or misrepresent; and (3) the statement must have been made while the person was under the stress of excitement caused by the startling event.
Stoll v. State, 762 So.2d 870, 873 (Fla. 2000).', 'mbe_2350', 0, '29'),
('mbe_378', 'mbe', '378', '214', 'MBE-1978-83-part5', '', '30', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'Pedersen''s counsel wants to introduce testimony of Sheriff that at the police station Carr told Sheriff, "I think this was probably my fault." The trial judge should rule this testimony', 'admissible as a part of the res gestae', 'admissible as an admission of a party', 'inadmissible because it includes a conclusion of law which the declarant was not qualified to make', 'inadmissible because it constitutes an opinion rather than an admission of specific facts', 'B', 'For an admission by a party-opponent to be admissible: 1) the statement must be a conscious or voluntary acknowledgment by a party-opponent of the existence of certain facts; 2) the matter acknowledged must be relevant to the cause of the party offering the admission; and 3) the matter acknowledged must be unfavorable to or inconsistent with the position now taken by the party-opponent. Bowls v. Scarborough, 950 S.W.2d 691, 702 (Mo.App.W.D.1997).', 'mbe_2351', 0, '30'),
('mbe_379', 'mbe', '379', '214', 'MBE-1978-83-part5', '', '31', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'Pedersen''s counsel wishes to prove that after the accident Carr went to Pedersen and offered $1,000 to settle Pedersen''s claim. The trial judge should rule this evidence', 'admissible as an admission of a party', 'admissible as an admission to show Carr''s liability, provided the court gives a cautionary instruction that the statement should not be considered as bearing on the issue of damages', 'inadmissible since it is not relevant either to the question of liability or the question of damages', 'inadmissible because even though relevant and an admission, the policy of the law is to encourage settlement negotiations', 'D', '(a) Prohibited Uses. Evidence of the following is not admissible — on behalf of any party — either to prove or disprove the validity or amount of a disputed claim or to impeach by a prior inconsistent statement or a contradiction: (1) furnishing, promising, or offering — or accepting, promising to accept, or offering to accept — a valuable consideration in compromising or attempting to compromise the claim; and (2) conduct or a statement made during compromise negotiations about the claim — except when offered in a criminal case and when the negotiations related to a claim by a public office in the exercise of its regulatory, investigative, or enforcement authority. b) Exceptions. The court may admit this evidence for another purpose, such as proving a witness’s bias or prejudice, negating a contention of undue delay, or proving an effort to obstruct a criminal investigation or prosecution.', 'mbe_2352', 0, '31'),
('mbe_38', 'mbe', '38', '22', 'MBE-1972-78-part2', '', '39', '', 'The bus in which Pat was riding was struck from the rear by a taxi. He sued Cab Company for a claimed neck injury. Cab Company claimed the impact was too slight to have caused the claimed injury and introduced testimony that all passengers had refused medical attention at the time of the accident. Pat called a doctor from City Hospital to testify that three persons (otherwise proved to have been on the bus) were admitted to the hospital for treatment of severe neck pain within a week after the accident. The trial judge should rule the doctor''s testimony', 'admissible, because a doctor is properly qualified as an expert in medical matters', 'admissible if other testimony establishes causal connection between the other passengers'' pain and the accident', 'inadmissible, because the testimony to neck pain is hearsay, not within any exception', 'inadmissible, because the testimony is not the best evidence of the other passengers'' pain and the passengers are not shown to be unavailable', 'B', 'While hearsay is generally inadmissible as evidence, a number of exclusions and exceptions allow statements that meet the definition of hearsay to be presented in court.

Expert witnesses frequently rely on the work of other experts to inform their opinions. The relied-upon professionals may not be present in court; in some instances, they may no longer even be alive. To what extent is an expert witness’s basis for an opinion admissible, and to what extent is it hearsay?

While various state courts differ as to the details of this question, some general guidelines can help attorneys begin to explore questions of hearsay in expert witness testimony.

Understanding Hearsay in the Expert Witness Context
Federal Rule of Evidence 703 allows an expert witness to “base an opinion on facts or data in the case that the expert has been made aware of or personally observed.”

Rule 703 goes on to explain that if the facts or data are the type that experts in the same field would reasonably rely on to form similar opinions, the facts or data do not have to be admissible in order for the witness’s opinion to be admissible. However, inadmissible facts or data may be disclosed to the jury “only if their probative value in helping the jury evaluate the opinion substantially outweighs their prejudicial effect.”

Rule 703 raises several issues worth considering when evaluating expert witness testimony for hearsay.', 'mbe_34', 0, '39'),
('mbe_380', 'mbe', '380', '214', 'MBE-1978-83-part5', '', '32', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'Pedersen''s counsel wants to have Sheriff testify to the following statement made to him by Walter Passenger, out of the presence of Carr: "We were returning from a party at which we had all been drinking." The trial judge should rule this testimony', 'admissible as an admission of a party', 'admissible as a declaration against interest', 'inadmissible as hearsay not within any exception', 'inadmissible because it would lead the court into nonessential side issues', 'C', 'Hearsay is generally defined as an out-of-court statement made by a declarant and offered for the truth of the matter asserted (see Nucci v. Proper, 95 N.Y.2d 597, 602, 721 N.Y.S.2d 593, 744 N.E.2d 128 [2001]; People v. Buie, 86 N.Y.2d 501, 505, 634 N.Y.S.2d 415, 658 N.E.2d 192 [1995];', 'mbe_2353', 0, '32'),
('mbe_381', 'mbe', '381', '214', 'MBE-1978-83-part5', '', '33', 'Carr ran into and injured Pedersen, a pedestrian. With Carr in his car were Wanda and Walter Passenger. Passerby saw the accident and called the police department, which sent Sheriff to investigate. All of these people are available as potential witnesses in the case of Pedersen v. Carr. Pedersen alleges that Carr, while drunk, struck Pedersen who was in a duly marked crosswalk.', 'On the evening of the day of the accident, Walter Passenger wrote a letter to his sister in which he described the accident. When Walter says he cannot remember some details of the accident, Pedersen''s counsel seeks to show him the letter to assist him in his testimony on direct examination. The trial judge should rule this', 'permissible under the doctrine of present recollection refreshed', 'permissible under the doctrine of past recollection recorded', 'objectionable because the letter was not a spontaneous utterance', 'objectionable because the letter is a self-serving declaration in so far as the witness, Walter, is concerned', 'A', 'In contrast, [u]nder present recollection refreshed the witness'' memory is refreshed or jogged through the employment of a writing, diagram, smell or even touch, and he testifies from his memory so refreshed. Because of the independent origin of the testimony actually elicited, the stimulation of an actual present recollection is not strictly bounded by fixed rules but, rather, is approached on a case-by-case basis looking to the peculiar facts and circumstances present.
Gibson, 333 N.C. at 50, 424 S.E.2d at 107. Because “the evidence is the testimony of the witness at trial, whereas with a past recollection recorded the evidence is the writing itself,” “the foundational questions raised by past recollection recorded are never reached.” Id. The relevant test, then, “is whether the witness has an independent recollection of the event and is merely using the memorandum to refresh details or whether the witness is using the memorandum as a testimonial crutch for something beyond his recall.” State v. York, 347 N.C. 79, 89, 489 S.E.2d 380, 386 (1997).', 'mbe_2354', 0, '33'),
('mbe_382', 'mbe', '382', '215', 'MBE-1978-83-part5', '', '34', '', 'The most generally accepted basis on which a court will hold that X has a legal duty to aid another is the recognition by X that there is immediate danger of serious harm to', 'another human being from a stranger''s wrongful conduct', 'his neighbor from a stranger''s wrongful conduct', 'his cousin from a stranger''s wrongful conduct', 'another human being from X''s own nonnegligent conduct', 'D', '“ ‘Duty is a legal conclusion about relationships between individuals, made after the fact.... The nature of the duty, and the specific persons to whom it is owed, are determined by the circumstances surrounding the conduct of the individual.’ ” Clohessy v. Bachelor, 237 Conn. 31, 45, 675 A.2d 852 (1996). Although one generally has no legal duty to aid another in peril, even when the aid can be provided without danger or inconvenience to the provider, there are four widely recognized situations in which the failure to act may constitute breach of a legal duty: (1) where one stands in a certain relationship to another; (2) where a statute imposes a duty to help another; (3) where one has assumed a contractual duty; and (4) where one voluntarily has assumed the care of another. 1 W. LaFave & A. Scott, supra, § 3.3(a)(1)–(4), pp. 284–87.14 The state argues that this case falls within both the first and fourth situations, or some combination thereof.', 'mbe_302', 0, '34'),
('mbe_383', 'mbe', '383', '216', 'MBE-1978-83-part5', '', '35', 'Questions 35-36 are based on the four case summaries below. For each question, select the case that would be most applicable as a precedent.', 'Jones, angry at a neighbor with whom he had quar. reled, for revenge surreptitiously removed a piece of stone statuary from the neighbor''s garden and concealed it in his garage. He intended to return it a day or two later, after giving the neighbor a chance to feel bad over its being stolen. Suspecting who was guilty, the neighbor had Jones arrested and charged with larceny.', 'Commonwealth v. Mason. Two sisters see a wealthy neighbor''s pedigreed dog on the street. They take the dog home, intending to conceal it until the owner offers a reward. Held, guilty of larceny.', 'Saferite v. State. Two young men saw a motor car on the street with the keys in the ignition lock. They drove the car to a neighboring town with the intention, they said, of visiting the wife of one of them. The car was wrecked on their way back. Conviction for larceny reversed.', 'People v. Noblett. Defendant, a tenant of a city apartment, advertised it for sublease. Will agreed to sublease for three months, and on March 12 paid Defendant $550, the total agreed rental. Will was to receive possession on March 20, but possession was never given him. Held, not guilty of common law larceny.', 'King v. Pear. From a stablekeeper, Defendant hired a horse to go to Sutton and back, saying he would be back at 8 p.m. He did not return. Invest. gation showed that Defendant had given a false address, and that he had sold the horse the same day. Conviction of larceny affirmed.', 'B', 'For purposes of 11 U.S.C. § 523(a)(4), “larceny” means the fraudulent and wrongful taking and carrying away of the property of another with intent to convert such property to the taker''s use without the consent of the owner. Sherali v. S & S Food Corp. (In re Sherali), 490 B.R. 104, 124 (Bankr. N.D. Tex. 2013)', 'mbe_303', 0, '35'),
('mbe_384', 'mbe', '384', '216', 'MBE-1978-83-part5', '', '36', 'Questions 35-36 are based on the four case summaries below. For each question, select the case that would be most applicable as a precedent.', 'Harris, a heroin addict, broke into a home and took several cameras and watches, which he promptly pawned to obtain cash with which to purchase a "fix." Harris was later charged with larceny of the cameras and watches.', 'Commonwealth v. Mason. Two sisters see a wealthy neighbor''s pedigreed dog on the street. They take the dog home, intending to conceal it until the owner offers a reward. Held, guilty of larceny.', 'Saferite v. State. Two young men saw a motor car on the street with the keys in the ignition lock. They drove the car to a neighboring town with the intention, they said, of visiting the wife of one of them. The car was wrecked on their way back. Conviction for larceny reversed.', 'People v. Noblett. Defendant, a tenant of a city apartment, advertised it for sublease. Will agreed to sublease for three months, and on March 12 paid Defendant $550, the total agreed rental. Will was to receive possession on March 20, but possession was never given him. Held, not guilty of common law larceny.', 'King v. Pear. From a stablekeeper, Defendant hired a horse to go to Sutton and back, saying he would be back at 8 p.m. He did not return. Invest. gation showed that Defendant had given a false address, and that he had sold the horse the same day. Conviction of larceny affirmed.', 'A', 'The general larceny crime is also divided into grand larceny and petit larceny depending upon the value of the property taken and whether it was taken from the person of another. 21 O.S.2011, § 1703 (larceny is divided into two degrees: grand larceny and petit larceny); 21 O.S.Supp.2016, § 1704 (grand larceny is larceny committed when the value of the property taken exceeds $1,000.00 or when such property, although not of value exceeding $1,000.00 is taken from the person of another; larceny in all other cases is petit larceny).
¶15 Title 21 O.S.2011, § 1717 further provides that “All animals of the dog kind, whether male or female, shall be considered the personal property of the owner thereof, for all purposes.” Title 21 O.S.2011, § 1718 states that: The taking of personal property of the kind defined in Section 1717 of this title, accomplished by fraud or stealth, and with the intent to deprive another thereof, is hereby defined as larceny and punishable in the same manner and to the same degree as in larceny of other descriptions of property. Id. (emphasis added). In other words, the theft of a dog may be prosecuted under the general larceny statute, i.e., Section 1701, as larceny of personal property.', 'mbe_304', 0, '36'),
('mbe_385', 'mbe', '385', '217', 'MBE-1978-83-part5', '', '37', '', 'Chase, as seller, and Scott, as buyer, enter into a written contract for the sale and purchase of land which is complete in all respects except that no reference is made to the quality of title to be conveyed. Which of the following will result?', 'The contract will be unenforceable.', 'Chase will be required to convey a marketable title.', 'Chase will be required to convey only what he owned on the date of the contract.', 'Chase will be required to convey only what he owned on the date of the contract plus whatever additional title rights he may acquire prior to the closing date.', 'B', '“Marketable title is one that may be ‘freely made the subject of resale’ and that can be sold at a ‘fair price to a reasonable purchaser or mortgaged to a person of reasonable prudence as security for the loan of money.’ ” Kelley v. Leucadia Fin. Corp., 846 P.2d 1238, 1243 (Utah 1992) (quoting 77 Am.Jur.2d Vendor and Purchaser § 131, at 313–14 (1975)).', 'mbe_2355', 0, '37'),
('mbe_386', 'mbe', '386', '218', 'MBE-1978-83-part5', '', '38', '', 'Baker, the seller, authorized Ruiz in writing to sign a contract for the sale and purchase of land for her. Arthur, the buyer, orally authorized Thomas to sign the contract for him. Ruiz and Thomas signed the contract: "Baker by Ruiz, her agent" and "Arthur by Thomas, his agent." Arthur refuses to complete the purchase. Baker sues Arthur who pleads the Statute of Frauds. Baker will', 'win, because the sales contract was in writing', 'win, because her agency contract was in writing', 'lose, because she did not sign the contract personally', 'lose, because Arthur''s agency contract was not in writing', 'D', 'The undisputed facts in this case support the trial court''s conclusion.  As a general rule, a contract involving the sale of land or interests therein “must be in writing to be enforceable.” Chomicky v. Buttolph, 147 Vt. 128, 130, 513 A.2d 1174, 1175 (1986); 12 V.S.A. § 181(5). An exception to this rule exists where a party demonstrates that he or she is equitably entitled to the claimed interest in land. Gorton, 167 Vt. at 361–62, 706 A.2d at 950–51. In such cases, “[e]nforcement is justified on the ground that repudiation by one party after the other has fully performed amounts to a virtual fraud.” Id. at 361, 706 A.2d at 950; see also Contractor''s Crane Serv., Inc. v. Vt. Whey Abatement Auth., 147 Vt. 441, 449, 519 A.2d 1166, 1172 (1986) (“[I]f a party relies on an oral promise, fully performing its end of the bargain, then a written promise is not required if it would be fraud to allow the promisor to deny the contract.”).', 'mbe_305', 0, '38'),
('mbe_387', 'mbe', '387', '219', 'MBE-1978-83-part5', '', '39', '', 'A state statute requires that all buses which operate as common carriers on the highways of the state shall be equipped with seat belts for passengers. Transport Lines, an interstate carrier, challenges the validity of the statute and the right of the state to make the requirement. What is the best basis for a constitutional challenge by Transport Lines?', 'Violation of the due process clause of the Fourteenth Amendment', 'Violation of the equal protection clause of the Fourteenth Amendment', 'Unreasonable burden on interstate commerce', 'Difficulty of enforcement', 'C', 'When a state law does not discriminate against interstate commerce, but burdens it in some way, the law will violate the dormant Commerce Clause under a rational basis test only if the burden on interstate commerce is clearly excessive in relation to the putative local benefits. U.S. Const. art. 1, § 8, cl. 3.', 'mbe_306', 0, '39'),
('mbe_388', 'mbe', '388', '220', 'MBE-1978-83-part5', '', '40', '', 'Amy Docent, a state college instructor, was discharged because of her refusal to comply with a state statute requiring public employees to swear or affirm that they will (1) "uphold and defend" the state and federal constitutions and (2) "oppose the overthrow" of the state or federal governments "by force, violence, or by any improper method." The statute had previously been held constitutional by the state supreme court. Docent filed a complaint in federal district court alleging the unconstitutionality of the statute and seeking an injunction and damages. Which of the following is the state''s strongest argument for sustaining the validity of the statute?', 'Government employment is a privilege, not a right.', 'The oath as a whole is only a commitment to abide by constitutional processes.', 'The First and Fourteenth Amendments permit a state to fix the conditions of state employment.', 'The state has a compelling need to keep disloyal persons out of governmental positions of trust.', 'B', 'Instead, as the U.S. Supreme Court has clarified, “the First Amendment simply protects a public employee''s right, in certain circumstances, to speak as a citizen addressing matters of public concern.” For this reason, if a public employee is not speaking as a private citizen and/or is not speaking about a matter of public concern, their federal employer is free to restrict their speech without violating the First Amendment.', 'mbe_307', 0, '40'),
('mbe_389', 'mbe', '389', '221', 'MBE-1978-83-part5', '', '41', 'All lawyers practicing in the state of Erewhon must be members of the State Bar Association, by order of the state supreme court. Several state officials serve on the Bar Association''s Board of Bar Governors. The Board of Bar Governors authorizes the payment of dues for two staff members to the Cosmopolitan Club, a private dining club licensed to sell alcohol beverages. The Cosmopolitan Club is frequented by affluent businessmen and professionals and by legislators. It is generally known that the purpose of the membership of the Bar Association staff is to enable them to go where members of the "elite" meet and to lobby for legislation in which the Bar Association is interested. The State Bar Association has numerous committees and subcommittees concerned with family law, real estate law, unauthorized practice, etc., and its recommendations often influence state policy. Some committee meetings are held at the Cosmopolitan Club. The club is known to have rules which restrict membership by race, religion, and sex. Plaintiffs, husband and wife, who are members of the Erewhon Bar Association, petition the Board of Bar Governors to adopt a resolution prohibiting the payment of club dues to and the holding of meetings of the Bar Association or its committees at places which discriminate on the basis of race, religion, or sex. After substantial public discussion, the Board of Bar Governors, by a close vote, fails to pass such a resolution. These events receive extensive coverage in the local newspapers. Plaintiffs bring an action in federal court seeking an injunction against such payments and the holding of meetings in such places as the Cosmopolitan Club.', 'The strongest argument for plaintiffs is', 'private rights to discriminate and associate freely must defer to a public interest against discrimination on the basis of race, religion, or sex', 'the failure of the State Bar Association to pass a resolution forbidding discrimination on the basis of race, religion, or sex constitutes a denial of equal protection', 'the State Bar Association is an agency of the state and its payment of dues to such private clubs promotes discrimination on the basis of race, religion, and sex', 'the State Bar Association''s payment of dues to such private clubs promotes discrimination on the basis of race, religion, and sex', 'C', 'When the government expressly classifies persons on the basis of race or national origin, however, its action is “ ‘immediately suspect.’ ” Johnson v. California, 543 U.S. 499, 125 S.Ct. 1141, 1148, 160 L.Ed.2d 949 (2005) (quoting Shaw v. Reno, 509 U.S. 630, 642, 113 S.Ct. 2816, 125 L.Ed.2d 511 (1993)). A plaintiff in such a lawsuit need not make an extrinsic showing of discriminatory animus or a discriminatory effect to trigger strict scrutiny. “No inquiry into legislative purpose is necessary when the racial classification appears on the face of the statute.”  Shaw, 509 U.S. at 642, 113 S.Ct. 2816. The burden of proof shifts, strict scrutiny applies, and “[u]nder strict scrutiny, the government [defending the constitutionality of the law] has the burden of proving that racial classifications ‘are narrowly tailored measures that further compelling governmental interests.’ ” Johnson, 125 S.Ct. at 1146 (quoting Adarand, 515 U.S. at 227, 115 S.Ct. 2097). As noted above, the Supreme Court has explained that we “ ‘apply strict scrutiny to all racial classifications to “smoke out” illegitimate uses of race by assuring that government is pursuing a goal important enough to warrant use of a highly suspect tool.’ ” Id. (quoting Croson, 488 U.S. at 493, 109 S.Ct. 706 (plurality opinion)) (emphasis in Johnson; alteration incorporated).', 'mbe_2643', 0, '41'),
('mbe_39', 'mbe', '39', '23', 'MBE-1972-78-part2', '', '40', '', 'Odum owned Brightacre (a tract of land) in fee simple. He conveyed it "to Pike, his heirs and assigns; but if Farley shall be living thirty years from the date of this deed, then to Farley, his heirs and assigns." The limitation "to Farley, his heirs and assigns" is', 'valid, because Farley''s interest is a reversion', 'valid, because the interest will vest, if at all, within a life in being', 'valid, because Farley''s interest is vested subject to divestment', 'invalid', 'B', 'the Rule Against Perpetuities. The Rule is violated when there is a possibility of vesting beyond the perpetuity period. Melcher v. Camp, supra, 435 P.2d at page 115.', 'mbe_35', 0, '40'),
('mbe_390', 'mbe', '390', '221', 'MBE-1978-83-part5', '', '42', 'All lawyers practicing in the state of Erewhon must be members of the State Bar Association, by order of the state supreme court. Several state officials serve on the Bar Association''s Board of Bar Governors. The Board of Bar Governors authorizes the payment of dues for two staff members to the Cosmopolitan Club, a private dining club licensed to sell alcohol beverages. The Cosmopolitan Club is frequented by affluent businessmen and professionals and by legislators. It is generally known that the purpose of the membership of the Bar Association staff is to enable them to go where members of the "elite" meet and to lobby for legislation in which the Bar Association is interested. The State Bar Association has numerous committees and subcommittees concerned with family law, real estate law, unauthorized practice, etc., and its recommendations often influence state policy. Some committee meetings are held at the Cosmopolitan Club. The club is known to have rules which restrict membership by race, religion, and sex. Plaintiffs, husband and wife, who are members of the Erewhon Bar Association, petition the Board of Bar Governors to adopt a resolution prohibiting the payment of club dues to and the holding of meetings of the Bar Association or its committees at places which discriminate on the basis of race, religion, or sex. After substantial public discussion, the Board of Bar Governors, by a close vote, fails to pass such a resolution. These events receive extensive coverage in the local newspapers. Plaintiffs bring an action in federal court seeking an injunction against such payments and the holding of meetings in such places as the Cosmopolitan Club.', 'Which of the following actions should a federal district court take with respect to jurisdiction?', 'Hear the case on the merits, because a federal claim is presented.', 'Hear the case on the merits, because the expenditure of state funds in support of segregation is forbidden by the Fifth Amendment.', 'Abstain from jurisdiction, because the constitutional issue should be litigated first in a state court.', 'Dismiss the case for lack of jurisdiction, because the issue of Bar Association activities is solely within the domain of state law.', 'A', '“[F]ederal jurisdiction demands not only a contested federal issue, *1010 but a substantial one, indicating a serious federal interest in claiming the advantages thought to be inherent in a federal forum.” Singh, 538 F.3d at 338.', 'mbe_2644', 0, '42'),
('mbe_391', 'mbe', '391', '222', 'MBE-1978-83-part5', '', '43', 'In 1945 Owen, owner of both Blackacre and Whiteacre, executed and delivered two separate deeds by which he conveyed the two tracts of land as follows: Blackacre was conveyed "To Alpha and his heirs as long as it is used exclusively for residential purposes, but if it is ever used for other than residential purposes, to the American Red Cross." Whiteacre was conveyed "To Beta and her heirs as long as it is used exclusively for residential purposes, but if it is used for other than residential purposes prior to 1965, then to the Salvation Army." In 1950 Owen died leaving a valid will by which he devised all his real estate to his brother, Bill. The will had no residuary clause. Owen was survived by Bill and by Owen''s daughter, Della, who was Owen''s sole heir. For the purpose of this set of questions, it may be assumed that the common law rule against perpetuities applies in the state where the land is located and that the state also has a statute providing that, "All future estates and interests are alienable, descendible, and devisable in the same manner as possessory estates and interests."', 'In 1955 Alpha and Della entered into a contract with John whereby Alpha and Della contracted to sell Blackacre to John in fee simple. After examining title, John refused to perform on the ground that Alpha and Della could not give good title. Alpha and Della joined in an action against John for specific performance. Prayer for specific performance will be', 'granted, because Alpha and Della together own a fee simple absolute in Blackacre', 'granted, because Alpha alone owns the entire fee simple in Blackacre', 'denied, because Bill has a valid interest in Blackacre', 'denied, because the American Red Cross has a valid interest in Blackacre', 'C', 'Specific performance is an equitable remedy, and the decision whether or not to order it is “confided to the ‘sound and informed discretion’ of the trial court.” “Specific performance of a contract is ordered when the legal remedy, usually money damages, is deemed to be either inadequate or impracticable. When land is the subject matter of the agreement, the legal remedy is assumed to be inadequate, since each parcel of land is unique....” Thus, it is routine for courts to enforce contracts to purchase real estate by ordering that they be specifically performed.', 'mbe_308', 0, '43'),
('mbe_392', 'mbe', '392', '222', 'MBE-1978-83-part5', '', '44', 'In 1945 Owen, owner of both Blackacre and Whiteacre, executed and delivered two separate deeds by which he conveyed the two tracts of land as follows: Blackacre was conveyed "To Alpha and his heirs as long as it is used exclusively for residential purposes, but if it is ever used for other than residential purposes, to the American Red Cross." Whiteacre was conveyed "To Beta and her heirs as long as it is used exclusively for residential purposes, but if it is used for other than residential purposes prior to 1965, then to the Salvation Army." In 1950 Owen died leaving a valid will by which he devised all his real estate to his brother, Bill. The will had no residuary clause. Owen was survived by Bill and by Owen''s daughter, Della, who was Owen''s sole heir. For the purpose of this set of questions, it may be assumed that the common law rule against perpetuities applies in the state where the land is located and that the state also has a statute providing that, "All future estates and interests are alienable, descendible, and devisable in the same manner as possessory estates and interests."', 'In 1946 the interest of the American Red Cross in Blackacre could be best described as a', 'valid contingent remainder', 'void executory interest', 'valid executory interest', 'void contingent remainder', 'B', 'The word “vest” in regards to the Rule refers to an immediate, fixed right of present or future enjoyment of the interest. Vest, BLACK''S LAW DICTIONARY (10th ed. 2014); see also Peveto, 645 S.W.2d at 772. The Rule does not apply to present or future interests that vest at their creation. Laddex, 513 S.W.3d at 480.  An executory interest is a future interest, held by a third person, that either cuts off another''s interest or begins after the natural termination of a preceding estate. Executory Interest, BLACK''S LAW DICTIONARY (10th ed. 2014). A springing executory interest is one that operates to end an interest left in the transferor. Springing Executory Interest, BLACK''S LAW DICTIONARY (10th ed. 2014); accord Peveto, 645 S.W.2d at 772. This interest does not vest at the execution of the deed, rather “executory interests vest an estate in the holder of the interest upon the happening of a condition or event.” 3 RICHARD R. POWELL, POWELL ON REAL PROPERTY § 20.05[2] (Michael Allan Wolf ed.). “Until such happening, they are non-vested future interests” and are subject to the Rule. Id. In contrast, a possibility of reverter is a future interest held by the grantor and is not subject to the Rule because it vests at the moment of creation. El Dorado Land Co., L.P. v. City of McKinney, 395 S.W.3d 798, 802–03 (Tex. 2013); see Luckel v. White, 819 S.W.2d 459, 464 (Tex. 1991). A possibility of reverter is “the grantor''s right to fee ownership in the real property reverting to him if the condition terminating the determinable fee occurs.” Luckel, 819 S.W.2d at 464. This interest is properly viewed as a “claim[ ] to property that the grantor never gave away.” El Dorado Land Co., L.P., 395 S.W.3d at 802–03 (citing 3 POWELL ON REAL PROPERTY § 20.02[1] ).T', 'mbe_309', 0, '44'),
('mbe_393', 'mbe', '393', '223', 'MBE-1978-83-part5', '', '45', 'Brill saved the life of Ace''s wife, Mary, who thereafter changed her will to leave Brill $1,000. However, upon Mary''s death she had no property except an undivided interest in real estate held in tenancy by the entirety of Ace. The property had been purchased by Ace from an inheritance. After Mary died, Ace signed and delivered to Brill the following instrument: "In consideration of Brill''s saving my wife''s life and his agreement to bring no claims against my estate based on her will, I hereby promise to pay Brill $1,000." Upon Ace''s death, Brill filed a claim for $1,000. Ace''s executor contested the claim on the ground that the instrument was not supported by sufficient consideration.', 'In most states, would Brill''s saving of Mary''s life be regarded as sufficient consideration for Ace''s promise?', 'Yes, because Ace was thereby morally obligated to Brill', 'Yes, because Ace was thereby materially benefited', 'No, because Ace had not asked Brill to save her', 'No, because the value of Brill''s act was too uncertain', 'C', 'Consideration is “some right, interest, profit or benefit or some forbearance, detriment, loss or responsibility given, suffered or undertaken by the other.” Homestyle Direct, LLC v. DHS, 354 Or. 253, 262, 311 P.3d 487 (2013); see also Restatement (Second) of Contracts § 71(2) (1981) (defining “consideration” as a performance or return promise “sought by the promisor in exchange for his promise” and “given by the promisee in exchange for that promise”). Consideration is “the basis for a bargain that two parties reach; it is what is sought by the promisor in exchange for a promise and given by the promisee in exchange for the promise.” State v. Villagomez, 362 Or. 390, 397, 412 P.3d 183 (2018).', 'mbe_177', 0, '45'),
('mbe_394', 'mbe', '394', '223', 'MBE-1978-83-part5', '', '46', 'Brill saved the life of Ace''s wife, Mary, who thereafter changed her will to leave Brill $1,000. However, upon Mary''s death she had no property except an undivided interest in real estate held in tenancy by the entirety of Ace. The property had been purchased by Ace from an inheritance. After Mary died, Ace signed and delivered to Brill the following instrument: "In consideration of Brill''s saving my wife''s life and his agreement to bring no claims against my estate based on her will, I hereby promise to pay Brill $1,000." Upon Ace''s death, Brill filed a claim for $1,000. Ace''s executor contested the claim on the ground that the instrument was not supported by sufficient consideration.', 'With respect to the recital that Brill had agreed not to file a claim against Ace''s estate, what additional fact would most strengthen Brill''s claim?', 'Brill''s agreement was made in a writing he signed.', 'Brill reasonably believed he had a valid claim when the instrument was siged.', 'Mary had contribute to accumulation of the real property.', 'Brill paid Ace $1 when he received the instrument.', 'B', 'Contracts often contain recitals: provisions that do not make binding promises but merely recite background information about factual context or the parties’ intentions. Maryland law recognizes the general principle that such recitals are not binding and, while they may aid the court in interpreting the contract''s operative terms, cannot displace or supplement operative terms that are clear. See Pulaski v. Riland, 199 Md. 426, 86 A.2d 907, 910 (1952); Cty. Comm''rs of Charles Cty. v. Panda-Brandywine, L.P., 663 F. Supp. 2d 424, 430 (D. Md. 2009), aff''d, 401 F. App''x 831 (4th Cir. 2010). While such recitals are often set forth at the beginning of the agreement in “whereas” clauses, that is not always the case. See, e.g., Aramony v. United Way of America, 254 F.3d 403, 406, 413 (2d Cir. 2001) (concluding section titled “Purpose of the Plan” in ERISA plan document consisted of nonbinding recitals).', 'mbe_310', 0, '46'),
('mbe_395', 'mbe', '395', '223', 'MBE-1978-83-part5', '', '47', 'Brill saved the life of Ace''s wife, Mary, who thereafter changed her will to leave Brill $1,000. However, upon Mary''s death she had no property except an undivided interest in real estate held in tenancy by the entirety of Ace. The property had been purchased by Ace from an inheritance. After Mary died, Ace signed and delivered to Brill the following instrument: "In consideration of Brill''s saving my wife''s life and his agreement to bring no claims against my estate based on her will, I hereby promise to pay Brill $1,000." Upon Ace''s death, Brill filed a claim for $1,000. Ace''s executor contested the claim on the ground that the instrument was not supported by sufficient consideration.', 'On which of the following theories would it be most likely that Brill could recover?', 'Ace and Brill have made a compromise.', 'Ace must give restitution for benefits it would be unjust to retain.', 'Ace is bound by promissory estoppel.', 'Ace executed a binding unilateral contract.', 'A', '“A compromise is valid if there is a meeting of the minds of the parties as to exactly what they intended when the compromise was reached.” Sileo v. Berger, 2011-0295, p. 8 (La.App. 4 Cir. 9/28/11), 74 So.3d 753, 758–59 (citing Elder v. Elder & Elder Enter., Ltd., 2006-0703, p. 3 (La.App. 4 Cir. 1/11/07), 948 So.2d 348, 350); Feingerts v. State Farm Mut. Auto. Ins. Co., 2012-1598, p. 11 (La.App. 4 Cir. 6/26/13), 117 So.3d 1294, 1301. “Compromises are favored in the law and the burden of proving the invalidity of such an agreement is on the party attacking it.” Sileo, 2011–0295 at p. 8, 74 So.3d at 759 (citing Elder, 2006–0703 at p. 3, 948 So.2d at 350).
Contracts are formed by the consent of the parties established through offer and acceptance. La. C.C. art. 1927. “It follows that an enforceable compromise agreement formed by offer and acceptance[ ] may not be revoked by either party. The ‘flip side’ of this principle is that an agreement that has not been formed by offer and acceptance is not enforceable and therefore can be revoked by either party.” Richardson v. O''Byrne, 2000-2202, p. 8 (La.App. 4 Cir. 10/16/02), 830 So.2d 1013, 1020.', 'mbe_311', 0, '47'),
('mbe_396', 'mbe', '396', '224', 'MBE-1978-83-part5', '', '48', '', 'Brown suffered from the delusion that he was a special agent of God. He frequently experienced hallucinations in the form of hearing divine commands. Brown believed God told him several times that the local Roman Catholic bishop was corrupting the diocese into heresy, and that the bishop should be "done away with." Brown, a devout Catholic, conceived of himself as a religious martyr. He knew that shooting bishops for heresy is against the criminal law. He nevertheless carefully planned how he might kill the bishop. One evening Brown shot the bishop, who was taken to the hospital where he died two weeks later. Brown told the police he assumed the institutions of society would support the ecclasiastical hierarchy, and he expected to be persecuted for his God-inspired actions. Psychiatrist Stevens examined Brown and found that Brown suffered from schizophrenic psychosis, that in the absence of this psychosis he would not have shot the bishop, and that because of the psychosis Brown found it extremely difficult to determine whether he should obey the specific command that he do away with the bishop or the general commandment "Thou shalt not kill." Brown was charged with murder. If Brown interposes an insanity defense and the jurisdiction in which he is tried has adopted only the M''Naghten test of insanity, then the strongest argument for the defense under that test is that', 'Brown did not know the nature of the act he was performing', 'Brown did not know that his act was morally wrong', 'Brown did not know the quality of the act he was performing', 'Brown''s acts were the product of a mental disease', 'B', '“A finding of insanity based upon OCGA § 16-3-3 requires proof that (1) the accused acted under a delusional compulsion; (2) the criminal act was connected with the delusion; and (3) the delusion related to a fact which, if true, would have justified the act.” Appling v. State, 222 Ga.App. 327, 329 (3), 474 S.E.2d 237 (1996) (citation omitted). Here, all three requirements were shown.', 'mbe_312', 0, '48'),
('mbe_397', 'mbe', '397', '225', 'MBE-1978-83-part5', '', '49', 'Walker, a pedestrian, started north across the street in a clearly marked north-south crosswalk with the green traffic light in her favor. Walker was in a hurry, and so before reaching the north curb of the street, she cut to her left diagonally across the street to the east-west crosswalk and started across it. Just after reaching the east-west crosswalk, the traffic light turned green in her favor. She proceeded about five steps farther across the street to the west in the crosswalk when she was struck by a car approaching from her right that she thought would stop, but did not. The car driven by Driver, 81 years of age, who failed to stop his car after seeing that the traffic light was red against him. Walker had a bone disease, resulting in very brittle bones, that is prevalent in only 0.02 percent of the population. As a result of the impact Walker suffered a broken leg and the destruction of her family heirloom, a Picasso original painting that she was taking to her bank for safe-keeping. The painting had been purchased by Walker''s grandmother for $750 but was valued at $500,000 at the time of the accident. Walker has filed suit against Driver. Driver''s attorney has alleged that Walker violated a state statute requiring that pedestrians stay in the crosswalks, and that if Walker had not violated the statute she would have had to walk 25 feet more to reach the impact point and therefore would not have been at a place where she could have been hit by Driver. Walker''s attorney ascertains that there is a statute as alleged by Driver, that his measurements are correct, that there is a state statute requiring observance of traffic lights, and that Driver''s license expired two years prior to the collision.', 'The violation of the crosswalk statute by Walker should not defeat her cause of action against Driver because', 'Driver violated the traffic light statute at a later point in time than Walker''s violation', 'pedestrians are entitled to assume that automobile drivers will obey the law', 'Walker was hit while in the crosswalk', 'the risks that the statute was designed to protect against probably did not include an earlier arrival at another point', 'D', 'A statute''s violation is deemed negligence per se if the claimed injury (a) was caused by the law''s violation, (b) was of the type intended to be prevented by the statute, and (c) the injured party was a member of the class meant to be protected by the statute. Lockhart, ¶ 6. The determinative issue of law in this appeal from a summary judgment is whether violation of § 154 constitutes a negligent breach of the standard of care.', 'mbe_313', 0, '49'),
('mbe_398', 'mbe', '398', '225', 'MBE-1978-83-part5', '', '50', 'Walker, a pedestrian, started north across the street in a clearly marked north-south crosswalk with the green traffic light in her favor. Walker was in a hurry, and so before reaching the north curb of the street, she cut to her left diagonally across the street to the east-west crosswalk and started across it. Just after reaching the east-west crosswalk, the traffic light turned green in her favor. She proceeded about five steps farther across the street to the west in the crosswalk when she was struck by a car approaching from her right that she thought would stop, but did not. The car driven by Driver, 81 years of age, who failed to stop his car after seeing that the traffic light was red against him. Walker had a bone disease, resulting in very brittle bones, that is prevalent in only 0.02 percent of the population. As a result of the impact Walker suffered a broken leg and the destruction of her family heirloom, a Picasso original painting that she was taking to her bank for safe-keeping. The painting had been purchased by Walker''s grandmother for $750 but was valued at $500,000 at the time of the accident. Walker has filed suit against Driver. Driver''s attorney has alleged that Walker violated a state statute requiring that pedestrians stay in the crosswalks, and that if Walker had not violated the statute she would have had to walk 25 feet more to reach the impact point and therefore would not have been at a place where she could have been hit by Driver. Walker''s attorney ascertains that there is a statute as alleged by Driver, that his measurements are correct, that there is a state statute requiring observance of traffic lights, and that Driver''s license expired two years prior to the collision.', 'The failure of Driver to have a valid driver''s license has which of the following effects?', 'It makes Driver liable to Walker because Driver is a trespasser on the highway.', 'It would not furnish a basis for liability.', 'It proves that Driver is an unfit driver in this instance.', 'It makes Driver absolutely liable for Walker''s injury.', 'B', 'Contributory negligence is defined as “conduct on the part of the plaintiff which falls below the standard to which he should conform for his own protection and which is the legally contributing cause, cooperating with the negligence of the defendant, in bringing about the plaintiff''s harm.” Guerra, 204 Kan. at 313, 461 P.2d 737. Over time, however, this court recognized distinctions between the two doctrines, with contributory negligence seen as arising from tort law, while assumption of risk arose from an implied contract. Guerra, 204 Kan. at 313, 461 P.2d 737.', 'mbe_314', 0, '50'),
('mbe_399', 'mbe', '399', '225', 'MBE-1978-83-part5', '', '51', 'Walker, a pedestrian, started north across the street in a clearly marked north-south crosswalk with the green traffic light in her favor. Walker was in a hurry, and so before reaching the north curb of the street, she cut to her left diagonally across the street to the east-west crosswalk and started across it. Just after reaching the east-west crosswalk, the traffic light turned green in her favor. She proceeded about five steps farther across the street to the west in the crosswalk when she was struck by a car approaching from her right that she thought would stop, but did not. The car driven by Driver, 81 years of age, who failed to stop his car after seeing that the traffic light was red against him. Walker had a bone disease, resulting in very brittle bones, that is prevalent in only 0.02 percent of the population. As a result of the impact Walker suffered a broken leg and the destruction of her family heirloom, a Picasso original painting that she was taking to her bank for safe-keeping. The painting had been purchased by Walker''s grandmother for $750 but was valued at $500,000 at the time of the accident. Walker has filed suit against Driver. Driver''s attorney has alleged that Walker violated a state statute requiring that pedestrians stay in the crosswalks, and that if Walker had not violated the statute she would have had to walk 25 feet more to reach the impact point and therefore would not have been at a place where she could have been hit by Driver. Walker''s attorney ascertains that there is a statute as alleged by Driver, that his measurements are correct, that there is a state statute requiring observance of traffic lights, and that Driver''s license expired two years prior to the collision.', 'If Walker establishes liability on the part of Driver for her physical injuries, should Walker''s recovery include damages for a broken leg?', 'No, since only 0.02 percent of the population have bones as brittle as Walker''s', 'No, unless a person of ordinary health would probably have suffered a broken leg from the impact', 'Yes, because Driver could foresee that there would be unforeseeable consequences of the impact', 'Yes, even though the extent of the injury was not a foreseeable consequence of the impact', 'D', 'the so-called “eggshell plaintiff” rule. Under this principle, the tortfeasor is responsible for the full extent of the plaintiff''s damages even if those injuries would not have occurred but for the plaintiff''s pre-existing physical condition, disease, or susceptibility to injury.', 'mbe_315', 0, '51'),
('mbe_4', 'mbe', '4', '2', 'MBE-1972-78-part2', '', '5', 'Sue owned a five-acre tract of land, one acre of which had previously been owned by Opal, but to which Sue had acquired title by adverse possession. Sue contracted to convey the full five-acre tract to Peg, but the contract did not specify the quality of title Sue would convey. At closing, Peg refused the tendered deed and demanded return of her earnest money.', 'Suppose Peg pays the purchase price and accepts a deed. Subsequently, Sue''s title to the one acre proves inadequate and Opal ejects Peg from that acre. Peg sues Sue for damages. Which of the following statements applies most accurately to the determination of Peg''s rights?', 'Sue''s deed was fraudulent.', 'The terms of the deed control Sue''s liability.', 'The only remedy available for breach of warranty of title is rescission.', 'Peg''s rights are based on the implied covenant that the title conveyed shall he marketable.', 'B', 'They are distinguishable  as well because they are predicated on the well-settled rule that a trustee in a deed of trust can only do with the trust property what the deed either in express terms or by necessary implication authorizes him to do. In other words, the powers of the person foreclosing under a mortgage or deed of trust are limited and defined by the instrument under which he acts, and he has only such authority as is thus expressly conferred upon him, together with incidental and implied powers that are necessarily included therein. Accordingly, the trustee or mortgagee must see that in all material matters he keeps within his powers, and must execute the trust in strict compliance therewith.
Schmidt & Wilson, Inc. v. Carneal, 164 Va. 412, 415, 180 S.E. 325, 326 (1935).3', 'mbe_2318', 0, '5'),
('mbe_40', 'mbe', '40', '24', 'MBE-1972-78-part2', '', '41', 'Neff and Owens owned adjoining residences in Smithville. In 1971, they hired a contractor to lay sidewalks in front of both of their homes. Each man was to pay the contractor for that part of the work attributable to his property. After he had paid the bill which the contractor had submitted to him, Neff became convinced that the contractor had erred and had charged him for labor and materials which were used for part of the sidewalk in front of Owens'' property. Neff thereupon asked Owens to reimburse him for the amount which he assumed he had erroneously paid the contractor. After a lengthy discussion, and although he was still convinced that he owed Neff nothing, Owens finally said: "I want to avoid trouble, and so if you agree not to sue for reimbursement, I''ll employ a caretaker for a three-year term to keep our sidewalks free of ice and snow." Neff orally assented. Although he could have hired the man for three years, Owens hired Parsons in October, 1971, to keep the snow and ice off the sidewalks for the winter, November 1971-March 1972. During the early fall of 1972, Owens decided to go to Florida for the winter. He told his nephew, Morse, that he could live in Owens'' house for the winter provided Morse would hire someone to keep the snow and ice off the walks in front of both Neff''s and Owens'' properties, and suggested that Morse could hire Parsons for that task at relatively little cost. Morse moved into Owens'' home in October, 1972, but moved out November, 1972, prior to any icing or snowfall. He did not employ anyone to remove snow and ice in front of either property. Owens did not know that Morse had moved out of his home until he returned to Smithville in the spring. During the winter Neff had kept his own walks clean. No one cleaned the snow and ice from the walks in front of Owens'' property.', 'Assume that the contractor had made no error and that Neff had paid only for labor and materials for the walk in front of his own property. Was Owens'' promise to hire a caretaker supported by consideration?', 'Yes.', 'No, because Owens did not believe that Neff had a valid claim.', 'No, because Neff''s claim was groundless.', 'No, because Owens'' promise to employ the caretaker was aleatory.', 'A', 'A contract is aleatory when, because of its nature or according to the parties'' intent, the performance of either party''s obligation, or the extent of the performance, depends on an uncertain event.', 'mbe_36', 0, '41'),
('mbe_400', 'mbe', '400', '225', 'MBE-1978-83-part5', '', '52', 'Walker, a pedestrian, started north across the street in a clearly marked north-south crosswalk with the green traffic light in her favor. Walker was in a hurry, and so before reaching the north curb of the street, she cut to her left diagonally across the street to the east-west crosswalk and started across it. Just after reaching the east-west crosswalk, the traffic light turned green in her favor. She proceeded about five steps farther across the street to the west in the crosswalk when she was struck by a car approaching from her right that she thought would stop, but did not. The car driven by Driver, 81 years of age, who failed to stop his car after seeing that the traffic light was red against him. Walker had a bone disease, resulting in very brittle bones, that is prevalent in only 0.02 percent of the population. As a result of the impact Walker suffered a broken leg and the destruction of her family heirloom, a Picasso original painting that she was taking to her bank for safe-keeping. The painting had been purchased by Walker''s grandmother for $750 but was valued at $500,000 at the time of the accident. Walker has filed suit against Driver. Driver''s attorney has alleged that Walker violated a state statute requiring that pedestrians stay in the crosswalks, and that if Walker had not violated the statute she would have had to walk 25 feet more to reach the impact point and therefore would not have been at a place where she could have been hit by Driver. Walker''s attorney ascertains that there is a statute as alleged by Driver, that his measurements are correct, that there is a state statute requiring observance of traffic lights, and that Driver''s license expired two years prior to the collision.', 'Walker''s violation of the crosswalk statute should not be considered by the jury because', 'there is no dispute in the evidence about factual cause', 'as a matter of law the violation of the statute results in liability for all resulting harm', 'as a matter of aw Driver''s conduct was an independent intervening cause', 'as a matter of law the injury to Walker was not the result of a risk the statute was designed to protect against', 'D', '“Under that doctrine [of negligence per se], the unexcused violation of a statute or ordinance constitutes negligence per se if the provision (1) ‘protect[s] the class of persons in which the plaintiff is included’ and (2) ‘protect[s] against the type of harm which has occurred as a result of the violation.’ ” Stachowski, 95 N.E.3d at 544 (quoting City of Fort Wayne v. Parrish, 32 N.E.3d 275, 277 (Ind. Ct. App. 2015)).', 'mbe_316', 0, '52'),
('mbe_401', 'mbe', '401', '226', 'MBE-1978-83-part6', '', '1', '', 'Paulsen was eating in a restaurant when he began to choke on a piece of food that had lodged in his throat. Dow, a physician who was sitting at a nearby table, did not wish to become involved and did not render any assistance, although prompt medical attention would have been effective in removing the obstruction from Paulsen''s throat. Because of the failure to obtain prompt medical attention, Paulsen suffered severe brain injury from lack of oxygen. If Paulsen asserts a claim against Dow for his injuries, will Paulsen prevail?', 'Yes, if the jurisdiction relieves physicians of malpractice liability for emergency first aid.', 'Yes, if a reasonably prudent person with Dow''s experience, training, and knowledge would have assisted Paulsen.', 'No, because Dow was not responsible for Paulsen''s condition.', 'No, unless Dow knew that Paulsen was substantially certain to sustain serious injury.', 'C', 'Generally, a bystander has no duty to provide affirmative aid to an injured person, even if the bystander has the ability to help.', 'mbe_317', 0, '1'),
('mbe_402', 'mbe', '402', '227', 'MBE-1978-83-part6', '', '2', 'The state of Champlain enacts the Young Adult Marriage Counseling Act, which provides that, before any persons less than 30 years of age may be issued a marriage license, they must receive at least five hours of marriage counseling from a state-licensed social worker. This counseling is designed to assure that applicants for marriage licenses know their legal rights and duties in relation to marriage and parenthood, understand the "true nature" of the marriage relationship, and understand the procedures for obtaining divorces.', 'Pine, aged 25, contemplates marrying Ross, aged 25. Both are residents of the state of Champlain. Pine has not yet proposed to Ross because he is offended by the counseling requirement. Pine sues in federal court seeking a declaratory judgment that the Young Adult Marriage Counseling Act is unconstitutional. Which of the following is the clearest ground for dismissal of this action by the court?', 'Pine and Ross are residents of the same state.', 'No substantial federal question is presented.', 'The suit presents a nonjusticiable political question.', 'The suit is unripe.', 'D', 'As used here, “ripeness” refers to “ ‘an aspect of the doctrine of justiciability, specifically, the requirement that there be an actual, as opposed to a hypothetical, injury to the individual invoking the judicial power.’ ” Beck v. City of Portland, 202 Or. App. 360, 366, 122 P.3d 131 (2005) (quoting Coast Range Conifers v. Board of Forestry, 192 Or. App. 126, 129, 83 P.3d 966 (2004), rev''d on other grounds, 339 Or. 136, 117 P.3d 990 (2005)). In U.S. West Communications v. City of Eugene, 336 Or. 181, 81 P.3d 702 (2003), the court concluded that ORS 28.020—which allows a person to seek a declaratory judgment if the person’s rights “are affected by a constitution, statute, municipal charter, ordinance, contract or franchise”—codifies a ripeness requirement for justiciability of a declaratory relief action. 336 Or. at 191, 81 P.3d 702; see also Beck, 202 Or. App. at 366, 122 P.3d 131 (describing U.S. West Communications as “appl[ying] the test for ripeness set out in [two prior cases] in which the court explicitly identified ripeness as a jurisdictional issue”). “[T]he legislature’s use of the present tense phrase ‘are affected’ implies [that] the controversy must involve a dispute based on present facts rather than on contingent or hypothetical events.” U.S. West Communications, 336 Or. at 191, 81 P.3d 702. Similarly, ORS 34.040 requires that “a substantial interest of a plaintiff has been injured” (emphasis added), thereby codifying a ripeness requirement for justiciability of a writ of review proceeding.', 'mbe_318', 0, '2'),
('mbe_403', 'mbe', '403', '227', 'MBE-1978-83-part6', '', '3', 'The state of Champlain enacts the Young Adult Marriage Counseling Act, which provides that, before any persons less than 30 years of age may be issued a marriage license, they must receive at least five hours of marriage counseling from a state-licensed social worker. This counseling is designed to assure that applicants for marriage licenses know their legal rights and duties in relation to marriage and parenthood, understand the "true nature" of the marriage relationship, and understand the procedures for obtaining divorces.', 'In a case in which the constitutionality of the Young Adult Marriage Counseling Act is in issue, the burden of persuasion will probably be on the', 'person challenging the law, because there is a strong presumption that elected state legisla. tors acted properly', 'person challenging the law, because the Tenth Amendment authorizes states to determine the conditions on which they issue marriage licenses', 'state, because there is a substantial impact on the right to marry, and that right is fundamental', 'state, because there is a substantial impact on the discrete and insular class of young adults', 'C', 'Two types of classifications cause the Court to depart from its usual rational basis scrutiny under the Equal Protection Clause: when group burdened by the classification is "suspect"  (e.g., a racial or  ethnic minority,  women,  aliens)  or when  the classification burdens  what the Court  determines to  be  a  "fundamental  right."  The Court  has  been reluctant  to  add to what  was  a relatively short  list of fundamental rights  recognized beginning in the 1960s, and specifically rejected the suggestions, for example, that welfare payments or education be labeled the sort of fundamental rights that trigger heightened scrutiny.  Heightened scutiny has been limited to cases involving substantial burdens placed on the right to vote, the right to be a candidate (access to the ballot), the right to migrate to another state, the right to marry and procreate and live as a family unit, and to fees that prevent indigents from obtaining equal access to justice  (e.g, divorcing, maintaining parental rights, and obtaining transcripts and securing legal assistance for a criminal appeal).', 'mbe_319', 0, '3'),
('mbe_404', 'mbe', '404', '228', 'MBE-1978-83-part6', '', '4', 'Ogden was the fee simple owner of three adjoining vacant lots fronting on a common street in a primarily residential section of a city which had no zoning laws. The lots were identified as Lots 1, 2, and 3. Ogden conveyed Lot 1 to Akers and Lot 2 to Bell. Ogden retained Lot 3, which consisted of three acres of woodland. Bell, whose lot was between the other two, built a house on his lot. Bell''s house included a large window on the side facing Lot 3. The window provided a beautiful view from Bell''s living room, thereby adding value to Bell''s house. Akers erected a house on his lot. Ogden made no complaint to either Akers or Bell concerning the houses they built. After both Akers and Bell had completed their houses, the two of them agreed to and did build a common driveway running from the street to the rear of their respective lots. The driveway was built on the line between the two houses so that one-half of the way was located on each lot. Akers and Bell exchanged right-ofway deeds by which each of them conveyed to the other, his heirs and assigns, an easement to continue the right of way. Both deeds were properly recorded. After Akers and Bell had lived in their respective houses for thirty years, a new public street was built bordering on the rear of Lots 1, 2, and 3. Akers informed Bell that, since the new street removed the need for their common driveway, he considered the right-of-way terminated; therefore, he intended to discontinue its use and expected Bell to do the same. At about the same time, Ogden began the erection of a six-story apartment house on Lot 3. If the apartment house is completed, it will block the view from Bell''s window and will substantially reduce the value of Bell''s lot.', 'In an action brought by Bell to enjoin Akers from interfering with Bell''s continued use of the common driveway between the two lots, the decision should be for', 'Akers, because the termination of the necessity for the easement terminated the easement', 'Akers, because the continuation of the easement after the change of circumstances would adversely affect the marketability of both lots without adding any commensurate value to either', 'Bell, because an incorporeal hereditament lies in grant and cannot be terminated without a writing', 'Bell, because the removal of the need for the easement created by express grant does not affect the right to the easement', 'D', 'An incorporeal hereditament is “[a]n intangible right in land, such as an easement.”  In other contexts, Utah courts have recognized an incorporeal hereditament as an interest in real property. In addressing a case involving a license to prospect and mine ore, the Utah Supreme Court discussed the potential for a mining license to ripen into an incorporeal hereditament and stated: This is not to say that a license is an incorporeal hereditament; it means that the grant was a license as long as it remained executory because it was not in proper form for a conveyance of an incorporeal hereditament. It ripened into an incorporeal hereditament when the licensee entered into enjoyment thereof and made expenditures and improvements. Other jurisdictions hold that revocation will not be allowed in such a case unless the licensee be compensated for his improvements.
This language supports a conclusion that the holder of an incorporeal hereditament would be considered the holder of a form of property interest entitling it to compensation under Utah law.', 'mbe_2356', 0, '4'),
('mbe_405', 'mbe', '405', '228', 'MBE-1978-83-part6', '', '5', 'Ogden was the fee simple owner of three adjoining vacant lots fronting on a common street in a primarily residential section of a city which had no zoning laws. The lots were identified as Lots 1, 2, and 3. Ogden conveyed Lot 1 to Akers and Lot 2 to Bell. Ogden retained Lot 3, which consisted of three acres of woodland. Bell, whose lot was between the other two, built a house on his lot. Bell''s house included a large window on the side facing Lot 3. The window provided a beautiful view from Bell''s living room, thereby adding value to Bell''s house. Akers erected a house on his lot. Ogden made no complaint to either Akers or Bell concerning the houses they built. After both Akers and Bell had completed their houses, the two of them agreed to and did build a common driveway running from the street to the rear of their respective lots. The driveway was built on the line between the two houses so that one-half of the way was located on each lot. Akers and Bell exchanged right-ofway deeds by which each of them conveyed to the other, his heirs and assigns, an easement to continue the right of way. Both deeds were properly recorded. After Akers and Bell had lived in their respective houses for thirty years, a new public street was built bordering on the rear of Lots 1, 2, and 3. Akers informed Bell that, since the new street removed the need for their common driveway, he considered the right-of-way terminated; therefore, he intended to discontinue its use and expected Bell to do the same. At about the same time, Ogden began the erection of a six-story apartment house on Lot 3. If the apartment house is completed, it will block the view from Bell''s window and will substantially reduce the value of Bell''s lot.', 'In an action brought by Bell to enjoin Ogden from erecting the apartment building in such a way as to obstruct the view from Bell''s livingroom window, the decision should be for', 'Bell, because Ogden''s proposed building would be an obstruction of Bell''s natural right to an easement for light and air', 'Bell, because Bell was misled by Ogden''s failure to complain when Bell was building his house', 'Ogden if, but only if, it can be shown that Ogden''s intention to erect such a building was made known to Bell at or prior to the time of Ogden''s conveyance to Bell', 'Ogden, because Bell has no easement for light, air, or view', 'D', 'An easement for light and air will not be implied under any circumstances short of a necessity so absolute as to destroy the use of the plaintiff''s building.', 'mbe_2357', 0, '5'),
('mbe_406', 'mbe', '406', '229', 'MBE-1978-83-part6', '', '6', '', 'Dever was indicted for the murder of Vickers by poison. At trial, the prosecutor calls the county coroner, Dr. Wolfe, who is a board-certified pathologist, to testify that, in accord with good practice in her specialty, she has studied microphotographic slides, made under her supervision by medical assistants, of tissue taken from Vickers'' corpse and that it is Wolfe''s opinion, based on that study, that Vickers died of poisoning. The slides have not been offered in evidence. Dr. Wolfe''s opinion should be', 'excluded, because the cause ofdeathis a critical issue to be decided by the trier of fact', 'excluded, because her opinion is based on facts not in evidence', 'admitted, because Wolfe followed accepted medical practice in arriving at her opinion', 'admitted, because her opinion is based on matters observed pursuant to a duty imposed by law', 'C', 'An expert opinion is competent if it is held to a reasonable degree of scientific or medical certainty. State v. Jackson, 92 Ohio St.3d 436, 751 N.E.2d 946 (2001) citing State v. Benner, 40 Ohio St.3d 301, 313, 533 N.E.2d 701, 714 (1988). The phrase “reasonable certainty” is synonymous with the term “probability.” Id.', 'mbe_2358', 0, '6'),
('mbe_407', 'mbe', '407', '230', 'MBE-1978-83-part6', '', '7', '', 'At the trial of Davis for a murder that occurred in Newtown, the prosecution called Waite, who testified that she saw Davis kill the victim. Davis believed that Waite was 600 miles away in Old Town, engaged in the illegal sale of narcotics, on the day in question. On cross-examination by Davis, Waite was asked whether she had in fact sold narcotics in Old Town on that date. Waite refused to answer on the ground of self-incrimination. The judge, over the prosecutor''s objection, ordered that if Waite did not testify, her direct testimony should be stricken. The order to testify or have the testimony stricken can best be supported on the basis that', 'Waite had not been charged with any crime and, thus, could claim no privilege against self-incrimination', 'Waite''s proper invocation of the privilege prevented adequate cross-examination', 'the public interest in allowing an accused to defend himself or herself outweighs the interest of a non-party witness in the privilege', 'the trial record, independent of testimony, does not establish that Waite''s answer could incriminate her', 'B', 'When a witness refuses to answer cross-examination questions necessary to test the witness''s direct testimony, that refusal undermines the trier of fact''s ability to rely on the witness''s direct testimony, and the trial court may strike the witness''s testimony.', 'mbe_2359', 0, '7'),
('mbe_408', 'mbe', '408', '231', 'MBE-1978-83-part6', '', '8', '', 'A statute of the state of Tuscarora made it a misdemeanor to construct any building of more than five stories without an automatic fire sprinkler system. A local construction company built in Tuscarora a ten-story federal office building. It constructed the building according to the precise specifications of a federal contract authorized by federal statutes. Because the building was built without the automatic fire sprinkler system required by state law, Tuscarora prosecutes the private contractor. Which of the following is the company''s strongest defense to that prosecution?', 'The state sprinkler requirement denies the company property or liberty without due process.', 'The state sprinkler requirement denies the company equal protection of the laws.', 'As applied, the state sprinkler requirement violates the supremacy clause.', 'As applied, the state sprinkler requirement violates the obligation of contracts clause.', 'C', '“The Supremacy Clause, U.S. Const., Art. VI, cl. 2, invalidates state laws that ‘interfere with, or are contrary to,’ federal law.” Qwest Corp. v. Minn. Pub. Utils. Comm''n, 684 F.3d 721, 726 (8th Cir.2012) (citations omitted).  The Supremacy Clause comes into play where, among other situations, “there is an actual conflict between state and federal law” such that “compliance with both federal and state regulations is a physical impossibility ... or when state law stands as an obstacle to the accomplishment and execution of the full purposes and objectives of Congress.” Id. (citations omitted). Federal regulations, like those at issue in this case, have the same preemptive force as federal laws. See Fid. Fed. Sav. & Loan Ass''n v. de la Cuesta, 458 U.S. 141, 153, 102 S.Ct. 3014, 73 L.Ed.2d 664 (1982).', 'mbe_113', 0, '8'),
('mbe_409', 'mbe', '409', '232', 'MBE-1978-83-part6', '', '9', '', 'On January 15, Carpenter agreed to repair Householder''s house according to certain specifications and to have the work completed by April 1. On March 1, Householder''s property was inundated by flood waters which did not abate until March 15. Householder could not get the house in a condition which would permit Carpenter to begin the repairs until March 31. On that date Carpenter notified Householder that he would not repair the house. Which one of the following facts, if it was the only one true and known to both parties on January 15, would best serve Carpenter as the basis for a defense in an action brought against him by Householder for breach of contract?', 'Carpenter''s busy schedule permitted him to work on Householder''s house only during the month of March.', 'Any delay in making the repairs would not seriously affect Householder''s use of the property.', 'The cost of making repairs was increasing at the rate of 3% a month.', 'The area around Householder''s property was frequently flooded during the month of March.', 'A', 'Under the defense of impossibility of performance, a party''s breach of its contractual obligation will be excused when “changed circumstances have rendered the promise vitally different from what reasonably should have been within the contemplation of both parties when they entered into the contract.” Colo. Performance Corp. v. Mariposa Assocs., 754 P.2d 401, 407 (Colo.Ct.App.1987) (quotation omitted)', 'mbe_2360', 0, '9'),
('mbe_41', 'mbe', '41', '24', 'MBE-1972-78-part2', '', '42', 'Neff and Owens owned adjoining residences in Smithville. In 1971, they hired a contractor to lay sidewalks in front of both of their homes. Each man was to pay the contractor for that part of the work attributable to his property. After he had paid the bill which the contractor had submitted to him, Neff became convinced that the contractor had erred and had charged him for labor and materials which were used for part of the sidewalk in front of Owens'' property. Neff thereupon asked Owens to reimburse him for the amount which he assumed he had erroneously paid the contractor. After a lengthy discussion, and although he was still convinced that he owed Neff nothing, Owens finally said: "I want to avoid trouble, and so if you agree not to sue for reimbursement, I''ll employ a caretaker for a three-year term to keep our sidewalks free of ice and snow." Neff orally assented. Although he could have hired the man for three years, Owens hired Parsons in October, 1971, to keep the snow and ice off the sidewalks for the winter, November 1971-March 1972. During the early fall of 1972, Owens decided to go to Florida for the winter. He told his nephew, Morse, that he could live in Owens'' house for the winter provided Morse would hire someone to keep the snow and ice off the walks in front of both Neff''s and Owens'' properties, and suggested that Morse could hire Parsons for that task at relatively little cost. Morse moved into Owens'' home in October, 1972, but moved out November, 1972, prior to any icing or snowfall. He did not employ anyone to remove snow and ice in front of either property. Owens did not know that Morse had moved out of his home until he returned to Smithville in the spring. During the winter Neff had kept his own walks clean. No one cleaned the snow and ice from the walks in front of Owens'' property.', 'Assuming there is an enforceable contract between Owens and Morse, does Neff have an action against Morse?', 'Yes, because Neff is a creditor thirdparty beneficiary of the contract.', 'Yes, because Neff is a donee third-party beneficiary of the contract.', 'No, because Neff is only an incidental beneficiary of the contract.', 'No, because there was no privity between Neff and Morse.', 'A', '“A third party may recover on a contract made between other parties only if the parties intended to secure some benefit to that third party, and only if the contracting parties entered into the contract directly for the third party''s benefit.” MCI Telecomms. Corp. v. Tex. Utils. Elec. Co., 995 S.W.2d 647, 651 (Tex.1999) (internal citations omitted). “To demonstrate that it is a third-party beneficiary to a contract, a party must prove that it is either a donee or creditor beneficiary of the contract, and not someone who is benefitted only incidentally by performance of the contract.” United Neurology, P.A. v. Hartford Lloyd''s Ins. Co., 101 F.Supp.3d 584, 592 (S.D.Tex.2015). The Supreme Court of Texas defines what constitutes a “donee beneficiary” and a “creditor beneficiary”:
One is a donee beneficiary if the performance promised will, when rendered, come to [it] as a pure donation.  If on the other hand, that performance will come to [it] in satisfaction of a legal duty owed to [it] by the promise, [it] is a creditor beneficiary ... this duty may be an “indebtedness, contractual obligation or other legally enforceable commitment” owed to the third party.
MCI Telecomms., 995 S.W.2d at 651 (internal citations omitted).', 'mbe_37', 0, '42'),
('mbe_410', 'mbe', '410', '233', 'MBE-1978-83-part6', '', '10', '', 'In a telephone call on March 1, Adams, an unemployed, retired person, said to Daws, "I will sell my automobile for $3,000 cash. I will hold this offer open through March 14." On March 12, Adams called Dawes and told her that he had sold the automobile to Clark. Adams in fact had not sold the automobile to anyone. On March 14, Dawes learned that Adams still owned the automobile, and on that date called Adams and said, "I''m coming over to your place with $3,000." Adams replied, "Don''t bother. I won''t deliver the automobile to you under any circumstances." Dawes protested, but made no further attempt to pay for or take delivery of the automobile. In an action by Dawes against Adams for breach of contract, Dawes probably will', 'succeed, because Adams had assured her that the offer would remain open through March 14', 'succeed, because Adams had not in fact sold the automobile to Clark', 'not succeed, because Dawes had not tendered the $3,000 to Adams on or before March 14', 'not succeed, because on March 12 Adams had told Dawes that he had sold the automobile to Clark', 'D', 'To properly plead breach of contract, “[t]he complaint must identify the specific provision of the contract allegedly breached by the defendant.” Donohue v. Apple, Inc., 871 F.Supp.2d 913, 930 (N.D.Cal.2012) (citing Progressive West Ins. Co. v. Super. Ct., 135 Cal.App.4th 263, 281, 37 Cal.Rptr.3d 434 (2005)).', 'mbe_2645', 0, '10'),
('mbe_411', 'mbe', '411', '234', 'MBE-1978-83-part6', '', '11', 'Parents purchased a new mobile home from Seller. The mobile home was manufactured by Mobilco and had a ventilating system designed by Mobilco with both a heating unit and an air conditioner. Mobilco installed a furnace manufactured by Heatco and an air conditioning unit manufactured by Coolco. Each was controlled by an independent thermostat installed by Mobilco. Because of the manner in which Mobilco designed the ventilating system, the first time the ventilating system was operated by Parents, cold air was vented into Parents'' bedroom to keep the temperature at 68F (20''C). The cold air then activated the heater thermostat, and hot air was pumped into the bedroom of Child, the six-month-old child of Parents. The temperature in Child''s room reached more than 170F (77''C) before Child''s mother became aware of the condition and shut the system off manually. As a result, Child suffered permanent physical injury. Claims have been asserted by Child, through a duly appointed guardian, against Mobilco, Seller, Heatco, and Coolco.', 'If Child''s claim against Seller is based on negligence, the minimum proof necessary to establish Seller''s liability is that the ventilating system', 'was defective', 'was defective and had not been inspected by Seller', 'was defective and had been inspected by Seller, and the defect was not discovered', 'was defective, and the defect would have been discovered if Seller had exercised reasonable care in inspecting the system', 'D', 'Additionally, “[a] manufacturer may be held strictly liable for placing a defective product on the market if the plaintiff''s injury results from a reasonably foreseeable use of the product.” Saller v. Crown Cork & Seal Co., Inc., 187 Cal.App.4th 1220, 1231, 115 Cal.Rptr.3d 151 (2010). Each theory requires that a plaintiff plead and prove causation and damages. See County of Santa Clara v. Atlantic Richfield Co., 137 Cal.App.4th 292, 318, 40 Cal.Rptr.3d 313 (2006).', 'mbe_320', 0, '11'),
('mbe_412', 'mbe', '412', '234', 'MBE-1978-83-part6', '', '12', 'Parents purchased a new mobile home from Seller. The mobile home was manufactured by Mobilco and had a ventilating system designed by Mobilco with both a heating unit and an air conditioner. Mobilco installed a furnace manufactured by Heatco and an air conditioning unit manufactured by Coolco. Each was controlled by an independent thermostat installed by Mobilco. Because of the manner in which Mobilco designed the ventilating system, the first time the ventilating system was operated by Parents, cold air was vented into Parents'' bedroom to keep the temperature at 68F (20''C). The cold air then activated the heater thermostat, and hot air was pumped into the bedroom of Child, the six-month-old child of Parents. The temperature in Child''s room reached more than 170F (77''C) before Child''s mother became aware of the condition and shut the system off manually. As a result, Child suffered permanent physical injury. Claims have been asserted by Child, through a duly appointed guardian, against Mobilco, Seller, Heatco, and Coolco.', 'If Child''s claims against Mobilco, Heatco, and Coolco are based on strict liability in tort, Child will probably recover against', 'Mobilco only, because the ventilating system was defectively designed by Mobilco', 'Heatco only, because it was the excessive heat from the furnace that caused Child''s injuries', 'Mobilco and Heatco only, because the combination of Mobilco''s design and Heatco''s furnace caused Child''s injuries', 'Mobilco, Heatco, and Coolco, because the combination of Mobilco''s design, Heatco''s furnace, and Coolco''s air conditioning unit caused Child''s injuries', 'A', 'a manufacturer is strictly liable if its product is defectively manufactured, defectively designed, or distributed without adequate instructions or warnings.', 'mbe_321', 0, '12'),
('mbe_413', 'mbe', '413', '235', 'MBE-1978-83-part6', '', '13', '', 'Cars driven by Pugh and Davidson collided, and Davidson was charged with driving while intoxicated in connection with the accident. She pleaded guilty and was merely fined, although under the statute the court could have sentenced her to two years in prison. Thereafter, Pugh, alleging that Davidson''s intoxication had caused the collision, sued Davidson for damages. At trial, Pugh offers the properly authenticated record of Davidson''s conviction. The record should be', 'admitted as proof of Davidson''s character', 'admitted as proof of Davidson''s intoxication', 'excluded, because the conviction was not the result of a trial', 'excluded, because it is hearsay not within any exception', 'B', 'we must determine what evidence is admissible as a “record of conviction” within the meaning of *525 Code § 19.2-295.1. Appellant argues that only a final order, signed by a judge, is admissible as a “record of conviction.” The Commonwealth contends that the statute should not be so narrowly construed. This is an issue of first impression. Nothing in the plain language of Code § 19.2-295.1 requires that a “record of conviction” be established only by the admission of a final order of conviction. The language of Code § 19.2-295.1 describes a “record,” not an “order.” The plain meaning of the word “record” is
[a] written account of some act, court proceeding, transaction, or instrument, drawn up, under authority of law, by a proper officer, and designed to remain as a memorial or permanent evidence of the matters to which it relates. Black''s Law Dictionary 1144 (5th ed.1979).  Thus, we find that “record of conviction” means a “record” evidencing the fact of conviction. While a final order of conviction may be the most expedient means of establishing a “record of conviction,” we do not find Code § 19.2-295.1 limited to such evidence.', 'mbe_322', 0, '13'),
('mbe_414', 'mbe', '414', '236', 'MBE-1978-83-part6', '', '14', '', 'Pitt sued Dow for damages for injuries that Pitt incurred when a badly rotted limb fell from a curbside tree in front of Dow''s home and hit Pitt. Dow claimed that the tree was on city property and thus was the responsibility of the city. At trial, Pitt offered testimony that a week after the accident, Dow had cut the tree down with a chainsaw. The offered evidence is', 'inadmissible, because there is a policy to encourage safety precautions', 'inadmissible, because it is irrelevant to the condition of the tree at the time of the accident', 'admissible to show the tree was on Dow''s property', 'admissible to show the tree was in a rotted condition', 'C', 'Basically, if evidence is to be admitted at court, it must be relevant, material, and competent. To be considered relevant, it must have some reasonable tendency to help prove or disprove some fact. It need not make the fact certain, but at least it must tend to increase or decrease the likelihood of some fact. Once admitted as relevant evidence, the finder of fact (judge or jury) will determine the appropriate weight to give a particular piece of evidence. A given piece of evidence is considered material if it is offered to prove a fact that is in dispute in a case. Evidence is considered "competent" if it complies with certain traditional notions of reliability. Courts are gradually diminishing the competency rules of evidence by making them issues related to the weight of evidence.', 'mbe_2361', 0, '14'),
('mbe_415', 'mbe', '415', '237', 'MBE-1978-83-part6', '', '15', '', 'A state statute makes it a felony for any teacher at a state institution of higher education to accept anything of value from a student at the same institution. Monroe, a student at the state university, offered Professor Smith, his English teacher, $50 in exchange for a good grade in his English course. Smith agreed and took the money. Professor Smith and Monroe are tried jointly for violation of the state statute. Professor Smith is charged with violating the statute and Monroe with aiding and abetting him. Monroe''s best argument for a dismissal of the charge against him is that', 'a principal and an accessory cannot be tried together, since the principal must be convicted first', 'he cannot be an accessory, since he is the victim of the crime', 'the legislature did not intend to punish the person giving the thing of value', 'he did not assist Professor Smith in violating the statute', 'C', 'In this regard, we note that “[i]n construing a statute, we must ascertain and give effect to the intent of the Legislature as that intent is expressed through the language of the statute,” and that “[t]he intent of the Legislature in adopting a statute may be gleaned from considering the language used, the reason and necessity for the statute, and the goals the Legislature sought to accomplish.” Ex parte Krothapalli, 762 So.2d 836, 838 (Ala.2000).', 'mbe_323', 0, '15'),
('mbe_416', 'mbe', '416', '238', 'MBE-1978-83-part6', '', '16', '', 'In which of the following situations is Defendant most likely to be guilty of the crime charged?', 'Without the permission of Owner, Defendant takes Owner''s car with the intention of driving it three miles to a grocery store and back. Defendant is charged with larceny.', 'Defendant gets permission to borrow Owner''s car for the evening by falsely promising to return it, although he does not intend to do so. Two days later, he changes his mind and returns the car. Defendant is charged with larceny by trick.', 'Defendant gets permission to borrow Owner''s car for the evening by misrepresenting his identity and falsely claiming he has a valid driver''s license. He returns the car the next day. Defendant is charged with obtaining property by false pretenses.', 'With permission, Defendant, promising to return it by 9:00 p.m., borrows Owner''s car. Later in the evening, Defendant decides to keep the car until the next morning and does so. Defendant is charged with embezzlement.', 'B', 'Similarly, to constitute theft by trick, “the following elements must be present: (1) there must be a taking; (2) there must be an asportation of the thing taken; (3) the thing taken must be the property of another; and (4) the taking and carrying away must be with an intent, without claim or pretense of right or justification, to deprive the owner of his property wholly and permanently [citation].” (People v. Woolson (1960) 181 Cal.App.2d 657, 668 [5 Cal.Rptr. 766].)', 'mbe_324', 0, '16'),
('mbe_417', 'mbe', '417', '239', 'MBE-1978-83-part6', '', '17', '', 'Carver is a chemical engineer. She has no interest in or connection with Chemco. Carver noticed that Chemco''s most recent publicly issued financial statement listed, as part of Chemco''s assets, a large inventory of a certain special chemical compound. This asset was listed at a cost of $100,000, but Carver knew that the ingredients of the compound were in short supply and that the current market value of the inventory was in excess of $1,000,000. There was no current public quotation of the price of Chemco stock. The book value of Chemco stock, according to the statement, was $5 a share; its actual value was $30 a share. Knowing these facts, Carver offered to purchase from Page at $6 a share the 1,000 shares of Chemco stock owned by Page. Page and Carver had not previously met. Page sold the stock to Carver for $6 a share. If Page asserts a claim based on misrepresentation against Carver, will Page prevail''?', 'Yes, because Carver knew that the value of the stock was greater than the price she offered.', 'Yes, if Carver did not inform Page of the true value of the inventory.', 'No, unless Carver told Page that the stock was not worth more than $6 a share.', 'No, if Chemco''s financial statement was available to Page.', 'C', 'The elements of fraudulent misrepresentation are: 1) a false material representation; 2) the speaker''s knowledge of the falsity of the misrepresentation or ignorance of the truth; 3) the speaker''s intent that the hearer act upon the misrepresentation in a manner reasonably contemplated; 4) the hearer''s ignorance of the falsity of the misrepresentation; 5) the hearer''s reliance on its truth; 6) the hearer''s right to rely thereon; and 7) the hearer''s consequent and proximately caused damages. Id. at 489–90; Roth v. Equitable Life Assurance Society, 210 S.W.3d 253, 258 (Mo.App. E.D.2006); Urologic Surgeons, Inc. v. Bullock, 117 S.W.3d 722, 725–26 (Mo.App. E.D.2003). If a plaintiff fails to establish any one of these elements, his claim also will fail. Mprove, 135 S.W.3d at 490.', 'mbe_2646', 0, '17'),
('mbe_418', 'mbe', '418', '240', 'MBE-1978-83-part6', '', '18', '', 'Dean, charged with murder, was present with her attorney at a preliminary examination when White, who was the defendant in a separate prosecution for concealing the body of the murder victim, testified for the prosecution against Dean. When called to testify at Dean''s trial, White refused to testify, though ordered to do so. The prosecution offers evidence of White''s testimony at the preliminary examination. The evidence is', 'admissible as former testimony', 'admissible as past recollection recorded', 'inadmissible, because it would violate White''s privilege against self-incrimination', 'inadmissible, because it is hearsay not within any exception', 'A', 'A party''s “interest and motive at a second proceeding is not dissimilar to his interest at a first proceeding within the meaning of Evidence Code section 1291, subdivision (a)(2), simply because events occurring after the first proceeding might have led counsel to alter the nature and scope of cross-examination of the witness in certain particulars. [Citation.] The ‘ “motives need not be identical, only ‘similar.’ ” ’ ” (People v. Harris (2005) 37 Cal.4th 310, 333, 33 Cal.Rptr.3d 509, 118 P.3d 545.) Where the party had the same motive to discredit the witness and challenge the witness''s credibility, the former testimony would be admissible under section 1291. (People v. Harris, at p. 333, 33 Cal.Rptr.3d 509, 118 P.3d 545.) Whether evidence is admissible under section 1291, moreover, depends on whether the party against whom the former testimony is offered had a motive and opportunity for cross-examination, not whether counsel actually cross-examined the witness. (People v. Williams (2008) 43 Cal.4th 584, 626–627, 75 Cal.Rptr.3d 691, 181 P.3d 1035.)', 'mbe_325', 0, '18'),
('mbe_419', 'mbe', '419', '241', 'MBE-1978-83-part6', '', '19', '', 'Potts, a building contractor, sued Dennis for failure to pay on a small cost-plus construction contract. At trial, Potts, who personally supervised all of the work, seeks to testify to what he remembers about the amount of pipe used, the number of workers used on the job, and the number of hours spent grading. Dennis objects on the ground that Potts had routinely recorded these facts in notebooks which are in Potts''s possession. Potts''s testimony is', 'admissible as a report of regularly conducted business activity', 'admissible as based on first-hand knowledge', 'inadmissible, because it violates the best evidence rule', 'inadmissible, because a summary of writings cannot be made unless the originals are available for examination', 'B', 'We believe that another fundamental rule of law is that witnesses must have first-hand knowledge of the subject on which they are testifying for that testimony to be admissible.', 'mbe_326', 0, '19'),
('mbe_42', 'mbe', '42', '25', 'MBE-1972-78-part2', '', '43', '', 'Defendant was driving his automobile at a legal speed in a residential zone. A child darted out in front of him and was run over and killed before Defendant could prevent it. Defendant''s driver''s license had expired three months previously; Defendant had neglected to check when it was due to expire. Driving without a valid license is a misdemeanor in the jurisdiction. On a charge of manslaughter, Defendant should be found', 'guilty under the misdemeanor-manslaughter rule', 'guilty because the licensing requirements are to protect life, and failure to obey is negligence', 'not guilty because the offense was not the proximate cause of the death', 'not guilty because there was no criminal intent', 'C', 'To find the defendant guilty of involuntary manslaughter you must be convinced beyond a reasonable doubt (that) the act or acts charged were the proximate cause of the death under such circumstances as to constitute involuntary manslaughter.
By the proximate cause of the death is meant that which, in natural and continued sequence, or chain of events, unbroken by an efficient intervening cause, aids in producing the death, and without which it would not have occurred.', 'mbe_38', 0, '43'),
('mbe_420', 'mbe', '420', '242', 'MBE-1978-83-part6', '', '20', '', 'While testifying as a witness in a civil trial, Walters was asked on cross-examination if he had been convicted in the circuit court of Jasper County of stealing $200 from his employer on August 16, 1977. Walters said, "No, I have never been convicted of any crime." In fact, Walters had pleaded guilty to such a charge and had been placed on probation. Walters was then charged with perjury on the ground that his statement denying the conviction was false. A statute in the jurisdiction defines perjury as knowingly making a false statement while under oath. At trial, the state proved Walters'' statement and the prior conviction. Walters testified that the attorney who represented him in the theft case had told him that, because he had been placed on probation, he had not been convicted of a crime. Walters had served his probationary period satisfactorily and been discharged from probation. The alleged advice of the attorney was incorrect. If the jury believes Walters, it should find him', 'guilty, because his mistake was one of law', 'guilty, because reliance on the advice of an attorney is not a defense', 'not guilty if the jury also finds that his reliance on the attorney''s advice was reasonable', 'not guilty, because he lacked the necessary mental state', 'D', 'For many but not all crimes, the prosecution must prove not only that the defendant carried out certain acts but also that they had a certain mental state. This is often known as the “mens rea” (“guilty mind”) element, and it prevents people from being punished when their intentions were innocent. When a prosecutor is trying to prove intent or another mental state, they may present evidence showing that a defendant had a motive to commit the crime. Conversely, a defendant may try to defeat a charge by showing that they did not have a motive to commit the crime. However, having a motive is not a required element of a crime.', 'mbe_327', 0, '20'),
('mbe_421', 'mbe', '421', '243', 'MBE-1978-83-part6', '', '21', '', 'A grand jury was investigating a bank robbery. The only information known to the prosecutor was a rumor that Taylor might have been involved. The grand jury subpoenaed Taylor. He refused to answer questions about the robbery and was granted use immunity. He then testified that he and Simmons had robbed the bank. The grand jury indicted both Taylor and Simmons for the bank robbery. The prosecutor permitted Simmons to enter a plea to a lesser offense in exchange for Simmons'' agreement to testify against Taylor. The prosecutor had no evidence as to the identity of the robbers except the testimony of Simmons and Taylor. At Taylor''s trial, his objection to Simmons'' being permitted to testify should be', 'sustained, because the prosecutor may not bargain away the rights of one codefendant in a deal with another', 'sustained, because Simmons'' testimony was acquired as a result of Taylor''s grand jury testimony', 'overruled, because the police suspected Taylor even before he testified in the grand jury hearing', 'overruled, because a witness cannot be precluded from testifying if his testimony is given voluntarily', 'B', 'Grand jury testimony is admissible as substantive evidence at trial in limited circumstances. See Commonwealth v. Stewart, 454 Mass. 527, 533, 911 N.E.2d 161 (2009).', 'mbe_328', 0, '21'),
('mbe_422', 'mbe', '422', '244', 'MBE-1978-83-part6', '', '22', '', 'Doe is prosecuted for giving his 14-year-old daughter a glass of wine in violation of a state statute prohibiting any person from serving any alcoholic beverage to a minor. Doe defends on the ground that the state statute as applied in his case unconstitutionally interferes with his free exercise of religion. In determining the constitutionality of this application of the state statute, the court may NOT properly', 'require the state to bear the burden of persuading the court that the statute is constitutional as applied to Doe', 'determine the reasonableness of Doe''s religious beliefs', 'ascertain whether Doe''s religious beliefs require him to serve wine to his child', 'decide whether Doe is sincere in his religious beliefs-that is, whether he really believes them', 'B', 'The Free Exercise Clause protects against regulations that discriminate against any religious beliefs (Lukumi, 508 U.S. at 532). The US Supreme Court has not given detailed guidance on what lower courts should consider when identifying a religious belief (Thomas v. Review Bd. of Ind. Emp''t Sec. Div., 450 U.S. 707, 714 (1981)).
To establish a free exercise claim, the plaintiff first must make a factual showing that:
The plaintiff espouses a bona fide religion.
The plaintiff sincerely holds these beliefs.
The desired activity is essential to the practice of the plaintiff''s religion.
(Van Dyke v. Washington, 896 F. Supp. 183, 187 (C.D. Ill. 1995) (citing Wisconsin v. Yoder, 406 U.S. 205, 207 (1972)).)', 'mbe_329', 0, '22'),
('mbe_423', 'mbe', '423', '245', 'MBE-1978-83-part6', '', '23', '', 'A federal statute requires United States civil service employees to retire at age 75. However, that statute also states that civil service employees of the armed forces must retire at age 65. Prentis, a 65-year-old civil service employee of the Department of the Army, seeks a declaratory judgment that would forbid his mandatory retirement until age 75. The strongest argument that Prentis can make to invalidate the requirement that he retire at age 65 is that the law', 'denies him a privilege or immunity of national citizenship', 'deprives him of a property right without just compensation', 'is not within the scope of any of the enumerated powers of Congress in Article I, 8', 'invidiously discriminates against him on the basis of age in violation of the Fifth Amendment', 'D', 'The Equal Protection Clause of the Fourteenth Amendment mandates that state and local governments treat all similarly-situated persons alike and broadly restricts invidious discrimination of individuals based on characteristics such as race or gender.', 'mbe_330', 0, '23'),
('mbe_424', 'mbe', '424', '246', 'MBE-1978-83-part6', '', '24', '', 'Light Company is the sole distributor of electrical power in City. The Company owns and maintains all of the electric poles and equipment in City. Light Company has complied with the National Electrical Safety Code, which establishes minimum requirements for the installation and maintenance of power poles. The Code has been approved by the federal and state governments. Light Company has had to replace insulators on its poles repeatedly because unknown persons repeatedly shoot at and destroy them. This causes the power lines to fall to the ground. On one of these occasions, Paul, Faber''s 5-year-old son, wandered out of Faber''s yard, intentionally touched a downed wire, and was seriously burned. If a claim on Paul''s behalf is asserted against Light Company, the probable result is that Paul will', 'recover if Light Company could have taken reasonable steps to prevent the lines from falling when the insulators were destroyed', 'recover, because a supplier of electricity is strictly liable in tort', 'not recover unless Light Company failed to exercise reasonable care to stop the destruction of the insulators', 'not recover, because the destruction of the insulators was intentional', 'A', 'Most dangerous property conditions are the result of a failure to maintain the property in good condition. Inadequate maintenance can give rise to a slip and fall, negligent security, or a swimming pool accident. Some typical types of inadequate maintenance include unrepaired fixtures, fallen merchandise, spills, broken windows, cracked sidewalks or tiles, broken locks, lack of security cameras, loose handrails, cluttered walkways, and overgrown vegetation. Duty to Inspect
Owners or occupiers typically have a duty to inspect their property at reasonable intervals to discover dangerous conditions, regardless of whether they receive complaints. All property owners are expected to maintain their properties and make reasonable repairs to avoid injuries to visitors to the property. However, in practice, property owners are often behind in inspecting, identifying, and fixing any dangerous conditions. It is only after someone is actually injured that the property owner takes steps to repair a dangerous condition or obtain adequate security. For example, customers may complain that there are broken lights near the entrance of a dance club, but it may be only after somebody is mugged or raped that the property owner fixes the broken lights. Condominiums or homeowners'' associations can also be held liable for failing to maintain a common area or to keep the common area clear of preventable hazards. The paperwork that creates the condominium board or homeowners'' association may spell out the obligations of that entity on the property. Among other things, it may define common areas for which the entity is responsible. Liability is usually found if the condominium or homeowners'' association created the hazard, or if it knew or should have known of the hazard. For example, the owners of individual units may complain to the condominium or homeowners'' association that steps on the ladder of the common swimming pool are broken. If the condominium board fails to make repairs or makes repairs negligently, and somebody is injured, the board may have to pay damages.', 'mbe_331', 0, '24'),
('mbe_425', 'mbe', '425', '247', 'MBE-1978-83-part6', '', '25', '', 'The city of Metropolis has an ordinance that makes it an offense, punishable by fine, for the owner of a dog to permit the dog to run unleashed on a public way. Smythe, a police officer, observed a small dog running loose in the street. As he picked the dog up, Nelson, who was seated in her car lawfully parked at the curb, called out, "Oh, thank you, Officer, for returning Fido." Smythe asked Nelson whether the dog was hers, and when she acknowledged ownership, he asked her to see her driver''s license. Nelson gave her name and address, but she refused to produce a driver''s license. Smythe then told her to produce her driver''s license if she did not want to go to jail. Nelson responded by saying, "Isn''t this ridiculous?" Smythe took her by the arm and said, "Let''s go. You are under arrest." Nelson cried out that Smythe was hurting her but he refused to release her arm, and she struck him with her free hand. Smythe then dragged Nelson from her car, forced her into his squad car, and took her to the police station. The incident took place on the street in front of the apartment where Nelson and her aged father, Joplin, lived. Smythe did not know that Joplin had observed what took place from a window in the apartment. If Nelson''s father, Joplin, asserts a claim against Smythe for the intentional infliction of emotional distress, will Joplin prevail?', 'Yes, if Smythe''s acts caused Joplin severe emotional distress.', 'Yes, if it is found that Smythe''s behavior was extreme and outrageous with respect to Nelson.', 'No, because Smythe did not know that Joplin was watching.', 'No, because Joplin was not within the zone of physical danger.', 'C', 'To state a claim of intentional infliction of emotional distress (“IIED”), Plaintiff must show “(1) that [defendant] intended, knew, or should have known that his conduct would cause emotional distress; (2) that the conduct was extreme and outrageous; (3) that the conduct caused emotional distress; and (4) that the emotional distress was severe.” Polay v. McMahon, 10 N.E.3d 1122, 1128 (Mass. 2014) (citing Howell v. Enterprise Publ. Co., 920 N.E.2d 1, 28 (Mass. 2010)).', 'mbe_332', 0, '25'),
('mbe_426', 'mbe', '426', '248', 'MBE-1978-83-part6', '', '26', '', 'Davison was driving through an apartment building area plagued with an unusually high incidence of burglaries and assaults. Acting pursuant to a police department plan to combat crime by the random stopping of automobiles in the area between midnight and 6:00 a.m., a police officer stopped Davison and asked him for identification. As Davison handed the officer his license, the officer directed a flashlight into the automobile and saw what appeared to be the barrel of a shotgun protruding from under the front seat on the passenger side of the car. The officer ordered Davison from the car, searched him, and discovered marijuana cigarettes and a shotgun. At Davison''s trial for unlawful possession of narcotics, his motion to suppress the use of the marijuana as evidence should be', 'sustained, because the marijuana was discovered as a result of the unlawful stopping of Davison''s automobile', 'sustained, because the use of the flashlight constituted a search of the interior of Davison''s automobile without probable cause', 'denied, because the officer''s conduct was consistent with the established police plan', 'denied, because the discovery of the gun in plain view created the reasonable suspicion necessary to justify the arrest and search of Davison', 'A', 'Normally, if an officer unlawfully prolongs a stop, any evidence uncovered as a result would be suppressed. See Davis, 564 U.S. at 231–32, 131 S.Ct. at 2423. But the exclusionary rule is subject to exceptions. Id. at 236–38, 131 S.Ct. at 2426–27.', 'mbe_333', 0, '26'),
('mbe_428', 'mbe', '428', '250', 'MBE-1978-83-part6', '', '28', '', 'Morgan conveyed Greenacre, her one-family residence, to "Perez for life, remainder to Rowan, her heirs and assigns, subject, however, to First Bank''s mortgage thereon." There was an unpaid balance on the mortgage of $10,000, which is payable in $1,000 annual installments plus interest at 6 percent on the unpaid balance, with the next payment due on July I. Perez is now occupying Greenacre. The reasonable rental value of the property exceeds the sum necessary to meet all current charges. There is no applicable statute. Under the rules governing contributions between life tenants and remaindermen, how should the burden for payment be allocated?', 'Rowan must pay the principal payment, but Perez must pay the interest to First Bank.', 'Rowan must pay both the principal and interest payments to First Bank.', 'Perez must pay both the principal and interest payments to First Bank.', 'Perez must pay the principal payment, but Rowan must pay the interest to First Bank.', 'A', 'A life tenant''s relation to the remainderman is a quasi-fiduciary one in the sense that he must exercise reasonable care to preserve the property intact for transmission to the remainderman and in that he can legally do nothing to prejudice or defeat the estate of the remainderman. 1 Tiffany, Real Property § 68 (3rd ed. 1939); 31 C.J.S. Estates § 34 (1964); 51 Am.Jur.2d, Life Tenants and Remaindermen §§ 27, 28 (1970). "[N]o such fiduciary relations exist between a life tenant and his remainderman as to make applicable to their transactions the rules of equity which govern trustees and cestuis que trustent, and preclude the life tenant from acquiring by gift or purchase from the remainderman his estate in remainder." Muzzy v. Muzzy, 364 Mo. 373, 380, 261 S.W.2d 927, 931 (1953). The life tenant has the obligation to list and pay the taxes on the property. G.S. 105-302(c)(8); G.S. 105-384. See Smith v. Smith, 261 N.C. 278, 134 S.E.2d 331 (1964); Meadows v. Meadows, 216 N.C. 413, 5 S.E.2d 128 (1939). Therefore he cannot defeat the estate of the remainderman by allowing the land to be sold for taxes and taking title in himself by purchase at the tax sale. See Farabow v. Perry, 223 N.C. 21, 26, 25 S.E.2d 173, 176 (1943); Creech v. Wilder, 212 N.C. 162, 166, 193 S.E. 281, 284 (1937); Miller v. Marriner, 187 N.C. 449, 457, 121 S.E. 770, 774 (1924); 51 Am.Jur.2d, supra, § 255; 1 Tiffany, supra, § 68. The life tenant''s purchase at a tax sale "is regarded as a payment of the tax, and the owner of the future interest is regarded as still holding under his original title." Simes and Smith, The Law of Future Interests, § 1700 (2d ed. 1956). In addition to the taxes, absent a different stipulation in the instrument creating the life estate, a life tenant owes a duty to the remaindermen to pay the interest accruing during the period of his estate on a mortgage encumbrance given prior to the creation of the life estate and remainder or reversion, at least to the extent of the income or rental value of the property. Simes and Smith, supra, § 1697. See 31 C.J.S. Estates § 48 (1964); 51 Am.Jur.2d, supra, § 277. "Being bound to pay the taxes and interest, he [a life tenant] cannot acquire a tax title or good title based on his failing to pay taxes or interest. He is a trustee to this extent." Miller v. Marriner, supra at 457, 121 S.E. at 774. If an encumbrance is foreclosed because of the default on the part of the life tenant in the payment of interest or otherwise, and he becomes the purchaser at the foreclosure sale, "he thereby restores the life estate and the estate in the remainder." 1 Tiffany, supra § 68. See Morehead v. Harris, 262 N.C. 330, 338, 137 S.E.2d 174, 182 (1964); Restatement of Property §§ 129, 130, 131, 149 (1936); 31 C.J.S. Estates § 35 (1964). In respect to a prior mortgage lien on the whole estate, unless obligated by the instrument creating his estate, the life tenant''s only duty to the remainderman is to pay the interest. He is under no obligation to pay any part of the principal. 31 C.J.S. Estates § 48 (1964); 51 Am.Jur.2d, supra, § 275. When a life tenant, in order to preserve his estate, "pays off an encumbrance upon the fee or estate property, whether the encumbrance is a mortgage, lien, charge or other type of encumbrance, he is entitled to reimbursement from the owners of future interests, such as reversioners or remaindermen, to the extent of their interest in the property which was subject to the encumbrance." 51 Am. Jur.2d, supra, § 275. See 31 C.J.S. Estates § 48 (1964); 1 Tiffany, supra, § 63. He "has a lien on the future interest for the amount which its owner is under a duty to pay." Simes and Smith, supra, § 1697. See Farabow v. Perry, supra, 223 N.C. at 26, 25 S.E.2d at 176; Creech v. Wilder, supra, 212 N.C. at 166, 193 S.E. at 284. When a mortgage falls due during the period of the life estate the question arises: Who has the burden of paying the principal? In Simes and Smith, The Law of Future Interests, § 1697 (2d ed. 1956), the question is answered as follows: "Courts have generally indicated that life tenant and reversioner or remainderman must each pay his due proportion of this amount. To require them to share the burden would seem to be just. By paying off the mortgage, the value of both life estate and future interest have been increased in proportion to their respective values. Hence it would seem that the due proportion would be based upon the respective values of life estate and the remainder or reversion.. . . The cases, however, are not clear as to what a due proportion of the principal is." The foregoing statement accords with the Restatement of Property § 132 (1936). Explanatory Comment e. under this section says that the proportionate contributions of the life estate and future interests to the payment of an encumbrance "are computable by employing the mortality tables and rate of interest regularly employed in valuing an estate for life in the state wherein the affected land is located." Id. at p. 433. See Faulkenburg v. Windorf, 194 Minn. 154, 157, 259 N.W. 802, 804 (1935). In Comment a. to § 132, supra, it is noted that absent some special provision in the instrument creating the estate for life, the life tenant has no duty to contribute from his other assets to the payment of the encumbrance. "He can, however, be compelled to choose between giving up his estate for life and making a contribution, from his other assets, to the new investment of capital." Id. at p. 431. When a mortgage, deed of trust or other encumbrance on the whole estate, the burden of which does not fall solely on the life tenant, is foreclosed, the life tenant may purchase the property at the sale in order to protect his interest. Yet he cannot purchase the fee on a foreclosure sale so as to exclude the remainderman if the remainderman is willing to contribute his share of the cost of acquisition within a reasonable time. "It is uniformly held that the purchase of land by a life tenant at a foreclosure sale under a mortgage or deed of trust will be deemed to have been made for the benefit of the remainderman or reversioner *745 if he contributes his portion of the purchase money within a reasonable time." 51 Am. Jur.2d supra, § 280. See Witcher v. Hanley, 299 Mo. 696, 253 S.W. 1002 (1923); Hager v. Connolly, 204 Ky. 147, 263 S.W. 723 (1924); Ward v. Chambless, 238 Ala. 165, 189 So. 890 (1939); Drane v. Smith, 271 Ala. 54, 122 So. 2d 135 (1960); 51 Am.Jur.2d, supra, § 279; 1 Tiffany, supra, § 68.', 'mbe_335', 0, '28'),
('mbe_429', 'mbe', '429', '251', 'MBE-1978-83-part6', '', '29', '', 'Anders conveyed her only parcel of land to Burton by a duly executed and delivered warranty deed, which provided: To have and to hold the described tract of land in fee simple, subject to the understanding that within one year from the date of the instrument said grantee shall construct and thereafter maintain and operate on said premises a public health center. The grantee, Burton, constructed a public health center on the tract within the time specified and operated it for five years. At the end of this period'' Burton converted the structure into a senior citizens'' recreational facility. It is conceded by all parties in interest that a senior citizens'' recreational facility is not a public health center. In an appropriate action, Anders seeks a declaration that the change in the use of the facility has caused the land and structure to revert to her. In this action, Anders should', 'win, because the language of the deed created a determinable fee, which leaves a possibility of reverter in the grantor', 'win, because the language of the deed created a fee subject to condition subsequent, which leaves a right of entry or power of termination in the grantor', 'lose, because the language of the deed created only a contractual obligation and did not provide for retention of property interest by the grantor', 'lose, because an equitable charge is enforceable only in equity', 'C', 'An equitable charge is like a trust in that in each case the legal title to property is vested in one person and an equitable interest in the property is given to another. The interest which the equitable encumbrancer has, however, is different from the interest of a beneficiary of a trust. The equitable encumbrancer has only a security interest in the property; the beneficiary of a trust is, to the extent of his beneficial interest, the equitable owner of the trust property.  If a devisee subject to an equitable charge fails to pay the equitable encumbrancer the sum to which he is entitled, the latter''s remedy is a suit in equity to obtain a decree for the sale of the land to pay the charge; if a trustee fails to perform his duties under the trust, the remedy of the beneficiary is a suit in equity to compel specific performance or redress of the breach of trust.”', 'mbe_336', 0, '29'),
('mbe_43', 'mbe', '43', '26', 'MBE-1972-78-part2', '', '44', '', 'Pauline, an unmarried female, was prominent in the women''s liberation movement. She recently gave birth to a baby and publicly announced that she had no intention of marrying the father or disclosing his identity. The local newspaper, Journal, decided to do a series of articles on Pauline, entitled "The Perils of Pauline." The first article about Pauline discussed her parents. The article correctly stated that Mary, her mother, had died recently and Frank, her father, is still living. The article referred to the fact that at the time of Pauline''s birth there were rumors that she had been born six months after the marriage of Mary and Frank, that Frank was not in fact her father, and that a person identified as Albert, who had played minor roles in two motion pictures, was her real father. Albert has lived in retirement for the last ten years. If Pauline asserts a claim based on invasion of privacy againstJournal for the statements in the first article about her birth and it is established that the statements are true, the most likely result is that Pauline will', 'not prevail, because truth is a complete defense', 'not prevail, because of her announcement concerning the birth of her own child', 'prevail, because the statements hold her up to ridicule and contempt', 'prevail, because the statements are embarrassing to her', 'B', 'There are a number of defenses to a public disclosure claim. Below, you''ll find explanations of some of the most common defenses:
Legitimate public interest
Whether the public has a legitimate interest in the facts-at-issue is a question that depends on the context of the case, and one in which there is no particular formula for the courts to follow. Whether this defense can be effectively asserted will depend largely on whether the person involved has made him or herself - in a temporary newsworthy capacity or a more permanent celebrity capacity - something of a public figure. In such cases, details of their private lives are more likely to be considered items of legitimate public interest. The passage of time may lessen the public interest in a given fact (the newsworthiness of it), which may weaken this defense.
Consent
Consent is a total defense. If the plaintiff has consented in some way to the disclosure, whether through a release form or through accepting an interview, then he or she cannot pursue a claim for public disclosure of private fact.
Public Record
Matters of public record, such as birth date, military service records, and others, are exempted. The defendant may claim this defense by showing that the disclosed fact was actually a matter of public record. However, it should be noted that, unlike defamation actions, truth is no defense to a claim for public disclosure of private facts. This means that a defendant cannot refute a claim by showing that the disclosed fact was actually true or accurate.', 'mbe_39', 0, '44'),
('mbe_430', 'mbe', '430', '252', 'MBE-1978-83-part6', '', '30', '', 'A group of children, ranging in age from 8 to 15, regularly played football on the common area of an apartment complex owned by O''Neill. Most of the children lived in the apartment complex, but some lived elsewhere. O''Neill knew that the children played on the common area and had not objected. Peter, a 13-year-old who did not live in the apartment complex, fell over a sprinkler head while running for a pass and broke his leg. Although Peter had played football on the common area before, he had never noticed the sprinkler heads, which protruded one inch above the ground and were part of a permanently installed underground sprinkler system. If a claim is asserted on Peter''s behalf, Peter will', 'prevail if the sprinkler head was a hazard that Peter probably would not discover', 'prevail, because O''Neill had not objected to children playing on the common area', 'not prevail, because Peter did not live in the apartment complex', 'not prevail unless the sprinkler heads were abnormally dangerous to users of the common area', 'A', 'a landowner has a duty to maintain his or her property in a reasonably safe condition, which includes providing a safe means of ingress and egress to tenants (see Peralta v. Henriquez, 100 N.Y.2d 139, 144, 760 N.Y.S.2d 741, 790 N.E.2d 1170 [2003]; Basso v. Miller, 40 N.Y.2d 233, 241, 386 N.Y.S.2d 564, 352 N.E.2d 868 [1976]; Gallagher v. St. Raymond''s R.C. Church, 21 N.Y.2d 554, 557, 289 N.Y.S.2d 401, 236 N.E.2d 632 [1968] ). The scope of such duty is determined “ ‘in view of all the circumstances, including the likelihood of injury to others, the seriousness of the injury, and the burden of avoiding the risk’ ” (Basso v. Miller, 40 N.Y.2d at 241, 386 N.Y.S.2d 564, 352 N.E.2d 868, quoting Smith v. Arbaugh''s Rest., Inc., 469 F.2d 97, 100 [D.C. Cir.1972], cert. denied 412 U.S. 939, 93 S.Ct. 2774, 37 L.Ed.2d 399 [1973]; accord Peralta v. Henriquez, 100 N.Y.2d at 144, 760 N.Y.S.2d 741, 790 N.E.2d 1170).', 'mbe_2362', 0, '30'),
('mbe_431', 'mbe', '431', '253', 'MBE-1978-83-part6', '', '31', '', 'Congress passes a law regulating the wholesale and retail prices of "every purchase or sale of oil, natural gas, and electric power made in the United States." The strongest argument in support of the constitutionality of this statute is that', 'the Constitution expressly empowers Congress to enact laws for "the general welfare"', 'Congress has the authority to regulate such products'' interstate transportation and importation from abroad', 'Congress may regulate the prices of every purchase and sale of goods and services made in this country, because commerce includes buying and selling', 'in inseverable aggregates, the domestic purchases or sales of such products affect interstate or foreign commerce', 'D', 'As we observed in Lopez, modern Commerce Clause jurisprudence has “identified three broad categories of activity that Congress may regulate under its commerce power.” 514 U.S., at 558, 115 S.Ct. 1624 (citing Hodel v. Virginia Surface Mining & Reclamation Assn., Inc., 452 U.S. 264, 276–277, 101 S.Ct. 2352, 69 L.Ed.2d 1 (1981); Perez v. United States, 402 U.S. 146, 150, 91 S.Ct. 1357, 28 L.Ed.2d 686 (1971)). “First, Congress may regulate the use of the channels of interstate commerce.” 514 U.S., at 558, 115 S.Ct. 1624 (citing Heart of Atlanta Motel, Inc. v. United States, 379 U.S. 241, 256, 85 S.Ct. 348, 13 L.Ed.2d 258 (1964); United States v. Darby, 312 U.S. 100, 114, 61 S.Ct. 451, 85 L.Ed. 609 (1941)).  “Second, Congress is empowered to regulate and protect the instrumentalities of interstate commerce, or persons or things in interstate commerce, even though the threat may come only from intrastate activities.” 514 U.S., at 558, 115 S.Ct. 1624 (citing Shreveport Rate Cases, 234 U.S. 342, 34 S.Ct. 833, 58 L.Ed. 1341 (1914); Southern R. Co. v. United States, 222 U.S. 20, 32 S.Ct. 2, 56 L.Ed. 72 (1911); Perez, supra, at 150, 91 S.Ct. 1357). “Finally, Congress'' commerce authority includes the power to regulate those activities having a substantial relation to interstate commerce, ... i.e., those activities that substantially affect interstate commerce.” 514 U.S., at 558–559, 115 S.Ct. 1624 (citing Jones & Laughlin Steel, supra, at 37, 57 S.Ct. 615).', 'mbe_337', 0, '31'),
('mbe_432', 'mbe', '432', '254', 'MBE-1978-83-part6', '', '32', 'In a written contract Singer agreed to deliver to Byer 500 described chairs at $20 each F.O.B. Singer''s place of business. The contract provided that "neither party will assign this contract without the written consent of the other." Singer placed the chairs on board a carrier on January 30. On February 1 Singer said in a signed writing, "I hereby assign to Wheeler all my rights under the Singer-Byer contract." Singer did not request and did not get Byer''s consent to this transaction. On February 2 the chairs while in transit were destroyed in a derailment of the carrier''s railroad car.', 'In an action by Wheeler against Byer, Wheeler probably will recover', '$10,000, the contract price', 'the difference between the contract price and the market value of the chairs', 'nothing, because the chairs had not been delivered', 'nothing, because the Singer-Byer contract forbade an assignment', 'A', 'Where a buyer wrongfully refuses to accept property purchased, seller may store the goods for buyer, give notice that he has done so and recover full contract price, or may keep the goods and recover excess of contract price above market value at time and place of delivery, or may sell the goods to the best advantage and recover of the buyer, the loss if the goods fail to bring the contract price.', 'mbe_338', 0, '32'),
('mbe_433', 'mbe', '433', '254', 'MBE-1978-83-part6', '', '33', 'In a written contract Singer agreed to deliver to Byer 500 described chairs at $20 each F.O.B. Singer''s place of business. The contract provided that "neither party will assign this contract without the written consent of the other." Singer placed the chairs on board a carrier on January 30. On February 1 Singer said in a signed writing, "I hereby assign to Wheeler all my rights under the Singer-Byer contract." Singer did not request and did not get Byer''s consent to this transaction. On February 2 the chairs while in transit were destroyed in a derailment of the carrier''s railroad car.', 'In an action by Byer against Singer for breach of contract, Byer probably will', 'succeed, because the carrier will be deemed to be Singer''s agent', 'succeed, because the risk of loss was on Singer', 'not succeed, because of impossibility of performance', 'not succeed, because the risk of loss was on Byer', 'D', '41-02-57. (2-509) Risk of loss in the absence of breach. 1. Where the contract requires or authorizes the seller to ship the goods by carrier
a. if it does not require him to deliver them at a particular destination, the risk of loss passes to the buyer when the goods are duly delivered to the carrier even though the shipment is under reservation (section 41-02-53); but
b. if it does require him to deliver them at a particular destination and the goods are there duly tendered while in the possession of the carrier, the risk of loss passes to the buyer when the goods are there duly so tendered as to enable the buyer to take delivery.', 'mbe_339', 0, '33'),
('mbe_434', 'mbe', '434', '255', 'MBE-1978-83-part6', '', '34', '', 'Dutton, disappointed by his 8-year-old son''s failure to do well in school, began systematically depriving the child of food during summer vacation. Although his son became seriously ill from malnutrition, Dutton failed to call a doctor. He believed that as a parent he had the sole right to determine whether the child was fed or received medical treatment. Eventually the child died. An autopsy disclosed that the child had suffered agonizingly as a result of the starvation, that a physician''s aid would have alleviated the suffering, and that although the child would have died in a few months from malnutrition, the actual cause of death was an untreatable form of cancer. The father was prosecuted for murder, defined in the jurisdiction as "unlawful killing of a human being with malice aforethought." The father should be', 'acquitted, because of the defendant''s goodfaith belief concerning parental rights in supervising children', 'acquitted, because summoning the physician or feeding the child would not have prevented the child''s death from cancer', 'convicted, because the father''s treatment of his son showed a reckless indifference to the value of life', 'convicted, because the child would have died from malnutrition had he not been afflicted with cancer', 'B', 'As we have discussed, but-for causation is not a discernment of degree. Rather, but-for causation determines whether a particular factor was necessary to produce a result, regardless of its percentage contribution to the result or weight in relation to other causal factors. See, e.g., Burrage, 571 U.S. at 218, 134 S.Ct. 881 (rejecting “substantial” or “contributing” factor tests because they seek to quantify the relationship between the relevant causal factor and the end result, thereby injecting uncertainty that cannot be squared with a beyond-a-reasonable-doubt standard). Importantly, the Council rejected “primarily” as a causation standard. Responding to the jury''s questions concerning the degree to which bias motivated the assault would not have clarified any confusion about the application of but-for causation. The trial court''s response, therefore, sought to steer the jury back to the critical inquiry of but-for causation.', 'mbe_340', 0, '34'),
('mbe_435', 'mbe', '435', '256', 'MBE-1978-83-part6', '', '35', '', 'Vance had cheated Dodd in a card game. Angered, Dodd set out for Vance''s house with the intention of shooting him. Just as he was about to set foot on Vance''s property, Dodd was arrested by a police officer who noticed that Dodd was carrying a revolver. A statute in the jurisdiction makes it a crime to "enter the property of another with the intent to commit any crime of violence thereon." If charged with attempting to violate the statute, Dodd should be found', 'not guilty, because the statute defines an attempt crime and there cannot be an attempt to attempt', 'not guilty, because to convict him would be to punish him simply for having a guilty mind', 'guilty, because he was close enough to entering the property and he had the necessary state of mind', 'guilty. because this is a statute designed to protect the public from violence and Dodd was dangerous', 'C', '“An attempt requires (1) an intent to engage in criminal conduct, and (2) conduct constituting a substantial step toward the commission of the substantive offense which strongly corroborates the actor''s criminal intent.”', 'mbe_341', 0, '35'),
('mbe_436', 'mbe', '436', '257', 'MBE-1978-83-part6', '', '36', '', 'Congress enacted a statute providing that persons may challenge a state energy law on the ground that it is in conflict with the federal Constitution in either federal or state court. According to this federal statute, any decision by a lower state court upholding a state energy law against a challenge based on the federal Constitution may be appealed directly to the United States Supreme Court. The provisions of this statute that authorize direct United States Supreme Court review of specified decisions rendered by lower state courts are', 'constitutional, because congressional control over questions of energy usage is plenary', 'constitutional, because Congress may establish the manner by which the appellate jurisdiction of the United States Supreme Court is exercised', 'unconstitutional, because they infringe the sovereign right of states to have their supreme courts review decisions of their lower state courts', 'unconstitutional, because under Article III of the Constitution the United States Supreme Court does not have authority to review directly decisions of lower state courts', 'B', '(“[T]he judicial power of the United States ... is (except in enumerated instances, applicable exclusively to this court) dependent ... entirely upon the action of Congress”); Hudson, supra, at 33 (similar). “To deny this position” would undermine the separation of powers by “elevat[ing] the judicial over the legislative branch.” Cary, supra, at 245.  Congress'' power over federal jurisdiction is “an essential ingredient of separation and equilibration of powers, restraining the courts from acting at certain times, and even restraining them from acting permanently regarding certain subjects.” Steel Co., supra, at 101, 118 S.Ct. 1003.', 'mbe_342', 0, '36'),
('mbe_437', 'mbe', '437', '258', 'MBE-1978-83-part6', '', '37', '', 'After several days of negotiations, Ohner wrote to Plummer: "Will pay you $3,000 if you will install new plumbing in my office building according to the specifications I have sent you. I must have your reply by March 30." Plummer replied by a letter that Ohner received on March 15: "Will not do it for less than $3,500." On March 20, Plummer wrote to Ohner: "Have changed my mind. I will do the work for $3,000. Unless I hear from you to the contrary, I will begin work on April 5." Ohner received this letter on March 22 but did not reply to it. Plummer, without Ohner''s knowledge, began the work on April 5. Which of the following best characterizes the legal relationship between Ohner and Plummer as of April 5?', 'A contract was formed on March 20 when Plummer posted his letter.', 'A contract was formed on March 22 when Ohner received Plummer''s letter.', 'A contract was formed on April 5 when Plummer began work.', 'There was no contract between the parties as of April 5.', 'D', 'A contract is formed when an offer is made and accepted, and the agreement is supported by consideration. Marquardt v. Perry, 200 P.3d 1126, 1129 (Colo.App.2008).  Acceptance of an offer is generally defined as words or conduct that, when objectively viewed, manifests an intent to accept an offer. Id. A person who, with knowledge of an offer''s terms, voluntarily takes the benefits of the offered services without objection is deemed to have accepted the offer and formed a contract. Restatement (Second), Contracts § 69.', 'mbe_343', 0, '37'),
('mbe_438', 'mbe', '438', '259', 'MBE-1978-83-part6', '', '38', 'On January 15, in a signed writing, Artisan agreed to remodel Ohner''s building according to certain specifications, Ohner to pay the agreed price of $5,000 to Artisan''s niece, Roberta Neese, as a birthday present. Neese did not learn of the agreement until her birthday on May 5. Before they signed the writing, Artisan and Ohner had orally agreed that their "written agreement will be null and void unless Ohner is able to obtain a $5,000 loan from the First National Bank before January 31."', 'For this question only, assume that Ohner was unable to obtain the loan, and, on January 31, phoned Artisan and told him, "Don''t begin the work. The deal is off." In an action for breach of contract brought against Ohner by the proper party, will Ohner be successful in asserting as a defense his inability to obtain a loan?', 'Yes, because obtaining a loan was a condition precedent to the existence of an enforceable contract.', 'Yes, because the agreement about obtaining a loan is a modification of a construction contract and is not required to be in writing.', 'No, because the agreement about obtaining a loan contradicts the express and implied terms of the writing.', 'No, because Ohner is estopped to deny the validity of the written agreement.', 'A', 'A “condition precedent” under a contract is an act that must be performed or an event that must occur before a contract becomes effective or before one party to an existing contract is obligated to perform.', 'mbe_344', 0, '38'),
('mbe_439', 'mbe', '439', '259', 'MBE-1978-83-part6', '', '39', 'On January 15, in a signed writing, Artisan agreed to remodel Ohner''s building according to certain specifications, Ohner to pay the agreed price of $5,000 to Artisan''s niece, Roberta Neese, as a birthday present. Neese did not learn of the agreement until her birthday on May 5. Before they signed the writing, Artisan and Ohner had orally agreed that their "written agreement will be null and void unless Ohner is able to obtain a $5,000 loan from the First National Bank before January 31."', 'For this question only, assume that Ohner obtained the loan, that Artisan completed the remodeling on May 1, and that on May 3, at Artisan''s request, Ohner paid the $5,000 to Artisan. If Neese learns of Ohner''s payment to Artisan on May 5, at the same time she learns of the written Artisan-Ohner contract, will she succeed in an action against Ohner for $5,000?', 'Yes, because she is an intended beneficiary of the written Artisan-Ohner contract.', 'Yes, because the written Artisan-Ohner contract operated as an assignment to Neese, and Artisan thereby lost whatever rights he may have had to the $5,000.', 'No, because Neese had not furnished any consideration to support Ohner''s promise to pay $5,000 to her.', 'No, because on May 3, Artisan and Ohner effectively modified their written contract, thereby depriving Neese of whatever rights she may have had under that contract.', 'D', '“A contract can be modified when there is clear and convincing evidence of the parties'' mutual intent to modify the contract through their course of dealing.” Third Fed. S. & L. Assn. of Cleveland v. Formanik, 8th Dist. Cuyahoga Nos. 100562 & 100810, 2014-Ohio-3234, 2014 WL 3700514, ¶ 13, citing Westgate Ford Truck Sales, Inc. v. Ford Motor Co., 2012-Ohio-1942, 971 N.E.2d 967, ¶¶ 24–25 (8th Dist.); see also RotoSolutions, Inc. v. Crane Plastics Siding, L.L.C., 10th Dist. Franklin Nos. 13AP-1 & 13AP–52, 2013-Ohio-4343, 2013 WL 5451702, ¶ 19 (“ ‘[A]n oral modification of a written contract can be enforceable notwithstanding a provision in the contract requiring modifications to be in writing where * * * the parties have engaged in a course of conduct in conformance with the oral modification and where the party seeking to enforce the oral modification would suffer injury if the modification were deemed invalid.’ ”), quoting Exact Software N. Am., Inc. v. Infocon Sys., Inc., N.D.Ohio No. 3:03CV7183, 2004 WL 952876 (Apr. 16, 2004); Miller Lakes Community Servs. Assn., Inc. v. Schmitt, 9th Dist. Wayne, 2016-Ohio-339, 2016 WL 515641, ¶¶ 18, 30 (“ ‘Parties may implicitly modify an agreement by their actions. A continued, different, course of performance between parties manifests a modification of the original agreement.’ ”), quoting St. Marys v. Auglaize Cty. Bd. of Commrs., 115 Ohio St.3d 387, 2007-Ohio-5026, 875 N.E.2d 561, ¶ 39; Kwikcolor Sand v. Fairmount Minerals Ltd., 8th Dist. Cuyahoga No. 96717, 2011-Ohio-6646, 2011 WL 6775580, ¶¶ 20–22 (where it was undisputed that the parties orally agreed to modify contract''s pricing schedule and operated under the modified pricing schedule for more than a year, plaintiff waived the contract''s no-oral modification provision and the parties were contractually bound to the modified pricing structure).', 'mbe_345', 0, '39')
